INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91289, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尖尖的，会扎疼手的东西。", "primary_collocate": null, "pronunciation": "cì", "ipa": "tsʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "我的手指里扎进了一根刺，很疼。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用针帮我把手上的刺挑了出来。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块木头上有很多小刺，别用手摸。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根刺太小了，我都看不见。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用手拔出了孩子手上的刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摸了一下旧木板，手上扎了刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手很疼，好像有什么刺在里面。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你小心，木桌上有刺，会扎手。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上的刺很小，要用针才能挑出来。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用镊子把手指上的刺夹了出来。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根刺", "label": "量词"}, {"form": "鱼刺", "label": "复合"}], "register": "中性", "sense_fingerprint": "刺：扎进手里的小尖东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T2: contains vocabulary far above tier T2: 镊 (Zipf 1.85)']::text[], 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91289, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺（cì）：尖细、能扎入皮肤的东西，正确答案。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 cì 声母不同（z/c），意思是文字的字。"}, {"text": "翅", "is_correct": false, "explanation": "chì 与 cì 声母不同（ch/c），意思是翅膀。"}, {"text": "此", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，意思是这。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 cì 声母不同（s/c），意思是数字四。"}], "explanations": {"刺": "刺（cì）：尖细、能扎入皮肤的东西，正确答案。", "字": "zì 与 cì 声母不同（z/c），意思是文字的字。", "翅": "chì 与 cì 声母不同（ch/c），意思是翅膀。", "此": "cǐ（第三声）与 cì（第四声）声调不同，意思是这。", "四": "sì 与 cì 声母不同（s/c），意思是数字四。"}, "sentence_index": null, "correct_answer": "刺"}, "level_3": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺：扎进手指的尖细东西，与“扎进”“很疼”相符。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子不会扎进手指，与“扎进”的动作不合。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：“扎进”后接的是尖细硬物，不说“扎进一根头发”。"}, {"text": "橡皮筋", "is_correct": false, "explanation": "语义：橡皮筋软，扎不进手指。"}], "explanations": {"刺": "刺：扎进手指的尖细东西，与“扎进”“很疼”相符。", "绳子": "语义：绳子不会扎进手指，与“扎进”的动作不合。", "头发": "搭配：“扎进”后接的是尖细硬物，不说“扎进一根头发”。", "橡皮筋": "语义：橡皮筋软，扎不进手指。"}, "sentence_index": 0, "correct_answer": "刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生用刺给我打了一针，我一点都不疼。", "explanation": "这里应该用〈针头〉。打针要靠针头扎入皮肤，刺是长在植物或物体上的尖东西，不能当注射用的工具。"}, {"text": "这只猫身上的刺很软，摸起来很舒服。", "explanation": "这里应该用〈毛〉。猫身上的是毛，刺指尖硬的东西，不会是软的。"}, {"text": "这根刺太细了，穿不过线。", "explanation": "这里应该用〈针〉。针细长，能穿线；刺是长在植物上或扎进物体的尖东西，不能用来穿线。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91289, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺（cì）：尖细、能扎入皮肤的东西，正确答案。"}, {"text": "词", "is_correct": false, "explanation": "cí（第二声）与 cì（第四声）声调不同，意思是词语。"}, {"text": "自", "is_correct": false, "explanation": "zì 与 cì 仅送气不同（z/c），意思是自己的自。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 cì 声母不同（s/c），意思是寺庙。"}, {"text": "慈", "is_correct": false, "explanation": "cí（第二声）与 cì 声调不同，意思是慈祥。"}], "explanations": {"刺": "刺（cì）：尖细、能扎入皮肤的东西，正确答案。", "词": "cí（第二声）与 cì（第四声）声调不同，意思是词语。", "自": "zì 与 cì 仅送气不同（z/c），意思是自己的自。", "寺": "sì 与 cì 声母不同（s/c），意思是寺庙。", "慈": "cí（第二声）与 cì 声调不同，意思是慈祥。"}, "sentence_index": null, "correct_answer": "刺"}, "level_3": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺：扎进皮肤里的尖细东西，与“手很疼”相符。"}, {"text": "眼泪", "is_correct": false, "explanation": "语义：眼泪不会藏在手里，与“手很疼”的原因不合。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“手很疼”的原因不能是“糖”，糖不会使手疼。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能待在手里，“有什么……在里面”指的是实物。"}], "explanations": {"刺": "刺：扎进皮肤里的尖细东西，与“手很疼”相符。", "眼泪": "语义：眼泪不会藏在手里，与“手很疼”的原因不合。", "糖": "搭配：“手很疼”的原因不能是“糖”，糖不会使手疼。", "声音": "语义：声音不能待在手里，“有什么……在里面”指的是实物。"}, "sentence_index": 6, "correct_answer": "刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用镊子把手指上的刺喝了下去。", "explanation": "刺是扎入皮肤的尖东西，不能喝下去。"}, {"text": "她用镊子把手指上的刺缝了起来。", "explanation": "缝合的对象是伤口或布料，刺不能被缝。"}, {"text": "她用镊子把手指上的刺穿在了线上。", "explanation": "能穿在线上的是针，刺不能被穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91289, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只刺很细，得用镊子才能拔出来。", "corrected_sentence": "这根刺很细，得用镊子才能拔出来。", "error_description": "量词错误：“刺”是细长的东西，应用“根”，不用“只”（“只”多用于动物或成对的东西）。应说“这根刺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91289, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我用针把手指上的一个刺挑了出来。", "corrected_sentence": "我用针把手指上的一根刺挑了出来。", "error_description": "量词错误：“刺”是细长的东西，应用“根”，不用“个”。应说“一根刺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
