INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "尖锐的、能扎入物体的东西，如植物茎上的刺。", "primary_collocate": null, "pronunciation": "cì", "ipa": "tsʰɨ˥˩", "syllable_count": 1, "sentences": [{"text": "玫瑰花很漂亮，可是茎上有很多刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仙人掌身上长满了刺，不能用手摸。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摘玫瑰的时候，要小心茎上的刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树的树枝上有又长又硬的刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野果树的枝上有刺，摘果子要戴手套。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玫瑰的刺很尖，会把手指扎疼。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把花茎上的刺都剪掉了。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这朵花没有刺，可以放心地拿着。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "野蔷薇的枝条上长着尖尖的刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，那丛草的茎上有细细的刺。", "target_word": "刺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根刺", "label": "量词"}], "register": "中性", "sense_fingerprint": "刺：植物茎枝上长的尖刺", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2e039c7-c01e-4c40-b644-454870abac61') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91290, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺（cì）：植物茎枝上的尖刺，正确答案。"}, {"text": "字", "is_correct": false, "explanation": "zì 与 cì 声母不同（z/c），意思是字。"}, {"text": "翅", "is_correct": false, "explanation": "chì 与 cì 声母不同（ch/c），意思是翅膀。"}, {"text": "此", "is_correct": false, "explanation": "cǐ（第三声）与 cì（第四声）声调不同，意思是这。"}], "explanations": {"刺": "刺（cì）：植物茎枝上的尖刺，正确答案。", "字": "zì 与 cì 声母不同（z/c），意思是字。", "翅": "chì 与 cì 声母不同（ch/c），意思是翅膀。", "此": "cǐ（第三声）与 cì（第四声）声调不同，意思是这。"}, "sentence_index": null, "correct_answer": "刺"}, "level_3": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺：植物茎上的尖刺，与“茎上”“很多”相符。"}, {"text": "钉子", "is_correct": false, "explanation": "语义：茎上不会长出钉子，与“玫瑰花很漂亮”的描述不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：茎上长不出石头，这里说的是植物本身。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“茎上有”指植物自身的部分，不说“茎上有绳子”。"}], "explanations": {"刺": "刺：植物茎上的尖刺，与“茎上”“很多”相符。", "钉子": "语义：茎上不会长出钉子，与“玫瑰花很漂亮”的描述不合。", "石头": "语义：茎上长不出石头，这里说的是植物本身。", "绳子": "搭配：“茎上有”指植物自身的部分，不说“茎上有绳子”。"}, "sentence_index": 0, "correct_answer": "刺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支铅笔的刺很尖，写字很清楚。", "explanation": "这里应该用〈笔尖〉。笔尖是铅笔写字的尖端，刺是长在植物上或扎进物体的尖东西，不能说铅笔的刺。"}, {"text": "我用刺把破了的袜子补好了。", "explanation": "补袜子要用针线，刺不能用来缝补。"}, {"text": "这种树的树枝上结满了又圆又红的刺。", "explanation": "树枝上结的是果子，刺不会结成圆红的果实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91290, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺（cì）：植物茎枝上的尖刺，正确答案。"}, {"text": "词", "is_correct": false, "explanation": "cí（第二声）与 cì（第四声）声调不同，意思是词语。"}, {"text": "寺", "is_correct": false, "explanation": "sì 与 cì 声母不同（s/c），意思是寺庙。"}, {"text": "慈", "is_correct": false, "explanation": "cí（第二声）与 cì 声调不同，意思是慈祥。"}, {"text": "四", "is_correct": false, "explanation": "sì 与 cì 声母不同（s/c），意思是数字四。"}], "explanations": {"刺": "刺（cì）：植物茎枝上的尖刺，正确答案。", "词": "cí（第二声）与 cì（第四声）声调不同，意思是词语。", "寺": "sì 与 cì 声母不同（s/c），意思是寺庙。", "慈": "cí（第二声）与 cì 声调不同，意思是慈祥。", "四": "sì 与 cì 声母不同（s/c），意思是数字四。"}, "sentence_index": null, "correct_answer": "刺"}, "level_3": {"options": [{"text": "刺", "is_correct": true, "explanation": "刺：植物茎上的尖刺，“剪掉”的对象正是它。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“剪掉”不能用于墨水这类液体。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：花茎上不会有需要剪掉的泥土。"}, {"text": "灰尘", "is_correct": false, "explanation": "搭配：“剪掉”一般用于枝条、条状物，不说“剪掉灰尘”。"}], "explanations": {"刺": "刺：植物茎上的尖刺，“剪掉”的对象正是它。", "墨水": "搭配：“剪掉”不能用于墨水这类液体。", "泥土": "语义：花茎上不会有需要剪掉的泥土。", "灰尘": "搭配：“剪掉”一般用于枝条、条状物，不说“剪掉灰尘”。"}, "sentence_index": 6, "correct_answer": "刺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用刺把衣服缝好了。", "explanation": "这里应该用〈针〉。缝衣服要用针，刺不是缝纫的工具。"}, {"text": "他用锤子把刺钉进了木板。", "explanation": "这里应该用〈钉子〉。钉子可以钉进木板，刺是长在植物上的东西，不能钉。"}, {"text": "这只猫的刺很软，摸起来很舒服。", "explanation": "这里应该用〈毛〉。猫身上的是毛，刺是尖硬的东西，不会是软的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "枝条上有一只很长的刺，别碰它。", "corrected_sentence": "枝条上有一根很长的刺，别碰它。", "error_description": "量词错误：“刺”是细长的东西，应用“根”，不用“只”。应说“一根很长的刺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种仙人掌上开着很多又长又硬的刺，别用手摸。", "corrected_sentence": "这种仙人掌上长着很多又长又硬的刺，别用手摸。", "error_description": "搭配错误：植物上的刺是“长”出来的，不是“开”出来的（“开”用于花）。应说“长着很多刺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ba49956-2a47-454c-a3a3-d17e30ab5578') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
