INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91291, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "旧时说话时放在句末的语气词，用于恳求或请求。", "primary_collocate": null, "pronunciation": "zé gè", "ipa": "tsɤ˧˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "掌柜的，借个火则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟，替我送封信则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大哥帮个忙则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘子，给我倒杯茶则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老爷，饶了小的则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店家，给我一间房住则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先生，教我认几个字则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客官，让我歇一歇则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大嫂，把门开开则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅，看看我的手相则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古旧", "sense_fingerprint": "旧时人说话放在句尾的语气字，常带请求的口气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91291, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哇", "is_correct": false, "explanation": "语域：“哇”是现代口语的感叹语气词，与旧白话语境不合。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示曾经发生，不作恳求的句末语气，“借个火过”不成句。"}, {"text": "则个", "is_correct": true, "explanation": "则个：旧时说话放在句末的语气字，用于恳求，与“借个火”的请求语境相合。"}, {"text": "咯", "is_correct": false, "explanation": "语域：“咯”是口语语气词，与旧时说话的语境不合。"}], "explanations": {"哇": "语域：“哇”是现代口语的感叹语气词，与旧白话语境不合。", "过": "语法：“过”表示曾经发生，不作恳求的句末语气，“借个火过”不成句。", "则个": "则个：旧时说话放在句末的语气字，用于恳求，与“借个火”的请求语境相合。", "咯": "语域：“咯”是口语语气词，与旧时说话的语境不合。"}, "sentence_index": 0, "correct_answer": "则个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨晚睡得很晚则个。", "explanation": "则个表示恳求，只用于请人做事的句末；陈述“睡得很晚”这类事实时不能用它，这句只需直接陈述。"}, {"text": "这碗面真香则个！", "explanation": "则个不用于赞叹美味，感叹语境中不能带恳求的口气；这里只说“这碗面真香”即可。"}, {"text": "这事我不管则个。", "explanation": "则个用于请别人帮忙的恳求语境，表示推脱或拒绝时不能带请求的口气，这句与则个的用法不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91291, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢", "is_correct": false, "explanation": "语义：“呢”多表疑问或持续的语气，不表恳求，与“教我认几个字”的请求语境不合。"}, {"text": "则个", "is_correct": true, "explanation": "则个：旧时说话放在句末的语气字，用于恳求，与“教我”的请求语境相合。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示动作持续，不能放在句末表恳求，“教我认几个字着”不成句。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示曾经发生，不作恳求的句末语气，“教我认几个字过”不成句。"}], "explanations": {"呢": "语义：“呢”多表疑问或持续的语气，不表恳求，与“教我认几个字”的请求语境不合。", "则个": "则个：旧时说话放在句末的语气字，用于恳求，与“教我”的请求语境相合。", "着": "语法：“着”表示动作持续，不能放在句末表恳求，“教我认几个字着”不成句。", "过": "语法：“过”表示曾经发生，不作恳求的句末语气，“教我认几个字过”不成句。"}, "sentence_index": 6, "correct_answer": "则个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若天气不好则个改期。", "explanation": "这里“则个”表示承接结果，但它只是句末语气助词，表示请求，不能用来引出结果；应说“若天气不好就改期”。"}, {"text": "谁昨天来过则个？", "explanation": "“则个”表示请求，用在疑问句末不合语境；问人来过没有应直接说“谁昨天来过”。"}, {"text": "我是他的弟弟则个。", "explanation": "“则个”表示请求，用在陈述身份的句末不合语境；这里应直接说“我是他的弟弟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
