INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91292, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "旧时白话中的语气助词，用于句末。", "primary_collocate": null, "pronunciation": "zé gè", "ipa": "tsɤ˧˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "官人行个方便则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小二哥，给我拿壶酒来则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客官请坐，听我说一段书则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员外，可怜小人则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "娘子莫要生气，听我说则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥，借你的马骑一骑则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请师父指点迷津则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老丈，告诉我这条路怎么走则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相公，赏我一碗饭吃则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小姐且慢，容我说句话则个。", "target_word": "则个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "古旧", "sense_fingerprint": "旧白话句末语气助词，多用于请求、恳求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91292, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过", "is_correct": false, "explanation": "语法：“过”表示曾经发生，不作恳求的句末语气，与请求语境不合。"}, {"text": "则个", "is_correct": true, "explanation": "则个：旧白话句末语气助词，用于恳求，与“官人行个方便”的请求语境相合。"}, {"text": "了", "is_correct": false, "explanation": "语法：“了”表示事情已完成，句子变为陈述，不表恳求。"}, {"text": "哇", "is_correct": false, "explanation": "语域：“哇”是现代口语的感叹语气词，与旧白话语境不合。"}], "explanations": {"过": "语法：“过”表示曾经发生，不作恳求的句末语气，与请求语境不合。", "则个": "则个：旧白话句末语气助词，用于恳求，与“官人行个方便”的请求语境相合。", "了": "语法：“了”表示事情已完成，句子变为陈述，不表恳求。", "哇": "语域：“哇”是现代口语的感叹语气词，与旧白话语境不合。"}, "sentence_index": 0, "correct_answer": "则个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天买了一本书则个。", "explanation": "则个是旧白话里用于请求、恳求的句末语气助词，陈述已经发生的事不用它；这句只需直接说“我昨天买了一本书”。"}, {"text": "天气真好则个！", "explanation": "则个表示恳求，不用于赞叹或感叹天气；这里只需说“天气真好”。"}, {"text": "我不去则个。", "explanation": "则个用于请对方做事的恳求语境，表示拒绝时不能带请求的口气，这句与则个的用法不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91292, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呢", "is_correct": false, "explanation": "语义：“呢”多表疑问或持续的语气，不表恳求，与“请师父”的请求语境不合。"}, {"text": "则个", "is_correct": true, "explanation": "则个：旧白话句末语气助词，用于恳求，与“请”字呼应。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示动作持续，不能放在句末表恳求，“指点迷津着”不成句。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示曾经发生，不作恳求的句末语气，“指点迷津过”不成句。"}], "explanations": {"呢": "语义：“呢”多表疑问或持续的语气，不表恳求，与“请师父”的请求语境不合。", "则个": "则个：旧白话句末语气助词，用于恳求，与“请”字呼应。", "着": "语法：“着”表示动作持续，不能放在句末表恳求，“指点迷津着”不成句。", "过": "语法：“过”表示曾经发生，不作恳求的句末语气，“指点迷津过”不成句。"}, "sentence_index": 6, "correct_answer": "则个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "若明天下雨则个取消活动。", "explanation": "这里“则个”表示承接结果，但它只是句末语气助词，表示请求，不能用来引出结果；应说“若明天下雨就取消活动”。"}, {"text": "谁明天去开会则个？", "explanation": "“则个”表示请求，用在疑问句末不合语境；问人去向应直接说“谁明天去开会”。"}, {"text": "我是他的同学则个。", "explanation": "“则个”表示请求，用在陈述身份的句末不合语境；这里应直接说“我是他的同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91292, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "掌柜的，再给我添碗汤则个则个。", "corrected_sentence": "掌柜的，再给我添碗汤则个。", "error_description": "“则个”是句末语气助词，只用一次，且放在句尾；“则个则个”重复，应写作“再给我添碗汤则个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
