INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91294, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示由于某种有利条件而避免了不好的结果。", "primary_collocate": null, "pronunciation": "xìng hǎo", "ipa": "ɕiŋ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "幸好我带了伞，没淋湿。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好他开得慢，没有出事故。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好有朋友帮忙，我们才按时完成了。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好我早点儿出门，没有迟到。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好医生来得快，他的病没有加重。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好今天不冷，我们没感冒。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好你提醒我，我差点儿忘了。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好地上有雪，他摔倒时没受伤。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好我留着票，不然进不去。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好车上有水，大家才不渴。", "target_word": "幸好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因某个有利条件，避免了本来可能出现的坏结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "幸好", "is_correct": true, "explanation": "正确：“幸好”表示因有利条件避免了坏结果，“幸好我带了伞，没淋湿”符合句意。"}, {"text": "可惜", "is_correct": false, "explanation": "语义：“可惜”表示遗憾，与句中“没淋湿”所表达的庆幸相反。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能修饰“我带了伞”这样的小句，不能放在句首作状语。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈地做出选择，与“没淋湿”的有利结果不相符。"}], "explanations": {"幸好": "正确：“幸好”表示因有利条件避免了坏结果，“幸好我带了伞，没淋湿”符合句意。", "可惜": "语义：“可惜”表示遗憾，与句中“没淋湿”所表达的庆幸相反。", "很": "搭配：“很”不能修饰“我带了伞”这样的小句，不能放在句首作状语。", "只好": "语义：“只好”表示无奈地做出选择，与“没淋湿”的有利结果不相符。"}, "sentence_index": 0, "correct_answer": "幸好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "幸好我没带伞，结果还是淋湿了。", "explanation": "“幸好”只用于避免了坏结果的情况，这里已经淋湿，结果是坏的，不能用“幸好”。"}, {"text": "幸好我不得不加班到深夜。", "explanation": "“幸好”表示避免了坏结果，而“不得不加班”是被迫的负担，二者语义不协调。这里应直接说“我不得不加班到深夜”。"}, {"text": "幸好我把钥匙弄丢了，只好等了一个小时。", "explanation": "“弄丢钥匙”是坏结果，“幸好”只用于避免了坏结果的情况，这里不能用。应直接说“我把钥匙弄丢了，只好等了一个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸好", "is_correct": true, "explanation": "正确：“幸好”表示多亏对方提醒，避免了忘记的结果，符合句意。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示与预期相反或故意，与“提醒我”带来的好处不相符。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”需要前文有同类情况作衔接，句首没有这种衔接，不能直接修饰“你提醒我”。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无奈的选择，与“提醒我”所表达的庆幸语气不符。"}], "explanations": {"幸好": "正确：“幸好”表示多亏对方提醒，避免了忘记的结果，符合句意。", "偏偏": "语义：“偏偏”表示与预期相反或故意，与“提醒我”带来的好处不相符。", "也": "搭配：“也”需要前文有同类情况作衔接，句首没有这种衔接，不能直接修饰“你提醒我”。", "只好": "语义：“只好”表示无奈的选择，与“提醒我”所表达的庆幸语气不符。"}, "sentence_index": 6, "correct_answer": "幸好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他幸好是医生，却把病人的病拖重了。", "explanation": "“幸好”表示避免了坏结果，这里病人的病拖重了，结果是坏的，不能用“幸好”。应直接说“他是医生，却把病人的病拖重了”。"}, {"text": "幸好他一定会来迟到。", "explanation": "“幸好”表示避免了坏结果，而“迟到”本身是坏结果，二者不能搭配。应直接说“他一定会迟到”。"}, {"text": "幸好你快来帮我。", "explanation": "“幸好”表示已经发生的庆幸，不能用于请求或命令；这里应直接说“你快来帮我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很幸好我早点儿回家，没有遇到堵车。", "corrected_sentence": "幸好我早点儿回家，没有遇到堵车。", "error_description": "错误：副词“很”修饰了“幸好”。正确：“幸好”是副词，不能被“很”修饰，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幸好是桥修好了，我们按时到了。", "corrected_sentence": "幸好桥修好了，我们按时到了。", "error_description": "错误：“幸好”后面不应加“是”。正确：应写作“幸好桥修好了”，“幸好”直接接小句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
