INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91296, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "曾经担任总统、现已卸任的人。", "primary_collocate": null, "pronunciation": "qián zǒng tǒng", "ipa": "tɕʰjɛn˧˥ tsʊŋ˨˩ tʰʊŋ˨˩", "syllable_count": 3, "sentences": [{"text": "他是我们国家的一位前总统。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前总统每年都会来学校看看。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位前总统已经七十岁了。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者问前总统现在过得怎么样。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前总统在会上讲了自己的故事。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请前总统来讲了一次课。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位前总统喜欢画画，也喜欢旅行。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "前总统坐飞机去了另一个国家。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家都有前总统。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不是现在的总统，而是前总统。", "target_word": "前总统", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已经卸任、不再担任总统的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91296, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前总统", "is_correct": true, "explanation": "“前总统”指曾任总统、现已卸任的人，与“一位”搭配，指称人物。"}, {"text": "首都", "is_correct": false, "explanation": "语义：“首都”是城市，不是人，不能用“一位”指称。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“位”用于人，“火车”不能用“一位”计量。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：“湖泊”是水域，不是人，不能用“一位”指称。"}], "explanations": {"前总统": "“前总统”指曾任总统、现已卸任的人，与“一位”搭配，指称人物。", "首都": "语义：“首都”是城市，不是人，不能用“一位”指称。", "火车": "搭配：“位”用于人，“火车”不能用“一位”计量。", "湖泊": "语义：“湖泊”是水域，不是人，不能用“一位”指称。"}, "sentence_index": 0, "correct_answer": "前总统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "前总统正在国会里主持表决。", "explanation": "这里应该用〈现任总统〉。前总统已经卸任，不能再主持国会表决。"}, {"text": "我在街上遇到了一座前总统。", "explanation": "这里应该用〈位〉。“前总统”指人，要用“位”计量，“座”多用于山、桥、房屋等。"}, {"text": "这座城市的前总统去年去世了。", "explanation": "这里应该用〈前市长〉。“前总统”只指国家的前任元首，城市的负责人应称“市长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91296, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前总统", "is_correct": true, "explanation": "“前总统”指人，与“那位”搭配，与喜欢画画、旅行的语境相合。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“位”只用于人，“闹钟”不能用“那位”计量，也不会画画旅行。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文学作品，不能喜欢画画和旅行。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，无法喜欢画画和旅行。"}], "explanations": {"前总统": "“前总统”指人，与“那位”搭配，与喜欢画画、旅行的语境相合。", "闹钟": "搭配：“位”只用于人，“闹钟”不能用“那位”计量，也不会画画旅行。", "小说": "语义：“小说”是文学作品，不能喜欢画画和旅行。", "桌子": "语义：“桌子”是家具，无法喜欢画画和旅行。"}, "sentence_index": 6, "correct_answer": "前总统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个前总统很好吃，我们尝尝吧。", "explanation": "这里应该用〈点心〉。“前总统”指人，不能用来形容食物。"}, {"text": "我用前总统写作业。", "explanation": "这里应该用〈铅笔〉。“前总统”指人，不能当作工具使用。"}, {"text": "前总统是蓝色的。", "explanation": "这里应该用〈天空〉。“前总统”指人，不能用来描述颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91296, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只前总统退休后住在乡下。", "corrected_sentence": "那位前总统退休后住在乡下。", "error_description": "量词错误：“前总统”指人，应用“位”计量，说“那位前总统”；“只”多用于动物，不能用来修饰“前总统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91296, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条前总统很喜欢读书。", "corrected_sentence": "这位前总统很喜欢读书。", "error_description": "量词错误：“前总统”指人，应用“位”计量，说“这位前总统”；“条”用于鱼、河、路等，不能修饰“前总统”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
