INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91297, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "划分是把一大块分成几小块。", "primary_collocate": null, "pronunciation": "huà fēn", "ipa": "xwa˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "农民把大田划分成六小块。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把这块空地划分成八块。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把院子划分成菜地和花园。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张纸划分成四个小格子。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水把村子划分为南北两半。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用线把操场划分成几个小区域。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把这片草地划分好了。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把办公室划分成三个小间。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地太大，要划分一下才好用。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把大房间划分成两个卧室。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "划分了", "label": "体标"}, {"form": "划分过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把一大块地方或东西切分、隔开成几个小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91297, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变成液体，大田不能被熔化成六小块。"}, {"text": "划分", "is_correct": true, "explanation": "划分：把一大块分成几小块，与“分成六小块”相符。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”指使物体降温变硬以便保存，与把大田分块无关。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”用于烹调食物，不用来指把大田分成小块。"}], "explanations": {"熔化": "语义：“熔化”指固体受热变成液体，大田不能被熔化成六小块。", "划分": "划分：把一大块分成几小块，与“分成六小块”相符。", "冷冻": "语义：“冷冻”指使物体降温变硬以便保存，与把大田分块无关。", "煎": "搭配：“煎”用于烹调食物，不用来指把大田分成小块。"}, "sentence_index": 0, "correct_answer": "划分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在池塘里划分小船。", "explanation": "这里“划分”的意思不对。“划”在这里指用桨使船前进，应说“划船”。"}, {"text": "这只猫把我的手划分了一道口子。", "explanation": "这里“划分”不能表示划破皮肤，应说“划了一道口子”，“划”表示用利器或爪子割开。"}, {"text": "妈妈把饭划分得很香。", "explanation": "“划分”指把整体分成几部分，不用来评价饭菜的香味；“香”与“划分”不搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91297, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热烹调食物，草地不能被煮好。"}, {"text": "划分", "is_correct": true, "explanation": "划分：把一大块分成几小块，与“划分好了”的结果相符。"}, {"text": "炖", "is_correct": false, "explanation": "语义：“炖”是用小火长时间烹调食物，与草地无关。"}, {"text": "熨", "is_correct": false, "explanation": "搭配：“熨”用于平整衣物等织物，不用来指草地。"}], "explanations": {"煮": "语义：“煮”指用水加热烹调食物，草地不能被煮好。", "划分": "划分：把一大块分成几小块，与“划分好了”的结果相符。", "炖": "语义：“炖”是用小火长时间烹调食物，与草地无关。", "熨": "搭配：“熨”用于平整衣物等织物，不用来指草地。"}, "sentence_index": 6, "correct_answer": "划分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不小心把杯子划分了。", "explanation": "这里应该用〈打碎〉。划分指把整体分成几部分，杯子摔坏应说“打碎”。"}, {"text": "工人把旧墙划分了。", "explanation": "这里应该用〈拆除〉。划分指分成几部分，拆掉旧墙要用“拆除”。"}, {"text": "小孩把窗户划分了。", "explanation": "这里应该用〈砸破〉。划分不表示把窗户打坏，应说“砸破”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91297, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民把大田划分了成两块。", "corrected_sentence": "农民把大田划分成两块。", "error_description": "“成”作结果补语，紧接在“划分”之后，中间不能插入“了”；正确说法是“农民把大田划分成两块”，“划分了成两块”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91297, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把大房间划分很整齐。", "corrected_sentence": "他们把大房间划分得很整齐。", "error_description": "“划分”作谓语带程度补语时，须用“得”连接补语；正确说法是“划分得很整齐”，漏掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
