INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91298, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把整体分成几部分。", "primary_collocate": null, "pronunciation": "huà fēn", "ipa": "xwa˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "老师把全班同学划分成四个小组。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把一天划分为三段时间。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市划分为十个区。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年可以划分为四个季节。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这本书划分成两个部分。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的内容划分得很清楚。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这篇文章划分成几段。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人划分为轻重两类。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把学习内容划分成五个单元。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上，中国划分成很多省。", "target_word": "划分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "划分了", "label": "体标"}, {"form": "划分过", "label": "体标"}], "register": "通用", "sense_fingerprint": "把一个整体（时间、内容、人群等）按标准分成几个部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b52513e-fedf-4788-b1e7-ec0fa96f5592') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91298, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瓜分", "is_correct": false, "explanation": "搭配：“瓜分”多用于土地、财产、利益，不用来指把一班同学分组。"}, {"text": "划分", "is_correct": true, "explanation": "划分：把整体分成几部分，与“分成四个小组”相符。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”指把几者合为一，与“分成四个小组”方向相反。"}, {"text": "拆解", "is_correct": false, "explanation": "搭配：“拆解”多用于机器、结构等有形之物，不用来指把一班同学分组。"}], "explanations": {"瓜分": "搭配：“瓜分”多用于土地、财产、利益，不用来指把一班同学分组。", "划分": "划分：把整体分成几部分，与“分成四个小组”相符。", "合并": "语义：“合并”指把几者合为一，与“分成四个小组”方向相反。", "拆解": "搭配：“拆解”多用于机器、结构等有形之物，不用来指把一班同学分组。"}, "sentence_index": 0, "correct_answer": "划分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要学会划分对错。", "explanation": "这里应该用〈区分〉。划分指把整体分成几部分，辨别对错要用“区分”。"}, {"text": "我想把这份快乐划分给你。", "explanation": "这里应该用〈分享〉。划分不表示把好事或感受告诉别人，分享快乐要用“分享”。"}, {"text": "他们划分了多年的友谊。", "explanation": "这里应该用〈断绝〉。划分不用于感情关系，说结束多年的友谊要用“断绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91298, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷冻", "is_correct": false, "explanation": "语义：“冷冻”指使物体降温变硬以便保存，不能把文章冷冻成几段。"}, {"text": "划分", "is_correct": true, "explanation": "划分：把整体分成几部分，与“分成几段”相符。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：“熔化”指固体受热变成液体，与把文章分段无关。"}, {"text": "煎", "is_correct": false, "explanation": "搭配：“煎”用于烹调食物，不用来指给文章分段。"}], "explanations": {"冷冻": "语义：“冷冻”指使物体降温变硬以便保存，不能把文章冷冻成几段。", "划分": "划分：把整体分成几部分，与“分成几段”相符。", "熔化": "语义：“熔化”指固体受热变成液体，与把文章分段无关。", "煎": "搭配：“煎”用于烹调食物，不用来指给文章分段。"}, "sentence_index": 6, "correct_answer": "划分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在湖上划分小船。", "explanation": "这里“划分”的意思不对。“划”在这里指用桨使船前进，应说“划船”，划分是把整体分开。"}, {"text": "他用笔在纸上划分了一个笑脸。", "explanation": "这里应该用〈画〉。划分指把整体分成几部分，画笑脸要用“画”。"}, {"text": "他随手划分了一根火柴点燃蜡烛。", "explanation": "这里的“划”指擦、划燃火柴，“划分”表示把整体分成几部分，不能用于擦火柴；应说“他随手划了一根火柴点燃蜡烛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91298, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这个班划分了成两组。", "corrected_sentence": "我们把这个班划分成两组。", "error_description": "“成”作结果补语，紧接在“划分”之后，中间不能插入“了”；正确说法是“我们把这个班划分成两组”，“划分了成两组”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91298, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书的单元划分很清楚。", "corrected_sentence": "这本书的单元划分得很清楚。", "error_description": "“划分”作谓语带程度补语时，须用“得”连接补语；正确说法是“划分得很清楚”，漏掉“得”则句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'adeadec7-0c05-4d1b-b490-379037d9a401') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
