INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91299, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "后台是舞台后面，演员准备的地方。", "primary_collocate": null, "pronunciation": "hòu tái", "ipa": "xoʊ˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "演员们正在后台化妆。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出前，她在后台紧张地等着。", "target_word": "后台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走进后台，找到了自己的衣服。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "后台太小，放不下这么多箱子。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导演在后台给演员们加油。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "观众不能进后台。", "target_word": "后台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "演出结束后，我去后台找朋友。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "后台的灯亮着，里面还有人。", "target_word": "后台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明第一次来后台，觉得什么都新鲜。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在后台换好了演出服。", "target_word": "后台", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "后臺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "剧场舞台后面供演员准备的空间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91299, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后台", "is_correct": true, "explanation": "正确。后台指舞台后面供演员化妆、候场的地方。"}, {"text": "后来", "is_correct": false, "explanation": "声母不同：lái 与 tái 只是声母 l/t 不同，意思是“之后”，不是舞台后面的地方。"}, {"text": "后胎", "is_correct": false, "explanation": "声调不同：tāi（第一声）与 tái（第二声）只差声调，意思是车轮的后胎。"}, {"text": "厚待", "is_correct": false, "explanation": "声母不同：dài 与 tái 只是声母 d/t 不同，声调也不同，意思是“好好对待”，不是舞台后面的地方。"}], "explanations": {"后台": "正确。后台指舞台后面供演员化妆、候场的地方。", "后来": "声母不同：lái 与 tái 只是声母 l/t 不同，意思是“之后”，不是舞台后面的地方。", "后胎": "声调不同：tāi（第一声）与 tái（第二声）只差声调，意思是车轮的后胎。", "厚待": "声母不同：dài 与 tái 只是声母 d/t 不同，声调也不同，意思是“好好对待”，不是舞台后面的地方。"}, "sentence_index": null, "correct_answer": "后台"}, "level_3": {"options": [{"text": "后台", "is_correct": true, "explanation": "正确。演员在舞台后面的后台化妆，符合句意。"}, {"text": "粉底", "is_correct": false, "explanation": "搭配：粉底是化妆品，不能作“在…化妆”的地点。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：课桌是学校的用具，不能作演员化妆的场所。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，与化妆的地点无关。"}], "explanations": {"后台": "正确。演员在舞台后面的后台化妆，符合句意。", "粉底": "搭配：粉底是化妆品，不能作“在…化妆”的地点。", "课桌": "搭配：课桌是学校的用具，不能作演员化妆的场所。", "工资": "语义：工资是报酬，与化妆的地点无关。"}, "sentence_index": 0, "correct_answer": "后台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在后台里做饭。", "explanation": "这里应该用〈厨房〉。后台的本义是剧场舞台后面供演员候场的地方，不能用来做饭；做饭应在厨房。"}, {"text": "孩子们在后台里种了几棵树。", "explanation": "这里应该用〈后院〉。后台是剧场里演员候场的空间，不能用来种树；后院是房屋后面的院子。"}, {"text": "我们在学校后台上体育课。", "explanation": "这里应该用〈操场〉。后台是剧场舞台后面供演员候场的地方，上体育课应在操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91299, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后台", "is_correct": true, "explanation": "正确。演出结束后去后台找人，符合句意。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是活动，不是可以去找人的地方。"}, {"text": "星期", "is_correct": false, "explanation": "配价：“去”后面要接地点，“星期”是时间词，不能作“去”的对象。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是书籍，不是找人的场所。"}], "explanations": {"后台": "正确。演出结束后去后台找人，符合句意。", "考试": "语义：考试是活动，不是可以去找人的地方。", "星期": "配价：“去”后面要接地点，“星期”是时间词，不能作“去”的对象。", "小说": "语义：小说是书籍，不是找人的场所。"}, "sentence_index": 6, "correct_answer": "后台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在医院后台挂了号。", "explanation": "这里应该用〈前台〉。前台指医院对外挂号、办事的地方；后台是剧场舞台后面的空间，不能用来挂号。"}, {"text": "这座后台很高，连演员都爬不上去。", "explanation": "量词错误：“座”用于山、桥、楼等大型固定物，后台是房间式的空间，不能用“座”计量。"}, {"text": "全家人在后台里看电视。", "explanation": "这里应该用〈客厅〉。后台是剧场舞台后面供演员候场的地方，不能用来看电视；看电视应在客厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91299, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出开始前，演员们都在一只后台里等着上台。", "corrected_sentence": "演出开始前，演员们都在后台里等着上台。", "error_description": "错误在“后台”的量词：“只”多用于动物或零散小物，不能修饰地点名词“后台”。应直接说“在后台里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91299, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演出结束后，我后台看看他。", "corrected_sentence": "演出结束后，我去后台看看他。", "error_description": "错误在“后台”前缺少动词“去”。“后台”是处所，要用“去后台”引出动作的地点，不能直接说“我后台……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
