INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91302, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一次又一次地重复。", "primary_collocate": null, "pronunciation": "fǎn fù", "ipa": "fan˨˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "他反复说着同一句话。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题反复出现了好几次。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她反复地问我同样的问题。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师反复讲了三遍，我才明白。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话反复响着，可是没有人接。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他反复想着昨天的事，睡不着。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们反复唱着这首歌。", "target_word": "反复", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我反复看了几次，还是不懂。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个消息反复出现在新闻里。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他反复对自己说：不要怕。", "target_word": "反复", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "反反复复", "label": "重叠"}], "register": "中性", "sense_fingerprint": "同一件事一次又一次地重复出现或进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反复", "is_correct": true, "explanation": "正确答案：反复 fǎnfù，意思是一次又一次地重复。"}, {"text": "繁复", "is_correct": false, "explanation": "fán（第二声）与 fǎn（第三声）声调不同，意思是繁多复杂。"}, {"text": "反腐", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是反对腐败。"}, {"text": "翻覆", "is_correct": false, "explanation": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、倾覆。"}], "explanations": {"反复": "正确答案：反复 fǎnfù，意思是一次又一次地重复。", "繁复": "fán（第二声）与 fǎn（第三声）声调不同，意思是繁多复杂。", "反腐": "fǔ（第三声）与 fù（第四声）声调不同，意思是反对腐败。", "翻覆": "fān（第一声）与 fǎn（第三声）声调不同，意思是翻转、倾覆。"}, "sentence_index": null, "correct_answer": "反复"}, "level_3": {"options": [{"text": "默默", "is_correct": false, "explanation": "语义：“默默”指不出声，与“说着”的出声动作矛盾。"}, {"text": "反复", "is_correct": true, "explanation": "正确：“反复”表示一次又一次地说同一句话，与“同一句话”呼应。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不与表示进行的“说着”搭配。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过等待后达到的结果，与反复重复的意思矛盾。"}], "explanations": {"默默": "语义：“默默”指不出声，与“说着”的出声动作矛盾。", "反复": "正确：“反复”表示一次又一次地说同一句话，与“同一句话”呼应。", "从来": "搭配：“从来”多与否定词连用，不与表示进行的“说着”搭配。", "终于": "语义：“终于”表示经过等待后达到的结果，与反复重复的意思矛盾。"}, "sentence_index": 0, "correct_answer": "反复"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的文件丢了，只好反复写了一遍。", "explanation": "这里应该用〈重新〉。“反复”强调同一动作多次进行，只写一遍要用“重新”。"}, {"text": "他一次就把整本书反复读完了。", "explanation": "这里应该用〈一口气〉。“反复”强调多次重复，“一次就读完整本书”是一次完成的动作，应去掉“反复”。"}, {"text": "他一口气反复喝完了一瓶水。", "explanation": "“一口气喝完”是一次完成的动作，与“反复”表示多次进行矛盾，这里应去掉“反复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91302, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "反复", "is_correct": true, "explanation": "正确答案：反复 fǎnfù，意思是一次又一次地重复。"}, {"text": "凡夫", "is_correct": false, "explanation": "fánfū（第二声、第一声）与 fǎnfù（第三声、第四声）声调不同，意思是平常的人。"}, {"text": "反顾", "is_correct": false, "explanation": "gù（第四声）与 fù（第四声）声母不同，意思是回头看。"}, {"text": "反目", "is_correct": false, "explanation": "mù（第四声）与 fù（第四声）声母不同，意思是彼此翻脸、决裂。"}], "explanations": {"反复": "正确答案：反复 fǎnfù，意思是一次又一次地重复。", "凡夫": "fánfū（第二声、第一声）与 fǎnfù（第三声、第四声）声调不同，意思是平常的人。", "反顾": "gù（第四声）与 fù（第四声）声母不同，意思是回头看。", "反目": "mù（第四声）与 fù（第四声）声母不同，意思是彼此翻脸、决裂。"}, "sentence_index": null, "correct_answer": "反复"}, "level_3": {"options": [{"text": "千万", "is_correct": false, "explanation": "搭配：“千万”用于祈使、叮嘱，不能修饰陈述句中的“唱着”。"}, {"text": "反复", "is_correct": true, "explanation": "正确：“反复”表示一次又一次地唱同一首歌，与句意相符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与表示正在进行的“唱着”矛盾。"}, {"text": "猛然", "is_correct": false, "explanation": "搭配：“猛然”多用于突然发现、想起等，不与持续的“唱着”搭配。"}], "explanations": {"千万": "搭配：“千万”用于祈使、叮嘱，不能修饰陈述句中的“唱着”。", "反复": "正确：“反复”表示一次又一次地唱同一首歌，与句意相符。", "从不": "语义：“从不”表示从来没有，与表示正在进行的“唱着”矛盾。", "猛然": "搭配：“猛然”多用于突然发现、想起等，不与持续的“唱着”搭配。"}, "sentence_index": 6, "correct_answer": "反复"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反复出生在北京。", "explanation": "“出生”只能发生一次，不能用“反复”修饰；“反复”要求同一动作多次进行。"}, {"text": "这是我第一次反复去北京。", "explanation": "“第一次”表示只有一次，与“反复”表示多次重复矛盾，这里应去掉“反复”。"}, {"text": "他一次性把作业反复写完了。", "explanation": "“一次性写完”是一次完成的动作，与“反复”表示多次进行矛盾，这里应去掉“反复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, vali