INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他反复的看了这本书三遍。", "corrected_sentence": "他反复看了这本书三遍。", "error_description": "错误：“的”插在副词“反复”和动词“看了”之间。正确：“反复”直接修饰动词，应说“反复看了”，“的”是定语标记，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
