INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91303, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "剑是又长又尖的东西，两边都能割，是以前的武器。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他手里拿着一把剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "武士拔出了剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剑又长又尖。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上挂着一把剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剑很重。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用剑打败了敌人。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很喜欢电影里的那把剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把剑放在桌子上。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那把剑两边都很锋利。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从腰上拔出了剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "又长又尖、两边锋利的武器，用把来数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91303, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：jiàn 指又长又尖、两边锋利的古代武器。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖（锐利的末端）。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。"}], "explanations": {"剑": "正确：jiàn 指又长又尖、两边锋利的古代武器。", "尖": "jiān（第一声）与 jiàn（第四声）声调不同，意思是尖（锐利的末端）。", "减": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。", "现": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。"}, "sentence_index": null, "correct_answer": "剑"}, "level_3": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：他手里拿着一把剑，「剑」是可以握在手里的兵器。"}, {"text": "胡子", "is_correct": false, "explanation": "语义：胡子长在脸上，不能拿在手里，与「手里拿着」不合。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：「拿着」搭配具体的物件，不说拿着「力气」。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪不是能拿在手里的东西，与「手里拿着」不合。"}], "explanations": {"剑": "正确：他手里拿着一把剑，「剑」是可以握在手里的兵器。", "胡子": "语义：胡子长在脸上，不能拿在手里，与「手里拿着」不合。", "力气": "搭配：「拿着」搭配具体的物件，不说拿着「力气」。", "年纪": "语义：年纪不是能拿在手里的东西，与「手里拿着」不合。"}, "sentence_index": 0, "correct_answer": "剑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用剑写字。", "explanation": "这里应该用〈笔〉。剑是兵器，不能用来写字，写字要用笔。"}, {"text": "他用剑刷牙。", "explanation": "这里应该用〈牙刷〉。剑是兵器，刷牙要用牙刷。"}, {"text": "他手里拿着一本剑。", "explanation": "这里应该用〈把〉。剑用「把」计量，「本」用于书籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91303, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：jiàn 指又长又尖、两边锋利的古代武器。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（-iang 与 -ian），意思是降低。"}, {"text": "坚", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚硬、坚定。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），意思是欠（债）。"}], "explanations": {"剑": "正确：jiàn 指又长又尖、两边锋利的古代武器。", "降": "jiàng 与 jiàn 韵母不同（-iang 与 -ian），意思是降低。", "坚": "jiān（第一声）与 jiàn（第四声）声调不同，意思是坚硬、坚定。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），意思是欠（债）。"}, "sentence_index": null, "correct_answer": "剑"}, "level_3": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：孩子们喜欢电影里的那把剑，「剑」是电影中的兵器。"}, {"text": "头发", "is_correct": false, "explanation": "语义：孩子们喜欢的应是电影里的兵器，不会喜欢「那把头发」。"}, {"text": "灰", "is_correct": false, "explanation": "搭配：「喜欢」搭配的对象一般是值得喜爱的事物，不说喜欢「那把灰」。"}, {"text": "盐", "is_correct": false, "explanation": "语义：盐是调味品，不是电影里让孩子喜欢的东西。"}], "explanations": {"剑": "正确：孩子们喜欢电影里的那把剑，「剑」是电影中的兵器。", "头发": "语义：孩子们喜欢的应是电影里的兵器，不会喜欢「那把头发」。", "灰": "搭配：「喜欢」搭配的对象一般是值得喜爱的事物，不说喜欢「那把灰」。", "盐": "语义：盐是调味品，不是电影里让孩子喜欢的东西。"}, "sentence_index": 6, "correct_answer": "剑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用剑拧螺丝。", "explanation": "这里应该用〈螺丝刀〉。剑是武器，不能用来拧螺丝，拧螺丝要用螺丝刀。"}, {"text": "他用剑盛饭。", "explanation": "这里应该用〈饭勺〉。剑是武器，不能用来盛饭，盛饭要用饭勺。"}, {"text": "他手里拿着一张剑。", "explanation": "这里应该用〈把〉。「张」用于纸张、桌子等平面的东西，剑要用「把」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
