INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91303, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那个剑挂在墙上。", "corrected_sentence": "他把那把剑挂在墙上。", "error_description": "剑的量词应为「把」，不能用「个」，正确说法是「他把那把剑挂在墙上」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
