INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91304, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "古代的兵器，长条形，两边有刃，前端尖。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "古代的将军常带着一把剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剑已经有两千年了。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人把剑挂在腰上。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有一把古代的剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种剑前面很尖，两边有刃。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王送给他一把剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，武士每天都练剑。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝把剑送给了大将军。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那时候的剑是铁做的。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用剑很厉害，没人能赢他。", "target_word": "剑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "劍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "古代的长条形兵器，两边有刃，前端尖", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91304, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：jiàn 指古代的长条形兵器，两边有刃，前端尖。"}, {"text": "肩", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是肩膀。"}, {"text": "减", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。"}, {"text": "捡", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是捡起来。"}], "explanations": {"剑": "正确：jiàn 指古代的长条形兵器，两边有刃，前端尖。", "肩": "jiān（第一声）与 jiàn（第四声）声调不同，意思是肩膀。", "减": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是减少。", "捡": "jiǎn（第三声）与 jiàn（第四声）声调不同，意思是捡起来。"}, "sentence_index": null, "correct_answer": "剑"}, "level_3": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：古代的将军常带着一把剑，「剑」是古代的兵器。"}, {"text": "胡子", "is_correct": false, "explanation": "语义：胡子长在脸上，将军不会带着一把胡子。"}, {"text": "力气", "is_correct": false, "explanation": "搭配：「带着」搭配具体的物件，不说带着「一把力气」。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：年纪不是可以随身携带的东西，与「带着」不合。"}], "explanations": {"剑": "正确：古代的将军常带着一把剑，「剑」是古代的兵器。", "胡子": "语义：胡子长在脸上，将军不会带着一把胡子。", "力气": "搭配：「带着」搭配具体的物件，不说带着「一把力气」。", "年纪": "语义：年纪不是可以随身携带的东西，与「带着」不合。"}, "sentence_index": 0, "correct_answer": "剑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用剑喝汤。", "explanation": "这里应该用〈勺子〉。剑是古代兵器，不能用来喝汤，喝汤要用勺子。"}, {"text": "她用剑梳头。", "explanation": "这里应该用〈梳子〉。剑是兵器，梳头要用梳子。"}, {"text": "他拿着一幅剑。", "explanation": "这里应该用〈把〉。「幅」用于字画，剑要用「把」计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91304, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：jiàn 指古代的长条形兵器，两边有刃，前端尖。"}, {"text": "降", "is_correct": false, "explanation": "jiàng 与 jiàn 韵母不同（-iang 与 -ian），意思是降低。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），意思是欠（债）。"}], "explanations": {"剑": "正确：jiàn 指古代的长条形兵器，两边有刃，前端尖。", "降": "jiàng 与 jiàn 韵母不同（-iang 与 -ian），意思是降低。", "现": "xiàn 与 jiàn 声母不同（x 与 j），意思是现在、出现。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），意思是欠（债）。"}, "sentence_index": null, "correct_answer": "剑"}, "level_3": {"options": [{"text": "剑", "is_correct": true, "explanation": "正确：古时候，武士每天都练剑，「练剑」指练习剑术。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是可以练习的技艺或器具，「练雨」不通。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：「练」不说练「饭」，吃饭不是练习的对象。"}, {"text": "山", "is_correct": false, "explanation": "语义：山不是可以练习的技艺或器具，「练山」不通。"}], "explanations": {"剑": "正确：古时候，武士每天都练剑，「练剑」指练习剑术。", "雨": "语义：雨不是可以练习的技艺或器具，「练雨」不通。", "饭": "搭配：「练」不说练「饭」，吃饭不是练习的对象。", "山": "语义：山不是可以练习的技艺或器具，「练山」不通。"}, "sentence_index": 6, "correct_answer": "剑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用剑写字很快。", "explanation": "这里应该用〈笔〉。剑是兵器，不能用来写字。"}, {"text": "他手里拿着一张剑。", "explanation": "这里应该用〈把〉。「张」用于纸张、桌子等平面的东西，剑要用「把」计量。"}, {"text": "他用剑扫地。", "explanation": "这里应该用〈扫帚〉。剑是兵器，扫地要用扫帚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91304, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个古剑很珍贵。", "corrected_sentence": "这把古剑很珍贵。", "error_description": "剑的量词应为「把」，不能用「个」，正确说法是「这把古剑」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91304, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "武士把一个剑插进剑鞘。", "corrected_sentence": "武士把一把剑插进剑鞘。", "error_description": "剑的量词应为「把」，不能用「个」，正确说法是「武士把一把剑插进剑鞘」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
