INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91306, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "获得奖项或荣誉的人。", "primary_collocate": null, "pronunciation": "dé zhǔ", "ipa": "tɤ˧˥ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "今年的音乐奖得主是一位年轻的女歌手。", "target_word": "得主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位得主在台上说了很多感谢的话。", "target_word": "得主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得主可以得到一万元奖金。", "target_word": "得主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束后，得主拿着奖杯拍了照。", "target_word": "得主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是去年的冠军得主。", "target_word": "得主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次的得主来自南方的一个小城市。", "target_word": "得主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家为新得主送上了热烈的掌声。", "target_word": "得主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节的最佳男演员奖得主是谁？", "target_word": "得主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得主的名字写在红色的卡片上。", "target_word": "得主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位诺贝尔奖得主给学生们讲了一堂课。", "target_word": "得主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "获得奖项或荣誉的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得主", "is_correct": true, "explanation": "正确：「得主」指获得奖项的人，与「是一位年轻的女歌手」相合。"}, {"text": "奖杯", "is_correct": false, "explanation": "语义：「奖杯」是物品，不是人，不能说「是一位年轻的女歌手」。"}, {"text": "身高", "is_correct": false, "explanation": "语义：「身高」是人的身体特征，不是人，不能说「是一位年轻的女歌手」。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：「奖金」是钱，不是人，不能说「是一位年轻的女歌手」。"}], "explanations": {"得主": "正确：「得主」指获得奖项的人，与「是一位年轻的女歌手」相合。", "奖杯": "语义：「奖杯」是物品，不是人，不能说「是一位年轻的女歌手」。", "身高": "语义：「身高」是人的身体特征，不是人，不能说「是一位年轻的女歌手」。", "奖金": "语义：「奖金」是钱，不是人，不能说「是一位年轻的女歌手」。"}, "sentence_index": 0, "correct_answer": "得主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这只小狗的得主。", "explanation": "这里应该用〈主人〉。「得主」指获得奖项的人，不指宠物的主人，应说「主人」。"}, {"text": "这次比赛有五十名得主，他们还在门口排队报名。", "explanation": "这里应该用〈选手〉。「得主」指获奖的人，比赛还没开始、人还在报名时，他们还不是得主，应说「选手」。"}, {"text": "车站里挤满了得主，大家都在等车。", "explanation": "这里应该用〈乘客〉。「得主」指获奖的人，不指等车的人，应说「乘客」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得主", "is_correct": true, "explanation": "正确：「得主」指获奖的人，可以接受「送上掌声」。"}, {"text": "花园", "is_correct": false, "explanation": "语义：「花园」是地方，不是获奖的人，不能接受「送上掌声」。"}, {"text": "天气", "is_correct": false, "explanation": "配价：「送上掌声」的对象应是人或事件，「天气」不能作接受者。"}, {"text": "病历", "is_correct": false, "explanation": "语义：「病历」是医疗记录，不是可以接受掌声的对象。"}], "explanations": {"得主": "正确：「得主」指获奖的人，可以接受「送上掌声」。", "花园": "语义：「花园」是地方，不是获奖的人，不能接受「送上掌声」。", "天气": "配价：「送上掌声」的对象应是人或事件，「天气」不能作接受者。", "病历": "语义：「病历」是医疗记录，不是可以接受掌声的对象。"}, "sentence_index": 6, "correct_answer": "得主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是这家公司的得主，负责决定公司的发展方向。", "explanation": "这里应该用〈老板〉。「得主」指获奖的人，不指公司的负责人；决定公司方向的是老板，不是得主。"}, {"text": "教室里坐满了得主，老师正在讲课。", "explanation": "这里应该用〈学生〉。「得主」指获奖的人，不指在课堂上学习的人，应说「学生」。"}, {"text": "医院里住着很多得主。", "explanation": "这里应该用〈病人〉。「得主」指获奖的人，不指住院的人，应说「病人」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是去年的一只得主。", "corrected_sentence": "他是去年的一位得主。", "error_description": "量词错误：指人的「得主」应该用量词「位」或「名」，不能用「只」（「只」用于动物或器物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她请来了一本诺贝尔奖得主。", "corrected_sentence": "她请来了一位诺贝尔奖得主。", "error_description": "量词错误：「得主」指人，应该用量词「位」或「名」，不能用「本」（「本」用于书本等物品）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
