INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "喜欢同样事情的人。", "primary_collocate": null, "pronunciation": "tóng hào", "ipa": "tʰʊŋ˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "他在俱乐部里找到了同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们是喜欢爬山的同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同好们常常在一起聊电影。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和同好一起做手工。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱养猫的同好都来参加了。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在学校认识一位同好。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的同好很多，都爱打篮球。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同好之间不用多说，就懂对方。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有同好一起学习，我更有信心。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个群里的同好都爱摄影。", "target_word": "同好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "喜欢同一件事的人，一起做这件事的伙伴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外星人", "is_correct": false, "explanation": "语义：俱乐部里找到外星人不符合现实语境，句子的意思无法成立。"}, {"text": "同好", "is_correct": true, "explanation": "正确：“同好”指喜欢同一件事的人，在俱乐部里找到，符合语境。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“周末”是时间，不能被“找到”，与句意不符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“找到”的对象应是人或具体的物，“天气”不能被找到。"}], "explanations": {"外星人": "语义：俱乐部里找到外星人不符合现实语境，句子的意思无法成立。", "同好": "正确：“同好”指喜欢同一件事的人，在俱乐部里找到，符合语境。", "周末": "搭配：“周末”是时间，不能被“找到”，与句意不符。", "天气": "搭配：“找到”的对象应是人或具体的物，“天气”不能被找到。"}, "sentence_index": 0, "correct_answer": "同好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们是同好，都做餐饮生意。", "explanation": "这里应该用〈同行〉。“同好”指爱好相同的人，做同一行业的人应说“同行”。"}, {"text": "两个人是同好，一起偷了店里的东西。", "explanation": "这里应该用〈同伙〉。“同好”指爱好相同的人，不能指一起作案的人。"}, {"text": "这家饭店的同好很有名，每天都有很多客人。", "explanation": "“同好”只能指有相同爱好的人，不能用来指饭店，这里应直接说“饭店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会爱打篮球，与“都爱打篮球”的句意矛盾。"}, {"text": "同好", "is_correct": true, "explanation": "正确：“同好”指喜欢同一件事的人，与“很多，都爱打篮球”相符。"}, {"text": "空调", "is_correct": false, "explanation": "搭配：“空调”不能用“他的……很多”来指人，句子也无法理解为“都爱打篮球”。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎不会爱打篮球，与整句的语境矛盾。"}], "explanations": {"石头": "语义：石头不会爱打篮球，与“都爱打篮球”的句意矛盾。", "同好": "正确：“同好”指喜欢同一件事的人，与“很多，都爱打篮球”相符。", "空调": "搭配：“空调”不能用“他的……很多”来指人，句子也无法理解为“都爱打篮球”。", "轮胎": "语义：轮胎不会爱打篮球，与整句的语境矛盾。"}, "sentence_index": 6, "correct_answer": "同好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两位医生是同好，两人一起偷了病人的药。", "explanation": "这里应该用〈同伙〉。“同好”指爱好相同的人，不能指一起作案的人。"}, {"text": "这次考试的同好都很紧张。", "explanation": "这里应该用〈考生〉。“同好”指爱好相同的人，参加考试的人应说“考生”。"}, {"text": "两国是同好，共同抵抗敌人。", "explanation": "这里应该用〈同盟〉。“同好”指爱好相同的人，共同对敌的国家应说“同盟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "俱乐部里有几只同好在下棋。", "corrected_sentence": "俱乐部里有几位同好在下棋。", "error_description": "错误：量词“只”多用于动物，不能用于人。“同好”指人，应用量词“位”，说“几位同好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91307, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他和几位同好的一起去郊游。", "corrected_sentence": "他和几位同好一起去郊游。", "error_description": "错误：“的”多余。“同好”后面不能加“的”再接“一起”。正确：“他和几位同好一起去郊游”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
