INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把一系列画面连续播放，形成运动效果的影片。", "primary_collocate": null, "pronunciation": "dòng huà", "ipa": "tʊŋ˥˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢看动画。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部动画很有意思。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们每天晚上看动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部动画是用电脑做的。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这部动画只有二十分钟长。", "target_word": "动画", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我和弟弟在家看了一部动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部日本动画的故事很感人。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想学做动画，所以去了北京。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影院正在放一部新动画。", "target_word": "动画", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部动画里的小狗会说话，大家都喜欢它。", "target_word": "动画", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "動畫", "label": "繁体"}, {"form": "动画片", "label": "复合"}, {"form": "动画电影", "label": "复合"}], "register": "中性", "sense_fingerprint": "由连续播放的画面形成运动效果的影片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82430042-cc86-4152-a716-ac186622f809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "搭配：“看”与“声音”不搭配，声音要用“听”。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“看动画”是常见搭配，指观看动画片，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道要用“闻”或“尝”，不能说“看”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，“看空气”说不通。"}], "explanations": {"声音": "搭配：“看”与“声音”不搭配，声音要用“听”。", "动画": "正确：“看动画”是常见搭配，指观看动画片，符合句意。", "味道": "搭配：味道要用“闻”或“尝”，不能说“看”。", "空气": "语义：空气看不见，“看空气”说不通。"}, "sentence_index": 0, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本动画是用纸画的。", "explanation": "这里应该用〈漫画〉。动画是连续播放的影片，不是一本书，应说“漫画”。"}, {"text": "这部动画是演员在舞台上演的。", "explanation": "这里应该用〈话剧〉。动画是画出来的影片，不是舞台上演出的戏，应说“话剧”。"}, {"text": "我买了一把动画。", "explanation": "这里量词应该用〈部〉。动画是影片，“把”用于有柄的器具，影片要用“部”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜没有能让人感动的故事，“这部蔬菜的故事”说不通。"}, {"text": "香水", "is_correct": false, "explanation": "量词：“这部”用于影视、书籍等作品，香水应说“这瓶”，句子不成立。"}, {"text": "动画", "is_correct": true, "explanation": "正确：“这部日本动画”指一部日本动画片，其故事很感人，符合句意。"}, {"text": "船", "is_correct": false, "explanation": "搭配：“这部”用于影视、书籍等作品，船要用“艘”。"}], "explanations": {"蔬菜": "语义：蔬菜没有能让人感动的故事，“这部蔬菜的故事”说不通。", "香水": "量词：“这部”用于影视、书籍等作品，香水应说“这瓶”，句子不成立。", "动画": "正确：“这部日本动画”指一部日本动画片，其故事很感人，符合句意。", "船": "搭配：“这部”用于影视、书籍等作品，船要用“艘”。"}, "sentence_index": 6, "correct_answer": "动画"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段动画很好喝。", "explanation": "这里应该用〈饮料〉。“好喝”形容饮品，动画是影片，不能说“好喝”。"}, {"text": "这部动画的关卡很难。", "explanation": "这里应该用〈游戏〉。关卡是游戏的组成部分，动画是影片，没有关卡。"}, {"text": "这段动画读起来很美。", "explanation": "这里应该用〈诗歌〉。“读”针对文字，动画是影片，不能说“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师带我们班看了一条动画。", "corrected_sentence": "老师带我们班看了一部动画。", "error_description": "量词错误：“动画”是影片，应用“部”，“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们喜欢那部很新动画。", "corrected_sentence": "孩子们喜欢那部新动画。", "error_description": "程度词错误：“很”不能直接修饰名词前的形容词定语，应说“新动画”，删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '329c3694-5d44-4224-a3c5-49edf76ba398') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
