INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91312, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "内心思想感情变化的过程。", "primary_collocate": null, "pronunciation": "xīn lù", "ipa": "ɕin˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影讲的是一位母亲的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在书里写了自己长大的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从失败到成功，他有一段难忘的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在文章里说出了当年的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本日记记录了我的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读他的日记，就能看到他的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位运动员谈了比赛前后的心路。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的心路很曲折，我们都没想到。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问他退休前的心路是怎样的。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说把主人公的心路写得很真实。", "target_word": "心路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "段", "label": "量词"}, {"form": "心路历程", "label": "复合"}], "register": "书面", "sense_fingerprint": "内心思想感情变化的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c42a730-6bf6-4d81-87f8-76c0aa20b02b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91312, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "心路", "is_correct": true, "explanation": "心路指内心思想感情变化的过程，是本词的正确读音与意思。"}, {"text": "心理", "is_correct": false, "explanation": "lǐ（第三声）与 lù（第四声）声调和韵母都不同，意思是心理，不是心路。"}, {"text": "心力", "is_correct": false, "explanation": "lì（第四声）与 lù（第四声）韵母不同（i 与 u），意思是精神力量，不是心路。"}, {"text": "心律", "is_correct": false, "explanation": "lǜ 与 lù 韵母不同（ü 与 u），意思是心跳节律，不是心路。"}], "explanations": {"心路": "心路指内心思想感情变化的过程，是本词的正确读音与意思。", "心理": "lǐ（第三声）与 lù（第四声）声调和韵母都不同，意思是心理，不是心路。", "心力": "lì（第四声）与 lù（第四声）韵母不同（i 与 u），意思是精神力量，不是心路。", "心律": "lǜ 与 lù 韵母不同（ü 与 u），意思是心跳节律，不是心路。"}, "sentence_index": null, "correct_answer": "心路"}, "level_3": {"options": [{"text": "心路", "is_correct": true, "explanation": "心路指内心思想感情变化的过程，符合电影讲述的内容。"}, {"text": "票价", "is_correct": false, "explanation": "语义：票价是买票的钱，不是电影讲述的内容，句意不通。"}, {"text": "尺码", "is_correct": false, "explanation": "语义：尺码是衣物大小，与电影讲述的人物经历无关。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重属于身体特征，不是电影讲述的内心历程。"}], "explanations": {"心路": "心路指内心思想感情变化的过程，符合电影讲述的内容。", "票价": "语义：票价是买票的钱，不是电影讲述的内容，句意不通。", "尺码": "语义：尺码是衣物大小，与电影讲述的人物经历无关。", "体重": "体貌：体重属于身体特征，不是电影讲述的内心历程。"}, "sentence_index": 0, "correct_answer": "心路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对这件事的心路很明确。", "explanation": "这里应该用〈观点〉。心路指思想感情变化的过程，不能用“明确”来形容，观点才能明确。"}, {"text": "他把书架搬到了心路。", "explanation": "这里把心路当成了〈房间〉一类的地点。心路指思想感情变化的过程，不是可以搬东西去的地方，书架应搬到〈房间〉里。"}, {"text": "我每天用心路刷牙。", "explanation": "这里把心路当成了〈牙刷〉一类的工具。心路指思想感情变化的过程，不能用来刷牙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91312, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心路", "is_correct": true, "explanation": "心路指思想感情变化的过程，可以“谈”，符合句意。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，与比赛无关，不是运动员谈的内容。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱是做菜的方法，与运动员谈比赛的内容不符。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“谈”一般说谈感受、经验，不说谈脚步。"}], "explanations": {"心路": "心路指思想感情变化的过程，可以“谈”，符合句意。", "乐谱": "语义：乐谱是记录音乐的符号，与比赛无关，不是运动员谈的内容。", "菜谱": "语义：菜谱是做菜的方法，与运动员谈比赛的内容不符。", "脚步": "搭配：“谈”一般说谈感受、经验，不说谈脚步。"}, "sentence_index": 6, "correct_answer": "心路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本小说的心路很高大。", "explanation": "这里把心路当成了〈体积〉一类的有形之物。心路指思想感情变化的过程，不能说它高大。"}, {"text": "这台机器的心路很复杂。", "explanation": "这里把心路用来描述〈构造〉。心路指人的思想感情变化过程，不能用来说机器的复杂结构。"}, {"text": "他的心路跳得很快。", "explanation": "这里把心路当成了〈心跳〉。心路指思想感情变化的过程，心脏的跳动应说〈心跳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91312, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把心路写很真实。", "corrected_sentence": "她把心路写得很真实。", "error_description": "状态补语漏用「得」：动词“写”后接状态补语“很真实”要加「得」，应说“写得很真实”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91312, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书记录了一段很长心路。", "corrected_sentence": "这本书记录了一段很长的心路。", "error_description": "“的”字漏用：形容词“很长”修饰名词“心路”时要加「的」，应说“很长的心路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '370d06a3-95d1-4628-a54b-8a6c8aebfa9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
