INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说“不是”，说“不对”。", "primary_collocate": null, "pronunciation": "fǒu dìng", "ipa": "foʊ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师否定了他的答案。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问他是不是病了，他马上否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她摇摇头，否定了我的话。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连连摆手，否定了我的推测。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到问题，他想也不想就否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问她是不是生气了，她笑着否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着否定了这个说法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问他是不是在骗人，他连忙否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人问他是不是班长，他否定了。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听完我的话，没有否定，只是笑着点头。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否定了", "label": "体标"}, {"form": "否定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "开口回答说不是、不对，当面表示不同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示老师认为答案不对，说“不是”，与句意相符。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”不能与“答案”搭配，“坐了他的答案”不成立。"}, {"text": "感动", "is_correct": false, "explanation": "配价：“感动”的宾语要是人，不能用“答案”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能接“答案”作宾语，“喝了他的答案”不通。"}], "explanations": {"否定": "否定：表示老师认为答案不对，说“不是”，与句意相符。", "坐": "搭配：“坐”不能与“答案”搭配，“坐了他的答案”不成立。", "感动": "配价：“感动”的宾语要是人，不能用“答案”作宾语。", "喝": "搭配：“喝”不能接“答案”作宾语，“喝了他的答案”不通。"}, "sentence_index": 0, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他否定地答应了朋友的邀请，说周末一定到。", "explanation": "否定与答应矛盾，这里应该用〈欣然〉。"}, {"text": "他否定了我的椅子，坐了上去。", "explanation": "否定针对说法、问题，不能对椅子用，这里应该用〈占〉。"}, {"text": "他否定地点了点头。", "explanation": "这里的“否定”表示说“不对”，与“点了点头”表示同意相矛盾，应改用〈摇了摇头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不认同这个说法，符合句意。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”的对象通常是人或帮助，不能说“感激这个说法”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”通常与歌曲搭配，不能说“唱这个说法”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“说法”作宾语，“吃了这个说法”不通。"}], "explanations": {"否定": "否定：表示不认同这个说法，符合句意。", "感激": "配价：“感激”的对象通常是人或帮助，不能说“感激这个说法”。", "唱": "搭配：“唱”通常与歌曲搭配，不能说“唱这个说法”。", "吃": "搭配：“吃”不能接“说法”作宾语，“吃了这个说法”不通。"}, "sentence_index": 6, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他否定了我送的那束花。", "explanation": "这里应该用〈婉拒〉。否定用于观点、说法，拒绝实物礼物要用婉拒。"}, {"text": "他否定了今天下午的会议。", "explanation": "这里应该用〈取消〉。否定用于观点、说法的不对，会议要取消，不能说否定。"}, {"text": "他否定地笑了笑，说：好的。", "explanation": "否定地修饰“笑”，又说“好的”，表示同意，前后矛盾，这里不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师否定得他的作文。", "corrected_sentence": "老师否定了他的作文。", "error_description": "错误：“否定”后面用了“得”，应改为“了”。正确：“否定了”表示动作已完成，“得”是补语标记，不能接在动词后直接带宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91313, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有否定了我的建议。", "corrected_sentence": "他没有否定过我的建议。", "error_description": "错误：“没有”否定经历时，“否定”后应用“过”，不能用“了”。正确：“没有否定过”，“了”不能与“没有”连用表示未发生的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：与“否定”没有反义关系，指到外地游览。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：与“否定”没有反义关系，指把物品保存起来。"}, {"text": "搜索", "is_correct": false, "explanation": "搜索：与“否定”没有反义关系，指到处寻找。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。", "旅行": "旅行：与“否定”没有反义关系，指到外地游览。", "收藏": "收藏：与“否定”没有反义关系，指把物品保存起来。", "搜索": "搜索：与“否定”没有反义关系，指到处寻找。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "肯定", "is_correct": true, "explanation": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。"}, {"text": "收拾", "is_correct": false, "explanation": "收拾：与“否定”没有反义关系，指整理、料理。"}, {"text": "漫步", "is_correct": false, "explanation": "漫步：与“否定”没有反义关系，指慢慢地散步。"}, {"text": "修补", "is_correct": false, "explanation": "修补：与“否定”没有反义关系，指修理破损的地方。"}], "correct_answer": "肯定", "explanations": {"肯定": "肯定：与“否定”相对，表示认为对、予以承认，是词典所列的反义词。", "收拾": "收拾：与“否定”没有反义关系，指整理、料理。", "漫步": "漫步：与“否定”没有反义关系，指慢慢地散步。", "修补": "修补：与“否定”没有反义关系，指修理破损的地方。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "不承认事物存在或不赞成；与“肯定”相对。", "primary_collocate": null, "pronunciation": "fǒu dìng", "ipa": "foʊ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们不能否定他的努力。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他否定了这个计划。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人否定这个办法的作用。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要因为一次错误就否定自己。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生否定了这种说法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的结果否定了他们的看法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都肯定他的做法，没人否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她否定了过去的生活方式。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能完全否定这个方法。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩，没有人能否定。", "target_word": "否定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "否定了", "label": "体标"}, {"form": "否定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "不承认某事物存在或价值，不赞成，与肯定相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不承认努力的价值，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“努力”搭配，“吃他的努力”不成立。"}, {"text": "感动", "is_correct": false, "explanation": "配价：“感动”的宾语要是人，“努力”不能作宾语。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”可接“困难”等，不能说“制造他的努力”。"}], "explanations": {"否定": "否定：表示不承认努力的价值，符合句意。", "吃": "搭配：“吃”不能与“努力”搭配，“吃他的努力”不成立。", "感动": "配价：“感动”的宾语要是人，“努力”不能作宾语。", "制造": "搭配：“制造”可接“困难”等，不能说“制造他的努力”。"}, "sentence_index": 0, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她否定了我送给她的花。", "explanation": "这里应该用〈婉拒〉。否定指否认观点或价值，花是实物，要用婉拒。"}, {"text": "她听到这个消息，否定地跳了起来。", "explanation": "否定不能修饰“跳”这样的动作，这里应该用〈激动〉。"}, {"text": "大家都否定他的努力，纷纷表示赞同。", "explanation": "这里应该用〈肯定〉。否定表示不承认价值，与“纷纷表示赞同”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "否定", "is_correct": true, "explanation": "否定：表示不认同，与前句“肯定”形成对照，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”与“肯定他的做法”的语境无关，句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“肯定”的对比无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与前句“肯定他的做法”形成的对比无关，句意不通。"}], "explanations": {"否定": "否定：表示不认同，与前句“肯定”形成对照，符合句意。", "哭": "语义：“哭”与“肯定他的做法”的语境无关，句意不通。", "睡": "语义：“睡”与“肯定”的对比无关，句意不通。", "游泳": "语义：“游泳”与前句“肯定他的做法”形成的对比无关，句意不通。"}, "sentence_index": 6, "correct_answer": "否定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他否定了昨天的天气。", "explanation": "这里应该用〈讨论〉。否定针对观点、价值的不承认，天气是现象，不能否定。"}, {"text": "这把椅子否定了我的请求。", "explanation": "否定的动作要由人来做，椅子不能否定请求，这里应该用〈拒绝〉。"}, {"text": "这盆花很漂亮，她否定地看了又看。", "explanation": "否定不能修饰“看”，这里应该用〈仔细〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不能了否定你的想法。", "corrected_sentence": "我们不能否定你的想法。", "error_description": "“了”不能插在“不能”与“否定”之间，应写作“不能否定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91314, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他否定了掉我的计划。", "corrected_sentence": "他否定掉了我的计划。", "error_description": "“掉”是结果补语，应紧跟动词，写作“否定掉了”，“了”不能放在“掉”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
