INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91315, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国际社会是世界上所有国家和国家里的人。", "primary_collocate": null, "pronunciation": "guó jì shè huì", "ipa": "kwo˧˥ tɕi˥˩ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 4, "sentences": [{"text": "国际社会里的每个国家都有责任。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法得不到国际社会的支持。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会的人们都在关心这场地震。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的故事感动了整个国际社会。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会要保护地球，大家都有责任。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解国际社会是怎么看这件事的。", "target_word": "国际社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛让国际社会认识了这个小国。", "target_word": "国际社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际社会的力量比一个国家大得多。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只有国际社会合作，才能解决气候问题。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会越来越重视环境保护。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "国际社会：世界上所有国家和其中的人们，指全世界的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91315, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际社会", "is_correct": true, "explanation": "国际社会指世界上所有国家的整体，包含“每个国家”，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校里不会有“每个国家”，句意不通。"}, {"text": "公司", "is_correct": false, "explanation": "语义：公司里不存在“每个国家”，句意不通。"}, {"text": "省份", "is_correct": false, "explanation": "搭配：省份属于一国之内的行政区，不能包含“每个国家”。"}], "explanations": {"国际社会": "国际社会指世界上所有国家的整体，包含“每个国家”，符合句意。", "学校": "语义：学校里不会有“每个国家”，句意不通。", "公司": "语义：公司里不存在“每个国家”，句意不通。", "省份": "搭配：省份属于一国之内的行政区，不能包含“每个国家”。"}, "sentence_index": 0, "correct_answer": "国际社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们去国际社会吃饭。", "explanation": "这里应该用〈餐厅〉。“国际社会”是世界各国的整体，不是可以前往的场所。"}, {"text": "这次国际社会有十支队伍参加比赛。", "explanation": "这里应该用〈国际比赛〉。“国际社会”是各国与国际组织的整体，不能像比赛一样有参赛队伍。"}, {"text": "这座城市的国际社会交通很方便。", "explanation": "这里应该用〈城区〉。“国际社会”不是地理范围，不能用来描述某座城市的交通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91315, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际社会", "is_correct": true, "explanation": "国际社会作为“认识”的主体，与“让……认识了这个小国”的句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能“认识”任何国家，句意不通。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水没有认识能力，句意不通。"}, {"text": "这个小国", "is_correct": false, "explanation": "语义：句中“认识了这个小国”已说明对象是这个小国，若再作主语则自己认识自己，句意矛盾。"}], "explanations": {"国际社会": "国际社会作为“认识”的主体，与“让……认识了这个小国”的句意相符。", "桌子": "语义：桌子是家具，不能“认识”任何国家，句意不通。", "雨水": "语义：雨水没有认识能力，句意不通。", "这个小国": "语义：句中“认识了这个小国”已说明对象是这个小国，若再作主语则自己认识自己，句意矛盾。"}, "sentence_index": 6, "correct_answer": "国际社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家国际社会的员工很努力。", "explanation": "这里应该用〈公司〉。“国际社会”不是有员工的企业，不能指公司。"}, {"text": "我们每天去国际社会上课。", "explanation": "这里应该用〈学校〉。“国际社会”是世界各国的整体，不是可以去上课的场所。"}, {"text": "假期我们准备去国际社会旅游。", "explanation": "这里应该用〈国外〉。“国际社会”是世界各国的整体，不是可以前往旅游的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91315, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国际社会们需要共同保护地球。", "corrected_sentence": "国际社会需要共同保护地球。", "error_description": "错误：“国际社会”指世界上所有国家的整体，是集合名词，不能加“们”。正确说法是“国际社会需要共同保护地球”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91315, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一个国际社会越来越关注这个小国的发展。", "corrected_sentence": "国际社会越来越关注这个小国的发展。", "error_description": "错误：“国际社会”是整体概念，前面不宜加“一个”这样的量词修饰。正确说法是“国际社会越来越关注这个小国的发展”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
