INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91316, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世界各国及国际组织组成的整体。", "primary_collocate": null, "pronunciation": "guó jì shè huì", "ipa": "kwo˧˥ tɕi˥˩ ʂɤ˥˩ xweɪ˥˩", "syllable_count": 4, "sentences": [{"text": "国际社会都希望世界和平。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国是国际社会的重要一员。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会应该一起帮助受灾的国家。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多国家向国际社会求助。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会对这件事十分关注。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会正在努力减少污染。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的行为受到了国际社会的批评。", "target_word": "国际社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国代表着整个国际社会的声音。", "target_word": "国际社会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对疫情，国际社会需要互相帮助。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国际社会欢迎两国签订和平协议。", "target_word": "国际社会", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "国际社会：世界各国及国际组织组成的整体，常作为呼吁、批评、支持的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际社会", "is_correct": true, "explanation": "国际社会指世界各国及国际组织组成的整体，能够“希望世界和平”，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意愿，不能“希望”世界和平。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌是家具，不能“希望”什么，句意不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是器物，没有意愿，不能“希望”世界和平。"}], "explanations": {"国际社会": "国际社会指世界各国及国际组织组成的整体，能够“希望世界和平”，符合句意。", "石头": "语义：石头没有意愿，不能“希望”世界和平。", "课桌": "语义：课桌是家具，不能“希望”什么，句意不通。", "雨伞": "语义：雨伞是器物，没有意愿，不能“希望”世界和平。"}, "sentence_index": 0, "correct_answer": "国际社会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "联合国是一个重要的国际社会，负责处理全球问题。", "explanation": "这里应该用〈国际组织〉。联合国是具体机构；“国际社会”指各国和国际组织组成的整体，不能用来指某一个机构。"}, {"text": "他毕业后去国际社会留学，学习了两年。", "explanation": "这里应该用〈外国〉。“留学”要前往具体的国家或地区，国际社会不是可以前往的地方。"}, {"text": "这次国际社会在跑步比赛中得了第一。", "explanation": "这里应该用〈某国选手〉。“国际社会”是各国与国际组织的整体，不能参赛获奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际社会", "is_correct": true, "explanation": "国际社会作为批评的主体，符合“这个国家的行为受到了……的批评”的句意。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水不会批评人，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“受到批评”的施事通常是人或机构，“天气”不能与之搭配。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包没有判断能力，不能批评任何人。"}], "explanations": {"国际社会": "国际社会作为批评的主体，符合“这个国家的行为受到了……的批评”的句意。", "雨水": "语义：雨水不会批评人，句意不通。", "天气": "搭配：“受到批评”的施事通常是人或机构，“天气”不能与之搭配。", "书包": "语义：书包没有判断能力，不能批评任何人。"}, "sentence_index": 6, "correct_answer": "国际社会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天坐地铁去国际社会上班。", "explanation": "这里应该用〈公司〉。“国际社会”是世界各国的整体，不是可以去上班的单位。"}, {"text": "国际社会今天参加了期末考试。", "explanation": "这里应该用〈学生〉。“国际社会”是各国与国际组织的整体，不能参加考试。"}, {"text": "国际社会住在我家楼下，每天和我打招呼。", "explanation": "这里应该用〈邻居〉。“国际社会”是各国与国际组织的整体，不能住在楼下、打招呼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国际社会们一直在关注这场冲突。", "corrected_sentence": "国际社会一直在关注这场冲突。", "error_description": "错误：“国际社会”是集合名词，表示整体，不能加“们”。正确说法是“国际社会一直在关注这场冲突”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个国际社会一直呼吁两国停火。", "corrected_sentence": "国际社会一直呼吁两国停火。", "error_description": "错误：“国际社会”是单一的整体概念，不能用“两个”计数。正确说法是“国际社会一直呼吁两国停火”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
