INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91317, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快转是让录像或声音很快地向前播放。", "primary_collocate": null, "pronunciation": "kuài zhuǎn", "ipa": "kʰuai̯˥˩ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师让我们把录像快转一下。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话没用，快转吧。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音太长了，我快转着听。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电视剧快转了两分钟。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频一开始很无聊，我就快转。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你快转到第十分钟。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想听这一段，快转过去吧。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看一边快转，没有看清楚。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录像带可以快转，也可以倒回去。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快转以后，声音变得很尖。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快转了", "label": "体标"}, {"form": "快转过", "label": "体标"}, {"form": "快轉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让录像或声音加速向前播放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91317, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快转", "is_correct": true, "explanation": "快转：让录像很快地往后走，与「一下」搭配，表示快速跳过一段。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：「冷冻」是降低温度使其凝固，与播放录像无关。"}, {"text": "夸大", "is_correct": false, "explanation": "搭配：「夸大」用于言论或事实，不能接「把录像」。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：「烘干」是把湿的东西弄干，与录像的播放无关。"}], "explanations": {"快转": "快转：让录像很快地往后走，与「一下」搭配，表示快速跳过一段。", "冷冻": "语义：「冷冻」是降低温度使其凝固，与播放录像无关。", "夸大": "搭配：「夸大」用于言论或事实，不能接「把录像」。", "烘干": "语义：「烘干」是把湿的东西弄干，与录像的播放无关。"}, "sentence_index": 0, "correct_answer": "快转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想把电视剧快转回去，再看一遍开头。", "explanation": "这里应该用〈倒带〉。快转是让录像快速往后推进，回看开头要用倒带。"}, {"text": "他把这篇文章快转了，很快就读完了。", "explanation": "快转只指让录像或声音加速前进，这里用在文章上，表示快速浏览，不是快转的意思。"}, {"text": "他用力快转门把手，门一下子就开了。", "explanation": "“快转”只指让录像或声音加速前进，这里是快速转动门把手，不是快转的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91317, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快转", "is_correct": true, "explanation": "快转：让录音很快地往后走，跳过不想听的一段。"}, {"text": "倒带", "is_correct": false, "explanation": "语义：「倒带」是往回走，与「快转过去」向前跳过的意思相反。"}, {"text": "收听", "is_correct": false, "explanation": "语义：「收听」是听，与「不想听」直接矛盾，不能表示跳过。"}, {"text": "录制", "is_correct": false, "explanation": "搭配：「录制」要接被记录的内容，不能接「过去」表示跳过。"}], "explanations": {"快转": "快转：让录音很快地往后走，跳过不想听的一段。", "倒带": "语义：「倒带」是往回走，与「快转过去」向前跳过的意思相反。", "收听": "语义：「收听」是听，与「不想听」直接矛盾，不能表示跳过。", "录制": "搭配：「录制」要接被记录的内容，不能接「过去」表示跳过。"}, "sentence_index": 6, "correct_answer": "快转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑步时按了快转，很快就跑到了终点。", "explanation": "快转只指让录像或声音加速前进，这里用在跑步上，表示加快速度，不是快转的意思。"}, {"text": "我把照片快转了，看得很清楚。", "explanation": "快转只指让录像或声音加速前进，这里用在照片上，表示快速翻看，不是快转的意思。"}, {"text": "他的成绩快转了，比上次高了很多。", "explanation": "快转只指让录像或声音加速前进，这里用在成绩上，表示成绩快速变化，不是快转的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91317, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把录像快转在结尾了。", "corrected_sentence": "他把录像快转到结尾了。", "error_description": "补语错误：表示动作到达某处，应用介词“到”，不能用“在”。“快转”后接地点应说“快转到结尾了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91317, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一边听一边快转在结尾。", "corrected_sentence": "他一边听一边快转到结尾。", "error_description": "补语错误：表示到达要用「到」，不能用「在」，应说「快转到结尾」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
