INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91318, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使影像或录音加速向前播放。", "primary_collocate": null, "pronunciation": "kuài zhuǎn", "ipa": "kʰuai̯˥˩ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这段广告太长，我把它快转了。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影太慢了，你可以快转一下。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看比赛时，常常快转无聊的部分。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌的前面太长，快转到后面吧。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段录音没什么内容，我们快转过去吧。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按遥控器让视频快转。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "录音开头没有声音，我就快转了。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈看电视剧时不喜欢快转。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "视频里有广告，请先快转吧。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按了快转，想看后面的内容。", "target_word": "快转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "快转了", "label": "体标"}, {"form": "快转过", "label": "体标"}, {"form": "快轉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让影像或录音加速向前播放", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快转", "is_correct": true, "explanation": "快转：让广告加速向前播放，跳过太长的部分，与「我把它……了」的语境相合。"}, {"text": "延长", "is_correct": false, "explanation": "语义：「延长」是把时间加长，与「太长」要跳过的语境相反。"}, {"text": "放大", "is_correct": false, "explanation": "搭配：「放大」用于画面或声音的大小，不能用来说广告的时长。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：「烘干」是把湿的东西弄干，与广告的播放无关。"}], "explanations": {"快转": "快转：让广告加速向前播放，跳过太长的部分，与「我把它……了」的语境相合。", "延长": "语义：「延长」是把时间加长，与「太长」要跳过的语境相反。", "放大": "搭配：「放大」用于画面或声音的大小，不能用来说广告的时长。", "烘干": "语义：「烘干」是把湿的东西弄干，与广告的播放无关。"}, "sentence_index": 0, "correct_answer": "快转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个视频太长了，我想把它快转回去，再看一遍开头。", "explanation": "这里应该用〈倒带〉。快转是向前加速播放，回看开头要用倒带。"}, {"text": "这本书太厚了，我想快转看完它。", "explanation": "快转只指加速播放影像或录音，这里用在书上，表示快速浏览，不是快转的意思。"}, {"text": "他用力快转水龙头，水很快就流了出来。", "explanation": "“快转”只指加速向前播放影像或录音，这里是快速拧转水龙头，不是快转的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快转", "is_correct": true, "explanation": "快转：让录音加速向前播放，跳过没有内容的开头，与「没有声音」相合。"}, {"text": "锁定", "is_correct": false, "explanation": "语义：「锁定」是固定不动，与录音开头没有声音、要跳过的语境不合。"}, {"text": "叠加", "is_correct": false, "explanation": "搭配：「叠加」要求两个或多个对象，不能用于录音的播放。"}, {"text": "打印", "is_correct": false, "explanation": "语义：「打印」是把内容印在纸上，与播放录音无关。"}], "explanations": {"快转": "快转：让录音加速向前播放，跳过没有内容的开头，与「没有声音」相合。", "锁定": "语义：「锁定」是固定不动，与录音开头没有声音、要跳过的语境不合。", "叠加": "搭配：「叠加」要求两个或多个对象，不能用于录音的播放。", "打印": "语义：「打印」是把内容印在纸上，与播放录音无关。"}, "sentence_index": 6, "correct_answer": "快转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按了快转，想看前面的内容。", "explanation": "这里应该用〈快退〉。快转是向前加速播放，回看前面要用快退。"}, {"text": "我想快转这顿饭，早点吃完。", "explanation": "快转只指加速播放影像或录音，这里用在吃饭上，表示加快进度，不是快转的意思。"}, {"text": "他骑车时按了快转，车子很快就到了学校。", "explanation": "快转只指加速播放影像或录音，这里用在骑车上，表示加快速度，不是快转的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段广告太长，我把它快转下来了。", "corrected_sentence": "这段广告太长，我把它快转过去了。", "error_description": "补语错误：「快转」后接「下来」不对，影像加速向前跳过应说「快转过去」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把录音快转在后面吧。", "corrected_sentence": "我把录音快转到后面吧。", "error_description": "补语错误：表示动作到达某处，应用介词“到”，不能用“在”。“快转”后应接“到后面”，应说“快转到后面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
