INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91319, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "吃东西时，舌头尝到的感觉。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "weɪ˥˩", "syllable_count": 1, "sentences": [{"text": "这个汤的味很淡。", "target_word": "味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "菜里没放盐，没有味。", "target_word": "味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你尝一下，看看味怎么样。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我感冒了，吃什么都没有味。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜的味太咸了。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶做的鱼，味特别好。", "target_word": "味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她只喜欢吃味重的东西。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这碗面的味有点儿怪，我不想吃了。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的地方，同一个菜的味也不一样。", "target_word": "味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子不爱吃味苦的药。", "target_word": "味", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "吃东西时舌头尝到的感觉，如咸、淡、苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91319, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "味", "is_correct": true, "explanation": "味（wèi）指舌头尝到的感觉，是正确答案。"}, {"text": "围", "is_correct": false, "explanation": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。"}, {"text": "威", "is_correct": false, "explanation": "威（wēi）与味（wèi）声调不同（第一声与第四声），意思是威力。"}, {"text": "尾", "is_correct": false, "explanation": "尾（wěi）与味（wèi）声调不同（第三声与第四声），意思是尾巴。"}, {"text": "问", "is_correct": false, "explanation": "问（wèn）与味（wèi）韵母不同（en 与 ei），意思是询问。"}, {"text": "被", "is_correct": false, "explanation": "被（bèi）与味（wèi）声母不同（b 与 w），意思是被动。"}], "explanations": {"味": "味（wèi）指舌头尝到的感觉，是正确答案。", "围": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。", "威": "威（wēi）与味（wèi）声调不同（第一声与第四声），意思是威力。", "尾": "尾（wěi）与味（wèi）声调不同（第三声与第四声），意思是尾巴。", "问": "问（wèn）与味（wèi）韵母不同（en 与 ei），意思是询问。", "被": "被（bèi）与味（wèi）声母不同（b 与 w），意思是被动。"}, "sentence_index": null, "correct_answer": "味"}, "level_3": {"options": [{"text": "味", "is_correct": true, "explanation": "味：指舌头尝到的感觉，“味很淡”搭配自然，正确。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“淡”可以形容味道，不能形容温度，“温度很淡”不成立。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“很淡”不能修饰重量，“重量很淡”不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是吃汤时尝到的感觉，与“这个汤的”后面的描述不合。"}], "explanations": {"味": "味：指舌头尝到的感觉，“味很淡”搭配自然，正确。", "温度": "搭配：“淡”可以形容味道，不能形容温度，“温度很淡”不成立。", "重量": "搭配：“很淡”不能修饰重量，“重量很淡”不通。", "时间": "语义：“时间”不是吃汤时尝到的感觉，与“这个汤的”后面的描述不合。"}, "sentence_index": 0, "correct_answer": "味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤有一只很淡的味。", "explanation": "这里应该用〈种〉。“只”用于动物或成对的东西，“味”要用“种”来计量。"}, {"text": "这个面包的味很软。", "explanation": "这里应该用〈口感〉。“软”形容口感，“味”指咸、甜、酸等味觉，不能说味道软。"}, {"text": "这句话的味很深，值得慢慢想。", "explanation": "这里应该用〈意味〉。“味”指舌头尝到的感觉，不表示话语的含义，应说“意味”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91319, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "味", "is_correct": true, "explanation": "味（wèi）指舌头尝到的感觉，是正确答案。"}, {"text": "费", "is_correct": false, "explanation": "费（fèi）与味（wèi）声母不同（f 与 w），意思是花费。"}, {"text": "围", "is_correct": false, "explanation": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。"}, {"text": "伟", "is_correct": false, "explanation": "伟（wěi）与味（wèi）声调不同（第三声与第四声），意思是伟大。"}, {"text": "备", "is_correct": false, "explanation": "备（bèi）与味（wèi）声母不同（b 与 w），意思是准备。"}, {"text": "倍", "is_correct": false, "explanation": "倍（bèi）与味（wèi）声母不同（b 与 w），意思是倍数。"}], "explanations": {"味": "味（wèi）指舌头尝到的感觉，是正确答案。", "费": "费（fèi）与味（wèi）声母不同（f 与 w），意思是花费。", "围": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。", "伟": "伟（wěi）与味（wèi）声调不同（第三声与第四声），意思是伟大。", "备": "备（bèi）与味（wèi）声母不同（b 与 w），意思是准备。", "倍": "倍（bèi）与味（wèi）声母不同（b 与 w），意思是倍数。"}, "sentence_index": null, "correct_answer": "味"}, "level_3": {"options": [{"text": "味", "is_correct": true, "explanation": "味：指味道的浓淡，“味重”指味道浓，正确。"}, {"text": "色", "is_correct": false, "explanation": "语义：“色”指颜色，与“吃”的对象不合，“吃色重的东西”不通。"}, {"text": "体积", "is_correct": false, "explanation": "语义：“体积”指物体大小，与“吃”的东西和口感无关。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“手重”形容下手用力，不能用来修饰“东西”。"}], "explanations": {"味": "味：指味道的浓淡，“味重”指味道浓，正确。", "色": "语义：“色”指颜色，与“吃”的对象不合，“吃色重的东西”不通。", "体积": "语义：“体积”指物体大小，与“吃”的东西和口感无关。", "手": "搭配：“手重”形容下手用力，不能用来修饰“东西”。"}, "sentence_index": 6, "correct_answer": "味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的味很亮，我一口都舍不得吃。", "explanation": "这里应该用〈鲜〉。“亮”形容光线或颜色，不能形容味道；形容味道的好坏应说“鲜”。"}, {"text": "他尝到了一条咸的味。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不用于味道；“味”应使用量词“种”。"}, {"text": "他把这碗汤的味端起来喝了。", "explanation": "这里应该用〈汤〉。“味”是感觉，不能被端起来或喝下去；应说“把这碗汤端起来喝了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91319, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道菜有一只特别的味。", "corrected_sentence": "这道菜有一种特别的味。", "error_description": "错误形式是“一只味”，正确形式是“一种味”。“只”用于动物或成对的东西，“味”应使用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91319, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他尝出了这碗汤的一张味。", "corrected_sentence": "他尝出了这碗汤的一种味。", "error_description": "错误是“一张味”，正确是“一种味”。“张”用于纸、桌子等平面的东西，不能用于味道；“味”应使用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
