INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91320, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "味道；舌头尝到或鼻子闻到的感觉。", "primary_collocate": null, "pronunciation": "wèi", "ipa": "weɪ˥˩", "syllable_count": 1, "sentences": [{"text": "厨房里有一股烧焦的味。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋里有股很浓的味，我想开窗。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种花没有什么味。", "target_word": "味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我闻到了一股鱼的味。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾桶有味，快拿出去。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他身上有一股汗的味。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后的空气里有泥土的味。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "药的味很苦，我不想喝。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间有味，你闻闻看。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新车里的味，我不太喜欢。", "target_word": "味", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "味道，舌头尝到或鼻子闻到的感觉，多指气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91320, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "味", "is_correct": true, "explanation": "味（wèi）指鼻子闻到的气味，是正确答案。"}, {"text": "微", "is_correct": false, "explanation": "微（wēi）与味（wèi）声调不同（第一声与第四声），意思是很小、细微。"}, {"text": "威", "is_correct": false, "explanation": "威（wēi）与味（wèi）声调不同（第一声与第四声），意思是威力。"}, {"text": "问", "is_correct": false, "explanation": "问（wèn）与味（wèi）韵母不同（en 与 ei），意思是询问。"}, {"text": "被", "is_correct": false, "explanation": "被（bèi）与味（wèi）声母不同（b 与 w），意思是被动。"}, {"text": "费", "is_correct": false, "explanation": "费（fèi）与味（wèi）声母不同（f 与 w），意思是花费。"}], "explanations": {"味": "味（wèi）指鼻子闻到的气味，是正确答案。", "微": "微（wēi）与味（wèi）声调不同（第一声与第四声），意思是很小、细微。", "威": "威（wēi）与味（wèi）声调不同（第一声与第四声），意思是威力。", "问": "问（wèn）与味（wèi）韵母不同（en 与 ei），意思是询问。", "被": "被（bèi）与味（wèi）声母不同（b 与 w），意思是被动。", "费": "费（fèi）与味（wèi）声母不同（f 与 w），意思是花费。"}, "sentence_index": null, "correct_answer": "味"}, "level_3": {"options": [{"text": "味", "is_correct": true, "explanation": "味：指烧焦的气味，“一股烧焦的味”搭配自然，正确。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是听到的，不是闻到的烧焦气味。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：烧焦是气味的特征，不能用来描述颜色，“一股烧焦的颜色”不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“一股”不能修饰温度，“一股烧焦的温度”不成立。"}], "explanations": {"味": "味：指烧焦的气味，“一股烧焦的味”搭配自然，正确。", "声音": "语义：“声音”是听到的，不是闻到的烧焦气味。", "颜色": "搭配：烧焦是气味的特征，不能用来描述颜色，“一股烧焦的颜色”不通。", "温度": "搭配：“一股”不能修饰温度，“一股烧焦的温度”不成立。"}, "sentence_index": 0, "correct_answer": "味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我闻到了一张鱼的味。", "explanation": "这里应该用〈股〉。“张”用于纸、桌子等平面的东西，不用于气味。"}, {"text": "他的味很高，衣服挑得很讲究。", "explanation": "这里应该用〈品味〉。“味”指味道或嗅觉、味觉的感觉，不指审美的高低，应说“品味”。"}, {"text": "院子里飘来阵阵味。", "explanation": "这里应该用〈香味〉。“阵阵”之后一般接“香味”“臭味”这类带修饰词的说法，单独的“味”接在“阵阵”后不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91320, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "味", "is_correct": true, "explanation": "味（wèi）指鼻子闻到的气味，是正确答案。"}, {"text": "尾", "is_correct": false, "explanation": "尾（wěi）与味（wèi）声调不同（第三声与第四声），意思是尾巴。"}, {"text": "围", "is_correct": false, "explanation": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。"}, {"text": "伟", "is_correct": false, "explanation": "伟（wěi）与味（wèi）声调不同（第三声与第四声），意思是伟大。"}, {"text": "备", "is_correct": false, "explanation": "备（bèi）与味（wèi）声母不同（b 与 w），意思是准备。"}, {"text": "倍", "is_correct": false, "explanation": "倍（bèi）与味（wèi）声母不同（b 与 w），意思是倍数。"}], "explanations": {"味": "味（wèi）指鼻子闻到的气味，是正确答案。", "尾": "尾（wěi）与味（wèi）声调不同（第三声与第四声），意思是尾巴。", "围": "围（wéi）与味（wèi）声调不同（第二声与第四声），意思是包围。", "伟": "伟（wěi）与味（wèi）声调不同（第三声与第四声），意思是伟大。", "备": "备（bèi）与味（wèi）声母不同（b 与 w），意思是准备。", "倍": "倍（bèi）与味（wèi）声母不同（b 与 w），意思是倍数。"}, "sentence_index": null, "correct_answer": "味"}, "level_3": {"options": [{"text": "味", "is_correct": true, "explanation": "味：指泥土的气味，“泥土的味”搭配自然，正确。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：泥土不能有“速度”，“泥土的速度”不成立。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是钱的数额，与空气中闻到的泥土气息无关。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，不是可以闻到的气味。"}], "explanations": {"味": "味：指泥土的气味，“泥土的味”搭配自然，正确。", "速度": "搭配：泥土不能有“速度”，“泥土的速度”不成立。", "价格": "语义：“价格”是钱的数额，与空气中闻到的泥土气息无关。", "音量": "语义：“音量”指声音的大小，不是可以闻到的气味。"}, "sentence_index": 6, "correct_answer": "味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用眼睛看了看那股味。", "explanation": "这里应该用〈闻〉。“味”是鼻子闻到的感觉，不能用眼睛去看，应说“闻”。"}, {"text": "屋里飘来一条烧焦的味。", "explanation": "这里应该用〈股〉。“条”用于细长的东西，不用于气味；气味应使用量词“股”。"}, {"text": "这间屋子的味很硬。", "explanation": "这里应该用〈浓〉。“硬”形容质地或力度，不能形容气味；形容气味的强弱应说“浓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋里有一张淡淡的味，不太好闻。", "corrected_sentence": "屋里有一股淡淡的味，不太好闻。", "error_description": "错误形式是“一张味”，正确形式是“一股味”。“张”用于平面的东西，气味要用量词“股”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一进门就闻出了屋里的一只味。", "corrected_sentence": "他一进门就闻出了屋里的一股味。", "error_description": "错误是“一只味”，正确是“一股味”。“只”用于动物或成对的东西，不用于气味；气味应使用量词“股”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
