INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91321, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在家是人在自己的家里。", "primary_collocate": null, "pronunciation": "zài jiā", "ipa": "tsaɪ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "你昨天晚上在家做什么了？", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天不用上班，整天都在家。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师打电话的时候，我不在家。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在家等着我们回来。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在家做了一桌好菜，等朋友来吃。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好以前，医生让他在家休息。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在家过春节，哪儿也不去。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家学习汉语，每天学两个小时。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班以后，爸爸总是在家陪孩子。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，这几天一直在家躺着。", "target_word": "在家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不在家", "label": "复合"}, {"form": "在家里", "label": "复合"}, {"form": "在家中", "label": "复合"}], "register": "口语", "sense_fingerprint": "某人身处自己的家中，可指做事或等待的地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91321, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在家", "is_correct": true, "explanation": "正确。“在家”表示身处家中，“你昨天晚上在家做什么了？”是问昨晚在家里的活动。"}, {"text": "早起", "is_correct": false, "explanation": "搭配：“早起”通常指清晨起床，与“昨天晚上”搭配不当。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”本身就是一件事，后面再问“做什么了”，语义重复，句子不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时一般不做别的事，与“做什么了”的提问冲突。"}], "explanations": {"在家": "正确。“在家”表示身处家中，“你昨天晚上在家做什么了？”是问昨晚在家里的活动。", "早起": "搭配：“早起”通常指清晨起床，与“昨天晚上”搭配不当。", "洗澡": "语义：“洗澡”本身就是一件事，后面再问“做什么了”，语义重复，句子不通。", "睡觉": "语义：睡觉时一般不做别的事，与“做什么了”的提问冲突。"}, "sentence_index": 0, "correct_answer": "在家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在家坐地铁去学校。", "explanation": "这里应该用〈出门〉。“在家”表示待在家中，与“坐地铁去学校”的外出行动矛盾，应说“出门坐地铁去学校”。"}, {"text": "我今年要在家留学。", "explanation": "这里应该用〈出国〉。“在家”表示身处家中，与“留学”要去国外的意思矛盾，应说“出国留学”。"}, {"text": "他明天在家去北京。", "explanation": "这里应该用〈离家〉。“在家”表示待在家中，与“去北京”的离家行动矛盾，应说“离家去北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91321, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在家", "is_correct": true, "explanation": "正确。“在家过春节”指在家中度过春节，与“哪儿也不去”呼应。"}, {"text": "外出", "is_correct": false, "explanation": "语义：“外出”指出门，与“哪儿也不去”直接矛盾。"}, {"text": "旅行", "is_correct": false, "explanation": "搭配：“旅行”后接“过春节”搭配不当，且与“哪儿也不去”矛盾。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：“逛街”是出门购物，与“哪儿也不去”矛盾。"}], "explanations": {"在家": "正确。“在家过春节”指在家中度过春节，与“哪儿也不去”呼应。", "外出": "语义：“外出”指出门，与“哪儿也不去”直接矛盾。", "旅行": "搭配：“旅行”后接“过春节”搭配不当，且与“哪儿也不去”矛盾。", "逛街": "语义：“逛街”是出门购物，与“哪儿也不去”矛盾。"}, "sentence_index": 6, "correct_answer": "在家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他周末在家爬山。", "explanation": "这里应该用〈去郊外〉。“在家”表示待在家中，与“爬山”需要到户外的行动矛盾。"}, {"text": "妈妈每周在家去超市。", "explanation": "这里应该用〈坐公交〉。“在家”表示待在家中，与“去超市”的外出行动矛盾，应说“坐公交去超市”。"}, {"text": "他下周在家去上海。", "explanation": "这里应该用〈乘飞机〉。“在家”表示待在家中，与“去上海”的远行矛盾，应说“乘飞机去上海”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91321, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班以后我去在家看电视。", "corrected_sentence": "下班以后我在家看电视。", "error_description": "错误：“在家”前多加了“去”。“去”表示前往，与“在家”（待在家中）矛盾。正确说法是“下班以后我在家看电视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91321, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几天我把在家看书，哪儿也不去。", "corrected_sentence": "这几天我在家看书，哪儿也不去。", "error_description": "错误：“在家”前多加了“把”。“把”字句要求“把”后有宾语，这里“把”后直接接“在家”，不通。正确说法是“这几天我在家看书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91325, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36cfc26a-16e9-4aec-93c8-c601166373e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
