INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91327, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "压是用力往下按。", "primary_collocate": null, "pronunciation": "yā", "ipa": "ja˥", "syllable_count": 1, "sentences": [{"text": "他用手压住那张纸。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用力压一下这个盖子。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把书压在枕头下面。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈压着箱子，我来关锁。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用手压了压我的肚子。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在箱子上，把盖子压紧了。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用力压水泵的把手，水就流出来了。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把树叶夹进书里，压了一个星期。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫压着我的脚，我动不了。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你压到我的手了，快起来。", "target_word": "压", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压了", "label": "完成体"}, {"form": "压着", "label": "持续体"}, {"form": "压过", "label": "经历体"}, {"form": "壓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "压：用力往下按", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89521d7c-795f-4734-8869-3f0a455f2e50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91327, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "压", "is_correct": true, "explanation": "正确。“压”是用力往下按。"}, {"text": "牙", "is_correct": false, "explanation": "yá（第二声）与 yā（第一声）声调不同，意思是牙齿。"}, {"text": "哑", "is_correct": false, "explanation": "yǎ（第三声）与 yā（第一声）声调不同，意思是不能说话。"}, {"text": "亚", "is_correct": false, "explanation": "yà（第四声）与 yā（第一声）声调不同，意思是亚洲或次一等的。"}, {"text": "烟", "is_correct": false, "explanation": "yān 比 yā 多一个鼻音韵尾 n，意思是烟。"}, {"text": "芽", "is_correct": false, "explanation": "yá（第二声）与 yā（第一声）声调不同，意思是芽。"}], "explanations": {"压": "正确。“压”是用力往下按。", "牙": "yá（第二声）与 yā（第一声）声调不同，意思是牙齿。", "哑": "yǎ（第三声）与 yā（第一声）声调不同，意思是不能说话。", "亚": "yà（第四声）与 yā（第一声）声调不同，意思是亚洲或次一等的。", "烟": "yān 比 yā 多一个鼻音韵尾 n，意思是烟。", "芽": "yá（第二声）与 yā（第一声）声调不同，意思是芽。"}, "sentence_index": null, "correct_answer": "压"}, "level_3": {"options": [{"text": "压", "is_correct": true, "explanation": "正确。“压住那张纸”是用手按住纸。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体或食物，不能说“喝那张纸”。"}, {"text": "驾驶", "is_correct": false, "explanation": "配价：“驾驶”需要车、船等交通工具作宾语，不能接“纸”。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”用于烹饪，与用手按纸的动作无关。"}], "explanations": {"压": "正确。“压住那张纸”是用手按住纸。", "喝": "搭配：“喝”的对象是液体或食物，不能说“喝那张纸”。", "驾驶": "配价：“驾驶”需要车、船等交通工具作宾语，不能接“纸”。", "煎": "语义：“煎”用于烹饪，与用手按纸的动作无关。"}, "sentence_index": 0, "correct_answer": "压"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈压着箱子，双手高高举过了头顶。", "explanation": "这里应该用〈举〉。压是用力往下按，与“高高举过了头顶”的向上动作矛盾。"}, {"text": "妈妈压着箱子，猛地把它甩向了空中。", "explanation": "这里应该用〈甩〉。压是用力往下按，与“甩向空中”的向上动作矛盾。"}, {"text": "妈妈压着菜篮，把它挂在了树梢上。", "explanation": "这里应该用〈挂〉。压是用力往下按，与“挂在树梢上”的悬空位置矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91327, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "压", "is_correct": true, "explanation": "正确。“压”是用力往下按。"}, {"text": "雅", "is_correct": false, "explanation": "yǎ（第三声）与 yā（第一声）声调不同，意思是高雅。"}, {"text": "涯", "is_correct": false, "explanation": "yá（第二声）与 yā（第一声）声调不同，意思是边际。"}, {"text": "蛙", "is_correct": false, "explanation": "wā 与 yā 声母不同（w 与 y），意思是青蛙。"}, {"text": "挖", "is_correct": false, "explanation": "wā 与 yā 声母不同（w 与 y），意思是挖掘。"}, {"text": "淹", "is_correct": false, "explanation": "yān 比 yā 多一个鼻音韵尾 n，意思是淹没。"}], "explanations": {"压": "正确。“压”是用力往下按。", "雅": "yǎ（第三声）与 yā（第一声）声调不同，意思是高雅。", "涯": "yá（第二声）与 yā（第一声）声调不同，意思是边际。", "蛙": "wā 与 yā 声母不同（w 与 y），意思是青蛙。", "挖": "wā 与 yā 声母不同（w 与 y），意思是挖掘。", "淹": "yān 比 yā 多一个鼻音韵尾 n，意思是淹没。"}, "sentence_index": null, "correct_answer": "压"}, "level_3": {"options": [{"text": "压", "is_correct": true, "explanation": "正确。“压水泵的把手”是用力往下按把手，所以水流了出来。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”不会使水流出，与“水就流出来了”的因果关系不通。"}, {"text": "漆", "is_correct": false, "explanation": "语义：“漆”是涂刷，无法让水流出来，句中不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，不能说“吃把手”。"}], "explanations": {"压": "正确。“压水泵的把手”是用力往下按把手，所以水流了出来。", "擦": "语义：“擦”不会使水流出，与“水就流出来了”的因果关系不通。", "漆": "语义：“漆”是涂刷，无法让水流出来，句中不通。", "吃": "搭配：“吃”的对象应是食物，不能说“吃把手”。"}, "sentence_index": 6, "correct_answer": "压"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你压着我的手，把它举到了头顶上。", "explanation": "这里应该用〈抬〉。压是用力往下按，与“举到头顶上”的向上动作矛盾。"}, {"text": "你压着气球，它一直往天上飞。", "explanation": "这里应该用〈放开〉。压是用力往下按，被压着的气球不会往天上飞。"}, {"text": "他用力压风筝，让它飞上了天。", "explanation": "这里应该用〈放〉。压是用力往下按，与“飞上了天”的向上运动矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91327, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把重物压了在纸箱上。", "corrected_sentence": "他把重物压在纸箱上。", "error_description": "“压”与后面的介词结构“在纸箱上”之间多加了“了”。正确形式是“压在纸箱上”，“压”后直接接“在”引出的处所，中间不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91327, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用石头住压了地图。", "corrected_sentence": "她用石头压住了地图。", "error_description": "“压住”的两个字顺序颠倒，写成了“住压”。正确形式是“压住”：“压”表示用力往下按，在前；“住”作结果补语，在后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6e868da-afe9-4960-92d8-722130b1a153') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进口", "is_correct": true, "explanation": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。"}, {"text": "出口", "is_correct": false, "explanation": "出口：指把货物运往国外，与“国产”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：表示买入，与“国产”的产地属性无关，不构成反义。"}, {"text": "销售", "is_correct": false, "explanation": "销售：表示卖出商品，与“国产”没有对应的反义关系。"}], "correct_answer": "进口", "explanations": {"进口": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。", "出口": "出口：指把货物运往国外，与“国产”没有反义关系。", "购买": "购买：表示买入，与“国产”的产地属性无关，不构成反义。", "销售": "销售：表示卖出商品，与“国产”没有对应的反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进口", "is_correct": true, "explanation": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。"}, {"text": "运送", "is_correct": false, "explanation": "运送：表示把人或物从一处送到另一处，与“国产”没有反义关系。"}, {"text": "出售", "is_correct": false, "explanation": "出售：表示卖出，与“国产”的产地属性无关，不构成反义。"}, {"text": "交易", "is_correct": false, "explanation": "交易：表示买卖往来，与“国产”没有对应的反义关系。"}], "correct_answer": "进口", "explanations": {"进口": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。", "运送": "运送：表示把人或物从一处送到另一处，与“国产”没有反义关系。", "出售": "出售：表示卖出，与“国产”的产地属性无关，不构成反义。", "交易": "交易：表示买卖往来，与“国产”没有对应的反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "在自己的国家里做出来的。", "primary_collocate": null, "pronunciation": "guó chǎn", "ipa": "kuo˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这辆车不是进口的，是国产的。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手机是国产的，价格不贵。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国产电影越来越好看了。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家商店只卖国产牛奶。", "target_word": "国产", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想买一台国产电视，不想买进口的。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说国产的茶叶比进口的便宜。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些水果都是国产的，不是外国来的。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多人喜欢买国产手机。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用的化妆品不是外国的，是国产的。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子的汽车是国产的，修起来很方便。", "target_word": "国产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國產", "label": "繁体"}, {"form": "国产货", "label": "复合"}], "register": "中性", "sense_fingerprint": "国产|属性|在本国制造的，与进口相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国产", "is_correct": true, "explanation": "国产：在本国制造的，与“不是进口的”形成对比。"}, {"text": "透明", "is_correct": false, "explanation": "语义：车不能是透明的，这样说不合常理。"}, {"text": "松软", "is_correct": false, "explanation": "语义：车的质地不会是松软的，句子说不通。"}, {"text": "冰凉", "is_correct": false, "explanation": "搭配：“冰凉”多用于温度或触感，不用来形容车辆。"}], "explanations": {"国产": "国产：在本国制造的，与“不是进口的”形成对比。", "透明": "语义：车不能是透明的，这样说不合常理。", "松软": "语义：车的质地不会是松软的，句子说不通。", "冰凉": "搭配：“冰凉”多用于温度或触感，不用来形容车辆。"}, "sentence_index": 0, "correct_answer": "国产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议有很多国产学者参加。", "explanation": "这里应该用〈国内〉。国产只用于说产品是本国制造的，不用于说学者。"}, {"text": "他是国产的，从小在北京长大。", "explanation": "这里应该用〈中国人〉。国产只用于说产品是本国制造的，指人时要说“中国人”，不能说“国产的”。"}, {"text": "这座山是国产的，景色很美。", "explanation": "这里应该用〈在国内〉。国产只说产品是本国制造的，山是地点，应说“这座山在国内”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国产", "is_correct": true, "explanation": "国产：本国制造的，与“不是外国来的”相符。"}, {"text": "滚烫", "is_correct": false, "explanation": "语义：水果不会是滚烫的，句子说不通。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：水果不能是寂静的，这样说不合常理。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”多用于人或动物的身材，不用来形容水果的外形。"}], "explanations": {"国产": "国产：本国制造的，与“不是外国来的”相符。", "滚烫": "语义：水果不会是滚烫的，句子说不通。", "寂静": "语义：水果不能是寂静的，这样说不合常理。", "矮小": "体貌：“矮小”多用于人或动物的身材，不用来形容水果的外形。"}, "sentence_index": 6, "correct_answer": "国产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气是国产的，很凉快。", "explanation": "这里应该用〈本地〉。国产只说产品是本国制造的，天气不是产品，应说“今天本地的天气很凉快”。"}, {"text": "那轮月亮是国产的，很圆。", "explanation": "这里应该去掉〈国产的〉。国产只说产品是本国制造的，月亮不是产品，应直接说“那轮月亮很圆”。"}, {"text": "国产的足球队在比赛中获胜了。", "explanation": "这里应该用〈本国〉。国产只用于说产品，不能用来说球队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂生产国产地汽车。", "corrected_sentence": "工厂生产国产的汽车。", "error_description": "“国产地汽车”错误，应为“国产的汽车”。修饰名词要用“的”，“地”用于修饰动词，这里“国产”修饰“汽车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91329, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台国产得洗衣机很好用。", "corrected_sentence": "这台国产的洗衣机很好用。", "error_description": "用词错误：修饰名词应用结构助词“的”，“得”不能用于“国产”和名词之间。正确说法是“国产的洗衣机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进口", "is_correct": true, "explanation": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。"}, {"text": "出口", "is_correct": false, "explanation": "出口：指把货物运往国外，与“国产”没有反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "购买：表示买入，与“国产”的产地属性无关，不构成反义。"}, {"text": "运输", "is_correct": false, "explanation": "运输：表示把货物从一处运到另一处，与“国产”没有反义关系。"}], "correct_answer": "进口", "explanations": {"进口": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。", "出口": "出口：指把货物运往国外，与“国产”没有反义关系。", "购买": "购买：表示买入，与“国产”的产地属性无关，不构成反义。", "运输": "运输：表示把货物从一处运到另一处，与“国产”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进口", "is_correct": true, "explanation": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。"}, {"text": "销售", "is_correct": false, "explanation": "销售：表示卖出商品，与“国产”没有反义关系。"}, {"text": "出售", "is_correct": false, "explanation": "出售：表示卖出，与“国产”的产地属性无关，不构成反义。"}, {"text": "交易", "is_correct": false, "explanation": "交易：表示买卖往来，与“国产”没有对应的反义关系。"}], "correct_answer": "进口", "explanations": {"进口": "进口：指从国外买入、运进国内，与“国产”正相反，是反义词。", "销售": "销售：表示卖出商品，与“国产”没有反义关系。", "出售": "出售：表示卖出，与“国产”的产地属性无关，不构成反义。", "交易": "交易：表示买卖往来，与“国产”没有对应的反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "本国生产制造的。", "primary_collocate": null, "pronunciation": "guó chǎn", "ipa": "kuo˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这台国产电脑用了五年，还很好用。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国产汽车的质量越来越好。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里有进口牛奶，也有国产牛奶。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋是国产品牌，价格很实惠。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国产飞机已经开始载客飞行了。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的冰箱是国产的，用得很放心。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国产手机的拍照功能很不错。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他送给朋友一瓶国产红酒。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏是国产的，很多中国人都玩。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前大家都爱买名牌，现在更爱买国产货。", "target_word": "国产", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "國產", "label": "繁体"}, {"form": "国产货", "label": "复合"}], "register": "中性", "sense_fingerprint": "国产|属性|本国生产制造的产品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad9311d-2259-4b31-9471-d7d48a98239a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国产", "is_correct": true, "explanation": "国产：本国生产制造的，与“用了五年，还很好用”相符。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：电脑不会是柔软的，这样说不合常理。"}, {"text": "甜", "is_correct": false, "explanation": "语义：电脑没有甜的味道，句子说不通。"}, {"text": "温柔", "is_correct": false, "explanation": "搭配：“温柔”多用来形容人的性格，不用来形容电脑。"}], "explanations": {"国产": "国产：本国生产制造的，与“用了五年，还很好用”相符。", "柔软": "语义：电脑不会是柔软的，这样说不合常理。", "甜": "语义：电脑没有甜的味道，句子说不通。", "温柔": "搭配：“温柔”多用来形容人的性格，不用来形容电脑。"}, "sentence_index": 0, "correct_answer": "国产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妹妹是国产的，今年刚上大学。", "explanation": "这里应该用〈中国人〉。国产只说产品是本国制造的，指人要说“中国人”，不能说“国产的”。"}, {"text": "这条河是国产的，水很清。", "explanation": "这里应该用〈在国内〉。国产只说产品是本国制造的，河是地点，应说“这条河在国内”。"}, {"text": "这次比赛的天空是国产的，很蓝。", "explanation": "这里应该去掉〈国产的〉。国产只说产品是本国制造的，天空不是产品，应说“这次比赛的天空很蓝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国产", "is_correct": true, "explanation": "国产：本国制造的，与“手机”和拍照功能的描述相符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：手机不能是寂静的，这样说不合常理。"}, {"text": "苦", "is_correct": false, "explanation": "语义：手机没有苦味，句子说不通。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容身材，不用来形容手机的外形。"}], "explanations": {"国产": "国产：本国制造的，与“手机”和拍照功能的描述相符。", "寂静": "语义：手机不能是寂静的，这样说不合常理。", "苦": "语义：手机没有苦味，句子说不通。", "矮小": "体貌：“矮小”形容身材，不用来形容手机的外形。"}, "sentence_index": 6, "correct_answer": "国产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天下的雨是国产的，很大。", "explanation": "这里应该去掉〈国产的〉。国产只说产品是本国制造的，雨不是产品，应说“今天下的雨很大”。"}, {"text": "这里的空气是国产的，很新鲜。", "explanation": "这里应该用〈本地〉。国产只说产品的产地，空气不是产品，应说“本地的空气很新鲜”。"}, {"text": "我们的汉语老师是国产的，很热情。", "explanation": "这里应该用〈中国人〉。国产只说产品是本国制造的，指人要说“中国人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一台国产的的冰箱。", "corrected_sentence": "我买了一台国产的冰箱。", "error_description": "“的”重复：修饰语“国产”后只用一个“的”，“国产的的冰箱”多了一个“的”。正确说法是“国产的冰箱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91330, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂生产国产地手机。", "corrected_sentence": "工厂生产国产的手机。", "error_description": "“国产地手机”错误，应为“国产的手机”。修饰名词要用“的”，不用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5595d58a-bcd7-4ec5-acd1-1b8be64c5b46') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
