INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91332, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以言语、行为对他人进行带有性意味的、违背其意愿的侵扰。", "primary_collocate": null, "pronunciation": "xìng sāo rǎo", "ipa": "ɕiŋ˥˩ saʊ˥ ʐaʊ˨˩˦", "syllable_count": 3, "sentences": [{"text": "性骚扰是违法的，法律会严厉惩罚。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对同事进行性骚扰是违法行为。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司设立了专门处理性骚扰的部门。", "target_word": "性骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他因为性骚扰同事，受到了法律处罚。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "性骚扰会给当事人带来很大的伤害。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法院审理了一起性骚扰案件。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家说，性骚扰常常发生在上下级之间。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她勇敢地站出来，指出自己遭受了性骚扰。", "target_word": "性骚扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要建立制度，防止性骚扰发生。", "target_word": "性骚扰", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "性骚扰不仅伤害个人，也破坏工作环境。", "target_word": "性骚扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "性骚扰：以言语或行为对他人进行带性意味的、违背其意愿的侵扰，法律与制度语境", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a33d6d74-ea1a-4c9f-88d6-078bbe064f42') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91332, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性骚扰", "is_correct": true, "explanation": "正确：“法律会严厉惩罚”的对象是违法行为，性骚扰符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是可以被惩罚的行为，与“法律严厉惩罚”不符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不属于需要法律惩罚的行为，句子不通。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“惩罚”一般搭配行为或人，“闹钟”是物品，不能被惩罚。"}], "explanations": {"性骚扰": "正确：“法律会严厉惩罚”的对象是违法行为，性骚扰符合句意。", "花园": "语义：花园不是可以被惩罚的行为，与“法律严厉惩罚”不符。", "饮料": "语义：饮料不属于需要法律惩罚的行为，句子不通。", "闹钟": "搭配：“惩罚”一般搭配行为或人，“闹钟”是物品，不能被惩罚。"}, "sentence_index": 0, "correct_answer": "性骚扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们因为他个子矮而性骚扰他。", "explanation": "这里应该用〈嘲笑〉。性骚扰带性意味且违背意愿；因为个子矮而取笑，属于嘲笑，应用〈嘲笑〉。"}, {"text": "工人们在公司门口性骚扰，要求增加工资。", "explanation": "这里应该用〈抗议〉。性骚扰针对他人且带性意味；工人在门口要求加薪是抗议，应用〈抗议〉。"}, {"text": "学者在会上性骚扰这个理论，引起了讨论。", "explanation": "这里应该用〈质疑〉。性骚扰指侵扰他人，不指对理论提出疑问；对理论提出疑问应用〈质疑〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91332, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性骚扰", "is_correct": true, "explanation": "正确：“发生在……之间”指一种行为事件，性骚扰符合句意，与“常常”搭配自然。"}, {"text": "乒乓球", "is_correct": false, "explanation": "语义：乒乓球是体育运动，不是常发生在上下级之间的事。"}, {"text": "饺子", "is_correct": false, "explanation": "搭配：“发生”搭配事件，“饺子”是食物，不能说“发生在上下级之间”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”是物品，不能与“发生在上下级之间”搭配。"}], "explanations": {"性骚扰": "正确：“发生在……之间”指一种行为事件，性骚扰符合句意，与“常常”搭配自然。", "乒乓球": "语义：乒乓球是体育运动，不是常发生在上下级之间的事。", "饺子": "搭配：“发生”搭配事件，“饺子”是食物，不能说“发生在上下级之间”。", "冰箱": "搭配：“冰箱”是物品，不能与“发生在上下级之间”搭配。"}, "sentence_index": 6, "correct_answer": "性骚扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈因为我考试不及格而性骚扰我。", "explanation": "这里应该用〈责备〉。性骚扰是带性意味、违背对方意愿的侵扰；考试不及格后的批评属于责备，应用〈责备〉。"}, {"text": "这个病毒一直性骚扰我的电脑，导致它死机。", "explanation": "这里应该用〈攻击〉。性骚扰针对的是人，且带性意味；病毒对电脑的恶意破坏应用〈攻击〉。"}, {"text": "小偷趁老人不注意性骚扰了钱包。", "explanation": "这里应该用〈偷走〉。性骚扰指带性意味的侵扰，不指拿走他人财物；偷东西应用〈偷走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91332, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这名员工性骚扰着同事，公司对他作出了处理。", "corrected_sentence": "这名员工性骚扰了同事，公司对他作出了处理。", "error_description": "体标错误：“着”表示动作正在持续，这里说的是已经发生的行为，应用“了”。“性骚扰着同事”应改为“性骚扰了同事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91332, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很性骚扰同事，最后被公司开除。", "corrected_sentence": "他性骚扰同事，最后被公司开除。", "error_description": "“很”只修饰形容词等表示程度的词，不能修饰“性骚扰”这样的动作性词语。“他很性骚扰同事”应改为“他性骚扰同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd2fda4f-08b0-4134-8437-cbdc80d892ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "单一：只有一种，与“多样；种类多”的意思相反。"}, {"text": "清晰", "is_correct": false, "explanation": "清晰：形容明白、不模糊，与种类多少无关，不构成反义。"}, {"text": "悠久", "is_correct": false, "explanation": "悠久：形容历史长，与“多样”没有反义关系。"}, {"text": "坚固", "is_correct": false, "explanation": "坚固：形容结实、不易损坏，与种类多少不构成反义。"}], "correct_answer": "单一", "explanations": {"单一": "单一：只有一种，与“多样；种类多”的意思相反。", "清晰": "清晰：形容明白、不模糊，与种类多少无关，不构成反义。", "悠久": "悠久：形容历史长，与“多样”没有反义关系。", "坚固": "坚固：形容结实、不易损坏，与种类多少不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一", "is_correct": true, "explanation": "单一：只有一种，与“多样；种类多”的意思相反。"}, {"text": "圆润", "is_correct": false, "explanation": "圆润：形容圆而光滑，与种类多少无关，不构成反义。"}, {"text": "迟缓", "is_correct": false, "explanation": "迟缓：形容动作或反应慢，与“多样”没有反义关系。"}, {"text": "耀眼", "is_correct": false, "explanation": "耀眼：形容光线强烈刺目，与种类多少不构成反义。"}], "correct_answer": "单一", "explanations": {"单一": "单一：只有一种，与“多样；种类多”的意思相反。", "圆润": "圆润：形容圆而光滑，与种类多少无关，不构成反义。", "迟缓": "迟缓：形容动作或反应慢，与“多样”没有反义关系。", "耀眼": "耀眼：形容光线强烈刺目，与种类多少不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "多样；种类多。", "primary_collocate": null, "pronunciation": "duō zhǒng", "ipa": "tuɔ⁵⁵ ʈʂʊŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "花园里有多种花。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家书店有多种杂志。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用多种方式学习汉语。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市卖多种蔬菜。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机有多种颜色。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市有多种交通工具。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说有多种药可以用。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校有多种活动。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面包有多种口味。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会做多种好吃的菜。", "target_word": "多种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说某处或某物种类多、很多样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多种", "is_correct": true, "explanation": "「多种」表示种类多，修饰“花”，句意通顺。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容质地硬，不能用来说花园里花的种类多。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：“滚烫”形容温度高，不能修饰“花”。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能修饰“花”。"}], "explanations": {"多种": "「多种」表示种类多，修饰“花”，句意通顺。", "坚硬": "语义：“坚硬”形容质地硬，不能用来说花园里花的种类多。", "滚烫": "搭配：“滚烫”形容温度高，不能修饰“花”。", "嘹亮": "搭配：“嘹亮”形容声音，不能修饰“花”。"}, "sentence_index": 0, "correct_answer": "多种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "超市今天卖了一个多种白菜，很快就卖完了。", "explanation": "这里应该用〈一种〉。多种说种类多，“一个”表示单个，二者矛盾；只卖一种白菜要用“一种”。"}, {"text": "这家超市今天来了一个多种顾客。", "explanation": "这里应该用〈一位〉。多种说种类多，“一个”表示单个，二者矛盾；指一位顾客要用“一位”。"}, {"text": "超市里的这个西瓜是多种西瓜。", "explanation": "这里说的是一个确定的西瓜，“多种”说种类多，用在单个对象上不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多种", "is_correct": true, "explanation": "「多种」表示种类多，修饰“药”，句意通顺。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”形容表演或文章出色，不能用来修饰药的种类。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰“药”。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面喧闹，与药的种类无关。"}], "explanations": {"多种": "「多种」表示种类多，修饰“药”，句意通顺。", "精彩": "语义：“精彩”形容表演或文章出色，不能用来修饰药的种类。", "清脆": "搭配：“清脆”形容声音，不能修饰“药”。", "热闹": "语义：“热闹”形容场面喧闹，与药的种类无关。"}, "sentence_index": 6, "correct_answer": "多种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她做了一个多种菜。", "explanation": "这里应该用〈一道〉。多种指种类多，“一个”表示单个，二者矛盾；单道菜要用“一道”。"}, {"text": "她每天只练习一个多种菜。", "explanation": "这里应该用〈一道〉。多种指种类多，“一个”表示单个，二者矛盾；练习的单道菜要用“一道”。"}, {"text": "她做的这道鱼是多种鱼。", "explanation": "这里说的是一道确定的鱼，“多种”说种类多，用在单个对象上不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市有一个多种美食。", "corrected_sentence": "这个城市有多种美食。", "error_description": "错误形式是“一个多种美食”，正确形式是“多种美食”。“多种”表示种类多，前面加“一个”表示单个，二者矛盾，应去掉“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91334, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家附近有得多种餐馆。", "corrected_sentence": "我们家附近有多种餐馆。", "error_description": "错误形式是“有得多种餐馆”，正确形式是“有多种餐馆”。“得”是结构助词，不能用在“有”和“多种”之间，应去掉“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
