INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "放在心上；介意。", "primary_collocate": null, "pronunciation": "zài hu", "ipa": "tsai˥˩ xu", "syllable_count": 2, "sentences": [{"text": "别人怎么说，我一点儿也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了几分钟，老师并不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这点小事，你就别在乎了。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，可他一点也不在乎，照样去跑步。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不在乎衣服贵不贵，只要好看就行。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友开玩笑，他从来都不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不在乎别人的看法，只做自己想做的事。", "target_word": "在乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿得很旧，可是一点也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人笑他，他会在乎吗？", "target_word": "在乎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "就算有人批评他，他也不在乎。", "target_word": "在乎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在乎过", "label": "体标"}, {"form": "满不在乎", "label": "复合"}], "register": "口语", "sense_fingerprint": "在乎：放在心上、介意，多用于否定，如不在乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上、介意，与“不”搭配，符合题意。"}, {"text": "游", "is_correct": false, "explanation": "语义：“游”指在水中前进，与“别人怎么说”的语境无关。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”指快速移动，与“说”的语境不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热食物，与“别人怎么说”的语境不合。"}], "explanations": {"在乎": "“在乎”表示放在心上、介意，与“不”搭配，符合题意。", "游": "语义：“游”指在水中前进，与“别人怎么说”的语境无关。", "跑": "语义：“跑”指快速移动，与“说”的语境不合。", "煮": "语义：“煮”指用水加热食物，与“别人怎么说”的语境不合。"}, "sentence_index": 0, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "钥匙在乎抽屉里。", "explanation": "这里应该用〈放〉。“在乎”表示放在心上，不能表示物体的位置，放东西要用“放”。"}, {"text": "早上我在乎了一杯咖啡。", "explanation": "这里应该用〈喝〉。“在乎”表示放在心上、介意，不表示喝东西。"}, {"text": "书包在乎椅子上。", "explanation": "这里可用〈搁〉或〈放〉。“在乎”不能表示物体的位置，书包放在椅子上要用这类动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在乎", "is_correct": true, "explanation": "“在乎”表示放在心上，与“不”搭配，表示不把别人的看法放在心上，符合题意。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”指用熨斗把衣物烫平，看法不能被熨。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”指用油加热食物，看法不能被煎。"}, {"text": "吵", "is_correct": false, "explanation": "配价：“吵”是不及物动词，不能带“别人的看法”作宾语。"}], "explanations": {"在乎": "“在乎”表示放在心上，与“不”搭配，表示不把别人的看法放在心上，符合题意。", "熨": "语义：“熨”指用熨斗把衣物烫平，看法不能被熨。", "煎": "语义：“煎”指用油加热食物，看法不能被煎。", "吵": "配价：“吵”是不及物动词，不能带“别人的看法”作宾语。"}, "sentence_index": 6, "correct_answer": "在乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的手机在乎口袋里。", "explanation": "这里应该用〈装〉。“在乎”不能表示物体的位置，手机装在口袋里要用“装”。"}, {"text": "他在乎会场的前排。", "explanation": "这里应该用〈坐〉。“在乎”表示放在心上，不能表示人所处的位置。"}, {"text": "他的篮球在乎箱子里。", "explanation": "这里应该用〈放〉。“在乎”不能表示位置，篮球放在箱子里要用“放”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一点儿也不不在乎别人的闲话。", "corrected_sentence": "他一点儿也不在乎别人的闲话。", "error_description": "否定词重复：“在乎”前只需一个“不”，应说“一点儿也不在乎”，不能说“不不在乎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她一直在乎了朋友的感受。", "corrected_sentence": "她一直在乎着朋友的感受。", "error_description": "体标错误：“在乎”表示持续的状态，应用动态助词“着”，说“在乎着朋友的感受”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
