INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国派驻他国的最高级外交代表。", "primary_collocate": null, "pronunciation": "dà shǐ", "ipa": "ta⁵¹ ʂʐ̩²¹⁴", "syllable_count": 2, "sentences": [{"text": "大使是驻在外国的最高外交代表。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国驻英国大使见了英国外交大臣。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统收下了新大使递交的国书。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使向本国政府报告了会谈情况。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国同意互相派大使。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位大使在东京工作了三年。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使出席了国庆招待会。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家任命他做驻德国大使。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大使今天上午会见了外交部长。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驻联合国大使发表了讲话。", "target_word": "大使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "一国派驻他国的最高级外交代表，外交场合用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91340, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大使", "is_correct": true, "explanation": "正确。大使指一国派驻他国的最高级外交代表。"}, {"text": "大事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是重要的事情。"}, {"text": "大师", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是在某个领域造诣很深的人。"}, {"text": "打湿", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）、shī（第一声）与 shǐ（第三声）声调都不同，意思是使东西沾上水。"}], "explanations": {"大使": "正确。大使指一国派驻他国的最高级外交代表。", "大事": "shì（第四声）与 shǐ（第三声）声调不同，意思是重要的事情。", "大师": "shī（第一声）与 shǐ（第三声）声调不同，意思是在某个领域造诣很深的人。", "打湿": "dǎ（第三声）与 dà（第四声）、shī（第一声）与 shǐ（第三声）声调都不同，意思是使东西沾上水。"}, "sentence_index": null, "correct_answer": "大使"}, "level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“学生”不是国家派驻他国的外交代表，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人，不能作外交代表，句子意思不通。"}, {"text": "大使", "is_correct": true, "explanation": "正确。“大使”是驻在外国的最高外交代表，与句中的定义相符。"}, {"text": "领事", "is_correct": false, "explanation": "搭配：“最高”与“领事”的级别不搭，领事不是国家在外国的最高外交代表。"}], "explanations": {"学生": "语义：“学生”不是国家派驻他国的外交代表，句子不成立。", "天气": "语义：“天气”不是人，不能作外交代表，句子意思不通。", "大使": "正确。“大使”是驻在外国的最高外交代表，与句中的定义相符。", "领事": "搭配：“最高”与“领事”的级别不搭，领事不是国家在外国的最高外交代表。"}, "sentence_index": 0, "correct_answer": "大使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在大使里面开了一次国庆招待会。", "explanation": "这里应该用〈大使馆〉。“大使”指人，不能作开会的场所，指地点要用“大使馆”。"}, {"text": "这位大使帮客户打赢了官司。", "explanation": "这里应该用〈律师〉。“大使”指派驻他国的外交代表，不从事诉讼代理，帮客户打官司的人应称“律师”。"}, {"text": "这位大使带领部队打了胜仗。", "explanation": "这里应该用〈将军〉。“大使”是外交代表，不指挥作战，带领部队打仗的人应称“将军”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91340, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大使", "is_correct": true, "explanation": "正确。大使指一国派驻他国的最高级外交代表。"}, {"text": "大势", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是事情发展的趋势。"}, {"text": "大石", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是大块的石头。"}, {"text": "打湿", "is_correct": false, "explanation": "dǎ（第三声）与 dà（第四声）、shī（第一声）与 shǐ（第三声）声调都不同，意思是使东西沾上水。"}], "explanations": {"大使": "正确。大使指一国派驻他国的最高级外交代表。", "大势": "shì（第四声）与 shǐ（第三声）声调不同，意思是事情发展的趋势。", "大石": "shí（第二声）与 shǐ（第三声）声调不同，意思是大块的石头。", "打湿": "dǎ（第三声）与 dà（第四声）、shī（第一声）与 shǐ（第三声）声调都不同，意思是使东西沾上水。"}, "sentence_index": null, "correct_answer": "大使"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能出席活动，句子不成立。"}, {"text": "大使", "is_correct": true, "explanation": "正确。“大使”是派驻外国的外交代表，可以出席国庆招待会。"}, {"text": "小混混", "is_correct": false, "explanation": "语域：“小混混”是口语且含贬义，与国庆招待会的正式语境不搭，也不能出席此类场合。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗不能出席招待会，句子意思不通。"}], "explanations": {"石头": "语义：石头不能出席活动，句子不成立。", "大使": "正确。“大使”是派驻外国的外交代表，可以出席国庆招待会。", "小混混": "语域：“小混混”是口语且含贬义，与国庆招待会的正式语境不搭，也不能出席此类场合。", "小狗": "语义：小狗不能出席招待会，句子意思不通。"}, "sentence_index": 6, "correct_answer": "大使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天上午都在大使里面写材料。", "explanation": "这里应该用〈办公室〉。“大使”指人，不能作写材料的场所。"}, {"text": "这位大使每天带队训练。", "explanation": "这里应该用〈教练〉。“大使”指派驻他国的外交代表，不从事体育训练，带队训练的人应称“教练”。"}, {"text": "这位大使给病人打了针。", "explanation": "这里应该用〈护士〉。“大使”是外交代表，不做护理工作，给病人打针的人应称“护士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只大使在会议上发言了。", "corrected_sentence": "一位大使在会议上发言了。", "error_description": "“大使”指人，量词应用“位”，不能用“只”（“只”用于动物或小物件）。应改为“一位大使在会议上发言了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几块大使出席了这次会议。", "corrected_sentence": "几位大使出席了这次会议。", "error_description": "“大使”指人，量词应用“位”，“块”用于片状或块状的东西。应改为“几位大使出席了这次会议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
