INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91341, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打电话告诉警察出事了。", "primary_collocate": null, "pronunciation": "bào jǐng", "ipa": "pɑʊ̯˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他拿出手机，打电话报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看见小偷，我马上用手机报警了。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险的时候，请拨110报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她躲在房间里，小声地打电话报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教孩子遇到坏人怎么打电话报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，他没办法报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有人受伤，我赶紧打电话报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居听到奇怪的声音，就打电话报警了。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在电话里报警，说家里进了小偷。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快用我的手机报警吧。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报了警", "label": "完成体"}, {"form": "报过警", "label": "经历体"}], "register": "中性", "sense_fingerprint": "出事时打电话通知警察", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91341, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报警", "is_correct": true, "explanation": "报警：打电话告诉警察出事了，符合句意。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与“拿出手机、打电话”的情境无关，句意不通。"}, {"text": "理发", "is_correct": false, "explanation": "语义：“理发”与打电话的动作搭不上，句子不成立。"}, {"text": "报账", "is_correct": false, "explanation": "搭配：“报账”需要提交票据，不能靠打电话完成，搭配不当。"}], "explanations": {"报警": "报警：打电话告诉警察出事了，符合句意。", "洗澡": "语义：“洗澡”与“拿出手机、打电话”的情境无关，句意不通。", "理发": "语义：“理发”与打电话的动作搭不上，句子不成立。", "报账": "搭配：“报账”需要提交票据，不能靠打电话完成，搭配不当。"}, "sentence_index": 0, "correct_answer": "报警"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他打电话给老师报警，说明天放假。", "explanation": "这里应该用〈通知〉。报警只用于打电话告诉警察出事，告诉老师放假消息要说〈通知〉。"}, {"text": "他打电话给税务局报警，说那家公司偷税。", "explanation": "这里应该用〈举报〉。报警只能打给警察，向税务局反映偷税要说〈举报〉。"}, {"text": "他打电话报警，说妻子生了个女儿。", "explanation": "这里应该用〈报喜〉。报喜用于好消息，打电话告诉警察出事才是报警。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91341, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报警", "is_correct": true, "explanation": "报警：打电话告诉警察出事了，符合句意。"}, {"text": "问候", "is_correct": false, "explanation": "语义：“问候”是寒暄，与路上有人受伤、需要紧急处理的情境不符。"}, {"text": "购物", "is_correct": false, "explanation": "语义：“购物”与紧急伤情毫无关系，句意不通。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”多搭配活动、考试，不搭配紧急情况。"}], "explanations": {"报警": "报警：打电话告诉警察出事了，符合句意。", "问候": "语义：“问候”是寒暄，与路上有人受伤、需要紧急处理的情境不符。", "购物": "语义：“购物”与紧急伤情毫无关系，句意不通。", "报名": "搭配：“报名”多搭配活动、考试，不搭配紧急情况。"}, "sentence_index": 6, "correct_answer": "报警"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子向班主任报警，说同桌抢了他的书。", "explanation": "这里应该用〈告状〉。报警只用于向警察报告出事，向班主任反映同学的行为要说〈告状〉。"}, {"text": "学校向他家长报警，说他考试作弊。", "explanation": "这里应该用〈通报〉。报警只用于告诉警察出事，学校向家长反映学生作弊要说〈通报〉。"}, {"text": "他打电话报警，说儿子考上了大学。", "explanation": "这里应该用〈报喜〉。报喜是告诉别人好消息，报警只用于告诉警察出事了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91341, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在电话里很报警了，说有人打架。", "corrected_sentence": "她在电话里报警了，说有人打架。", "error_description": "程度副词错位：“很”不能修饰动词“报警”，应去掉“很”，说“在电话里报警了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91341, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把电话里报警，说楼下有人打架。", "corrected_sentence": "她在电话里报警，说楼下有人打架。", "error_description": "介词错误：表示通过电话的方式要用“在电话里”，“把”不能这样用。正确应为“在电话里报警”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
