INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91342, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "向警察机关报告危险或案件。", "primary_collocate": null, "pronunciation": "bào jǐng", "ipa": "pɑʊ̯˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "发现小偷以后，他立刻向警方报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丢了钱包，你应该去派出所报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居家里进了小偷，他们马上报警了。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人打架，路人决定报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里遇到抢劫，老板冒着危险报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的车丢了，我要去警察局报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现可疑的包，请不要碰，赶快报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她上当受骗了，朋友劝她去报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发生了车祸，有人受伤，快报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子着火了，大家一边救火一边报警。", "target_word": "报警", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "报了警", "label": "完成体"}, {"form": "报过警", "label": "经历体"}], "register": "中性", "sense_fingerprint": "遇到危险或案件时向警察机关报告", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报警", "is_correct": true, "explanation": "报警：向警察机关报告案件，符合句意。"}, {"text": "报喜", "is_correct": false, "explanation": "语义：“报喜”是报告好消息，与小偷、警方的情境相矛盾。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”要向领导或老师请，不能向警方请假。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：发现小偷后向警方微笑，与句中“立刻”所表示的紧急行动不符。"}], "explanations": {"报警": "报警：向警察机关报告案件，符合句意。", "报喜": "语义：“报喜”是报告好消息，与小偷、警方的情境相矛盾。", "请假": "搭配：“请假”要向领导或老师请，不能向警方请假。", "微笑": "语义：发现小偷后向警方微笑，与句中“立刻”所表示的紧急行动不符。"}, "sentence_index": 0, "correct_answer": "报警"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每周都向经理报警。", "explanation": "这里应该用〈汇报〉。报警只能向警察报告危险或案件，向经理定期汇报工作要说〈汇报〉。"}, {"text": "孩子考了满分，爸爸马上报警了。", "explanation": "这里应该用〈报喜〉。报喜用于告诉别人好消息，报警只用于危险或案件。"}, {"text": "他打电话报警，想问去火车站怎么走。", "explanation": "这里应该用〈问路〉。报警只用于向警察报告危险或案件，打听怎么走要说〈问路〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报警", "is_correct": true, "explanation": "报警：向警察机关报告可疑情况，符合句意。"}, {"text": "打开", "is_correct": false, "explanation": "语义：“打开”与“请不要碰”前后矛盾，句意不通。"}, {"text": "理发", "is_correct": false, "explanation": "语义：“理发”与可疑的包、紧急情况毫无关系。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”多搭配活动、比赛，不用于紧急情况。"}], "explanations": {"报警": "报警：向警察机关报告可疑情况，符合句意。", "打开": "语义：“打开”与“请不要碰”前后矛盾，句意不通。", "理发": "语义：“理发”与可疑的包、紧急情况毫无关系。", "报名": "搭配：“报名”多搭配活动、比赛，不用于紧急情况。"}, "sentence_index": 6, "correct_answer": "报警"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向税务局报警，说那家公司偷税。", "explanation": "这里应该用〈举报〉。报警只能向警察机关报告，向税务局反映违法行为要说〈举报〉。"}, {"text": "孩子向老师报警，说同桌借了他的橡皮。", "explanation": "这里应该用〈告状〉。报警只用于危险或案件，向老师反映同学的小事要说〈告状〉。"}, {"text": "他向人事部报警，说工资被扣得太多了。", "explanation": "这里应该用〈申诉〉。报警只能向警察报告危险或案件，对单位扣工资的处理不满要说〈申诉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才去派出所很报警了。", "corrected_sentence": "我刚才去派出所报警了。", "error_description": "程度副词错位：“很”是程度副词，不能修饰动词“报警”，应去掉“很”，说“去派出所报警了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我马上把警察报警，请他们快来。", "corrected_sentence": "我马上向警察报警，请他们快来。", "error_description": "介词错误：“报警”的对象是警察机关，应用介词“向”引出，不能用“把”。正确应为“向警察报警”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
