INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91343, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "户籍是记着一家人住在哪里的登记。", "primary_collocate": null, "pronunciation": "hù jí", "ipa": "xu˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我的户籍在北京。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把户籍迁到了上海。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子上学要看户籍。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的户籍在哪个城市？", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她结婚后，户籍还在老家。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户籍上写着我家有四口人。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去派出所办户籍。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把户籍转到妻子家。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的户籍很难办。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的户籍一直在农村。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "户籍本", "label": "复合"}], "register": "中性", "sense_fingerprint": "户籍：一家人居住地的登记，生活中常说的“户口”所在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91343, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国籍", "is_correct": false, "explanation": "语义：国籍说明国家归属，不能说“在北京”，与“住在哪里的登记”不符。"}, {"text": "户籍", "is_correct": true, "explanation": "户籍：记着一家人住在哪里的登记，所以“我的户籍在北京”成立。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”不能用“在北京”表示所在地，地点搭配不成立。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人的数值，不能放在某个城市。"}], "explanations": {"国籍": "语义：国籍说明国家归属，不能说“在北京”，与“住在哪里的登记”不符。", "户籍": "户籍：记着一家人住在哪里的登记，所以“我的户籍在北京”成立。", "年龄": "搭配：“年龄”不能用“在北京”表示所在地，地点搭配不成立。", "体重": "语义：体重是人的数值，不能放在某个城市。"}, "sentence_index": 0, "correct_answer": "户籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都去户籍上班。", "explanation": "这里应该用〈派出所〉。户籍是登记，不是可以去上班的场所；去上班的地方要说派出所。"}, {"text": "这个户籍很好吃。", "explanation": "这里应该用〈菜〉。户籍是登记，不能吃；“很好吃”要用于菜。"}, {"text": "他把户籍转到了新学校。", "explanation": "这里应该用〈学籍〉。学籍随学校转，户籍随居住地迁，户籍不能转到学校。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91343, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病历", "is_correct": false, "explanation": "语义：病历由医院保存，派出所不办理病历，与“办”的对象不符。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“办”后一般不接“工资”，常说“领工资”。"}, {"text": "户籍", "is_correct": true, "explanation": "户籍：派出所办理的居民登记，“去派出所办户籍”成立。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票由售票处出售，派出所不办理门票。"}], "explanations": {"病历": "语义：病历由医院保存，派出所不办理病历，与“办”的对象不符。", "工资": "搭配：“办”后一般不接“工资”，常说“领工资”。", "户籍": "户籍：派出所办理的居民登记，“去派出所办户籍”成立。", "门票": "语义：门票由售票处出售，派出所不办理门票。"}, "sentence_index": 6, "correct_answer": "户籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给户籍打了一个电话。", "explanation": "这里应该用〈派出所〉。户籍是登记记录，不是可以打电话的机构；打电话要找派出所。"}, {"text": "这个户籍预报很准。", "explanation": "这里应该用〈天气〉。户籍是登记册，不能做预报；“预报很准”要用于天气。"}, {"text": "他在户籍买了很多菜。", "explanation": "这里应该用〈超市〉。户籍不是卖东西的地方，买菜要去超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91343, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一条户籍已经迁到了南京。", "corrected_sentence": "他的户籍已经迁到了南京。", "error_description": "错误：“一条户籍”；正确：“户籍”。户籍是登记，一般不用“条”等量词来数，应直接说“他的户籍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91343, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的一只户籍是去年迁来的。", "corrected_sentence": "他的户籍是去年迁来的。", "error_description": "错误：“一只户籍”；正确：“户籍”。户籍一般不用量词来数，“只”用于动物，应直接说“他的户籍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
