INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91344, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以户为单位登记的居民身份与居住地的册籍。", "primary_collocate": null, "pronunciation": "hù jí", "ipa": "xu˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "警察查了他的户籍资料。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户籍管理是政府的重要工作。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户籍册上有每个居民的名字。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在核对户籍信息。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全村人的户籍都记在这本册子里。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年都会更新户籍。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着户籍证明去办手续。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户籍制度影响着人们的生活。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要看学生的户籍证明。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "户籍登记要写清楚地址。", "target_word": "户籍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "户籍本", "label": "复合"}], "register": "中性", "sense_fingerprint": "户籍：以户为单位登记居民身份与住址的册籍和管理资料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72ce21c1-82f6-40df-91c8-18dde08ef184') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的记录，警察不会查他的食谱资料。"}, {"text": "户籍", "is_correct": true, "explanation": "户籍：居民身份与居住地的登记资料，警察查的正是这类资料。"}, {"text": "风景", "is_correct": false, "explanation": "搭配：“风景资料”不成立，“资料”要说记录人或事情的信息。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是音乐记号，与警察查的身份资料无关。"}], "explanations": {"食谱": "语义：食谱是做菜的记录，警察不会查他的食谱资料。", "户籍": "户籍：居民身份与居住地的登记资料，警察查的正是这类资料。", "风景": "搭配：“风景资料”不成立，“资料”要说记录人或事情的信息。", "乐谱": "语义：乐谱是音乐记号，与警察查的身份资料无关。"}, "sentence_index": 0, "correct_answer": "户籍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士正在照顾户籍。", "explanation": "这里应该用〈病人〉。户籍是登记册，不能被照顾；照顾的对象是人，要用病人。"}, {"text": "他的户籍记录了三次升职。", "explanation": "这里应该用〈档案〉。档案记录工作经历和升职，户籍只登记户口和居住信息，不记录升职。"}, {"text": "工作人员正在洗户籍。", "explanation": "这里应该用〈衣服〉。户籍是登记资料，不能用“洗”；洗的对象要用衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日记", "is_correct": false, "explanation": "语义：日记记录个人想法，没有“日记证明”这种办手续用的文件。"}, {"text": "字帖", "is_correct": false, "explanation": "搭配：“字帖证明”不成立，字帖是练字用的。"}, {"text": "户籍", "is_correct": true, "explanation": "户籍：记居民身份和住址的登记，办手续常要户籍证明。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习的任务，不是办手续要带的文件。"}], "explanations": {"日记": "语义：日记记录个人想法，没有“日记证明”这种办手续用的文件。", "字帖": "搭配：“字帖证明”不成立，字帖是练字用的。", "户籍": "户籍：记居民身份和住址的登记，办手续常要户籍证明。", "作业": "语义：作业是学习的任务，不是办手续要带的文件。"}, "sentence_index": 6, "correct_answer": "户籍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生都做完了户籍。", "explanation": "这里应该用〈练习题〉。户籍是登记资料，不是可以做的题目；“做完”的对象要用练习题。"}, {"text": "这个户籍预报很准。", "explanation": "这里应该用〈天气〉。户籍是登记册，不能做预报；“预报很准”要用于天气。"}, {"text": "他在户籍买了很多菜。", "explanation": "这里应该用〈超市〉。户籍不是卖东西的地方，买菜要去超市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察查了一条他的户籍。", "corrected_sentence": "警察查了他的户籍。", "error_description": "错误：“一条户籍”；正确：“他的户籍”。户籍一般不用“条”等量词来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他早就办好了一只户籍。", "corrected_sentence": "他早就办好了户籍。", "error_description": "错误：“一只户籍”；正确：“户籍”。户籍一般不用量词来数，“只”用于动物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b2ffe84-2ee0-49cf-a988-649173c1b319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
