INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打场是把收来的粮食在场地上弄下粒来。", "primary_collocate": null, "pronunciation": "dǎ cháng", "ipa": "ta˨˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "秋天到了，村里人都在打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸今天一早就去打场了。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "麦子收回来了，明天开始打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打场时，大家用力打麦子。", "target_word": "打场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷年轻时，每年秋天都要打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气好，我们赶快打场吧。", "target_word": "打场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "场上很热闹，大家都在打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们也去帮忙打场，累得满头大汗。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们打场打了一整天，很累。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前没有机器，农民只能用工具打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了场", "label": "体标：了"}, {"form": "打过场", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "把收回来的粮食在场地上弄下粒（动作、过程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补课", "is_correct": false, "explanation": "语义：秋天的农村收获场景与“补课”不合，句子读起来不通。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：「冬眠」是冬季的休眠，与秋天村里人忙收获的语境不合。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”说的是身体状况，与“村里人都在”的集体劳动语境不合。"}, {"text": "打场", "is_correct": true, "explanation": "“打场”指把收回来的粮食在场地上脱粒，符合秋天村里人忙收获的语境。"}], "explanations": {"补课": "语义：秋天的农村收获场景与“补课”不合，句子读起来不通。", "冬眠": "语义：「冬眠」是冬季的休眠，与秋天村里人忙收获的语境不合。", "发烧": "语义：“发烧”说的是身体状况，与“村里人都在”的集体劳动语境不合。", "打场": "“打场”指把收回来的粮食在场地上脱粒，符合秋天村里人忙收获的语境。"}, "sentence_index": 0, "correct_answer": "打场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一下午都在电脑前打场，手指都酸了。", "explanation": "“打场”指在场地上把收来的粮食脱粒，不能用于电脑打字，此处应说“打字”。"}, {"text": "他拿着扫帚，在屋里打场，把地板扫得很干净。", "explanation": "“打场”是处理收回来的粮食，不是打扫房间，此处应说“打扫”。"}, {"text": "奶奶在厨房里打场，把鸡蛋打碎做了一碗蛋汤。", "explanation": "“打场”的对象是粮食，鸡蛋不能用“打场”，此处应说“打鸡蛋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“场上很热闹”与“睡觉”矛盾，大家都睡觉时场上不会热闹。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：热闹的场面与“哭泣”的情绪不协调，句子读起来不通。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：「场上很热闹」与「沉睡」矛盾，大家都在沉睡时场上不会热闹。"}, {"text": "打场", "is_correct": true, "explanation": "“打场”指在场上给收回来的粮食脱粒，符合“场上很热闹”的劳动场景。"}], "explanations": {"睡觉": "语义：“场上很热闹”与“睡觉”矛盾，大家都睡觉时场上不会热闹。", "哭泣": "语义：热闹的场面与“哭泣”的情绪不协调，句子读起来不通。", "沉睡": "语义：「场上很热闹」与「沉睡」矛盾，大家都在沉睡时场上不会热闹。", "打场": "“打场”指在场上给收回来的粮食脱粒，符合“场上很热闹”的劳动场景。"}, "sentence_index": 6, "correct_answer": "打场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天播种以前，农民先把田地打场，才能种庄稼。", "explanation": "“打场”是收割后把粮食摊在场上脱粒，春天播种前整理田地应说“翻地”。"}, {"text": "农民在水里打场，把麦子泡得软软的。", "explanation": "“打场”是在场地上脱粒，此处误把它当成了“浸泡”的意思，应说“浸泡”。"}, {"text": "他在院子里拿起棍子打场，把门口的狗打跑了。", "explanation": "“打场”指粮食的脱粒过程，没有驱赶动物的意思，此处应说“赶走”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们打场完，就把粮食装进了袋子。", "corrected_sentence": "他们打完场，就把粮食装进了袋子。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，说“打完场”，不能说“打场完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91345, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候打场过，知道这活儿很累。", "corrected_sentence": "他小时候打过场，知道这活儿很累。", "error_description": "体标位置错误：经验体“过”应紧跟动词，说“打过场”，不能说“打场过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
