INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91346, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "农民把收割的谷物摊在场上，脱粒后晒干。", "primary_collocate": null, "pronunciation": "dǎ cháng", "ipa": "ta˨˩ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "农民在场上打场，再把粮食晒干。", "target_word": "打场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年麦子多，农民们打场很忙。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打场以后，场上留下很多麦粒。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳很大，正好打场晒粮。", "target_word": "打场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶说，小时候她常帮家里打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里的老人还会用旧方法打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋收以后，家家都在场院打场。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要先打场，才能把谷子装进袋子。", "target_word": "打场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天天晴，农民打场打到天黑。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在很多地方用机器打场，不用人工了。", "target_word": "打场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了场", "label": "体标：了"}, {"form": "打过场", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "农民把收割的谷物摊在场上脱粒并晒干（农事流程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91346, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发芽", "is_correct": false, "explanation": "语义：粮食不会在场上发芽，“农民在场上发芽”读起来不通。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“在场上结婚”与农事流程不合，句子读起来不通。"}, {"text": "拉", "is_correct": false, "explanation": "配价：“拉”需要带宾语，如拉车、拉粮，“在场上拉”不完整。"}, {"text": "打场", "is_correct": true, "explanation": "“打场”指把收割的谷物摊在场上脱粒，之后再晒干，符合句中的农事流程。"}], "explanations": {"发芽": "语义：粮食不会在场上发芽，“农民在场上发芽”读起来不通。", "结婚": "语义：“在场上结婚”与农事流程不合，句子读起来不通。", "拉": "配价：“拉”需要带宾语，如拉车、拉粮，“在场上拉”不完整。", "打场": "“打场”指把收割的谷物摊在场上脱粒，之后再晒干，符合句中的农事流程。"}, "sentence_index": 0, "correct_answer": "打场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天早上去菜市场打场，买了很多菜。", "explanation": "“打场”是农民脱粒晒粮的农事，与去菜市场无关，此处应说“采购”。"}, {"text": "我把一大筐鸡蛋放在桌上打场，然后做了蛋饼。", "explanation": "“打场”的对象是谷物，鸡蛋不能作为打场的对象，此处应说“打蛋”。"}, {"text": "明天要开会，我们先在会议室打场，再讨论计划。", "explanation": "“打场”指在农家场地上脱粒晒粮，不能指在会议室做准备工作，此处应说“布置”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "语义：场院是摊晒粮食的地方，「游泳」与秋收后的劳动场景完全不合。"}, {"text": "种地", "is_correct": false, "explanation": "语义：场院是摊晒粮食的地方，不是耕种的场所，与秋收后的语境不合。"}, {"text": "嫁接", "is_correct": false, "explanation": "语义：「嫁接」是把植物的枝芽接到另一株上，不在场院进行，与秋收后脱粒晒粮的语境不合。"}, {"text": "打场", "is_correct": true, "explanation": "“打场”指在场院把收回来的粮食脱粒，符合秋收之后家家忙碌的场景。"}], "explanations": {"游泳": "语义：场院是摊晒粮食的地方，「游泳」与秋收后的劳动场景完全不合。", "种地": "语义：场院是摊晒粮食的地方，不是耕种的场所，与秋收后的语境不合。", "嫁接": "语义：「嫁接」是把植物的枝芽接到另一株上，不在场院进行，与秋收后脱粒晒粮的语境不合。", "打场": "“打场”指在场院把收回来的粮食脱粒，符合秋收之后家家忙碌的场景。"}, "sentence_index": 6, "correct_answer": "打场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民秋天用镰刀打场，把麦子都割倒了。", "explanation": "“打场”是收割后把粮食脱粒晒干，不是用镰刀割麦子，此处应说“收割”。"}, {"text": "今年春天，农民还没收割，就先去场上打场。", "explanation": "“打场”要在收割之后把粮食脱粒，收割前还不能打场，此处应说“准备场地”。"}, {"text": "他这次考试很用功，每天都在家里打场，成绩进步很大。", "explanation": "“打场”是农事，不能用来形容学习用功，此处应说“复习”或“学习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在场上打场完，再把粮食晒干。", "corrected_sentence": "农民在场上打完场，再把粮食晒干。", "error_description": "补语位置错误：结果补语“完”应紧跟动词，说“打完场”，不能说“打场完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年秋天，他们在场上打场过。", "corrected_sentence": "去年秋天，他们在场上打过场。", "error_description": "体标位置错误：经验体“过”应紧跟动词，说“打过场”，不能说“打场过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
