INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91347, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "心地好，爱帮助别人的人。", "primary_collocate": null, "pronunciation": "hǎo rén", "ipa": "xɑʊ̯˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "邻居王奶奶是个好人，常常帮大家。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个好人，看到老人过马路就去扶。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位好人捡到钱包，马上还给了失主。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的人都说他是好人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人有好报，这句话老人常说。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家遇到困难，他总是第一个帮忙，真是个好人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里有一个好人，每天给流浪猫送饭。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人做了好事，从来不想让别人知道。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多亏一位好人帮忙，我才找到了回家的路。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈总是教我要做一个好人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个好人", "label": "量词"}, {"form": "好人好事", "label": "复合"}], "register": "中性", "sense_fingerprint": "心地好、爱帮助别人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91347, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好人", "is_correct": true, "explanation": "hǎo rén：目标词，指心地好、爱帮助别人的人。"}, {"text": "老人", "is_correct": false, "explanation": "lǎo rén 与 hǎo rén 声母不同（l/h），意思是年纪大的人。"}, {"text": "好认", "is_correct": false, "explanation": "hǎo rèn 与 hǎo rén 第二音节声调不同（第四声与第二声），意思是容易辨认。"}, {"text": "保人", "is_correct": false, "explanation": "bǎo rén 与 hǎo rén 声母不同（b/h），意思是担保人。"}], "explanations": {"好人": "hǎo rén：目标词，指心地好、爱帮助别人的人。", "老人": "lǎo rén 与 hǎo rén 声母不同（l/h），意思是年纪大的人。", "好认": "hǎo rèn 与 hǎo rén 第二音节声调不同（第四声与第二声），意思是容易辨认。", "保人": "bǎo rén 与 hǎo rén 声母不同（b/h），意思是担保人。"}, "sentence_index": null, "correct_answer": "好人"}, "level_3": {"options": [{"text": "好人", "is_correct": true, "explanation": "好人：心地好、爱帮助别人的人，与“常常帮大家”一致。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：“坏人”与“常常帮大家”相矛盾。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“常常帮大家”相矛盾。"}, {"text": "恶人", "is_correct": false, "explanation": "语域：“恶人”语气重、偏书面，与平和的叙述不协调，且同样与“常常帮大家”矛盾。"}], "explanations": {"好人": "好人：心地好、爱帮助别人的人，与“常常帮大家”一致。", "坏人": "语义：“坏人”与“常常帮大家”相矛盾。", "小偷": "语义：“小偷”与“常常帮大家”相矛盾。", "恶人": "语域：“恶人”语气重、偏书面，与平和的叙述不协调，且同样与“常常帮大家”矛盾。"}, "sentence_index": 0, "correct_answer": "好人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵好人开得特别漂亮，大家都来拍照。", "explanation": "这里应该用〈花〉。“好人”指人，不能用来指花。"}, {"text": "这条好人在河里游得很快，孩子们都看呆了。", "explanation": "这里应该用〈鱼〉。“好人”指人，不能用来指鱼。"}, {"text": "这盘好人炒得很香，大家都吃光了。", "explanation": "这里应该用〈菜〉。“好人”指人，不能用来指菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91347, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好人", "is_correct": true, "explanation": "好人：心地好、爱帮助别人的人，与“每天给流浪猫送饭”一致。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：小区里不会有“皇帝”这样的人，句意荒谬。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：“外星人”与日常的小区情境不符，句意荒谬。"}, {"text": "士大夫", "is_correct": false, "explanation": "语域：“士大夫”是古代读书人的称呼，口语叙述中不会这样用。"}], "explanations": {"好人": "好人：心地好、爱帮助别人的人，与“每天给流浪猫送饭”一致。", "皇帝": "语义：小区里不会有“皇帝”这样的人，句意荒谬。", "外星人": "语义：“外星人”与日常的小区情境不符，句意荒谬。", "士大夫": "语域：“士大夫”是古代读书人的称呼，口语叙述中不会这样用。"}, "sentence_index": 6, "correct_answer": "好人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "谢谢你的好人，我心领了。", "explanation": "这里应该用〈好意〉。“好人”指人，表示善意的心意要说〈好意〉。"}, {"text": "她的好人让我很感动。", "explanation": "这里应该用〈好心〉。“好人”指人，形容善良的心要说〈好心〉。"}, {"text": "他出身好人，从小就很努力。", "explanation": "这里应该用〈好人家〉。“出身”后要说“好人家”，指家庭出身好，不能说“好人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91347, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有一条好人，大家都很尊敬他。", "corrected_sentence": "村里有一个好人，大家都很尊敬他。", "error_description": "量词错误：“好人”指人，应用量词“个”，“条”用于细长的东西，不能说“一条好人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91347, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我认识一好人，他每天都去帮助邻居。", "corrected_sentence": "我认识一个好人，他每天都去帮助邻居。", "error_description": "量词漏掉：数量词“一”后面要加量词“个”，应说“一个好人”，不能说“一好人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
