INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91348, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "品行端正、心地善良的人。", "primary_collocate": null, "pronunciation": "hǎo rén", "ipa": "xɑʊ̯˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "他品行端正，大家都说他是好人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人不一定有钱，但一定心地善良。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的好人最后赢了坏人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师常说，做个好人比做个聪明人更重要。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是好人，从来不说谎。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看他样子很凶，其实是个好人。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我相信他是好人，不会做坏事。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子常问，这个人是好人还是坏人？", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好人也会犯错，我们要给他机会。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个好人一辈子都没有做过坏事。", "target_word": "好人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个好人", "label": "量词"}, {"form": "好人好事", "label": "复合"}], "register": "中性", "sense_fingerprint": "品行端正、心地善良的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好人", "is_correct": true, "explanation": "hǎo rén：目标词，指品行端正、心地善良的人。"}, {"text": "老人", "is_correct": false, "explanation": "lǎo rén 与 hǎo rén 声母不同（l/h），意思是年纪大的人。"}, {"text": "好认", "is_correct": false, "explanation": "hǎo rèn 与 hǎo rén 第二音节声调不同（第四声与第二声），意思是容易辨认。"}, {"text": "保人", "is_correct": false, "explanation": "bǎo rén 与 hǎo rén 声母不同（b/h），意思是担保人。"}], "explanations": {"好人": "hǎo rén：目标词，指品行端正、心地善良的人。", "老人": "lǎo rén 与 hǎo rén 声母不同（l/h），意思是年纪大的人。", "好认": "hǎo rèn 与 hǎo rén 第二音节声调不同（第四声与第二声），意思是容易辨认。", "保人": "bǎo rén 与 hǎo rén 声母不同（b/h），意思是担保人。"}, "sentence_index": null, "correct_answer": "好人"}, "level_3": {"options": [{"text": "好人", "is_correct": true, "explanation": "好人：品行端正、心地善良的人，与“品行端正”一致。"}, {"text": "骗子", "is_correct": false, "explanation": "语义：“骗子”与“品行端正”相矛盾。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：“小偷”与“品行端正”相矛盾。"}, {"text": "奸人", "is_correct": false, "explanation": "语域：“奸人”偏书面、语气重，且与“品行端正”相矛盾。"}], "explanations": {"好人": "好人：品行端正、心地善良的人，与“品行端正”一致。", "骗子": "语义：“骗子”与“品行端正”相矛盾。", "小偷": "语义：“小偷”与“品行端正”相矛盾。", "奸人": "语域：“奸人”偏书面、语气重，且与“品行端正”相矛盾。"}, "sentence_index": 0, "correct_answer": "好人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏好人照亮了整个房间，大家都很感激。", "explanation": "这里应该用〈灯〉。“好人”指人，不能用来指灯。"}, {"text": "他的好人让我很感动。", "explanation": "这里应该用〈善意〉。“好人”指人，表示善意要说〈善意〉。"}, {"text": "这块好人闪闪发光，像天上的星星。", "explanation": "这里应该用〈宝石〉。“好人”指人，不能用来指宝石。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91348, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好人", "is_correct": true, "explanation": "好人：品行端正、心地善良的人，与“不会做坏事”一致。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：“坏人”与“不会做坏事”自相矛盾。"}, {"text": "恶棍", "is_correct": false, "explanation": "语域：“恶棍”偏书面，口语里不会这样评价朋友。"}, {"text": "凶手", "is_correct": false, "explanation": "语义：“凶手”指杀人的人，与“不会做坏事”相矛盾。"}], "explanations": {"好人": "好人：品行端正、心地善良的人，与“不会做坏事”一致。", "坏人": "语义：“坏人”与“不会做坏事”自相矛盾。", "恶棍": "语域：“恶棍”偏书面，口语里不会这样评价朋友。", "凶手": "语义：“凶手”指杀人的人，与“不会做坏事”相矛盾。"}, "sentence_index": 6, "correct_answer": "好人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你的好人我很感激，谢谢。", "explanation": "这里应该用〈好意〉。“好人”指人，表示善意的心意要说〈好意〉。"}, {"text": "他对邻居的好人让人感动。", "explanation": "这里应该用〈好心〉。“好人”指人，形容善良的心要说〈好心〉。"}, {"text": "他出身好人，家里很有钱。", "explanation": "这里应该用〈好人家〉。“出身”后要说“好人家”，指家庭出身好，不能说“好人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父亲常说，做条好人最重要。", "corrected_sentence": "父亲常说，做个好人最重要。", "error_description": "量词错误：“好人”指人，应用量词“个”，不能用“条”，应说“做个好人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我爸爸是一好人，他从不说谎。", "corrected_sentence": "我爸爸是一个好人，他从不说谎。", "error_description": "量词漏掉：数量词“一”后面要加量词“个”，应说“一个好人”，不能说“一好人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
