INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91349, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "批发是一次买进很多东西，价钱比零买便宜。", "primary_collocate": null, "pronunciation": "pī fā", "ipa": "pʰi˥ fa˥", "syllable_count": 2, "sentences": [{"text": "开店以前，他先去工厂批发了一些货。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市场批发了一百件衣服。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每次都去市场批发水果，比在超市买便宜很多。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想批发一些笔，送给学生。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个月去那家店批发玩具。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批发的东西多，价钱就低一点。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，批发十个以上可以打折。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的小店从大市场批发饮料。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他批发过很多年的蔬菜。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想批发的话，请先打电话问一下。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "批发了", "label": "体标"}, {"form": "批发过", "label": "体标"}, {"form": "批发商", "label": "复合"}], "register": "中性", "sense_fingerprint": "一次买进很多东西，价钱比零买便宜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91349, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批发", "is_correct": true, "explanation": "pī fā，一次买卖很多东西，价钱比较便宜，即本义。"}, {"text": "疲乏", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，fá 与 fā 声调也不同，意思是身体没有力气。"}, {"text": "贫乏", "is_correct": false, "explanation": "pín 比 pī 多一个韵尾 n，声调也不同；fá 与 fā 声调不同，意思是缺少、不足。"}, {"text": "拼法", "is_correct": false, "explanation": "pīn 比 pī 多一个韵尾 n，fǎ（第三声）与 fā（第一声）声调不同，意思是拼写的方法。"}], "explanations": {"批发": "pī fā，一次买卖很多东西，价钱比较便宜，即本义。", "疲乏": "pí（第二声）与 pī（第一声）声调不同，fá 与 fā 声调也不同，意思是身体没有力气。", "贫乏": "pín 比 pī 多一个韵尾 n，声调也不同；fá 与 fā 声调不同，意思是缺少、不足。", "拼法": "pīn 比 pī 多一个韵尾 n，fǎ（第三声）与 fā（第一声）声调不同，意思是拼写的方法。"}, "sentence_index": null, "correct_answer": "批发"}, "level_3": {"options": [{"text": "招聘", "is_correct": false, "explanation": "语义：招聘的对象是人，不能说“招聘了一些货”。"}, {"text": "批发", "is_correct": true, "explanation": "批发：一次买进很多货，开店前进货，符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”不能带“货”作宾语，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”与进货无关，不能带“货”。"}], "explanations": {"招聘": "语义：招聘的对象是人，不能说“招聘了一些货”。", "批发": "批发：一次买进很多货，开店前进货，符合句意。", "唱歌": "语义：“唱歌”不能带“货”作宾语，句意不通。", "洗澡": "语义：“洗澡”与进货无关，不能带“货”。"}, "sentence_index": 0, "correct_answer": "批发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市批发了一瓶矿泉水。", "explanation": "这里应该用〈买〉。批发是成批买卖，买一瓶水属于零买，不能说“批发”。"}, {"text": "我在小卖部批发了一块口香糖。", "explanation": "这里应该用〈买〉。批发是一次买进很多，只买一块属于零买。"}, {"text": "我决定批发你的建议。", "explanation": "这里应该用〈采纳〉。批发只用于商品，建议不是货物，要说“采纳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91349, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "零卖", "is_correct": false, "explanation": "语义：零卖是一件一件地卖，与“十个以上”的大批量相矛盾。"}, {"text": "退", "is_correct": false, "explanation": "语义：“退”是退还，句中说的是买卖优惠，不合句意。"}, {"text": "批发", "is_correct": true, "explanation": "批发：成批买卖，“十个以上”正说明数量大，才能打折。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”是留存物品，不能和“十个以上可以打折”这样的买卖条件搭配。"}], "explanations": {"零卖": "语义：零卖是一件一件地卖，与“十个以上”的大批量相矛盾。", "退": "语义：“退”是退还，句中说的是买卖优惠，不合句意。", "批发": "批发：成批买卖，“十个以上”正说明数量大，才能打折。", "收藏": "搭配：“收藏”是留存物品，不能和“十个以上可以打折”这样的买卖条件搭配。"}, "sentence_index": 6, "correct_answer": "批发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他批发了一张电影票。", "explanation": "这里应该用〈买〉。批发是大量买进，一张票只能说“买”。"}, {"text": "我批发了一个面包，当早饭吃。", "explanation": "这里应该用〈买〉。批发是成批买卖，只买一个面包属于零买，不能说“批发”。"}, {"text": "这种衣服在商场批发得很贵。", "explanation": "这里应该用〈卖〉。批发的价钱本来较低，说“批发得很贵”与词义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91349, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们店从工厂批发得一批鞋子。", "corrected_sentence": "我们店从工厂批发了一批鞋子。", "error_description": "错误：“批发”后用了“得”，动词缺少补语，句子不通；正确：用“了”，说“从工厂批发了一批鞋子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91349, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们厂把衣服批发外地的商家。", "corrected_sentence": "我们厂把衣服批发给外地的商家。", "error_description": "错误：漏掉了“给”；正确：“批发”后面要带接收方，应说“批发给外地的商家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生产", "is_correct": false, "explanation": "生产是制造物品，与批发不是反义词。"}, {"text": "零售", "is_correct": true, "explanation": "零售与批发是一对反义词：批发是成批卖给零售商，零售是直接卖给消费者。"}, {"text": "运输", "is_correct": false, "explanation": "运输是运送货物，与批发不构成反义关系。"}, {"text": "存放", "is_correct": false, "explanation": "存放是把东西放在某处保存，与批发没有反义关系。"}], "correct_answer": "零售", "explanations": {"生产": "生产是制造物品，与批发不是反义词。", "零售": "零售与批发是一对反义词：批发是成批卖给零售商，零售是直接卖给消费者。", "运输": "运输是运送货物，与批发不构成反义关系。", "存放": "存放是把东西放在某处保存，与批发没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收藏", "is_correct": false, "explanation": "收藏是留存物品，与批发不构成反义关系。"}, {"text": "零售", "is_correct": true, "explanation": "零售与批发是一对反义词：批发是成批卖给零售商，零售是直接卖给消费者。"}, {"text": "印刷", "is_correct": false, "explanation": "印刷是把文字图像印在纸上，与批发没有反义关系。"}, {"text": "租借", "is_correct": false, "explanation": "租借是暂时使用别人的东西，与批发不构成反义关系。"}], "correct_answer": "零售", "explanations": {"收藏": "收藏是留存物品，与批发不构成反义关系。", "零售": "零售与批发是一对反义词：批发是成批卖给零售商，零售是直接卖给消费者。", "印刷": "印刷是把文字图像印在纸上，与批发没有反义关系。", "租借": "租借是暂时使用别人的东西，与批发不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "成批地出售商品，多卖给零售商。", "primary_collocate": null, "pronunciation": "pī fā", "ipa": "pʰi˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这家工厂把鞋批发给各地的小店。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老板在城里批发水果。", "target_word": "批发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司只批发，不卖给个人。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他批发了很多年的茶叶。", "target_word": "批发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店白天批发，晚上零售。", "target_word": "批发", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂家把新手机批发给零售商。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家批发家用电器，生意很好。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李批发蔬菜给附近的饭馆。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批货批发出去以后，小店老板很快就卖完了。", "target_word": "批发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老板专门批发文具。", "target_word": "批发", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "批发了", "label": "体标"}, {"form": "批发过", "label": "体标"}, {"form": "批发商", "label": "复合"}], "register": "中性", "sense_fingerprint": "成批出售商品，对象多是零售商", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "批发", "is_correct": true, "explanation": "pī fā，成批地卖给零售商，即本义。"}, {"text": "疲乏", "is_correct": false, "explanation": "pí（第二声）与 pī（第一声）声调不同，fá 与 fā 声调也不同，意思是身体没有力气。"}, {"text": "贫乏", "is_correct": false, "explanation": "pín 比 pī 多一个韵尾 n，声调也不同；fá 与 fā 声调不同，意思是缺少、不足。"}, {"text": "拼法", "is_correct": false, "explanation": "pīn 比 pī 多一个韵尾 n，fǎ（第三声）与 fā（第一声）声调不同，意思是拼写的方法。"}], "explanations": {"批发": "pī fā，成批地卖给零售商，即本义。", "疲乏": "pí（第二声）与 pī（第一声）声调不同，fá 与 fā 声调也不同，意思是身体没有力气。", "贫乏": "pín 比 pī 多一个韵尾 n，声调也不同；fá 与 fā 声调不同，意思是缺少、不足。", "拼法": "pīn 比 pī 多一个韵尾 n，fǎ（第三声）与 fā（第一声）声调不同，意思是拼写的方法。"}, "sentence_index": null, "correct_answer": "批发"}, "level_3": {"options": [{"text": "收购", "is_correct": false, "explanation": "语义：“收购”是向别人买进，句中工厂是把鞋卖给小店，方向相反。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是留存物品，与“给各地的小店”的送出方向不合。"}, {"text": "购买", "is_correct": false, "explanation": "语义：“购买”是买方的动作，句中工厂是卖方，方向相反。"}, {"text": "批发", "is_correct": true, "explanation": "批发：成批卖给，与“把鞋……给各地的小店”相合。"}], "explanations": {"收购": "语义：“收购”是向别人买进，句中工厂是把鞋卖给小店，方向相反。", "收藏": "语义：“收藏”是留存物品，与“给各地的小店”的送出方向不合。", "购买": "语义：“购买”是买方的动作，句中工厂是卖方，方向相反。", "批发": "批发：成批卖给，与“把鞋……给各地的小店”相合。"}, "sentence_index": 0, "correct_answer": "批发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在小店批发了一颗糖。", "explanation": "这里应该用〈买〉。批发是成批买卖，买一颗糖属于零买，不能说“批发”。"}, {"text": "她把饮料批发给一位顾客。", "explanation": "这里应该用〈卖给〉。批发的对象是零售商，卖给一位顾客要说“卖给”。"}, {"text": "我批发了一箱饮料，自己慢慢喝。", "explanation": "这里应该用〈订〉。批发是为了转卖，自己喝的东西要说“订”，不能说“批发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "培养", "is_correct": false, "explanation": "搭配：“培养”的对象多为人或能力，不能用于家用电器。"}, {"text": "批发", "is_correct": true, "explanation": "批发：成批卖出，与“生意很好”相合，符合句意。"}, {"text": "赔偿", "is_correct": false, "explanation": "语义：“赔偿”是补偿损失，与“生意很好”的意思相矛盾。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与“生意很好”的经营语境相矛盾。"}], "explanations": {"培养": "搭配：“培养”的对象多为人或能力，不能用于家用电器。", "批发": "批发：成批卖出，与“生意很好”相合，符合句意。", "赔偿": "语义：“赔偿”是补偿损失，与“生意很好”的意思相矛盾。", "偷": "语义：“偷”是窃取，与“生意很好”的经营语境相矛盾。"}, "sentence_index": 6, "correct_answer": "批发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位老板很快批发了我的建议。", "explanation": "这里应该用〈采纳〉。批发只用于商品，建议不是货物，要说“采纳”。"}, {"text": "他在书店批发了一本词典，留着自己用。", "explanation": "这里应该用〈买〉。批发是成批买卖，只为自己留用的一本书要说“买”，不能说“批发”。"}, {"text": "这些文具在小店批发得很贵。", "explanation": "这里应该用〈卖〉。批发的价钱本来较低，说“批发得很贵”与词义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们上个月批发得五十箱饮料。", "corrected_sentence": "他们上个月批发了五十箱饮料。", "error_description": "错误：“批发”后用了“得”，动词缺少补语，句子不通；正确：用“了”，说“批发了五十箱饮料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91350, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老赵每天把蔬菜批发附近的饭馆。", "corrected_sentence": "老赵每天把蔬菜批发给附近的饭馆。", "error_description": "错误：漏掉了“给”；正确：“批发”后面要带接收方，应说“批发给附近的饭馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终", "is_correct": true, "explanation": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。"}, {"text": "看", "is_correct": false, "explanation": "“看”指视觉动作，与“开始”没有反义关系。"}, {"text": "留", "is_correct": false, "explanation": "“留”指停留或保存，与“开始”没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”指进食，与“开始”没有反义关系。"}], "correct_answer": "终", "explanations": {"终": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。", "看": "“看”指视觉动作，与“开始”没有反义关系。", "留": "“留”指停留或保存，与“开始”没有反义关系。", "吃": "“吃”指进食，与“开始”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "终", "is_correct": true, "explanation": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。"}, {"text": "坐", "is_correct": false, "explanation": "“坐”指身体停留在椅子等物上，与“开始”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“开始”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指书写文字，与“开始”没有反义关系。"}], "correct_answer": "终", "explanations": {"终": "“始”与“终”是反义：“始”指开头，“终”指结尾，如“有始有终”。", "坐": "“坐”指身体停留在椅子等物上，与“开始”没有反义关系。", "跑": "“跑”指快速移动，与“开始”没有反义关系。", "写": "“写”指书写文字，与“开始”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始；起头。", "primary_collocate": null, "pronunciation": "shǐ", "ipa": "ʂɻ̩˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个故事始于一个雨天。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春节的习俗始于很久以前。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的旅行始于北京。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河始于西边的雪山。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一切都始于一个小小的想法。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成功始于每天早起。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这段友谊始于小学。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会议始于下午两点，止于五点。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项比赛始于一百多年前。", "target_word": "始", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大雪始于昨天晚上。", "target_word": "始", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "开始", "label": "复合"}, {"form": "起始", "label": "复合"}], "register": "书面语", "sense_fingerprint": "始：开始、起头，常见于“始于…”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a68bebce-125a-410b-b066-2e5bc672fe83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "始", "is_correct": true, "explanation": "正确答案。“始”读 shǐ（第三声），意思是开始。"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“是”。"}, {"text": "事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“事情”。"}, {"text": "市", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“城市”。"}, {"text": "石", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是“石头”。"}], "explanations": {"始": "正确答案。“始”读 shǐ（第三声），意思是开始。", "是": "shì（第四声）与 shǐ（第三声）声调不同，意思是“是”。", "事": "shì（第四声）与 shǐ（第三声）声调不同，意思是“事情”。", "市": "shì（第四声）与 shǐ（第三声）声调不同，意思是“城市”。", "石": "shí（第二声）与 shǐ（第三声）声调不同，意思是“石头”。"}, "sentence_index": null, "correct_answer": "始"}, "level_3": {"options": [{"text": "始", "is_correct": true, "explanation": "“始于”表示开始于某个时间或地点，与题干“故事”的开端语境相符。"}, {"text": "属", "is_correct": false, "explanation": "搭配：“属于”表示归属，不能说故事属于一个雨天。"}, {"text": "归", "is_correct": false, "explanation": "语义：“归于”指最终归向或归属，与故事的开端不合。"}, {"text": "集", "is_correct": false, "explanation": "语义：“集于”指聚集，故事不能聚集在一个雨天。"}], "explanations": {"始": "“始于”表示开始于某个时间或地点，与题干“故事”的开端语境相符。", "属": "搭配：“属于”表示归属，不能说故事属于一个雨天。", "归": "语义：“归于”指最终归向或归属，与故事的开端不合。", "集": "语义：“集于”指聚集，故事不能聚集在一个雨天。"}, "sentence_index": 0, "correct_answer": "始"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛始于终点。", "explanation": "“始于”后要接起点，“终点”是结束的地方，不能作起点。"}, {"text": "这段友谊始于结束。", "explanation": "“始于”后要接起点，“结束”是终点，不能作起点。"}, {"text": "这段旅程始于结局。", "explanation": "“始于”后要接起点，“结局”是结束的状态，不能作起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "始", "is_correct": true, "explanation": "正确答案。“始”读 shǐ（第三声），意思是开始。"}, {"text": "世", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“世界”。"}, {"text": "试", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“尝试”。"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是“数字十”。"}, {"text": "室", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是“房间”。"}], "explanations": {"始": "正确答案。“始”读 shǐ（第三声），意思是开始。", "世": "shì（第四声）与 shǐ（第三声）声调不同，意思是“世界”。", "试": "shì（第四声）与 shǐ（第三声）声调不同，意思是“尝试”。", "十": "shí（第二声）与 shǐ（第三声）声调不同，意思是“数字十”。", "室": "shì（第四声）与 shǐ（第三声）声调不同，意思是“房间”。"}, "sentence_index": null, "correct_answer": "始"}, "level_3": {"options": [{"text": "始", "is_correct": true, "explanation": "“始于”表示开始于某个时间，与题干“友谊”的开端语境相符。"}, {"text": "落", "is_correct": false, "explanation": "语义：“落于”指降落、落在某处，友谊不能落在小学。"}, {"text": "置", "is_correct": false, "explanation": "搭配：“置于”用于物体的放置，友谊不能被放置于小学。"}, {"text": "陷", "is_correct": false, "explanation": "语义：“陷于”指陷入某种困境，与友谊开始于小学的语境不合。"}], "explanations": {"始": "“始于”表示开始于某个时间，与题干“友谊”的开端语境相符。", "落": "语义：“落于”指降落、落在某处，友谊不能落在小学。", "置": "搭配：“置于”用于物体的放置，友谊不能被放置于小学。", "陷": "语义：“陷于”指陷入某种困境，与友谊开始于小学的语境不合。"}, "sentence_index": 6, "correct_answer": "始"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的爱情始于告别。", "explanation": "“始于”后要接起点，“告别”是结束，不能作起点。"}, {"text": "这份工作始于退休。", "explanation": "“始于”后要接起点，“退休”是结束，不能作起点。"}, {"text": "这个故事始于谢幕。", "explanation": "“始于”后要接起点，“谢幕”是演出结束的时候，不能作起点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd360a919-9abe-40f8-8f86-b56d07902ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
