INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91353, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找回是把丢了的东西找到并拿回来。", "primary_collocate": null, "pronunciation": "zhǎo huí", "ipa": "ʈʂaʊ˨˩˦ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我终于找回了丢掉的钱包。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在公园找回了他的帽子。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察帮她找回了手机。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在车里找回了钥匙。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找回去年丢的那本书。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师帮学生找回了丢失的作业本。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭着说想找回爸爸送的手表。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你帮我找回了书包。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在雪地里找回了孩子的手套。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没有找回那只猫。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "找回了", "label": "体标"}, {"form": "找回过", "label": "体标"}], "register": "中性", "sense_fingerprint": "找到丢失的具体物品并拿回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91353, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找回", "is_correct": true, "explanation": "“找回”指把丢了的东西找到并拿回来，符合“丢掉的钱包”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：钱包不能吃，句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“钱包”作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：钱包不能煮，句意不合。"}], "explanations": {"找回": "“找回”指把丢了的东西找到并拿回来，符合“丢掉的钱包”。", "吃": "语义：钱包不能吃，句意不合。", "唱": "配价：“唱”不能以“钱包”作宾语。", "煮": "语义：钱包不能煮，句意不合。"}, "sentence_index": 0, "correct_answer": "找回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书店找回了一本新书。", "explanation": "这里应该用〈找到〉。“找回”指找回原来丢了的东西，第一次发现的东西要用〈找到〉。"}, {"text": "他找回了一张从未见过的地图。", "explanation": "这里应该用〈得到〉。“找回”要求东西曾经属于自己，从未有过的东西要用〈得到〉。"}, {"text": "科学家找回了一颗新星。", "explanation": "这里应该用〈发现〉。“找回”只用于找回失去的东西，第一次发现的天体要用〈发现〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找回", "is_correct": true, "explanation": "“找回”指把丢失的东西重新拿回，符合“想……爸爸送的手表”。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的宾语应为声音，不能说“听手表”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：手表不能咬，句意不合。"}, {"text": "闻", "is_correct": false, "explanation": "语义：手表不能闻，句意不合。"}], "explanations": {"找回": "“找回”指把丢失的东西重新拿回，符合“想……爸爸送的手表”。", "听": "搭配：“听”的宾语应为声音，不能说“听手表”。", "咬": "语义：手表不能咬，句意不合。", "闻": "语义：手表不能闻，句意不合。"}, "sentence_index": 6, "correct_answer": "找回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找回了被烧毁的房子。", "explanation": "这里应该用〈重建〉。“找回”只用于找到失去的东西，已被烧毁的房子要用〈重建〉。"}, {"text": "我找回了昨天的会议。", "explanation": "这里应该用〈参加〉。“找回”只用于找回丢失的东西，会议是活动，要说〈参加〉。"}, {"text": "他找回了那场精彩的比赛。", "explanation": "这里应该用〈观看〉。「找回」只用于找到丢失的东西，比赛是活动，应说〈观看〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没找回了那只丢失的手表。", "corrected_sentence": "他找回了那只丢失的手表。", "error_description": "错误在“没”与“了”同时出现：“没”否定已发生的动作时，动词后不能再带“了”。若要否定，说“他没找回那只丢失的手表。”；若要陈述已找回，说“他找回了那只丢失的手表。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天终于找回着那只猫。", "corrected_sentence": "我昨天终于找回了那只猫。", "error_description": "错误在体标：“找回”表示已完成的结果，应用“了”。“着”表示持续的状态，不能用于已完成的找回，错误形式“找回着”，正确形式为“找回了那只猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
