INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使失去的自信、记忆、状态、面子等重新回来。", "primary_collocate": null, "pronunciation": "zhǎo huí", "ipa": "ʈʂaʊ˨˩˦ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他想找回失去的自信。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过努力，她找回了往日的笑容。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人慢慢找回了过去的记忆。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队终于找回了比赛的状态。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想找回对生活的热情。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次旅行让我找回了平静。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用好成绩找回了面子。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要找回丢掉的好习惯。", "target_word": "找回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用三年时间找回了健康。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话帮我找回了信心。", "target_word": "找回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "找回了", "label": "体标"}, {"form": "找回过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使失去的自信、记忆、状态等重新回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "找回", "is_correct": true, "explanation": "“找回”指使失去的东西重新回来，符合“失去的自信”。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”说数量的增长，已失去的自信要说“找回”，不能说“增加失去的自信”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“自信”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“自信”这类抽象名词作宾语。"}], "explanations": {"找回": "“找回”指使失去的东西重新回来，符合“失去的自信”。", "增加": "语义：“增加”说数量的增长，已失去的自信要说“找回”，不能说“增加失去的自信”。", "吃": "搭配：“吃”不能与“自信”搭配。", "唱": "配价：“唱”不能以“自信”这类抽象名词作宾语。"}, "sentence_index": 0, "correct_answer": "找回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他找回了桌上的一道裂痕。", "explanation": "这里应该用〈修补〉。“找回”指失去的状态重新回来，裂痕是新出现的损伤，应说〈修补〉。"}, {"text": "他找回了身上的伤。", "explanation": "这里应该用〈治愈〉。“找回”用于曾经有过又失去的状态，伤口要说〈治愈〉。"}, {"text": "我今天找回了一台新电脑。", "explanation": "这里应该用〈买到〉。“找回”要求东西曾经失去，新买的东西要用〈买到〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "找回", "is_correct": true, "explanation": "“找回”指使失去的面子重新回来，符合“用好成绩”的语境。"}, {"text": "丢", "is_correct": false, "explanation": "语义：“丢”与“好成绩”语义相反，用好成绩不能“丢面子”。"}, {"text": "写", "is_correct": false, "explanation": "语义：面子不能写，句意不合。"}, {"text": "切", "is_correct": false, "explanation": "配价：“切”不能以“面子”作宾语。"}], "explanations": {"找回": "“找回”指使失去的面子重新回来，符合“用好成绩”的语境。", "丢": "语义：“丢”与“好成绩”语义相反，用好成绩不能“丢面子”。", "写": "语义：面子不能写，句意不合。", "切": "配价：“切”不能以“面子”作宾语。"}, "sentence_index": 6, "correct_answer": "找回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们找回了那场比赛。", "explanation": "这里应该用〈参加〉。“找回”用于重新获得的状态或失物，比赛是活动，要说〈参加〉。"}, {"text": "他找回了那片大海。", "explanation": "这里应该用〈望见〉。“找回”用于能重新拥有的东西，大海是自然景物，只能说〈望见〉。"}, {"text": "朋友的话帮我找回了身高。", "explanation": "这里应该用〈长高〉。“找回”用于曾经有过又失去的状态，身高不能失而复得，要说〈长高〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于找回着一个灿烂的笑容。", "corrected_sentence": "她终于找回了一个灿烂的笑容。", "error_description": "错误在体标：“找回”表示已完成的结果，应用“了”。“着”表示持续的状态，不能用于已完成的找回，错误形式“找回着”，正确形式为“找回了一个灿烂的笑容”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还是没找回了往日的信心。", "corrected_sentence": "他还是没找回往日的信心。", "error_description": "错误在“没”与“了”同时出现：用“没”否定“找回”时，动词后不能再带“了”。错误形式“没找回了”，正确形式为“没找回往日的信心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
