INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多学生一起出来，大声说出自己的想法。", "primary_collocate": null, "pronunciation": "xué shēng yùn dòng", "ipa": "ɕɥe˧˥ ʂɤŋ˥ yn˥˩ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "为了保护校园的树，同学们发起了一场学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生运动里，大家举着牌子大声说话。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到学生运动的照片，我也想说出自己的想法。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想取消假期，同学们就开始了学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生运动那天，街上有很多年轻人。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在学生运动中喊着口号。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场学生运动一点也不乱。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈担心我参加学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生运动不是玩，大家都很认真。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师支持学生运动，因为学生说的有道理。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场学生运动", "label": "量词"}, {"form": "学生運動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多学生一起走出来表达自己的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生运动", "is_correct": true, "explanation": "“同学们发起了一场”描述集体行动，与“为了保护校园的树”的诉求相符。"}, {"text": "感冒", "is_correct": false, "explanation": "搭配：“发起”用于活动或倡议，“感冒”是疾病，不能发起，也与句中的诉求无关。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“发起”用于活动或倡议，不能发起“天气”。"}, {"text": "打闹", "is_correct": false, "explanation": "语义：“打闹”没有保护树木这样的诉求，与句中的目的不符。"}], "explanations": {"学生运动": "“同学们发起了一场”描述集体行动，与“为了保护校园的树”的诉求相符。", "感冒": "搭配：“发起”用于活动或倡议，“感冒”是疾病，不能发起，也与句中的诉求无关。", "天气": "搭配：“发起”用于活动或倡议，不能发起“天气”。", "打闹": "语义：“打闹”没有保护树木这样的诉求，与句中的目的不符。"}, "sentence_index": 0, "correct_answer": "学生运动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班在教室里安静地进行了一场学生运动，大家都在做题。", "explanation": "这里应该用〈自习〉。学生运动要求大家大声说出想法，安静做题不属于此类。"}, {"text": "学校请专家做了一场学生运动。", "explanation": "这里应该用〈讲座〉。学生运动是学生的集体行动，不是专家的讲座。"}, {"text": "他每天早上都在公园里跑步，这种锻炼就是他的学生运动。", "explanation": "这里应该用〈晨练〉。学生运动要求大家大声说出想法，跑步锻炼不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生运动", "is_correct": true, "explanation": "“一点也不乱”描述有组织的集体行动，与学生运动的语义相符。"}, {"text": "地震", "is_correct": false, "explanation": "语义：“一点也不乱”说的是有秩序的集体行动，地震不能这样评价。"}, {"text": "雨", "is_correct": false, "explanation": "配价：“乱”描述人群或行动的状态，不能作为雨的谓语。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能用“一点也不乱”来形容。"}], "explanations": {"学生运动": "“一点也不乱”描述有组织的集体行动，与学生运动的语义相符。", "地震": "语义：“一点也不乱”说的是有秩序的集体行动，地震不能这样评价。", "雨": "配价：“乱”描述人群或行动的状态，不能作为雨的谓语。", "感冒": "语义：“感冒”是疾病，不能用“一点也不乱”来形容。"}, "sentence_index": 6, "correct_answer": "学生运动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们举行了一场学生运动，要求提高工资。", "explanation": "这里应该用〈示威〉。学生运动特指学生参加的运动，工人的集会示威不属于此类。"}, {"text": "学校举办了一场学生运动，大家都很开心。", "explanation": "这里应该用〈晚会〉。学生运动是学生表达想法的运动，不是联欢活动。"}, {"text": "他在医院里进行了一场学生运动，医生们都很忙。", "explanation": "这里应该用〈手术〉。学生运动要求很多学生大声说出想法，医院里的手术不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们为了抗议取消假期，发起了一条学生运动。", "corrected_sentence": "同学们为了抗议取消假期，发起了一场学生运动。", "error_description": "量词错误：“学生运动”应用量词“场”，“条”用于细长的事物，不能修饰运动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在操场上集合，决定发起一把学生运动。", "corrected_sentence": "同学们在操场上集合，决定发起一场学生运动。", "error_description": "量词错误：“学生运动”应用量词“场”，“把”用于有柄的物件，不能修饰运动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
