INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由学生发起并参加的、具有政治或社会诉求的群众性运动。", "primary_collocate": null, "pronunciation": "xué shēng yùn dòng", "ipa": "ɕɥe˧˥ ʂɤŋ˥ yn˥˩ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "一九一九年的五四运动是一次学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场学生运动要求政府改变政策。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里写了很多关于学生运动的故事。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生运动让社会听到了年轻人的声音。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一年，全国的城市都有学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了那次学生运动的原因。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时参加过学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次学生运动一直没有停下来。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生运动开始以后，很多工人也来支持。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一本书，介绍当年的学生运动。", "target_word": "学生运动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场学生运动", "label": "量词"}, {"form": "学生運動", "label": "繁体"}], "register": "书面", "sense_fingerprint": "学生发起、带有政治或社会诉求的群众运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生运动", "is_correct": true, "explanation": "五四运动本身就是学生发起的群众运动，“一次学生运动”与句中的历史事件相符。"}, {"text": "体育运动", "is_correct": false, "explanation": "语义：五四运动是有政治诉求的学生运动，不是体育活动，句子与史实相悖。"}, {"text": "文化", "is_correct": false, "explanation": "搭配：“一次”用于可计数的活动，“文化”是抽象概念，不能说“一次文化”。"}, {"text": "事儿", "is_correct": false, "explanation": "语域：“事儿”是口语词，与这句书面的历史叙述不符，“一次事儿”搭配也不自然。"}], "explanations": {"学生运动": "五四运动本身就是学生发起的群众运动，“一次学生运动”与句中的历史事件相符。", "体育运动": "语义：五四运动是有政治诉求的学生运动，不是体育活动，句子与史实相悖。", "文化": "搭配：“一次”用于可计数的活动，“文化”是抽象概念，不能说“一次文化”。", "事儿": "语域：“事儿”是口语词，与这句书面的历史叙述不符，“一次事儿”搭配也不自然。"}, "sentence_index": 0, "correct_answer": "学生运动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天都做学生运动，身体很好。", "explanation": "这里应该用〈体育运动〉。学生运动指学生发起的有政治或社会诉求的群众运动，不指锻炼身体，也不能说“做”。"}, {"text": "工人们举行学生运动，要求提高工资。", "explanation": "这里应该用〈罢工〉。学生运动特指学生参加的运动，工人集体停工要说罢工。"}, {"text": "市民们在广场上进行学生运动，要求改善交通。", "explanation": "这里应该用〈抗议活动〉。学生运动只指学生发起并参加的运动，市民的集体抗议不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生运动", "is_correct": true, "explanation": "“参加过”与学生运动这种集体活动搭配，符合“他年轻时参加过”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“参加”用于活动或组织，不能说参加“天气”。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不是可以参加的活动，与句中的“参加过”语义冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语词，不适合这种书面叙述的语气，也不能被“参加”。"}], "explanations": {"学生运动": "“参加过”与学生运动这种集体活动搭配，符合“他年轻时参加过”的语境。", "天气": "搭配：“参加”用于活动或组织，不能说参加“天气”。", "饭菜": "语义：“饭菜”不是可以参加的活动，与句中的“参加过”语义冲突。", "玩意儿": "语域：“玩意儿”是口语词，不适合这种书面叙述的语气，也不能被“参加”。"}, "sentence_index": 6, "correct_answer": "学生运动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板让员工进行学生运动，不然就扣奖金。", "explanation": "这里应该用〈加班〉。学生运动由学生发起并参加，员工被要求的额外工作不属于此类。"}, {"text": "村里举行了一场学生运动，村民都来投票。", "explanation": "这里应该用〈选举〉。学生运动指学生参加的运动，村里的投票不属于学生运动。"}, {"text": "学校为了庆祝元旦，举办了一场学生运动，大家都很开心。", "explanation": "这里应该用〈联欢会〉。学生运动有政治或社会诉求，联欢活动不属于此类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那一年，全国发生了一条学生运动。", "corrected_sentence": "那一年，全国发生了一场学生运动。", "error_description": "量词错误：“学生运动”应用量词“场”，应说“一场学生运动”；“条”用于细长的事物，不能修饰运动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在大学时参加过一位学生运动。", "corrected_sentence": "他在大学时参加过一次学生运动。", "error_description": "量词错误：“位”用于人，学生运动应用“次”或“场”计量，应说“一次学生运动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
