INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91357, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拉关系是想办法和人变熟，好让他帮忙。", "primary_collocate": null, "pronunciation": "lā guān xi", "ipa": "la˥ kwan˥ ɕi", "syllable_count": 3, "sentences": [{"text": "新来的同事想跟大家拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常给邻居送水果，想跟邻居拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想让经理帮忙，就先跟他拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别跟我拉关系，我帮不了你。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刚搬来，他就开始跟房东拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李想借书，先和管理员拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着过来跟我拉关系，原来想借钱。", "target_word": "拉关系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想办成这件事，得先跟他拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想拉关系，就主动请老同学吃饭。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会拉关系，没几天就和房东熟了。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拉拉关系", "label": "重叠"}, {"form": "拉过关系", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "想办法和人变熟，好请对方帮忙（日常、较轻）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91357, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "躲避", "is_correct": false, "explanation": "配价：“躲避”直接带宾语，不能用“跟大家”引出对象，应说“躲避大家”。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”是心理动词，不能作为“想跟大家”之后的行为动作，与句意不符。"}, {"text": "拉关系", "is_correct": true, "explanation": "“拉关系”指想办法和人变熟，好请对方帮忙，符合“新来的同事”想与大家熟悉的语境。"}, {"text": "拉", "is_correct": false, "explanation": "配价：“拉”需要带宾语，“想跟大家拉”不完整。"}], "explanations": {"躲避": "配价：“躲避”直接带宾语，不能用“跟大家”引出对象，应说“躲避大家”。", "讨厌": "搭配：“讨厌”是心理动词，不能作为“想跟大家”之后的行为动作，与句意不符。", "拉关系": "“拉关系”指想办法和人变熟，好请对方帮忙，符合“新来的同事”想与大家熟悉的语境。", "拉": "配价：“拉”需要带宾语，“想跟大家拉”不完整。"}, "sentence_index": 0, "correct_answer": "拉关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和弟弟从小一起长大，每天都跟他拉关系，感情很好。", "explanation": "“拉关系”指有意与人变熟以求帮忙，对亲兄弟不用这个词，兄弟之间的亲近应说“亲近”。"}, {"text": "他跑去给书架拉关系，忘了我们约好的时间。", "explanation": "“拉关系”指有意与人变熟以求帮忙，书架不是人，此处误把它当成了“与物件亲近”的意思，应说“整理”。"}, {"text": "这次考试没考好，我心情很差，就跟朋友拉关系，把心事说了出来。", "explanation": "“拉关系”指有意与人变熟以求帮忙，不指倾诉心事，此处应说“倾诉”或“聊天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91357, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吵架", "is_correct": false, "explanation": "语义：“笑着过来”表示友好，与“吵架”矛盾，句子读起来不通。"}, {"text": "生气", "is_correct": false, "explanation": "语义：“笑着过来”与“跟我生气”的态度相反，而且后半句“原来想借钱”也接不上。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”单独使用需要带宾语，“跟我叫”不成句。"}, {"text": "拉关系", "is_correct": true, "explanation": "“拉关系”指想办法和人变熟，好请对方帮忙，与“笑着过来”及“原来想借钱”前后呼应。"}], "explanations": {"吵架": "语义：“笑着过来”表示友好，与“吵架”矛盾，句子读起来不通。", "生气": "语义：“笑着过来”与“跟我生气”的态度相反，而且后半句“原来想借钱”也接不上。", "叫": "配价：“叫”单独使用需要带宾语，“跟我叫”不成句。", "拉关系": "“拉关系”指想办法和人变熟，好请对方帮忙，与“笑着过来”及“原来想借钱”前后呼应。"}, "sentence_index": 6, "correct_answer": "拉关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拉关系把门打开了，然后走了进去。", "explanation": "此处“拉”是拉动之义，门可以被拉开，但“关系”不能被拉开，拉关系只指与人变熟。"}, {"text": "这盆花很会拉关系，所以开得特别漂亮。", "explanation": "“拉关系”指想办法与人变熟以求帮忙，此处误把它当成了“与事物亲近”的意思，植物应说“长得好”。"}, {"text": "这场足球比赛，我们队在场上跟对方拉关系，最后赢了。", "explanation": "“拉关系”指为求帮忙而与人变熟，此处误把它当成了“与对手周旋”的意思，比赛应说“交锋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想把新同事拉关系，以后好请他帮忙。", "corrected_sentence": "我想跟新同事拉关系，以后好请他帮忙。", "error_description": "错误在介词。「拉关系」需用「跟」引出对象，「把」不能与之搭配；应说「想跟新同事拉关系」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不把人拉关系，只靠自己的能力。", "corrected_sentence": "他从来不跟人拉关系，只靠自己的能力。", "error_description": "错误在介词。「拉关系」需用「跟」引出对象，「把」不能与之搭配；应说「从来不跟人拉关系」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
