INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91358, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "为谋取好处而与有权势或有用处的人结交往来。", "primary_collocate": null, "pronunciation": "lā guān xi", "ipa": "la˥ kwan˥ ɕi", "syllable_count": 3, "sentences": [{"text": "他总爱和领导拉关系。", "target_word": "拉关系", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "想找好工作，不能只靠拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了升职，天天找经理拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人很会拉关系，认识不少官员。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他请客吃饭，是想跟老板拉关系。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "靠拉关系得到的机会，我不要。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有学会拉关系，所以一直没升职。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有些人喜欢拉关系，不愿意好好做事。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拉关系的办法就是送礼。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不想拉关系，只想靠自己进公司。", "target_word": "拉关系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拉拉关系", "label": "重叠"}, {"form": "拉过关系", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "为谋取好处而巴结有权势或有用的人（带贬义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91358, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "疏远", "is_correct": false, "explanation": "语义：“总爱”说的是喜欢去做的事，“疏远”是保持距离，与句意矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "配价：“躲避”直接带宾语，应说“躲避领导”，不能用“和领导”引出对象。"}, {"text": "拉", "is_correct": false, "explanation": "配价：“拉”单独使用需要带宾语，“和领导拉”不成句。"}, {"text": "拉关系", "is_correct": true, "explanation": "“拉关系”指为谋取好处而与有权势的人结交往来，符合“总爱和领导”的语境。"}], "explanations": {"疏远": "语义：“总爱”说的是喜欢去做的事，“疏远”是保持距离，与句意矛盾。", "躲避": "配价：“躲避”直接带宾语，应说“躲避领导”，不能用“和领导”引出对象。", "拉": "配价：“拉”单独使用需要带宾语，“和领导拉”不成句。", "拉关系": "“拉关系”指为谋取好处而与有权势的人结交往来，符合“总爱和领导”的语境。"}, "sentence_index": 0, "correct_answer": "拉关系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和老同学天天拉关系，一起回忆童年的趣事。", "explanation": "“拉关系”含有为谋取好处而结交有用之人的功利色彩，此处只是老同学叙旧，应说“联络感情”。"}, {"text": "他跟电脑拉关系，每天都在修理键盘。", "explanation": "“拉关系”指为谋取好处而与有权势或有用的人结交，电脑不是人，此处误把它当成了“与物件亲近”的意思，应说“跟电脑打交道”。"}, {"text": "他拉关系把箱子搬进了屋里。", "explanation": "此处“拉”是拖拽之义，“关系”不能被拖动，与“拉关系”指结交人的含义完全不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91358, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”是心理状态，此处缺少对象，且与“所以一直没升职”没有因果关系。"}, {"text": "拉关系", "is_correct": true, "explanation": "“拉关系”指为谋取好处而与有权势的人结交，符合“没有学会”与“没升职”之间的因果关系。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：发呆不是需要学习的技能，而且与“所以一直没升职”之间没有因果关系。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，不能以“他”为主语，也不能说“学会下雨”。"}], "explanations": {"讨厌": "语义：“讨厌”是心理状态，此处缺少对象，且与“所以一直没升职”没有因果关系。", "拉关系": "“拉关系”指为谋取好处而与有权势的人结交，符合“没有学会”与“没升职”之间的因果关系。", "发呆": "语义：发呆不是需要学习的技能，而且与“所以一直没升职”之间没有因果关系。", "下雨": "语义：“下雨”是天气现象，不能以“他”为主语，也不能说“学会下雨”。"}, "sentence_index": 6, "correct_answer": "拉关系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两件事拉关系很密切，所以得一起解决。", "explanation": "“拉关系”只用于人与人之间为谋取好处而结交，两件事之间的联系应说“有联系”。"}, {"text": "比赛开始前，他拉关系把球网拉紧了。", "explanation": "此处误把「拉关系」当成拉扯的意思，「关系」不能被拉紧，应说「把球网拉紧」。"}, {"text": "为了考试及格，他每天拉关系背单词。", "explanation": "“拉关系”指与人结交以谋取好处，不能表示学习的动作，此处误把它当成了“学习”的意思，应说“复习”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为了升职，经常把经理拉关系。", "corrected_sentence": "他为了升职，经常跟经理拉关系。", "error_description": "错误在介词。「拉关系」需用「跟」引出对象，「把」不能与之搭配；应说「经常跟经理拉关系」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来不把人拉关系，只埋头做事。", "corrected_sentence": "他从来不跟人拉关系，只埋头做事。", "error_description": "错误在介词。「拉关系」需用「跟」引出对象，「把」不能与之搭配；应说「从来不跟人拉关系」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
