INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91359, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "大声告诉大家一件大事。", "primary_collocate": null, "pronunciation": "xuān gào", "ipa": "ɕɥɛn˥ kau˥˩", "syllable_count": 2, "sentences": [{"text": "他站在台上，大声宣告好消息。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长大声宣告：明天开会！", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跑进教室，大声宣告考试取消了。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人走到广场中间，大声宣告喜事。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸笑着大声宣告：我们要搬家了！", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察走上前，大声宣告新规定。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王大声宣告自己要结婚了。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵大声宣告胜利的消息。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站起来大声宣告：我是第一名！", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导游大声向大家宣告出发时间。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣告了", "label": "体标（了）"}, {"form": "宣告过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "大声向众人说出一件大事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣告", "is_correct": true, "explanation": "正确：宣告表示大声告诉众人，与“大声”和“好消息”搭配，符合句意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”是不让人知道，与“大声”的说出动作矛盾。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”指记不住，无法与“大声说出好消息”的动作相配。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”不能接“好消息”作宾语。"}], "explanations": {"宣告": "正确：宣告表示大声告诉众人，与“大声”和“好消息”搭配，符合句意。", "隐瞒": "语义：“隐瞒”是不让人知道，与“大声”的说出动作矛盾。", "忘": "语义：“忘”指记不住，无法与“大声说出好消息”的动作相配。", "修": "搭配：“修”不能接“好消息”作宾语。"}, "sentence_index": 0, "correct_answer": "宣告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在教室里小声宣告了几句。", "explanation": "〈嘟囔〉。小声嘟囔是私下低声说，“宣告”要求大声告诉众人，两者矛盾。"}, {"text": "小贩在街上大声宣告水果便宜。", "explanation": "〈叫卖〉。小贩大声招揽顾客、推销商品应说“叫卖”，“宣告”用于郑重宣布大事，不能用来吆喝买卖。"}, {"text": "他凑到我耳边大声宣告了几句。", "explanation": "〈耳语〉。凑到耳边轻声说应用“耳语”，“宣告”是对众人大声说，与“凑到耳边”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣告", "is_correct": true, "explanation": "正确：宣告表示大声告知，与“自己要结婚了”搭配，符合句意。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“自己要结婚了”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，与说出消息无关。"}, {"text": "埋", "is_correct": false, "explanation": "语义：“埋”指掩埋，与“大声”告知的动作相矛盾。"}], "explanations": {"宣告": "正确：宣告表示大声告知，与“自己要结婚了”搭配，符合句意。", "哭": "配价：“哭”是不及物动词，不能带“自己要结婚了”作宾语。", "吃": "语义：“吃”指吞咽食物，与说出消息无关。", "埋": "语义：“埋”指掩埋，与“大声”告知的动作相矛盾。"}, "sentence_index": 6, "correct_answer": "宣告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在屋里悄悄宣告孩子睡觉。", "explanation": "〈哄〉。哄孩子睡觉应用“哄”；“宣告”要求大声告诉大家一件大事，“悄悄”与之矛盾。"}, {"text": "他宣告我帮个忙。", "explanation": "〈请〉。请人帮忙应用“请”，“宣告”不用于提出请求。"}, {"text": "大家宣告她的勇气。", "explanation": "〈赞美〉。称赞别人的品质应用“赞美”，“宣告”用于宣布事件或决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在广场上大声了宣告喜讯。", "corrected_sentence": "她在广场上大声宣告喜讯。", "error_description": "错误：“了”放在了“宣告”前面。“宣告”前不能加“了”，这里不需要“了”，应说“她在广场上大声宣告喜讯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判大声宣告比赛了结束。", "corrected_sentence": "裁判大声宣告比赛结束。", "error_description": "错误：“了”不能放在“比赛”和“结束”中间，“比赛了结束”不成立。去掉“了”，应说“裁判大声宣告比赛结束”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
