INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91360, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开正式地告知；宣布。", "primary_collocate": null, "pronunciation": "xuān gào", "ipa": "ɕɥɛn˥ kau˥˩", "syllable_count": 2, "sentences": [{"text": "学校正式宣告新校区成立。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院宣告这家公司破产。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席宣告大会正式开始。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王宣告了新法律。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司宣告新产品上市了。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生宣告病人已经去世。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人宣告结束战争。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判宣告红队获胜。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统宣告国家进入紧急状态。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长宣告学校明天放假。", "target_word": "宣告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宣告了", "label": "体标（了）"}, {"form": "宣告过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "公开正式地宣布某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣告", "is_correct": true, "explanation": "正确：宣告表示正式公开地宣布，与“新校区成立”搭配，符合句意。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，与“新校区成立”的宣布义不合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆除，与“新校区成立”的意思相矛盾。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“新校区成立”这样的宾语。"}], "explanations": {"宣告": "正确：宣告表示正式公开地宣布，与“新校区成立”搭配，符合句意。", "挖": "语义：“挖”指挖掘，与“新校区成立”的宣布义不合。", "拆": "语义：“拆”指拆除，与“新校区成立”的意思相矛盾。", "睡": "配价：“睡”是不及物动词，不能带“新校区成立”这样的宾语。"}, "sentence_index": 0, "correct_answer": "宣告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把好消息宣告了父母。", "explanation": "〈告诉〉。宣告是公开、正式地宣布，私下告诉家人应用“告诉”。"}, {"text": "我给朋友打电话宣告他聚会时间。", "explanation": "〈通知〉。给个人打电话说明聚会时间应用“通知”，“宣告”用于公开场合的正式宣布。"}, {"text": "奶奶给我宣告童年的故事。", "explanation": "〈讲述〉。讲故事应用“讲述”，“宣告”只用于正式宣布重大事件或决定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣告", "is_correct": true, "explanation": "正确：宣告表示郑重宣布，与“结束战争”搭配，符合句意。"}, {"text": "签", "is_correct": false, "explanation": "搭配：“签”后一般接“协议”“条约”，不直接接“结束战争”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，与“结束战争”无关。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带“结束战争”这样的宾语。"}], "explanations": {"宣告": "正确：宣告表示郑重宣布，与“结束战争”搭配，符合句意。", "签": "搭配：“签”后一般接“协议”“条约”，不直接接“结束战争”。", "吃": "语义：“吃”指吞咽食物，与“结束战争”无关。", "跑": "配价：“跑”是不及物动词，不能带“结束战争”这样的宾语。"}, "sentence_index": 6, "correct_answer": "宣告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在背后宣告他的事情。", "explanation": "〈议论〉。宣告是正式公开地宣布，背后私下议论应用“议论”。"}, {"text": "妈妈宣告了我的生日礼物。", "explanation": "〈送〉。宣告的对象是事件或决定，不能是物品；送礼物应用“送”。"}, {"text": "她在我耳边悄悄宣告了一句话。", "explanation": "〈低语〉。在耳边悄悄说应用“低语”，“宣告”是公开正式地宣布，与“悄悄”“耳边”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市政府正式了宣告了新的交通规定。", "corrected_sentence": "市政府正式宣告了新的交通规定。", "error_description": "错误：“正式”与“宣告”之间多出一个“了”，体标“了”不能放在动词前。删去多余的“了”，应说“市政府正式宣告了新的交通规定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两国政府把宣告停战。", "corrected_sentence": "两国政府宣告停战。", "error_description": "错误：多出一个“把”。“宣告”是动词，不能直接放在“把”后作把字句的宾语。删去“把”，应说“两国政府宣告停战”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
