INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91361, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "招募是请人来参加做事。", "primary_collocate": null, "pronunciation": "zhāo mù", "ipa": "ʈʂɑʊ˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "学校想招募几个学生帮忙做饭。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区正在招募人来打扫公园。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们想招募几个人一起去山里种树。", "target_word": "招募", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师招募了五个同学来布置教室。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王想招募几个人，周末一起踢球。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小店要招募人来帮忙卖东西。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里招募年轻人去修路，大家都很高兴。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在群里招募人一起做饭。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王老师正在招募人手，准备办生日会。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去年招募过十个人来帮忙搬家。", "target_word": "招募", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "招募了", "label": "体标：了"}, {"form": "招募过", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "请人来参加做事（小范围、日常帮忙）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招募", "is_correct": true, "explanation": "招募：请人来参加做事，与「请学生帮忙做饭」相合。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：「解雇」针对在职员工，学生不是员工，不能用于请人帮忙。"}, {"text": "驱散", "is_correct": false, "explanation": "语义：「驱散」是赶走人群，与请学生参加做事的意思不合。"}, {"text": "罢免", "is_correct": false, "explanation": "语域：「罢免」是正式的职务用语，不用于请学生帮忙这类日常事务。"}], "explanations": {"招募": "招募：请人来参加做事，与「请学生帮忙做饭」相合。", "解雇": "语义：「解雇」针对在职员工，学生不是员工，不能用于请人帮忙。", "驱散": "语义：「驱散」是赶走人群，与请学生参加做事的意思不合。", "罢免": "语域：「罢免」是正式的职务用语，不用于请学生帮忙这类日常事务。"}, "sentence_index": 0, "correct_answer": "招募"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师招募我去她家吃饭。", "explanation": "这里应该用〈邀请〉。招募是请人来参加做事，请人赴宴要用邀请。"}, {"text": "我想招募一场大雨来浇花。", "explanation": "招募只用于请人来参加做事，这里用在大雨上，表示使下雨，不是招募的意思。"}, {"text": "大家都很忙，老师招募大家开会。", "explanation": "这里应该用〈召集〉。招募是请人参加做事，召集大家开会要用召集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招募", "is_correct": true, "explanation": "招募：请人来参加做事，与村里请年轻人修路的语境相合。"}, {"text": "强迫", "is_correct": false, "explanation": "语义：「强迫」含有违背意愿的意思，与「大家都很高兴」的语境不合。"}, {"text": "训斥", "is_correct": false, "explanation": "搭配：「训斥」是责骂，不能接「去修路」这样的任务。"}, {"text": "惩罚", "is_correct": false, "explanation": "语义：「惩罚」是处罚，与大家都很高兴的语境相反。"}], "explanations": {"招募": "招募：请人来参加做事，与村里请年轻人修路的语境相合。", "强迫": "语义：「强迫」含有违背意愿的意思，与「大家都很高兴」的语境不合。", "训斥": "搭配：「训斥」是责骂，不能接「去修路」这样的任务。", "惩罚": "语义：「惩罚」是处罚，与大家都很高兴的语境相反。"}, "sentence_index": 6, "correct_answer": "招募"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我招募大家的意见，决定去哪里玩。", "explanation": "这里应该用〈征求〉。招募是请人来参加做事，征求意见要用征求。"}, {"text": "我们去年招募了十把椅子来帮忙搬家。", "explanation": "招募只用于请人来参加做事，这里用在椅子上，等于征用物品，不是招募的意思。"}, {"text": "我们去年招募过十个人一起吃饭。", "explanation": "这里应该用〈请〉。招募是请人来参加做事，请人吃饭要用请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区想招募了几个人一起修路。", "corrected_sentence": "社区想招募几个人一起修路。", "error_description": "体标错误：「想」表示尚未发生的打算，与表示已完成的「了」矛盾，应说「想招募几个人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长去年招募了过几个同学来帮忙。", "corrected_sentence": "班长去年招募过几个同学来帮忙。", "error_description": "体标错误：「了」与「过」不能同时用在动词后，应只用「招募过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
