INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开招收、征集人员。", "primary_collocate": null, "pronunciation": "zhāo mù", "ipa": "ʈʂɑʊ˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司公开招募新员工。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队每年在全国招募新兵。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院正在向社会招募志愿者。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司招募了二十名新员工。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大学计划明年招募一批研究人员。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在网上发了通知，招募志愿者。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个球队去年招募过很多年轻球员。", "target_word": "招募", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆面向社会招募讲解员。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司招募新人，要求会说英语。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们招募到了三十名合适的人才。", "target_word": "招募", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "招募了", "label": "体标：了"}, {"form": "招募过", "label": "体标：过"}], "register": "书面", "sense_fingerprint": "公开向社会招收、征集人员（公司、军队、机构）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '183145e1-d4a2-4203-b065-5266430b4a50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "招募", "is_correct": true, "explanation": "招募：公开向社会征集人员，与「公开」和「新员工」相合。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：「解雇」是辞退在职员工，与公开招收新员工的语境相反。"}, {"text": "通缉", "is_correct": false, "explanation": "语义：「通缉」针对犯罪嫌疑人，不能用于员工。"}, {"text": "发配", "is_correct": false, "explanation": "搭配：「发配」指把人流放到远处，不能与「新员工」搭配。"}], "explanations": {"招募": "招募：公开向社会征集人员，与「公开」和「新员工」相合。", "解雇": "语义：「解雇」是辞退在职员工，与公开招收新员工的语境相反。", "通缉": "语义：「通缉」针对犯罪嫌疑人，不能用于员工。", "发配": "搭配：「发配」指把人流放到远处，不能与「新员工」搭配。"}, "sentence_index": 0, "correct_answer": "招募"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "总统招募了三位部长。", "explanation": "这里应该用〈任命〉。招募是公开征集人员，任命官员要用任命。"}, {"text": "学校招募了五千元善款。", "explanation": "招募只用于公开征集人员，这里是在募集钱款，不是招募的意思。"}, {"text": "这个乐队招募了很多粉丝。", "explanation": "招募只用于公开征集人员，这里说的是吸引粉丝，不是招募的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "招募", "is_correct": true, "explanation": "招募：公开征集人员，与球队招收年轻球员的语境相合。"}, {"text": "放逐", "is_correct": false, "explanation": "语义：「放逐」是流放，与球队招收年轻球员的语境无关。"}, {"text": "取缔", "is_correct": false, "explanation": "搭配：「取缔」用于组织、活动，不能用来说取缔球员。"}, {"text": "拘捕", "is_correct": false, "explanation": "语义：「拘捕」是抓人，与球员招募的语境不合。"}], "explanations": {"招募": "招募：公开征集人员，与球队招收年轻球员的语境相合。", "放逐": "语义：「放逐」是流放，与球队招收年轻球员的语境无关。", "取缔": "搭配：「取缔」用于组织、活动，不能用来说取缔球员。", "拘捕": "语义：「拘捕」是抓人，与球员招募的语境不合。"}, "sentence_index": 6, "correct_answer": "招募"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们招募了三十位客人，一起吃饭。", "explanation": "这里应该用〈招待〉。招募是公开征集人员，招待客人要用招待。"}, {"text": "他总是招募麻烦。", "explanation": "招募只用于公开征集人员，这里说的是引来麻烦，不是招募的意思。"}, {"text": "商店招募了三十台电脑。", "explanation": "这里应该用〈出售〉。招募的对象是人员，出售商品要用出售。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
