INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校昨天公开招募着几名老师。", "corrected_sentence": "这所学校昨天公开招募了几名老师。", "error_description": "体标错误：「着」表示持续的状态，与表示某一天发生的一次性动作的「昨天」不搭配，应说「昨天公开招募了几名老师」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5b484a7-b61a-4581-b8e9-76c258c33a70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指人多、有生气，正是“身边没有人陪”的反面。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：“聪明”形容头脑灵活，与“寂寞”的情感义没有相对关系。"}, {"text": "整齐", "is_correct": false, "explanation": "无反义关系：“整齐”形容摆放规整，不是“寂寞”的反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线充足，与“寂寞”的情感义没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指人多、有生气，正是“身边没有人陪”的反面。", "聪明": "无反义关系：“聪明”形容头脑灵活，与“寂寞”的情感义没有相对关系。", "整齐": "无反义关系：“整齐”形容摆放规整，不是“寂寞”的反义词。", "明亮": "无反义关系：“明亮”形容光线充足，与“寂寞”的情感义没有相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指有人陪伴、气氛活跃，与“身边没有人说话”正好相反。"}, {"text": "干净", "is_correct": false, "explanation": "无反义关系：“干净”指没有灰尘或污物，与“寂寞”的情感义无关。"}, {"text": "高大", "is_correct": false, "explanation": "无反义关系：“高大”形容体型，与“寂寞”没有相对关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "无反义关系：“漂亮”形容外貌美好，与“寂寞”没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指有人陪伴、气氛活跃，与“身边没有人说话”正好相反。", "干净": "无反义关系：“干净”指没有灰尘或污物，与“寂寞”的情感义无关。", "高大": "无反义关系：“高大”形容体型，与“寂寞”没有相对关系。", "漂亮": "无反义关系：“漂亮”形容外貌美好，与“寂寞”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身边没有人陪，心里空空的。", "primary_collocate": null, "pronunciation": "jì mò", "ipa": "tɕi˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "朋友都回家了，我一个人很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人住在大城市，常常觉得寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都去上学了，奶奶在家很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末没有人找我玩，我有点寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上他一个人吃饭，感到很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你寂寞的时候，可以给我打电话。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国第一个月，我很想家，也很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都走了，宿舍里只有我，真寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养了一只猫，不再寂寞了。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人身边没有人说话，心里很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身边没有人陪伴，心里空虚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89422d92-e8b7-408c-a79e-eb0b7d409ade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”表示身边没有人陪、心里空虚，与“朋友都回家了，我一个人”的语境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、气氛活跃，与“我一个人”的语境相矛盾。"}, {"text": "拥挤", "is_correct": false, "explanation": "搭配：“拥挤”说人多、空间挤，不能用来形容“我一个人”的状态。"}, {"text": "喧闹", "is_correct": false, "explanation": "语义：“喧闹”指声音大、人声嘈杂，与“朋友都回家了”之后只剩我一个人的情形不符。"}], "explanations": {"寂寞": "正确：“寂寞”表示身边没有人陪、心里空虚，与“朋友都回家了，我一个人”的语境相符。", "热闹": "语义：“热闹”指人多、气氛活跃，与“我一个人”的语境相矛盾。", "拥挤": "搭配：“拥挤”说人多、空间挤，不能用来形容“我一个人”的状态。", "喧闹": "语义：“喧闹”指声音大、人声嘈杂，与“朋友都回家了”之后只剩我一个人的情形不符。"}, "sentence_index": 0, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部电影太寂寞了，我看了一半就走了。", "explanation": "这里应该用〈无聊〉。“寂寞”说人身边没人陪、心里空虚，形容电影乏味要用“无聊”。"}, {"text": "这次考试我考得很寂寞。", "explanation": "这里应该用〈不理想〉。“寂寞”指人身边没人陪、心里空虚，评价考试结果要说“考得不理想”。"}, {"text": "比赛赢了，他寂寞得跳了起来。", "explanation": "这里应该用〈兴奋〉。“寂寞”指人孤单空虚，赢球后的激动心情要用“兴奋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”与“很想家”同属思乡时的孤单心情，与“也很”的并列语气相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”描述外貌，与“很想家”的心情无关，读起来不通。"}, {"text": "幽静", "is_correct": false, "explanation": "语义：“幽静”多形容环境或安静的性情，与“很想家”的孤单心情不符，“也很幽静”接在这里意思不合。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，与“很想家”的心情毫不相干，“也很高大”不通。"}], "explanations": {"寂寞": "正确：“寂寞”与“很想家”同属思乡时的孤单心情，与“也很”的并列语气相符。", "漂亮": "体貌：“漂亮”描述外貌，与“很想家”的心情无关，读起来不通。", "幽静": "语义：“幽静”多形容环境或安静的性情，与“很想家”的孤单心情不符，“也很幽静”接在这里意思不合。", "高大": "体貌：“高大”形容身材，与“很想家”的心情毫不相干，“也很高大”不通。"}, "sentence_index": 6, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "图书馆里很寂寞，大家都在认真看书。", "explanation": "这里应该用〈安静〉。“寂寞”指人心里孤单，形容读书的环境要用“安静”。"}, {"text": "上台前，他寂寞得手心直冒汗。", "explanation": "这里应该用〈紧张〉。“寂寞”指人身边没人陪、心里空虚，上台前心里发慌要用“紧张”。"}, {"text": "这道数学题他做得很寂寞。", "explanation": "这里应该用〈做得对〉。“寂寞”指人心里孤单，评价做题情况要说“做得对”或“做得快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "放假以后，宿舍里很安静，我被寂寞。", "corrected_sentence": "放假以后，宿舍里很安静，我很寂寞。", "error_description": "错误：“寂寞”是形容词，表示心里的状态，不能用“被”构成被动句。应去掉“被”，改为“我很寂寞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一个人住在老家，寂寞很。", "corrected_sentence": "他一个人住在老家，寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指人多、有生气，与“冷清孤单”的意思相反。"}, {"text": "精致", "is_correct": false, "explanation": "无反义关系：“精致”形容做工细致，与“寂寞”没有相对关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线充足，与“寂寞”的意思不相对。"}, {"text": "结实", "is_correct": false, "explanation": "无反义关系：“结实”形容牢固、强壮，与“寂寞”无关。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指人多、有生气，与“冷清孤单”的意思相反。", "精致": "无反义关系：“精致”形容做工细致，与“寂寞”没有相对关系。", "明亮": "无反义关系：“明亮”形容光线充足，与“寂寞”的意思不相对。", "结实": "无反义关系：“结实”形容牢固、强壮，与“寂寞”无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热闹", "is_correct": true, "explanation": "反义：“热闹”与“寂寞”相对，指生活有人陪伴、气氛活跃，与“很寂寞”相反。"}, {"text": "富有", "is_correct": false, "explanation": "无反义关系：“富有”指资产多或内容丰富，与“寂寞”没有相对关系。"}, {"text": "整洁", "is_correct": false, "explanation": "无反义关系：“整洁”形容干净利落，与“寂寞”无关。"}, {"text": "响亮", "is_correct": false, "explanation": "无反义关系：“响亮”形容声音清楚有力，与“寂寞”没有相对关系。"}], "correct_answer": "热闹", "explanations": {"热闹": "反义：“热闹”与“寂寞”相对，指生活有人陪伴、气氛活跃，与“很寂寞”相反。", "富有": "无反义关系：“富有”指资产多或内容丰富，与“寂寞”没有相对关系。", "整洁": "无反义关系：“整洁”形容干净利落，与“寂寞”无关。", "响亮": "无反义关系：“响亮”形容声音清楚有力，与“寂寞”没有相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "孤单冷清，内心感到无依无靠。", "primary_collocate": null, "pronunciation": "jì mò", "ipa": "tɕi˥˩ mwo˥˩", "syllable_count": 2, "sentences": [{"text": "夜深了，街上没有人，显得很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子冬天很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的夜晚安静又寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了亲人，内心十分寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪地里只有一棵树，看上去很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着寂寞的生活，没有亲人，也没有朋友。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在异乡无依无靠，心里寂寞极了。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大房子里只有老人，冷清又寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的夜里，寂寞的歌声传了过来。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休以后，他觉得生活很寂寞。", "target_word": "寂寞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "环境冷清孤单，内心无依无靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89422d92-e8b7-408c-a79e-eb0b7d409ade') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”形容街上没人、冷清孤单，与“街上没有人”相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有生气，与“街上没有人”正好相反。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：“拥挤”指人或物挤在一起，与“街上没有人”矛盾。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音乱，与“没有人”所描写的安静场景不搭配。"}], "explanations": {"寂寞": "正确：“寂寞”形容街上没人、冷清孤单，与“街上没有人”相符。", "热闹": "语义：“热闹”指人多、有生气，与“街上没有人”正好相反。", "拥挤": "语义：“拥挤”指人或物挤在一起，与“街上没有人”矛盾。", "嘈杂": "搭配：“嘈杂”形容声音乱，与“没有人”所描写的安静场景不搭配。"}, "sentence_index": 0, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "跑完马拉松，他寂寞得站不起来。", "explanation": "这里应该用〈累〉。“寂寞”指人孤单无依，形容身体劳累要用“累”。"}, {"text": "孩子对新玩具很寂寞。", "explanation": "这里应该用〈好奇〉。“寂寞”指人孤单无依，孩子对新事物的兴趣要用“好奇”。"}, {"text": "这次演讲他讲得很寂寞。", "explanation": "这里应该用〈精彩〉。“寂寞”指人孤单无依，评价演讲好坏要说“讲得精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寂寞", "is_correct": true, "explanation": "正确：“寂寞”形容心里孤单、无依无靠，与“在异乡无依无靠”相符。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指物质充足，与“无依无靠”的处境正相反，“心里富裕”与句子的孤单之意矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，用在“心里”上不通。"}, {"text": "庞大", "is_correct": false, "explanation": "体貌：“庞大”形容体积或规模，不能用来形容心里的感受。"}], "explanations": {"寂寞": "正确：“寂寞”形容心里孤单、无依无靠，与“在异乡无依无靠”相符。", "富裕": "语义：“富裕”指物质充足，与“无依无靠”的处境正相反，“心里富裕”与句子的孤单之意矛盾。", "高大": "体貌：“高大”形容身材，用在“心里”上不通。", "庞大": "体貌：“庞大”形容体积或规模，不能用来形容心里的感受。"}, "sentence_index": 6, "correct_answer": "寂寞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座城市的地铁站很寂寞，人很多，声音也很大。", "explanation": "这里应该用〈热闹〉。“寂寞”指冷清、孤单，描写人多声大的场面要用“热闹”。"}, {"text": "这次面试他表现得很寂寞。", "explanation": "这里应该用〈出色〉。“寂寞”指人孤单无依，评价面试表现要用“出色”。"}, {"text": "房东对我很寂寞，见面时总会热情地打招呼。", "explanation": "这里应该用〈热情〉。“寂寞”指人孤单无依，形容对人的态度要用“热情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下了课，校园里没有人，我觉得寂寞很。", "corrected_sentence": "下了课，校园里没有人，我觉得寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "节日过后，他一个人在屋里，觉得寂寞很。", "corrected_sentence": "节日过后，他一个人在屋里，觉得寂寞得很。", "error_description": "错误：程度补语的标记“得”漏掉了。“寂寞”后要用“得很”作程度补语，应说“寂寞得很”，不能说“寂寞很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17a21db-b574-4c86-a3f7-9c1da3f93732') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
