INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91365, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得一个人很好，对他很有礼貌。", "primary_collocate": null, "pronunciation": "zūn jìng", "ipa": "tsu̯ən˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们都很尊敬王老师。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都尊敬他，因为他对人很好。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要尊敬老人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我尊敬爷爷，每次见他都问好。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很有礼貌，同学们都尊敬她。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小尊敬父母，说话总是很客气。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直尊敬这位邻居大叔。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么这么尊敬他？", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太尊敬说话不客气的人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，人们尊敬老年人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊敬了", "label": "体标"}, {"form": "尊敬过", "label": "体标"}], "register": "中性", "sense_fingerprint": "觉得某人很好，并对他有礼貌", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：尊敬 zūnjìng，觉得某人很好，并对他有礼貌。"}, {"text": "尊姓", "is_correct": false, "explanation": "j 与 x 声母不同，声调相同。「尊姓」是问对方姓氏的敬辞。"}, {"text": "村警", "is_correct": false, "explanation": "c 与 z 声母不同，第二字声调也不同（jǐng 与 jìng）。「村警」指农村的警察。"}, {"text": "钻井", "is_correct": false, "explanation": "韵母不同（zuān 与 zūn），第二字声调也不同（jǐng 与 jìng）。「钻井」指钻探打井。"}], "explanations": {"尊敬": "正确：尊敬 zūnjìng，觉得某人很好，并对他有礼貌。", "尊姓": "j 与 x 声母不同，声调相同。「尊姓」是问对方姓氏的敬辞。", "村警": "c 与 z 声母不同，第二字声调也不同（jǐng 与 jìng）。「村警」指农村的警察。", "钻井": "韵母不同（zuān 与 zūn），第二字声调也不同（jǐng 与 jìng）。「钻井」指钻探打井。"}, "sentence_index": null, "correct_answer": "尊敬"}, "level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：“很尊敬”的对象是老师，符合句意。"}, {"text": "整理", "is_correct": false, "explanation": "搭配：“整理”的对象是房间、东西或资料，不能整理人。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是东西，不能修理人。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等，不用来测量人。"}], "explanations": {"尊敬": "正确：“很尊敬”的对象是老师，符合句意。", "整理": "搭配：“整理”的对象是房间、东西或资料，不能整理人。", "修理": "搭配：“修理”的对象是东西，不能修理人。", "测量": "搭配：“测量”的对象是长度、重量等，不用来测量人。"}, "sentence_index": 0, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要尊敬别人的隐私。", "explanation": "这里应该用〈尊重〉。“尊敬”针对值得敬重的人，“隐私”要用“尊重”。"}, {"text": "公司很尊敬安全。", "explanation": "这里应该用〈重视〉。“尊敬”针对人，“安全”要用“重视”。"}, {"text": "我很尊敬你的帮助。", "explanation": "这里应该用〈感激〉。“尊敬”针对人的品格，“帮助”要用“感激”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：“尊敬”表示对人的敬重，正好用在“邻居大叔”身上。"}, {"text": "安装", "is_correct": false, "explanation": "搭配：“安装”的对象是设备，不能安装人。"}, {"text": "订购", "is_correct": false, "explanation": "搭配：“订购”的对象是商品或服务，不能订购人。"}, {"text": "批准", "is_correct": false, "explanation": "配价：“批准”的对象是申请或计划，不能批准一个人。"}], "explanations": {"尊敬": "正确：“尊敬”表示对人的敬重，正好用在“邻居大叔”身上。", "安装": "搭配：“安装”的对象是设备，不能安装人。", "订购": "搭配：“订购”的对象是商品或服务，不能订购人。", "批准": "配价：“批准”的对象是申请或计划，不能批准一个人。"}, "sentence_index": 6, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师尊敬他的成绩。", "explanation": "这里应该用〈称赞〉。“尊敬”针对人，“成绩”要用“称赞”。"}, {"text": "我尊敬这里的风景。", "explanation": "这里应该用〈欣赏〉。“尊敬”针对人，“风景”要用“欣赏”。"}, {"text": "他尊敬天气。", "explanation": "这里应该用〈埋怨〉。“尊敬”用于值得敬重的人，“天气”要用“埋怨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我别尊敬那种说谎的人。", "corrected_sentence": "我不尊敬那种说谎的人。", "error_description": "否定词错误：“别”用于劝阻或禁止，不用于陈述“我”的态度。应说“不尊敬”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经尊敬了那位老教授。", "corrected_sentence": "他曾经尊敬过那位老教授。", "error_description": "体标错误：“曾经”表示经历，应搭配表示经历的“过”，不能用表示完成的“了”。正确应为“曾经尊敬过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
