INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敬重；怀着敬意对待。", "primary_collocate": null, "pronunciation": "zūn jìng", "ipa": "tsu̯ən˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们尊敬每一位认真工作的人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们尊敬他，因为他一生都在帮助别人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生救了很多人，大家都尊敬医生。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要尊敬长辈，大家才会喜欢你。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我尊敬他的勇敢和诚实。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊敬为国家工作的人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很尊敬自己的老师，一直记着他的话。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家尊敬这位老科学家。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先尊敬别人，别人才会尊敬你。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从小就尊敬军人。", "target_word": "尊敬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尊敬了", "label": "体标"}, {"form": "尊敬过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对人的品德或贡献怀有敬意并加以敬重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：尊敬 zūnjìng，敬重；怀着敬意对待。"}, {"text": "尊姓", "is_correct": false, "explanation": "j 与 x 声母不同，声调相同。「尊姓」是问对方姓氏的敬辞。"}, {"text": "村警", "is_correct": false, "explanation": "c 与 z 声母不同，第二字声调也不同（jǐng 与 jìng）。「村警」指农村的警察。"}, {"text": "钻井", "is_correct": false, "explanation": "韵母不同（zuān 与 zūn），第二字声调也不同（jǐng 与 jìng）。「钻井」指钻探打井。"}], "explanations": {"尊敬": "正确：尊敬 zūnjìng，敬重；怀着敬意对待。", "尊姓": "j 与 x 声母不同，声调相同。「尊姓」是问对方姓氏的敬辞。", "村警": "c 与 z 声母不同，第二字声调也不同（jǐng 与 jìng）。「村警」指农村的警察。", "钻井": "韵母不同（zuān 与 zūn），第二字声调也不同（jǐng 与 jìng）。「钻井」指钻探打井。"}, "sentence_index": null, "correct_answer": "尊敬"}, "level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：“尊敬”表示敬重，“每一位认真工作的人”正好用它。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：“搬运”的对象是货物，不能搬运人。"}, {"text": "出租", "is_correct": false, "explanation": "搭配：“出租”的对象是房屋等物品，不能出租人。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热食物，句子说的是对人的态度。"}], "explanations": {"尊敬": "正确：“尊敬”表示敬重，“每一位认真工作的人”正好用它。", "搬运": "搭配：“搬运”的对象是货物，不能搬运人。", "出租": "搭配：“出租”的对象是房屋等物品，不能出租人。", "烤": "语义：“烤”是加热食物，句子说的是对人的态度。"}, "sentence_index": 0, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都尊敬这首歌。", "explanation": "这里应该用〈喜欢〉。“尊敬”用于有品德或贡献的人，歌曲要用“喜欢”。"}, {"text": "我们要尊敬这台冰箱，别随便乱敲。", "explanation": "这里应该用〈爱护〉。“尊敬”针对值得敬重的人或品德，冰箱这类物品要用“爱护”。"}, {"text": "我们要尊敬机会，别浪费。", "explanation": "这里应该用〈珍惜〉。“尊敬”针对人，“机会”要用“珍惜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尊敬", "is_correct": true, "explanation": "正确：“尊敬”指敬重自己的老师，正好用在“自己的老师”上。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“包装”的对象是商品，不能包装人。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新事物，不能用来形容对老师的态度。"}, {"text": "保存", "is_correct": false, "explanation": "语义：“保存”指留存物品，句子说的是对老师的态度。"}], "explanations": {"尊敬": "正确：“尊敬”指敬重自己的老师，正好用在“自己的老师”上。", "包装": "搭配：“包装”的对象是商品，不能包装人。", "发明": "语义：“发明”指创造新事物，不能用来形容对老师的态度。", "保存": "语义：“保存”指留存物品，句子说的是对老师的态度。"}, "sentence_index": 6, "correct_answer": "尊敬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我尊敬这种臭味。", "explanation": "这里应该用〈讨厌〉。“尊敬”用于值得敬重的人或品德，不用于气味。"}, {"text": "他很尊敬这种吵闹。", "explanation": "这里应该用〈厌烦〉。“尊敬”针对值得敬重的人或品德，不用于吵闹这类令人反感的事。"}, {"text": "我尊敬童年。", "explanation": "这里应该用〈怀念〉。“尊敬”表示敬重，不表示对过去的思念。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我曾经尊敬了一位老医生。", "corrected_sentence": "我曾经尊敬过一位老医生。", "error_description": "体标错误：“曾经”表示经历，应搭配表示经历的“过”，不能用表示完成的“了”。正确应为“曾经尊敬过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都把尊敬那位老教授。", "corrected_sentence": "我们都很尊敬那位老教授。", "error_description": "句式错误：“把”不能直接放在动词“尊敬”前，这里应用程度副词“很”修饰“尊敬”。正确应为“我们都很尊敬那位老教授”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
