INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91367, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿走是把东西拿着离开。", "primary_collocate": null, "pronunciation": "ná zǒu", "ipa": "na˧˥ tsoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把你的书包拿走。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿走了桌上的手机。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人走的时候，别忘了拿走雨伞。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把我的鞋拿走了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以拿走这些旧报纸。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈拿走了盘子，洗干净了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁拿走了我的笔？", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，服务员拿走了空碗。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个箱子太重，我没办法拿走。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把行李拿走，就出门了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿走了", "label": "体标"}, {"form": "拿走过", "label": "体标"}], "register": "中性", "sense_fingerprint": "拿着东西离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91367, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拿走", "is_correct": true, "explanation": "拿走：把东西拿着离开，与释义一致。"}, {"text": "拉走", "is_correct": false, "explanation": "lā（第一声）与 ná（第二声）声母不同（l/n），且声调也不同，意思是用力拉走，不是拿着离开。"}, {"text": "难走", "is_correct": false, "explanation": "nán（第二声）与 ná 韵母不同（多了 n），意思是难以行走。"}, {"text": "拿手", "is_correct": false, "explanation": "shǒu 与 zǒu 声母不同（sh/z），意思是擅长，不是拿走。"}], "explanations": {"拿走": "拿走：把东西拿着离开，与释义一致。", "拉走": "lā（第一声）与 ná（第二声）声母不同（l/n），且声调也不同，意思是用力拉走，不是拿着离开。", "难走": "nán（第二声）与 ná 韵母不同（多了 n），意思是难以行走。", "拿手": "shǒu 与 zǒu 声母不同（sh/z），意思是擅长，不是拿走。"}, "sentence_index": null, "correct_answer": "拿走"}, "level_3": {"options": [{"text": "拿走", "is_correct": true, "explanation": "“拿走”指把东西拿着离开，与“请把……”的请求语境相合。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，不能说“吃书包”。"}, {"text": "喝掉", "is_correct": false, "explanation": "语义：书包不能喝，句意不合。"}, {"text": "唱完", "is_correct": false, "explanation": "配价：“唱”不能以“书包”作宾语。"}], "explanations": {"拿走": "“拿走”指把东西拿着离开，与“请把……”的请求语境相合。", "吃掉": "搭配：“吃”的宾语应为食物，不能说“吃书包”。", "喝掉": "语义：书包不能喝，句意不合。", "唱完": "配价：“唱”不能以“书包”作宾语。"}, "sentence_index": 0, "correct_answer": "拿走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察把那个小偷拿走了。", "explanation": "这里应该用〈带走〉。“拿走”只用于能用手拿着的物品，带人离开要用〈带走〉。"}, {"text": "这场大火拿走了三条生命。", "explanation": "这里应该用〈夺走〉。“拿走”指用手拿着离开，生命无法拿走，夺去生命要说〈夺走〉。"}, {"text": "他拿走了我的信心。", "explanation": "这里应该用〈夺走〉。“拿走”只用于具体物品，信心这类抽象事物要用〈夺走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿走", "is_correct": true, "explanation": "“拿走”表示把东西带离，符合“谁……了我的笔”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：笔不能吃，句意不合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：笔不能煮，句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“笔”作宾语。"}], "explanations": {"拿走": "“拿走”表示把东西带离，符合“谁……了我的笔”的语境。", "吃": "语义：笔不能吃，句意不合。", "煮": "语义：笔不能煮，句意不合。", "唱": "配价：“唱”不能以“笔”作宾语。"}, "sentence_index": 6, "correct_answer": "拿走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿走了整个操场。", "explanation": "这里应该用〈占据〉。“拿走”的对象必须能被拿着离开，操场这类场地只能说〈占据〉。"}, {"text": "他拿走了三年的时光。", "explanation": "这里应该用〈度过〉。“拿走”只用于具体物品，时间只能说〈度过〉。"}, {"text": "我拿走了一声巨响。", "explanation": "这里应该用〈发出〉。“拿走”只用于具体物品，声音要说〈发出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把拿走了一把伞。", "corrected_sentence": "他拿走了一把伞。", "error_description": "错误在“把”：“把”字句要把宾语放在“把”后、动词前，这句“把”后没有宾语，不能在“拿走”前直接加“把”。正确形式为“他拿走了一把伞。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把那本书拿走着。", "corrected_sentence": "他把那本书拿走了。", "error_description": "错误在体标：表示“拿走”这一动作已经完成要用“了”，不能用“着”（“着”表示持续的状态，与“拿走”的完成义不合）。正确形式为“他把那本书拿走了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
