INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91368, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "取下并带离原处。", "primary_collocate": null, "pronunciation": "ná zǒu", "ipa": "na˧˥ tsoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他从墙上拿走了那张旧照片。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把门口的牌子拿走了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从架子上拿走你要的书。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小偷拿走了抽屉里的钱。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师拿走了黑板上的纸。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天到了，他们把窗外的花盆拿走了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从冰箱里拿走一瓶水。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人把树上的灯拿走了。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要拿走桌上的卡片。", "target_word": "拿走", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿走了书架上最上面的那本书。", "target_word": "拿走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拿走了", "label": "体标"}, {"form": "拿走过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西从原来的位置取下带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9e3b165-144c-41ad-80d9-3863d69cfc1f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "拿走", "is_correct": true, "explanation": "拿走：取下并带离原处，与释义一致。"}, {"text": "拉走", "is_correct": false, "explanation": "lā（第一声）与 ná（第二声）声母（l/n）和声调都不同，意思是拉走，不是取下带离。"}, {"text": "难走", "is_correct": false, "explanation": "nán（第二声）与 ná 韵母不同（多了 n），意思是难以行走。"}, {"text": "拿手", "is_correct": false, "explanation": "shǒu 与 zǒu 声母不同（sh/z），意思是擅长，不是拿走。"}], "explanations": {"拿走": "拿走：取下并带离原处，与释义一致。", "拉走": "lā（第一声）与 ná（第二声）声母（l/n）和声调都不同，意思是拉走，不是取下带离。", "难走": "nán（第二声）与 ná 韵母不同（多了 n），意思是难以行走。", "拿手": "shǒu 与 zǒu 声母不同（sh/z），意思是擅长，不是拿走。"}, "sentence_index": null, "correct_answer": "拿走"}, "level_3": {"options": [{"text": "拿走", "is_correct": true, "explanation": "“拿走”表示从原位取下并带离，符合“从墙上”的语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应为食物，照片不能吃。"}, {"text": "煮", "is_correct": false, "explanation": "语义：照片不能煮，句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不能以“照片”作宾语。"}], "explanations": {"拿走": "“拿走”表示从原位取下并带离，符合“从墙上”的语境。", "吃": "搭配：“吃”的宾语应为食物，照片不能吃。", "煮": "语义：照片不能煮，句意不合。", "唱": "配价：“唱”不能以“照片”作宾语。"}, "sentence_index": 0, "correct_answer": "拿走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿走了一个坏消息。", "explanation": "这里应该用〈听到〉。「拿走」只用于可以被拿着离开的具体物品，消息要说〈听到〉。"}, {"text": "警察拿走了那个嫌疑人。", "explanation": "这里应该用〈押走〉。“拿走”只用于物品，押送人员要用〈押走〉。"}, {"text": "他拿走了我的回忆。", "explanation": "这里应该用〈带走〉。“拿走”只用于能用手取下的具体物品，回忆这类抽象事物要说〈带走〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿走", "is_correct": true, "explanation": "“拿走”表示从冰箱里取出并带离，符合句意。"}, {"text": "修", "is_correct": false, "explanation": "语义：水不能修理，与“从冰箱里”的语境不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语应为衣物，不能说“穿一瓶水”。"}, {"text": "咬", "is_correct": false, "explanation": "语义：水不能咬，句意不合。"}], "explanations": {"拿走": "“拿走”表示从冰箱里取出并带离，符合句意。", "修": "语义：水不能修理，与“从冰箱里”的语境不合。", "穿": "搭配：“穿”的宾语应为衣物，不能说“穿一瓶水”。", "咬": "语义：水不能咬，句意不合。"}, "sentence_index": 6, "correct_answer": "拿走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿走了一个下午。", "explanation": "这里应该用〈度过〉。“拿走”只用于具体物品，时间只能说〈度过〉。"}, {"text": "他拿走了一声叹息。", "explanation": "这里应该用〈发出〉。“拿走”只用于具体物品，叹息要说〈发出〉。"}, {"text": "他拿走了整片森林。", "explanation": "这里应该用〈占据〉。「拿走」的对象须能被拿着离开，整片森林这类大片地域不能这样拿走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从架子上拿走着一本书。", "corrected_sentence": "他从架子上拿走了一本书。", "error_description": "错误在体标：“拿走”表示一次性完成的动作，应用完成体“了”；“着”表示持续状态，与“拿走一本书”的完成义不符。正确形式为“他从架子上拿走了一本书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没拿走了书架上的那本旧书。", "corrected_sentence": "他昨天没拿走书架上的那本旧书。", "error_description": "错误在体标：用「没」否定「拿走」时，后面不能再加「了」。应去掉「了」，改为「他昨天没拿走书架上的那本旧书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '696d06f6-48c8-4abf-bf2f-a64f447654d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91371, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔出", "is_correct": true, "explanation": "拔出：把插进去的东西抽出来，与“插入”的动作方向相反，是反义关系。"}, {"text": "吃饭", "is_correct": false, "explanation": "吃饭：把食物送进嘴里，与“插入”没有反义关系。"}, {"text": "洗澡", "is_correct": false, "explanation": "洗澡：用水清洁身体，与“插入”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：用笔写出文字，与“插入”没有反义关系。"}], "correct_answer": "拔出", "explanations": {"拔出": "拔出：把插进去的东西抽出来，与“插入”的动作方向相反，是反义关系。", "吃饭": "吃饭：把食物送进嘴里，与“插入”没有反义关系。", "洗澡": "洗澡：用水清洁身体，与“插入”没有反义关系。", "写字": "写字：用笔写出文字，与“插入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
