INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91371, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "插入是把东西放进另一样东西里面。", "primary_collocate": null, "pronunciation": "chā rù", "ipa": "tʂʰa˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他把笔插入笔筒里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把插头插入墙上的插座。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一根竹签插入肉块里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把银行卡插入读卡机。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一根小棍插入沙子里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把书签插入书页中间。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把螺丝刀插入缝里，打开了盖子。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一把小刀插入木头中。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把树枝插入泥土中。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友把吸管插入果汁盒里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "插入了", "label": "体标（了）"}, {"form": "插入过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "把东西放进另一样东西里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91371, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "插入", "is_correct": true, "explanation": "chā rù，意思是把东西放进另一样东西里面。"}, {"text": "杀入", "is_correct": false, "explanation": "shā（第一声）与 chā（第一声）声母不同（sh 与 ch），杀入意思是冲进去，与插入不同。"}, {"text": "插足", "is_correct": false, "explanation": "chā zú 与 chā rù 第二个音节不同（zú 与 rù），插足意思是参与进去、介入，与插入不同。"}, {"text": "掺入", "is_correct": false, "explanation": "chān（第一声）与 chā（第一声）韵母不同（an 与 a），掺入意思是混合进去，与插入不同。"}], "explanations": {"插入": "chā rù，意思是把东西放进另一样东西里面。", "杀入": "shā（第一声）与 chā（第一声）声母不同（sh 与 ch），杀入意思是冲进去，与插入不同。", "插足": "chā zú 与 chā rù 第二个音节不同（zú 与 rù），插足意思是参与进去、介入，与插入不同。", "掺入": "chān（第一声）与 chā（第一声）韵母不同（an 与 a），掺入意思是混合进去，与插入不同。"}, "sentence_index": null, "correct_answer": "插入"}, "level_3": {"options": [{"text": "插入", "is_correct": true, "explanation": "正确：插入表示把笔放进笔筒，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指用笔写字，与“笔筒里”的放入动作不合。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，与把笔放进笔筒的动作不合。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”不能带“笔筒里”这样的处所补足语作宾语，句子不成立。"}], "explanations": {"插入": "正确：插入表示把笔放进笔筒，符合句意。", "写": "语义：“写”指用笔写字，与“笔筒里”的放入动作不合。", "喝": "语义：“喝”指饮用，与把笔放进笔筒的动作不合。", "说": "配价：“说”不能带“笔筒里”这样的处所补足语作宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "插入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请把牛奶插入咖啡里。", "explanation": "〈倒入〉。液体倒进容器应用“倒入”，“插入”指把细长物体插进去，不用于倒牛奶。"}, {"text": "请把糖插入牛奶里。", "explanation": "〈加入〉。把糖加进牛奶应说“加入”，“插入”不用于溶入或加入食材。"}, {"text": "他把一桶水插入水箱。", "explanation": "〈注入〉。大量液体流入容器应用“注入”，“插入”指把细长物体插进缝隙或孔洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "插入", "is_correct": true, "explanation": "正确：插入表示把螺丝刀伸进缝里，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹调，与“螺丝刀”和“缝里”不合。"}, {"text": "讲", "is_correct": false, "explanation": "配价：“讲”不能带处所宾语“缝里”，句子不成立。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指用水清洁，与把螺丝刀伸进缝隙的动作不合。"}], "explanations": {"插入": "正确：插入表示把螺丝刀伸进缝里，符合句意。", "煮": "语义：“煮”指加热烹调，与“螺丝刀”和“缝里”不合。", "讲": "配价：“讲”不能带处所宾语“缝里”，句子不成立。", "洗": "语义：“洗”指用水清洁，与把螺丝刀伸进缝隙的动作不合。"}, "sentence_index": 6, "correct_answer": "插入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "救护车把伤员插入医院。", "explanation": "〈送入〉。把人送到医院应用“送入”，“插入”不用于运送人员。"}, {"text": "工人把货物插入箱子。", "explanation": "〈装入〉。把货物装进箱子应用“装入”，“插入”指把细长物体插进去。"}, {"text": "卡车把木材插入仓库。", "explanation": "〈运入〉。把大批货物运进仓库应用“运入”，“插入”不用于运输货物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
