INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件东西放进另一件东西中间或里面。", "primary_collocate": null, "pronunciation": "chā rù", "ipa": "tʂʰa˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "他把钥匙插入锁里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把卡插入机器里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一张照片插入相册里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明把电源线插入了插座。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把针慢慢插入手臂。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先把电池插入遥控器。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把书插入书架中间。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把一张纸插入书页里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把筷子插入米饭中。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁管插入土里。", "target_word": "插入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "插入了", "label": "体标（了）"}, {"form": "插入过", "label": "体标（过）"}], "register": "通用", "sense_fingerprint": "把物体放进另一物体里面或中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b04d6d01-112c-4ea5-821a-a4681d4a9772') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91372, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "插入", "is_correct": true, "explanation": "chā rù，意思是把东西放进另一样东西里面。"}, {"text": "杀入", "is_correct": false, "explanation": "shā（第一声）与 chā（第一声）声母不同（sh 与 ch），杀入意思是冲进去，与插入不同。"}, {"text": "插足", "is_correct": false, "explanation": "chā zú 与 chā rù 第二个音节不同（zú 与 rù），插足意思是介入，与插入不同。"}, {"text": "掺入", "is_correct": false, "explanation": "chān（第一声）与 chā（第一声）韵母不同（an 与 a），掺入意思是混合进去，与插入不同。"}], "explanations": {"插入": "chā rù，意思是把东西放进另一样东西里面。", "杀入": "shā（第一声）与 chā（第一声）声母不同（sh 与 ch），杀入意思是冲进去，与插入不同。", "插足": "chā zú 与 chā rù 第二个音节不同（zú 与 rù），插足意思是介入，与插入不同。", "掺入": "chān（第一声）与 chā（第一声）韵母不同（an 与 a），掺入意思是混合进去，与插入不同。"}, "sentence_index": null, "correct_answer": "插入"}, "level_3": {"options": [{"text": "插入", "is_correct": true, "explanation": "正确：插入表示把钥匙放进锁孔，符合句意。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布或手摩擦表面，与“锁里”的放入义不合。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”要求“挂在＋处所”，“把钥匙挂锁里”不成立。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与把钥匙放进锁里的动作无关。"}], "explanations": {"插入": "正确：插入表示把钥匙放进锁孔，符合句意。", "擦": "语义：“擦”指用布或手摩擦表面，与“锁里”的放入义不合。", "挂": "配价：“挂”要求“挂在＋处所”，“把钥匙挂锁里”不成立。", "唱": "语义：“唱”指唱歌，与把钥匙放进锁里的动作无关。"}, "sentence_index": 0, "correct_answer": "插入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把水果插入篮子里。", "explanation": "〈放入〉。插入强调把细长或窄的东西插进缝隙或孔洞，装水果进篮子应用“放入”。"}, {"text": "他把工资插入银行。", "explanation": "〈存入〉。把钱存进银行应用“存入”，“插入”不用于往银行存钱。"}, {"text": "工人把一车土插入坑里。", "explanation": "〈填入〉。往坑里填土应用“填入”，“插入”只用于把细长物体插进缝隙或孔洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "插入", "is_correct": true, "explanation": "正确：插入表示把书放进书架中间，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指弄破，与把书放进书架的动作不合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吞咽食物，与“书架中间”无关。"}, {"text": "叠", "is_correct": false, "explanation": "配价：“叠”要求“叠在＋处所”，“把书叠书架中间”缺少“在”。"}], "explanations": {"插入": "正确：插入表示把书放进书架中间，符合句意。", "撕": "语义：“撕”指弄破，与把书放进书架的动作不合。", "吃": "语义：“吃”指吞咽食物，与“书架中间”无关。", "叠": "配价：“叠”要求“叠在＋处所”，“把书叠书架中间”缺少“在”。"}, "sentence_index": 6, "correct_answer": "插入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把热水插入杯子里。", "explanation": "〈注入〉。液体流入容器要用“注入”，“插入”指把细长物体插进缝隙或孔洞。"}, {"text": "他把盐插入汤里。", "explanation": "〈加入〉。把调料加进汤里应说“加入”，“插入”不指往汤里放调料。"}, {"text": "他把氢气插入气球。", "explanation": "〈充入〉。把气体灌进气球应用“充入”，“插入”不用于充气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把充电线插入在手机的接口。", "corrected_sentence": "他把充电线插入手机的接口。", "error_description": "错误：“插入”后面多加了“在”。“插入”本身已表示放进去，应说“把充电线插入手机的接口”，去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她已经把签字笔了插入笔袋的夹层。", "corrected_sentence": "她已经把签字笔插入笔袋的夹层。", "error_description": "错误：“了”放在了“把”字句的宾语后、动词前。“插入”的“了”应放在动词后面，或者不用“了”，说“她已经把签字笔插入笔袋的夹层”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b42b0a87-2c4a-428e-8c0f-9ae44edb9615') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
