INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91373, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "用来说一块地有多大的叫法。", "primary_collocate": null, "pronunciation": "píng fāng qiān mǐ", "ipa": "pʰiŋ˧˥ faŋ˥ tɕʰjɛn˥ mi˨˩˦", "syllable_count": 4, "sentences": [{"text": "这块草地有五平方千米大。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城市有三百平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座岛不到十平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片森林有二十平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城外有一大片地，大约八平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有多少平方千米？", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座公园大约四平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场的土地有六平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小镇只有两平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片草原有一百多平方千米。", "target_word": "平方千米", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方公里", "label": "同义异称"}], "register": "书面", "sense_fingerprint": "说明土地大小的量词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91373, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平方千米", "is_correct": true, "explanation": "正确：句中要填能说明地块大小的量词，平方千米正是用来说地有多大的。"}, {"text": "吨", "is_correct": false, "explanation": "语义：吨是重量单位，不能用来说草地有多大。"}, {"text": "升", "is_correct": false, "explanation": "语义：升是容积单位，不能用来说草地的面积。"}, {"text": "度", "is_correct": false, "explanation": "搭配：“度”多指温度、角度，不用来说草地的大小。"}], "explanations": {"平方千米": "正确：句中要填能说明地块大小的量词，平方千米正是用来说地有多大的。", "吨": "语义：吨是重量单位，不能用来说草地有多大。", "升": "语义：升是容积单位，不能用来说草地的面积。", "度": "搭配：“度”多指温度、角度，不用来说草地的大小。"}, "sentence_index": 0, "correct_answer": "平方千米"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小花园有五十平方千米。", "explanation": "这里应该用〈平方米〉。花园很小，平方千米太大，要用平方米。"}, {"text": "这个湖有三平方千米深。", "explanation": "平方千米量的是面积，说深浅要用米，这个词在这里不这么用。"}, {"text": "我班有二十平方千米的学生。", "explanation": "这里应该用〈名〉。平方千米是面积单位，数人要用量词“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91373, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平方千米", "is_correct": true, "explanation": "正确：平方千米说的是地块的面积，“大约四”后面接它最合适。"}, {"text": "立方米", "is_correct": false, "explanation": "语义：立方米是体积单位，不能用来说公园的地面面积。"}, {"text": "公斤", "is_correct": false, "explanation": "语义：公斤是重量单位，不能用来说公园的大小。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”多用于买卖时称重，不用来说公园的面积。"}], "explanations": {"平方千米": "正确：平方千米说的是地块的面积，“大约四”后面接它最合适。", "立方米": "语义：立方米是体积单位，不能用来说公园的地面面积。", "公斤": "语义：公斤是重量单位，不能用来说公园的大小。", "斤": "搭配：“斤”多用于买卖时称重，不用来说公园的面积。"}, "sentence_index": 6, "correct_answer": "平方千米"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子有一百平方千米。", "explanation": "这里应该用〈平方米〉。屋子很小，平方千米太大，要用平方米。"}, {"text": "他一天要吃两平方千米的饭。", "explanation": "这里应该用〈碗〉。平方千米量的是面积，饭要用量词“碗”来计量。"}, {"text": "这条河有五平方千米宽。", "explanation": "平方千米量的是面积，说宽窄要用米，这个词在这里不这么用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91373, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片草场有六块平方千米。", "corrected_sentence": "这片草场有六平方千米。", "error_description": "错误在“平方千米”前多加了“块”。平方千米本身就是量词，数字后直接接它，应说“六平方千米”，不能说“六块平方千米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91373, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛有三个平方千米。", "corrected_sentence": "这座岛有三平方千米。", "error_description": "错误在“平方千米”前多加了“个”。平方千米本身就是量词，数字后直接接它，应说“三平方千米”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
