INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91375, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摩擦是两样东西碰在一起来回动。", "primary_collocate": null, "pronunciation": "mó cā", "ipa": "mwɔ˧˥ tsʰa˥", "syllable_count": 2, "sentences": [{"text": "冬天两只手互相摩擦就会变暖。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎和地面摩擦，发出很大的声音。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力摩擦两块石头，想生火。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鞋底和地板摩擦时会发热。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干树枝互相摩擦，很容易着火。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车刹车的时候，轮胎在路上摩擦着。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摩擦双手，想让手暖和一点。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两块木头摩擦了很久，才冒出一点烟。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服和皮肤摩擦，脖子有点红。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球和头发互相摩擦，头发就会竖起来。", "target_word": "摩擦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摩擦了", "label": "体标"}, {"form": "摩擦着", "label": "体标"}, {"form": "摩擦力", "label": "复合"}], "register": "中性", "sense_fingerprint": "两样东西接触并来回移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "摩擦：两只手相互接触、来回移动会产生热，所以会变暖。"}, {"text": "摇", "is_correct": false, "explanation": "语义：“摇”只是晃动，不会产生热量，与“变暖”不符。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”指把东西放置，不说“互相放”，与产生热量也无关。"}, {"text": "撞", "is_correct": false, "explanation": "语义：撞击带来的是冲击，不会使手变暖。"}], "explanations": {"摩擦": "摩擦：两只手相互接触、来回移动会产生热，所以会变暖。", "摇": "语义：“摇”只是晃动，不会产生热量，与“变暖”不符。", "放": "搭配：“放”指把东西放置，不说“互相放”，与产生热量也无关。", "撞": "语义：撞击带来的是冲击，不会使手变暖。"}, "sentence_index": 0, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力摩擦那个箱子，想把它推开。", "explanation": "这里应该用〈推〉。把箱子推开要用推，摩擦只是两物接触后来回移动，推不开箱子。"}, {"text": "他摩擦了一下电灯开关，屋里就亮了。", "explanation": "这里应该用〈按〉。按下开关要用按，摩擦是两个接触面来回移动，不能用于开关。"}, {"text": "他摩擦了一个苹果，吃得很开心。", "explanation": "这里应该用〈吃〉。摩擦是两样东西接触后来回动，不表示吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦", "is_correct": true, "explanation": "摩擦：摩擦双手能产生热，所以手会暖和。"}, {"text": "举", "is_correct": false, "explanation": "语义：举起双手不会产生热，与“想让手暖和”不符。"}, {"text": "压", "is_correct": false, "explanation": "语义：“压”是用力按住，与双手取暖无关，句意不通。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能用于双手，句意不通。"}], "explanations": {"摩擦": "摩擦：摩擦双手能产生热，所以手会暖和。", "举": "语义：举起双手不会产生热，与“想让手暖和”不符。", "压": "语义：“压”是用力按住，与双手取暖无关，句意不通。", "写": "搭配：“写”的对象是文字，不能用于双手，句意不通。"}, "sentence_index": 6, "correct_answer": "摩擦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把面条摩擦熟了。", "explanation": "这里应该用〈煮〉。把食物煮熟要用煮，摩擦不能用来加热食物。"}, {"text": "他把黄瓜摩擦成了片。", "explanation": "这里应该用〈切〉。把黄瓜切成片要用切，摩擦不能把食物切开。"}, {"text": "工人们在墙上摩擦了一扇门。", "explanation": "这里应该用〈安装〉。在墙上装门要用安装，摩擦不能用来装设门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前摩擦了过木棍，所以很快就生了火。", "corrected_sentence": "他以前摩擦过木棍，所以很快就生了火。", "error_description": "体标错误：经历体“过”应直接接在动词后，“了”不能插在“摩擦”和“过”之间，应说“摩擦过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两根塑料管互相摩擦得，会产生静电。", "corrected_sentence": "两根塑料管互相摩擦，会产生静电。", "error_description": "错误：“摩擦”后多出了“得”，动词后缺少补语，句子不通；正确：去掉“得”，说“互相摩擦，会产生静电”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
