INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因为很喜欢一个人，给他起的好听的小名字。", "primary_collocate": null, "pronunciation": "ài chēng", "ipa": "aɪ̯˥˩ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "因为很喜欢女儿，爸爸给她起了爱称“糖糖”。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爱称是外婆起的，很好听。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她这么可爱，我们都想给她起个爱称。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "男朋友给我起的爱称是“小猫”。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个爱称里有爸爸对我的喜爱。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢他，所以给他起了一个爱称。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的爱称叫“小虎”，因为他很勇敢。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不喜欢这个爱称，觉得太小孩子气。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都喜欢她，给她起了一个爱称。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好听的爱称让人觉得很温暖。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "愛稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "出于喜爱给某人起的好听的小名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱称", "is_correct": true, "explanation": "“爱称”是出于喜爱给人起的好听小名，与“因为很喜欢女儿”相符。"}, {"text": "学号", "is_correct": false, "explanation": "语义：“学号”是学生的编号，不是出于喜爱而起的称呼。"}, {"text": "假期", "is_correct": false, "explanation": "语义：“假期”是休息的时段，不能用来给人起名。"}, {"text": "书名", "is_correct": false, "explanation": "语义：“书名”只用于书籍，不能给女儿起名。"}], "explanations": {"爱称": "“爱称”是出于喜爱给人起的好听小名，与“因为很喜欢女儿”相符。", "学号": "语义：“学号”是学生的编号，不是出于喜爱而起的称呼。", "假期": "语义：“假期”是休息的时段，不能用来给人起名。", "书名": "语义：“书名”只用于书籍，不能给女儿起名。"}, "sentence_index": 0, "correct_answer": "爱称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用爱称发表了小说。", "explanation": "这里应该用〈笔名〉。爱称是亲近的人之间的喜爱称呼，不能用来署名发表作品。"}, {"text": "老师在点名册上写了他的爱称。", "explanation": "这里应该用〈大名〉。爱称不是正式姓名，点名册上要写大名。"}, {"text": "他在合同上签字时，写下了自己的爱称。", "explanation": "这里应该用〈姓名〉。爱称是亲近的人之间起的小名字，签合同要写正式姓名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱称", "is_correct": true, "explanation": "“爱称”是出于喜爱起的小名，与“叫“小虎””的称呼用法相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“叫”后接的是名字，“体重”不能用来称呼人。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是身体的数据，不是称呼，与句中的“叫”不符。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不能作为“弟弟”的称呼。"}], "explanations": {"爱称": "“爱称”是出于喜爱起的小名，与“叫“小虎””的称呼用法相符。", "体重": "搭配：“叫”后接的是名字，“体重”不能用来称呼人。", "身高": "语义：“身高”是身体的数据，不是称呼，与句中的“叫”不符。", "生日": "语义：“生日”是日期，不能作为“弟弟”的称呼。"}, "sentence_index": 6, "correct_answer": "爱称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "皇帝赐给大臣一个爱称。", "explanation": "这里应该用〈封号〉。爱称是亲近的人之间表示喜爱的称呼，不由皇帝赐予。"}, {"text": "警察局给他编了一个爱称，是“0042”。", "explanation": "这里应该用〈编号〉。爱称是亲昵喜爱的小名字，档案里的数字编码不属于此类。"}, {"text": "法官在判决书里写的是他的爱称。", "explanation": "这里应该用〈称谓〉。爱称只在亲近的人之间使用，判决书里要用正式称谓。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很喜欢我，给我起了一条爱称。", "corrected_sentence": "妈妈很喜欢我，给我起了一个爱称。", "error_description": "量词错误：“爱称”应用量词“个”，“条”用于细长的东西，不能修饰“爱称”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他太聪明了，同学们就给他起了一位爱称。", "corrected_sentence": "他太聪明了，同学们就给他起了一个爱称。", "error_description": "量词错误：“位”用于人，“爱称”应用量词“个”计量，应说“一个爱称”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
