INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91378, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示亲昵喜爱的称呼。", "primary_collocate": null, "pronunciation": "ài chēng", "ipa": "aɪ̯˥˩ ʈʂʰɤŋ˥", "syllable_count": 2, "sentences": [{"text": "小明的爱称是“明明”。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈常用爱称叫我，听起来很亲切。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "情侣之间常常用爱称互相叫。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“宝贝”是父母对孩子的爱称。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶叫我的爱称是“豆豆”。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上不用爱称，只叫大名。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的爱称是什么？", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当着朋友叫她的爱称，她有点不好意思。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文里有很多爱称，比如“小宝”和“乖乖”。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个爱称太可爱了，我很喜欢。", "target_word": "爱称", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "愛稱", "label": "繁体"}], "register": "中性", "sense_fingerprint": "亲近的人之间表示喜爱的称呼，如宝贝、豆豆", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱称", "is_correct": true, "explanation": "“爱称”指亲昵的称呼，与“是“明明””这样的叠字称呼相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能用一个称呼来说明。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不是称呼，与“是“明明””不符。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“是”后接的应是称呼，“饮料”不能与之搭配。"}], "explanations": {"爱称": "“爱称”指亲昵的称呼，与“是“明明””这样的叠字称呼相符。", "身高": "体貌：“身高”是身体特征，不能用一个称呼来说明。", "生日": "语义：“生日”是日期，不是称呼，与“是“明明””不符。", "饮料": "搭配：“是”后接的应是称呼，“饮料”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "爱称"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被学校授予“三好学生”的爱称。", "explanation": "这里应该用〈称号〉。爱称是亲近的人之间表示喜爱的称呼，不能由学校授予；“三好学生”是荣誉称号。"}, {"text": "大家尊敬地称他为“泰斗”，这是他的爱称。", "explanation": "这里应该用〈尊称〉。爱称表示亲昵喜爱，不用来表示敬重。"}, {"text": "同学给他起了一个难听的爱称，叫他“笨蛋”。", "explanation": "这里应该用〈绰号〉。爱称表示亲昵喜爱，难听的称呼要用绰号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱称", "is_correct": true, "explanation": "“爱称”是亲昵的称呼，问“你的爱称是什么”语义通顺。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体特征，问法应是“多少”，不能说“是什么”。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：问饭量用“多少”，“饭量是什么”不成立。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：问年龄用“多大”或“多少”，与“是什么”搭配不当。"}], "explanations": {"爱称": "“爱称”是亲昵的称呼，问“你的爱称是什么”语义通顺。", "体重": "体貌：“体重”是身体特征，问法应是“多少”，不能说“是什么”。", "饭量": "搭配：问饭量用“多少”，“饭量是什么”不成立。", "年龄": "搭配：问年龄用“多大”或“多少”，与“是什么”搭配不当。"}, "sentence_index": 6, "correct_answer": "爱称"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被封为“公爵”，这是他的爱称。", "explanation": "这里应该用〈头衔〉。爱称是亲近的人之间表示喜爱的称呼，不是正式的封号。"}, {"text": "这份档案里记录的他的爱称是“0042”。", "explanation": "这里应该用〈编号〉。爱称是亲昵喜爱的称呼，档案里的数字编码不属于此类。"}, {"text": "车站广播里报出他的爱称，请他去柜台取行李。", "explanation": "这里应该用〈大名〉。爱称只用于亲近的人之间，公开广播要用大名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我起了一只爱称，叫“小宝”。", "corrected_sentence": "妈妈给我起了一个爱称，叫“小宝”。", "error_description": "量词错误：“爱称”应用量词“个”，“只”多用于动物，不能修饰“爱称”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给好朋友起了一把爱称，大家都很喜欢。", "corrected_sentence": "我给好朋友起了一个爱称，大家都很喜欢。", "error_description": "量词错误：“爱称”应用量词“个”，“把”用于有柄的物件，不能修饰“爱称”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
