INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91379, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "写作是用笔或电脑，把想说的话写成文章。", "primary_collocate": null, "pronunciation": "xiě zuò", "ipa": "ɕje²¹⁴ tswo⁵¹", "syllable_count": 2, "sentences": [{"text": "她每天早上写作两个小时。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在安静的咖啡馆里写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用电脑写作，不用笔。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷喜欢用笔写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上孩子睡了，妈妈才开始写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在写作，请你别打扰他。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边喝茶，一边写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在海边的小房子里写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我写作的时候喜欢听轻音乐。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在窗边，安静地写作。", "target_word": "写作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "写作了", "label": "体标"}, {"form": "写作过", "label": "体标"}, {"form": "寫作", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用笔或电脑把想说的话写成文章的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f8102f3-2b9d-4b5e-9770-fb2903a345ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "眨眼", "is_correct": false, "explanation": "语义：“眨眼”是瞬间的动作，不能持续两个小时。"}, {"text": "写作", "is_correct": true, "explanation": "正确。“写作”表示持续地写文章，可以与“两个小时”搭配。"}, {"text": "长高", "is_correct": false, "explanation": "语义：“长高”是身体的变化，不是可以持续两个小时的活动。"}, {"text": "打哈欠", "is_correct": false, "explanation": "语义：“打哈欠”是短暂的动作，不能持续两个小时。"}], "explanations": {"眨眼": "语义：“眨眼”是瞬间的动作，不能持续两个小时。", "写作": "正确。“写作”表示持续地写文章，可以与“两个小时”搭配。", "长高": "语义：“长高”是身体的变化，不是可以持续两个小时的活动。", "打哈欠": "语义：“打哈欠”是短暂的动作，不能持续两个小时。"}, "sentence_index": 0, "correct_answer": "写作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在窗边写作了一幅画。", "explanation": "这里应该用〈绘画〉。“写作”指用笔或电脑写文章，不能用于绘制图画。"}, {"text": "他在钢琴旁边写作了一首曲子。", "explanation": "这里应该用〈作曲〉。“写作”指写文章，不能用于创作乐曲。"}, {"text": "他在书上写作了自己的名字。", "explanation": "这里应该用〈签名〉。“写作”指写文章，不能用于在书上写名字，在书上写名字应称“签名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "睡觉", "is_correct": false, "explanation": "语义：“一边…一边”要求两个动作同时进行，喝茶和睡觉不能同时进行。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“一边…一边”要求两个动作能同时进行，“游泳”与“喝茶”不能这样搭配。"}, {"text": "写作", "is_correct": true, "explanation": "正确。“写作”是可以与“喝茶”同时进行的活动，与“一边…一边”搭配。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状态，不能主动与“喝茶”同时进行。"}], "explanations": {"睡觉": "语义：“一边…一边”要求两个动作同时进行，喝茶和睡觉不能同时进行。", "游泳": "搭配：“一边…一边”要求两个动作能同时进行，“游泳”与“喝茶”不能这样搭配。", "写作": "正确。“写作”是可以与“喝茶”同时进行的活动，与“一边…一边”搭配。", "发烧": "语义：“发烧”是身体状态，不能主动与“喝茶”同时进行。"}, "sentence_index": 6, "correct_answer": "写作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她坐在窗边写作了一道数学题。", "explanation": "这里应该用〈解答〉。“写作”指写文章，不能用于解数学题。"}, {"text": "她坐在窗边写作了一顿饭。", "explanation": "这里应该用〈做〉。“写作”指写文章，不能用来指做饭。"}, {"text": "她坐在窗边写作了一座房子。", "explanation": "这里应该用〈盖〉。“写作”指写文章，不能用来指盖房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天晚上厨房写作。", "corrected_sentence": "妈妈每天晚上在厨房写作。", "error_description": "地点状语“在厨房”缺少介词“在”，“厨房”直接放在动词“写作”前面，不成立。应改为“妈妈每天晚上在厨房写作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写作了过很多年。", "corrected_sentence": "她写作过很多年。", "error_description": "错误：「写作了过」；正确：「写作过」。“了”和“过”不能同时用在同一个动词后面，多出的“了”应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9548790-2410-4f0c-85c8-0374e98ae550') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
