INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91381, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改建是把旧房子变成新样子。", "primary_collocate": null, "pronunciation": "gǎi jiàn", "ipa": "kaɪ˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这座旧房子去年改建了。", "target_word": "改建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷把老房子改建成了新家。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打算明年改建厨房。", "target_word": "改建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在改建村口的旧房子。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子太旧了，所以房东决定改建。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改建以后，旧房子变得又新又亮。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上的老房子都改建过。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们花了三个月改建这间小屋。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把一楼的旧房间改建一下。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "改建后的房子比以前大多了。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改建了", "label": "体标"}, {"form": "改建过", "label": "体标"}, {"form": "改建工程", "label": "复合"}], "register": "中性", "sense_fingerprint": "把旧房子重新修建成新样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改建", "is_correct": true, "explanation": "改建指在原有旧房子基础上改造、重新修建，与“旧房子”和“去年”相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”指挪动可移动的物品，房子不能搬，“这座旧房子搬了”不通。"}, {"text": "盖", "is_correct": false, "explanation": "语义：“盖”指新建，与“旧房子”矛盾，新盖的房子不会是旧的。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是人或动物的动作，房子不会跑，句子不通。"}], "explanations": {"改建": "改建指在原有旧房子基础上改造、重新修建，与“旧房子”和“去年”相符。", "搬": "搭配：“搬”指挪动可移动的物品，房子不能搬，“这座旧房子搬了”不通。", "盖": "语义：“盖”指新建，与“旧房子”矛盾，新盖的房子不会是旧的。", "跑": "语义：“跑”是人或动物的动作，房子不会跑，句子不通。"}, "sentence_index": 0, "correct_answer": "改建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块空地上原来没有房子，他们正在改建一座新房子。", "explanation": "这里应该用〈新建〉。改建要求原来已有建筑，这块空地上没有房子，只能新建。"}, {"text": "他们正在改建这个旧想法。", "explanation": "这里应该用〈改造〉。改建只用于房屋等建筑，抽象的“想法”要用改造。"}, {"text": "他们正在改建这套旧规则。", "explanation": "这里应该用〈修订〉。改建只用于建筑物，规章条款的调整要用修订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改建", "is_correct": true, "explanation": "改建指把老房子改造重建，可以用“都改建过”表示有过这种经历。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”的主体是人，老房子不能说话，句子不通。"}, {"text": "改成", "is_correct": false, "explanation": "配价：“改成”后面必须带“成”后的宾语，句中缺少这一成分，“都改成过”不完整。"}, {"text": "迁居", "is_correct": false, "explanation": "语义：“迁居”的主体是人，老房子不能迁居，“都迁居过”与语境不符。"}], "explanations": {"改建": "改建指把老房子改造重建，可以用“都改建过”表示有过这种经历。", "说": "语义：“说”的主体是人，老房子不能说话，句子不通。", "改成": "配价：“改成”后面必须带“成”后的宾语，句中缺少这一成分，“都改成过”不完整。", "迁居": "语义：“迁居”的主体是人，老房子不能迁居，“都迁居过”与语境不符。"}, "sentence_index": 6, "correct_answer": "改建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把弟弟改建成了一个更聪明的人。", "explanation": "这里应该用〈培养〉。改建只用于建筑物，把人变得更聪明要用培养。"}, {"text": "他把老房子改建到了村口。", "explanation": "这里应该用〈搬迁〉。改建是在原地改造，不改变位置，把房子迁到别处要用搬迁。"}, {"text": "他把发型改建了一下。", "explanation": "这里应该用〈改变〉。改建只用于建筑物，发型的改动要用改变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们去年把村里的旧房子改建了新样子。", "corrected_sentence": "他们去年把村里的旧房子改建成了新样子。", "error_description": "补语遗漏：“改建”后面要用补语“成”引出改变后的结果，应说“改建成了新样子”，不能直接说“改建了新样子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这间小屋以前改建了过，现在空着。", "corrected_sentence": "这间小屋以前改建过，现在空着。", "error_description": "体标错误：经历体“过”应直接接在动词后，“了”不能插在“改建”和“过”之间，应说“改建过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
