INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91382, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在原有基础上改变结构或用途重新建造。", "primary_collocate": null, "pronunciation": "gǎi jiàn", "ipa": "kaɪ˨˩˦ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这家旧工厂改建成了博物馆。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府决定把旧车站改建成图书馆。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的老礼堂要改建成体育馆。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥太窄，明年要改建。", "target_word": "改建", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把旧仓库改建成了咖啡店。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旧体育馆改建以后，新增了一个游泳池。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教学楼正在改建，学生暂时不能进去。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座旧车库改建成了书房。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师打算改建这座大楼，让它的抗震能力更强。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧电影院改建后，成了一家大书店。", "target_word": "改建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "改建了", "label": "体标"}, {"form": "改建过", "label": "体标"}, {"form": "改建工程", "label": "复合"}], "register": "中性", "sense_fingerprint": "在原有建筑基础上改变结构或用途再建", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c255381d-c25f-404f-8dba-7242ed6bc659') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改建", "is_correct": true, "explanation": "改建指改变旧工厂的结构或用途后再建，与“成了博物馆”的用途变化相符。"}, {"text": "卖", "is_correct": false, "explanation": "搭配：“卖”表示转让，不能说“卖成了博物馆”来表示建筑变成别的用途。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”会毁掉工厂，无法使它变成博物馆。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”只是停业，并不会改变工厂的结构或用途。"}], "explanations": {"改建": "改建指改变旧工厂的结构或用途后再建，与“成了博物馆”的用途变化相符。", "卖": "搭配：“卖”表示转让，不能说“卖成了博物馆”来表示建筑变成别的用途。", "烧": "语义：“烧”会毁掉工厂，无法使它变成博物馆。", "关": "语义：“关”只是停业，并不会改变工厂的结构或用途。"}, "sentence_index": 0, "correct_answer": "改建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里原来没有桥，明年要改建一座桥。", "explanation": "这里应该用〈新建〉。改建要求原来已有建筑，原来没有桥就只能新建。"}, {"text": "这份计划太粗，明年要改建。", "explanation": "这里应该用〈修改〉。改建针对建筑物，计划和文件要用修改。"}, {"text": "这件衣服太大，明年要改建。", "explanation": "这里应该用〈改〉。改建只用于建筑物，衣服的大小调整要说改。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改建", "is_correct": true, "explanation": "改建：楼房正在改建，所以学生暂时不能进去，与语境吻合。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指对外开放，与“学生暂时不能进去”相矛盾。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”的主体是人，楼房不能跑步，句子不通。"}, {"text": "放假", "is_correct": false, "explanation": "搭配：“放假”用于学校、单位等，楼房不能放假。"}], "explanations": {"改建": "改建：楼房正在改建，所以学生暂时不能进去，与语境吻合。", "开放": "语义：“开放”指对外开放，与“学生暂时不能进去”相矛盾。", "跑步": "语义：“跑步”的主体是人，楼房不能跑步，句子不通。", "放假": "搭配：“放假”用于学校、单位等，楼房不能放假。"}, "sentence_index": 6, "correct_answer": "改建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家旧电影院改建了名字，现在叫书店。", "explanation": "这里应该用〈改名〉。改建指在原地重建或改造建筑，更换名字要用改名。"}, {"text": "旧电影院改建了一台空调。", "explanation": "这里应该用〈安装〉。改建针对建筑结构，设备的加装要用安装。"}, {"text": "工人们改建了那部手机。", "explanation": "这里应该用〈修理〉。改建只用于建筑物，手机的维修要用修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校去年把旧图书馆改建了咖啡厅。", "corrected_sentence": "学校去年把旧图书馆改建成了咖啡厅。", "error_description": "补语遗漏：改建为另一种用途时要用补语“成”引出结果，应说“改建成了咖啡厅”，不能直接接宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家老影院以前改建了过，现在变成了书店。", "corrected_sentence": "这家老影院以前改建过，现在变成了书店。", "error_description": "体标错误：经历体“过”应直接接在动词后，“了”不能插在“改建”和“过”之间，应说“改建过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f2f93bd-1c0b-4487-a1a6-0e95bf552944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
