INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "长大了，变成大人。", "primary_collocate": null, "pronunciation": "chéng nián", "ipa": "ʈʂʰɤŋ³⁵ njɛn³⁵", "syllable_count": 2, "sentences": [{"text": "我女儿明年就成年了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子成年以后，要自己生活。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成年了，不再是小孩子了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗成年需要一年左右的时间。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等你成年了，爸爸给你买车。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着孩子慢慢成年，妈妈很高兴。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫已经成年了，不会再长大了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子成年后，我们就轻松了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小离家，还没成年就自己赚钱。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年以后，我才明白父母的辛苦。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成年了", "label": "体标"}, {"form": "成年人", "label": "复合"}], "register": "通用", "sense_fingerprint": "孩子长大变成大人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "退休", "is_correct": false, "explanation": "语义：「退休」只用于退出工作岗位的人，女儿不能退休。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：「结束」的主语是活动或事件，不能说「女儿结束了」。"}, {"text": "成年", "is_correct": true, "explanation": "正确。「成年」指长大成人，符合「明年就……了」的语境。"}, {"text": "变老", "is_correct": false, "explanation": "语义：女儿明年不会变老，「变老」与「明年就」的成长语境不符。"}], "explanations": {"退休": "语义：「退休」只用于退出工作岗位的人，女儿不能退休。", "结束": "搭配：「结束」的主语是活动或事件，不能说「女儿结束了」。", "成年": "正确。「成年」指长大成人，符合「明年就……了」的语境。", "变老": "语义：女儿明年不会变老，「变老」与「明年就」的成长语境不符。"}, "sentence_index": 0, "correct_answer": "成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜已经成年了。", "explanation": "这里应该用〈成熟〉。成年只指人或动物达到成年，瓜果成熟要用「成熟」。"}, {"text": "这家公司今年成年了。", "explanation": "这里应该用〈成立〉。成年只指人或动物达到成年年龄，公司建立要用「成立」。"}, {"text": "这门技术已经成年了。", "explanation": "这里应该用〈成熟〉。成年只指人或动物达到成年年龄，技术成熟要用「成熟」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毕业", "is_correct": false, "explanation": "语义：「毕业」只用于在学校完成学业的人，猫不能毕业。"}, {"text": "退学", "is_correct": false, "explanation": "语义：「退学」只用于在校学生，猫不在学校，不能退学。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：「上班」要用于有工作单位的人，不能说猫「上班」。"}, {"text": "成年", "is_correct": true, "explanation": "正确。「成年」指猫已长到成年，与「不会再长大了」相符。"}], "explanations": {"毕业": "语义：「毕业」只用于在学校完成学业的人，猫不能毕业。", "退学": "语义：「退学」只用于在校学生，猫不在学校，不能退学。", "上班": "搭配：「上班」要用于有工作单位的人，不能说猫「上班」。", "成年": "正确。「成年」指猫已长到成年，与「不会再长大了」相符。"}, "sentence_index": 6, "correct_answer": "成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车已经成年了。", "explanation": "这里应该用〈老化〉。成年指人或动物达到成年，车辆等物件的衰老要用「老化」。"}, {"text": "这部电影已经成年了。", "explanation": "这里应该用〈上映〉。成年不用于影片，影片公开放映要用「上映」。"}, {"text": "这座桥已经成年了。", "explanation": "这里应该用〈建成〉。成年只指人或动物达到成年年龄，桥梁完工要用「建成」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我侄子明年很成年了。", "corrected_sentence": "我侄子明年就成年了。", "error_description": "错误在「很」。「成年」是动词，不能用程度副词「很」修饰。表示将来某时达到成年，应说「就成年了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91383, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他成年过以后就搬出去住了。", "corrected_sentence": "他成年以后就搬出去住了。", "error_description": "错误在「过」。「成年」表示达到成年年龄，不能加「过」表示经历，应说「成年以后」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
