INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人发育成熟，达到法定的成人年龄。", "primary_collocate": null, "pronunciation": "chéng nián", "ipa": "ʈʂʰɤŋ³⁵ njɛn³⁵", "syllable_count": 2, "sentences": [{"text": "在中国，满十八岁才算成年。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还没成年，不能开车。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年后，你就可以去投票了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年刚满十八岁，已经成年了。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，十八岁就是成年。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成年那天，家人给她办了生日会。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成年了，就要对自己负责。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他成年后第一件事是考驾照。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟明年满十八岁，才算成年。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的人十八岁成年。", "target_word": "成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成年了", "label": "体标"}, {"form": "成年人", "label": "复合"}], "register": "通用", "sense_fingerprint": "达到法律规定的成人年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730fb564-1f17-41e9-bd26-11f585744996') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开学", "is_correct": false, "explanation": "搭配：「开学」指学校开始上课，不能说「满十八岁才算开学」。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：「毕业」指完成学业，与年龄标准无关。"}, {"text": "成年", "is_correct": true, "explanation": "正确。法律上满十八岁为「成年」，与句中的年龄标准相符。"}, {"text": "结束", "is_correct": false, "explanation": "搭配：「结束」表示活动或事件终止，不能用来指人的年龄状态。"}], "explanations": {"开学": "搭配：「开学」指学校开始上课，不能说「满十八岁才算开学」。", "毕业": "语义：「毕业」指完成学业，与年龄标准无关。", "成年": "正确。法律上满十八岁为「成年」，与句中的年龄标准相符。", "结束": "搭配：「结束」表示活动或事件终止，不能用来指人的年龄状态。"}, "sentence_index": 0, "correct_answer": "成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的想法已经成年了。", "explanation": "这里应该用〈成熟〉。成年指达到法定年龄，说想法、思想等心智水平要用「成熟」。"}, {"text": "他去年从大学成年了。", "explanation": "这里应该用〈毕业〉。成年指达到法定年龄，不指完成学业，从大学毕业要用「毕业」。"}, {"text": "这项工程终于成年了。", "explanation": "这里应该用〈完工〉。成年只指人达到法定年龄，工程做完要用「完工」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：「出生」指刚来到世界，与「就要对自己负责」的成年责任不符。"}, {"text": "长牙", "is_correct": false, "explanation": "语义：「长牙」是婴儿的生理变化，与「对自己负责」的语境不符。"}, {"text": "断奶", "is_correct": false, "explanation": "搭配：「断奶」用于婴幼儿，不能用于需要对自己负责的人。"}, {"text": "成年", "is_correct": true, "explanation": "正确。「成年」指达到法定年龄，要承担对自己负责的责任。"}], "explanations": {"出生": "语义：「出生」指刚来到世界，与「就要对自己负责」的成年责任不符。", "长牙": "语义：「长牙」是婴儿的生理变化，与「对自己负责」的语境不符。", "断奶": "搭配：「断奶」用于婴幼儿，不能用于需要对自己负责的人。", "成年": "正确。「成年」指达到法定年龄，要承担对自己负责的责任。"}, "sentence_index": 6, "correct_answer": "成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座房子已经成年了。", "explanation": "这里应该用〈建成〉。成年只指人或动物，房屋完工要用「建成」。"}, {"text": "这家商店已经成年了。", "explanation": "这里应该用〈营业〉。成年只指人，店铺开始经营要用「营业」。"}, {"text": "这份报告已经成年了。", "explanation": "这里应该用〈定稿〉。成年只指人，报告写完确定下来要用「定稿」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她刚满十八岁，很成年了。", "corrected_sentence": "她刚满十八岁，就成年了。", "error_description": "错误在「很」。「成年」是动词，不能用程度副词「很」修饰。表示刚达到年龄，应说「就成年了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个男孩被成年了。", "corrected_sentence": "这个男孩成年了。", "error_description": "错误在「被」。「成年」是不及物动词，不能用「被」字句，应说「这个男孩成年了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29c39e0f-5bca-4770-9f3e-362aee4b3c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
