INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91386, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示出乎意料。", "primary_collocate": null, "pronunciation": "jū rán", "ipa": "tɕy˥ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "我以为他不会来，他居然真的来了。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的题，他居然做错了。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下着大雨，他居然没带伞出门。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子才五岁，居然会说三种语言。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了半天的手机，居然在冰箱里。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很爱睡觉，今天居然五点就起床了。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店的饭居然比大饭店的还好吃。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都十二点了，你居然还没吃饭？", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们好几年没见，他居然还记得我的名字。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板居然同意给我们多放一天假。", "target_word": "居然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；表示事情的发生出乎说话人的意料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当然", "is_correct": false, "explanation": "语义：“当然”表示理所当然，与“我以为他不会来”的预期相矛盾。"}, {"text": "居然", "is_correct": true, "explanation": "“居然”表示没想到他真的来了，与“以为他不会来”形成对比，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”要与否定词连用（从来不……），不能修饰肯定的“真的来了”。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示确定的推断，与“以为他不会来”的想法相矛盾。"}], "explanations": {"当然": "语义：“当然”表示理所当然，与“我以为他不会来”的预期相矛盾。", "居然": "“居然”表示没想到他真的来了，与“以为他不会来”形成对比，符合句意。", "从来": "搭配：“从来”要与否定词连用（从来不……），不能修饰肯定的“真的来了”。", "一定": "语义：“一定”表示确定的推断，与“以为他不会来”的想法相矛盾。"}, "sentence_index": 0, "correct_answer": "居然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早就料到他会来，他居然来了。", "explanation": "这里应该用〈果然〉。“我早就料到他会来”说明结果在预料之中，“居然”表示出乎意料，二者矛盾。"}, {"text": "学生居然要上课。", "explanation": "这里应该用〈当然〉。上课是学生理所当然的事，没有出乎意料的意思，不能用“居然”。"}, {"text": "天气预报说今天会下雨，今天居然下雨了。", "explanation": "这里应该用〈果真〉。天气预报已经预报了下雨，结果符合预料，“居然”表示出乎意料，不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与“比大饭店的还好吃”所表达的意外感不合。"}, {"text": "居然", "is_correct": true, "explanation": "“居然”表示没想到小店的饭比大饭店还好吃，出乎意料，符合句意。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”不能用在“比……还好吃”这样的比较结构中。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示紧接着发生，与饭菜的口味比较无关。"}], "explanations": {"故意": "语义：“故意”表示有意为之，与“比大饭店的还好吃”所表达的意外感不合。", "居然": "“居然”表示没想到小店的饭比大饭店还好吃，出乎意料，符合句意。", "十分": "搭配：“十分”不能用在“比……还好吃”这样的比较结构中。", "马上": "语义：“马上”表示紧接着发生，与饭菜的口味比较无关。"}, "sentence_index": 6, "correct_answer": "居然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年居然有十二个月。", "explanation": "这里不能用〈居然〉。一年有十二个月是常识，没有出乎意料的意思。"}, {"text": "我们每周居然开会。", "explanation": "这里应该用〈照例〉。每周开会是固定的安排，不是意外，“居然”不能用。"}, {"text": "请你居然把窗户关上。", "explanation": "这里不能用〈居然〉。“居然”表示出乎意料，不能用于请求，直接说“请”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很忙，今天居燃回家吃晚饭了。", "corrected_sentence": "妈妈很忙，今天居然回家吃晚饭了。", "error_description": "错误形式：“居燃”；正确形式：“居然”。“然”和“燃”读音相同，但“燃”是燃烧的意思。副词“居然”表示出乎意料，要写“然”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他平时很懒，今天距然没有迟到。", "corrected_sentence": "他平时很懒，今天居然没有迟到。", "error_description": "错误形式：“距然”；正确形式：“居然”。“距”和“居”读音相近，但“距”是距离的意思。表示出乎意料的副词要写“居然”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
