INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "敲是用手或东西打在上面，发出响声。", "primary_collocate": null, "pronunciation": "qiāo", "ipa": "tɕʰiɑu˥", "syllable_count": 1, "sentences": [{"text": "有人在敲门，你快去看看。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手指轻轻敲着桌子。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师敲了敲黑板，让大家安静。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我敲了三下门，里面没人回答。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明拿筷子敲碗，发出叮叮的响声。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先敲门，再走进办公室。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她敲过好几次窗户，可是没人理她。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用小锤子敲墙，听听里面是不是空的。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边听音乐，一边用笔敲着桌子。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜有人敲窗，我吓了一跳。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "敲了", "label": "完成体"}, {"form": "敲着", "label": "持续体"}, {"form": "敲过", "label": "经历体"}, {"form": "敲敲", "label": "重叠"}, {"form": "敲门", "label": "复合"}], "register": "中性", "sense_fingerprint": "用手或东西打在物体上，发出响声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91387, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敲", "is_correct": true, "explanation": "敲：用手或东西打在物体上，发出响声。"}, {"text": "桥", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是桥。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiāo（第一声）声调不同，意思是灵巧、巧妙。"}, {"text": "翘", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是翘起。"}, {"text": "瞧", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是看。"}], "explanations": {"敲": "敲：用手或东西打在物体上，发出响声。", "桥": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是桥。", "巧": "qiǎo（第三声）与 qiāo（第一声）声调不同，意思是灵巧、巧妙。", "翘": "qiào（第四声）与 qiāo（第一声）声调不同，意思是翘起。", "瞧": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是看。"}, "sentence_index": null, "correct_answer": "敲"}, "level_3": {"options": [{"text": "敲", "is_correct": true, "explanation": "“敲”表示用手或东西打在门上，句中是有人在叫门。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲、戏曲，不能说“唱门”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，门不能被吃，与句意不符。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是可以抛掷的东西，不能说“扔门”。"}], "explanations": {"敲": "“敲”表示用手或东西打在门上，句中是有人在叫门。", "唱": "搭配：“唱”的对象是歌曲、戏曲，不能说“唱门”。", "吃": "语义：“吃”指进食，门不能被吃，与句意不符。", "扔": "搭配：“扔”的对象是可以抛掷的东西，不能说“扔门”。"}, "sentence_index": 0, "correct_answer": "敲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用抹布把桌子敲得干干净净。", "explanation": "“敲”不能替换〈擦〉：用抹布让桌子变干净要用“擦”；“敲”只表示击打发出声音，不能让桌子变干净。"}, {"text": "他给我敲了一个电话，我没接到。", "explanation": "“敲”不能替换〈打〉：打电话要用“打”，不说“敲电话”。"}, {"text": "他敲了一张照片，大家都笑了。", "explanation": "“敲”不能替换〈拍〉：拍照片要用“拍”，不能说“敲照片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91387, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敲", "is_correct": true, "explanation": "敲：用手或东西打在物体上，发出响声。"}, {"text": "乔", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，多用作姓，或用于“乔木”（高大的树）。"}, {"text": "俏", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是俊俏、好看。"}, {"text": "撬", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是用工具用力抬起或打开。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 qiāo 声母不同（x 与 q），意思是消失。"}], "explanations": {"敲": "敲：用手或东西打在物体上，发出响声。", "乔": "qiáo（第二声）与 qiāo（第一声）声调不同，多用作姓，或用于“乔木”（高大的树）。", "俏": "qiào（第四声）与 qiāo（第一声）声调不同，意思是俊俏、好看。", "撬": "qiào（第四声）与 qiāo（第一声）声调不同，意思是用工具用力抬起或打开。", "消": "xiāo 与 qiāo 声母不同（x 与 q），意思是消失。"}, "sentence_index": null, "correct_answer": "敲"}, "level_3": {"options": [{"text": "敲", "is_correct": true, "explanation": "“敲”表示用手或东西打在窗户上，与“没人理她”的情境相符。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”不能以窗户为对象，不能说“听窗户”。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不能以窗户为对象，不能说“笑窗户”。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，与“窗户”的动作不符，句意不通。"}], "explanations": {"敲": "“敲”表示用手或东西打在窗户上，与“没人理她”的情境相符。", "听": "搭配：“听”不能以窗户为对象，不能说“听窗户”。", "笑": "搭配：“笑”不能以窗户为对象，不能说“笑窗户”。", "闻": "语义：“闻”指用鼻子嗅，与“窗户”的动作不符，句意不通。"}, "sentence_index": 6, "correct_answer": "敲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她敲了一首钢琴曲，大家都很感动。", "explanation": "“敲”不能替换〈弹〉：钢琴曲要用“弹”，不用“敲”。"}, {"text": "他敲了一根火柴，屋里亮了起来。", "explanation": "“敲”不能替换〈划〉：火柴要用“划”，不用“敲”。"}, {"text": "妈妈敲了一支蜡烛，房间立刻亮了。", "explanation": "“敲”不能替换〈点〉：蜡烛要用“点”，表示点燃，不用“敲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他敲了一个门，然后走了进去。", "corrected_sentence": "他敲了一下门，然后走了进去。", "error_description": "错误：“敲”的动量词应为“下”，应说“敲了一下门”，不能用“个”。“下”是敲击动作的计量单位。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她着敲窗户，想叫醒熟睡的邻居。", "corrected_sentence": "她敲着窗户，想叫醒熟睡的邻居。", "error_description": "错误：“着”表示动作持续，须紧跟在动词后，应说“敲着窗户”，不能放在“敲”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
