INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91388, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在物体上打击使发出声音。", "primary_collocate": null, "pronunciation": "qiāo", "ipa": "tɕʰiɑu˥", "syllable_count": 1, "sentences": [{"text": "庙里的和尚每天早上都敲钟。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，大家一起敲锣打鼓。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着小棍子敲鼓，声音很大。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用小锤子敲了敲铜锣，声音传得很远。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人师傅敲了敲水管，听听有没有水。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的钟已经敲过十二下了。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们敲着盆子唱歌。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用铃鼓敲出了节奏，大家跟着拍手。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他敲了一下杯子，大家都安静了。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用勺子敲了敲锅，告诉孩子吃饭了。", "target_word": "敲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "敲了", "label": "完成体"}, {"form": "敲着", "label": "持续体"}, {"form": "敲过", "label": "经历体"}, {"form": "敲敲", "label": "重叠"}, {"form": "敲钟", "label": "复合"}], "register": "中性", "sense_fingerprint": "打击钟鼓等物体使其发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91388, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "敲", "is_correct": true, "explanation": "敲：在物体上打击，使其发出声音。"}, {"text": "桥", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是桥。"}, {"text": "翘", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是翘起。"}, {"text": "俏", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是俊俏、好看。"}, {"text": "瞧", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是看。"}], "explanations": {"敲": "敲：在物体上打击，使其发出声音。", "桥": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是桥。", "翘": "qiào（第四声）与 qiāo（第一声）声调不同，意思是翘起。", "俏": "qiào（第四声）与 qiāo（第一声）声调不同，意思是俊俏、好看。", "瞧": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是看。"}, "sentence_index": null, "correct_answer": "敲"}, "level_3": {"options": [{"text": "敲", "is_correct": true, "explanation": "“敲”表示在钟上打击使其发出声音，与和尚敲钟的情境相符。"}, {"text": "念", "is_correct": false, "explanation": "搭配：“念”的对象是经文、文字，不能说“念钟”。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”是用气流发声，与用物体撞击钟的动作不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲、经文，不能说“唱钟”。"}], "explanations": {"敲": "“敲”表示在钟上打击使其发出声音，与和尚敲钟的情境相符。", "念": "搭配：“念”的对象是经文、文字，不能说“念钟”。", "吹": "语义：“吹”是用气流发声，与用物体撞击钟的动作不符。", "唱": "搭配：“唱”的对象是歌曲、经文，不能说“唱钟”。"}, "sentence_index": 0, "correct_answer": "敲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他敲了一声口哨，大家都围过来。", "explanation": "“敲”不能替换〈吹〉：口哨要用“吹”，不用“敲”。"}, {"text": "他敲了一首歌，大家都跟着唱。", "explanation": "“敲”不能替换〈唱〉：歌要用“唱”，不用“敲”。"}, {"text": "她敲了一首小提琴曲，大家都鼓掌。", "explanation": "“敲”不能替换〈拉〉：小提琴曲要用“拉”，不用“敲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91388, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "敲", "is_correct": true, "explanation": "敲：在物体上打击，使其发出声音。"}, {"text": "乔", "is_correct": false, "explanation": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是高。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiāo（第一声）声调不同，意思是灵巧、巧妙。"}, {"text": "撬", "is_correct": false, "explanation": "qiào（第四声）与 qiāo（第一声）声调不同，意思是用工具用力抬起或打开。"}, {"text": "消", "is_correct": false, "explanation": "xiāo 与 qiāo 声母不同（x 与 q），意思是消失。"}], "explanations": {"敲": "敲：在物体上打击，使其发出声音。", "乔": "qiáo（第二声）与 qiāo（第一声）声调不同，意思是高。", "巧": "qiǎo（第三声）与 qiāo（第一声）声调不同，意思是灵巧、巧妙。", "撬": "qiào（第四声）与 qiāo（第一声）声调不同，意思是用工具用力抬起或打开。", "消": "xiāo 与 qiāo 声母不同（x 与 q），意思是消失。"}, "sentence_index": null, "correct_answer": "敲"}, "level_3": {"options": [{"text": "敲", "is_correct": true, "explanation": "“敲”表示用东西打击盆子使其发声，与孩子们敲盆子唱歌相符。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”的对象是琴弦乐器，不能说“弹盆子”。"}, {"text": "闻", "is_correct": false, "explanation": "语义：“闻”指用鼻子嗅，与用东西打击盆子的动作不符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿，不能咬着盆子唱歌，句意不合。"}], "explanations": {"敲": "“敲”表示用东西打击盆子使其发声，与孩子们敲盆子唱歌相符。", "弹": "搭配：“弹”的对象是琴弦乐器，不能说“弹盆子”。", "闻": "语义：“闻”指用鼻子嗅，与用东西打击盆子的动作不符。", "咬": "语义：“咬”指用牙齿，不能咬着盆子唱歌，句意不合。"}, "sentence_index": 6, "correct_answer": "敲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用勺子敲了敲汤，告诉孩子吃饭了。", "explanation": "“敲”不能替换〈搅〉：汤要用“搅”，不用“敲”。"}, {"text": "我用锅铲敲了敲菜，告诉孩子吃饭了。", "explanation": "“敲”不能替换〈炒〉：菜要用“炒”，不用“敲”。"}, {"text": "我在牙刷上敲了一点牙膏，告诉孩子该刷牙了。", "explanation": "“敲”不能替换〈挤〉：把牙膏弄到牙刷上要用“挤”，不用“敲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.