INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做一件事要填的表、要走的步骤。", "primary_collocate": null, "pronunciation": "shǒu xù", "ipa": "ʂoʊ̯˨˩˦ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "我今天去银行办手续。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办签证的手续很复杂。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先填表，再去办手续。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "入学手续已经办好了。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手续不难，十分钟就够了。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你带身份证了吗？办手续要用。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房子要办什么手续？", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手续太多了，我有点儿不耐烦。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国前，他把手续都办完了。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上办手续比去窗口方便多了。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "手續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办事时要填写的表格和要走的步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：手续 shǒuxù，指办事要填的表和要走的步骤。"}, {"text": "手术", "is_correct": false, "explanation": "x 与 sh 声母不同，声调相同。「手术」指外科治疗，与办事程序无关。"}, {"text": "守护", "is_correct": false, "explanation": "x 与 h 声母不同，声调相同。「守护」指保卫和照顾。"}, {"text": "首秀", "is_correct": false, "explanation": "ü 与 iu 韵母不同，声调相同。「首秀」指第一次公开表演。"}, {"text": "手速", "is_correct": false, "explanation": "x 与 s 声母不同，声调相同。「手速」指手操作或打字的速度。"}], "explanations": {"手续": "正确：手续 shǒuxù，指办事要填的表和要走的步骤。", "手术": "x 与 sh 声母不同，声调相同。「手术」指外科治疗，与办事程序无关。", "守护": "x 与 h 声母不同，声调相同。「守护」指保卫和照顾。", "首秀": "ü 与 iu 韵母不同，声调相同。「首秀」指第一次公开表演。", "手速": "x 与 s 声母不同，声调相同。「手速」指手操作或打字的速度。"}, "sentence_index": null, "correct_answer": "手续"}, "level_3": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：去银行办理事务可以说“办手续”，这是固定搭配。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：银行不办饭菜，与“去银行”的场景不符。"}, {"text": "笑话", "is_correct": false, "explanation": "搭配：“办”不接“笑话”，说笑话要用“讲”。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形外貌，不能用“办”来处理。"}], "explanations": {"手续": "正确：去银行办理事务可以说“办手续”，这是固定搭配。", "饭菜": "语义：银行不办饭菜，与“去银行”的场景不符。", "笑话": "搭配：“办”不接“笑话”，说笑话要用“讲”。", "身材": "体貌：“身材”指人的体形外貌，不能用“办”来处理。"}, "sentence_index": 0, "correct_answer": "手续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把手续放进了钱包。", "explanation": "这里应该用〈驾照〉。手续是办事要走的程序，不能放进钱包里。"}, {"text": "这个问题我想了很多手续。", "explanation": "这里应该用〈办法〉。“想”的对象是办法，手续是办事的程序，不能被想。"}, {"text": "他把手续挂在了客厅的墙上。", "explanation": "这里应该用〈奖状〉。手续是办事要走的程序，不是能挂在墙上的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：手续 shǒuxù，指办事要填的表和要走的步骤。"}, {"text": "首度", "is_correct": false, "explanation": "x 与 d 声母不同，ü 与 u 韵母不同，声调相同。「首度」指第一次。"}, {"text": "受训", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同，xùn 比 xù 多一个 n。「受训」指接受培训。"}, {"text": "守墓", "is_correct": false, "explanation": "m 与 x 声母不同，声调相同。「守墓」指看守坟墓。"}, {"text": "手部", "is_correct": false, "explanation": "x 与 b 声母不同，声调相同。「手部」指手的部位。"}], "explanations": {"手续": "正确：手续 shǒuxù，指办事要填的表和要走的步骤。", "首度": "x 与 d 声母不同，ü 与 u 韵母不同，声调相同。「首度」指第一次。", "受训": "shòu 与 shǒu 声调不同，xùn 比 xù 多一个 n。「受训」指接受培训。", "守墓": "m 与 x 声母不同，声调相同。「守墓」指看守坟墓。", "手部": "x 与 b 声母不同，声调相同。「手部」指手的部位。"}, "sentence_index": null, "correct_answer": "手续"}, "level_3": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：租房前要办的事务叫手续，“办什么手续”很自然。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“办”不接“歌曲”，歌曲要“唱”或“录”。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：租房与粮食无关，句子问的是要办理的事务。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是房屋的环境，不是需要办理的事务。"}], "explanations": {"手续": "正确：租房前要办的事务叫手续，“办什么手续”很自然。", "歌曲": "搭配：“办”不接“歌曲”，歌曲要“唱”或“录”。", "粮食": "语义：租房与粮食无关，句子问的是要办理的事务。", "花园": "语义：花园是房屋的环境，不是需要办理的事务。"}, "sentence_index": 6, "correct_answer": "手续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "网上开手续比去窗口方便多了。", "explanation": "这里应该用〈证明〉。“开”配证明，手续是办事要走的程序，不能“开”。"}, {"text": "网上填手续比去窗口方便多了。", "explanation": "这里应该用〈表格〉。“填”配表格，手续不是可以填写的东西。"}, {"text": "网上买手续比去窗口方便多了。", "explanation": "这里应该用〈票〉。“买”配票，手续不是可以买的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我一共办了三手续。", "corrected_sentence": "我一共办了三项手续。", "error_description": "错误：“手续”前面漏掉了量词。应为“三项手续”，手续的量词是“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的手续终于办了完。", "corrected_sentence": "今天的手续终于办完了。", "error_description": "错误：结果补语“完”应紧接动词“办”，“了”应放在“办完”之后，应说“办完了”，不能说“办了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
