INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91390, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "办事时必须依次完成的程序和环节。", "primary_collocate": null, "pronunciation": "shǒu xù", "ipa": "ʂoʊ̯˨˩˦ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "办护照有几个手续，要一个一个来。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手续不全，医院不让他住院。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些手续必须按顺序完成。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房的手续有哪些环节？", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "换工作要先走完离职手续。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有办完手续，不能上班。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手续一步也不能少。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理手续的时候要排队等。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师告诉我们入学手续的顺序。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手续都完成了，你可以进去了。", "target_word": "手续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "手續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办事时必须按顺序完成的程序和环节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f3093e3-711e-4558-951f-c3aa1fa2e268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：手续 shǒuxù，指办事时必须依次完成的程序。"}, {"text": "手术", "is_correct": false, "explanation": "x 与 sh 声母不同，声调相同。「手术」指外科治疗，与办事程序无关。"}, {"text": "守护", "is_correct": false, "explanation": "x 与 h 声母不同，声调相同。「守护」指保卫和照顾。"}, {"text": "首秀", "is_correct": false, "explanation": "ü 与 iu 韵母不同，声调相同。「首秀」指第一次公开表演。"}, {"text": "手速", "is_correct": false, "explanation": "x 与 s 声母不同，声调相同。「手速」指手操作或打字的速度。"}], "explanations": {"手续": "正确：手续 shǒuxù，指办事时必须依次完成的程序。", "手术": "x 与 sh 声母不同，声调相同。「手术」指外科治疗，与办事程序无关。", "守护": "x 与 h 声母不同，声调相同。「守护」指保卫和照顾。", "首秀": "ü 与 iu 韵母不同，声调相同。「首秀」指第一次公开表演。", "手速": "x 与 s 声母不同，声调相同。「手速」指手操作或打字的速度。"}, "sentence_index": null, "correct_answer": "手续"}, "level_3": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：办护照要依次完成几道程序，可以说“几个手续”。"}, {"text": "行李", "is_correct": false, "explanation": "语义：办护照是办理程序，“行李”与办理无关。"}, {"text": "电影", "is_correct": false, "explanation": "语义：办护照不涉及电影，句子问的是办理的程序。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：“面孔”指人的脸，不是办理的对象。"}], "explanations": {"手续": "正确：办护照要依次完成几道程序，可以说“几个手续”。", "行李": "语义：办护照是办理程序，“行李”与办理无关。", "电影": "语义：办护照不涉及电影，句子问的是办理的程序。", "面孔": "体貌：“面孔”指人的脸，不是办理的对象。"}, "sentence_index": 0, "correct_answer": "手续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请先填写手续，再去窗口办理。", "explanation": "这里应该用〈表格〉。“填写”的对象是表格，手续不能填写。"}, {"text": "请到窗口开手续。", "explanation": "这里应该用〈证明〉。“开”配证明，手续不能开。"}, {"text": "店里挂着营业手续。", "explanation": "这里应该用〈执照〉。“挂”配执照，手续是办事的程序，不能挂在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91390, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：手续 shǒuxù，指办事时必须依次完成的程序。"}, {"text": "首度", "is_correct": false, "explanation": "x 与 d 声母不同，ü 与 u 韵母不同，声调相同。「首度」指第一次。"}, {"text": "受训", "is_correct": false, "explanation": "shòu 与 shǒu 声调不同，xùn 比 xù 多一个 n。「受训」指接受培训。"}, {"text": "守墓", "is_correct": false, "explanation": "m 与 x 声母不同，声调相同。「守墓」指看守坟墓。"}, {"text": "手部", "is_correct": false, "explanation": "x 与 b 声母不同，声调相同。「手部」指手的部位。"}], "explanations": {"手续": "正确：手续 shǒuxù，指办事时必须依次完成的程序。", "首度": "x 与 d 声母不同，ü 与 u 韵母不同，声调相同。「首度」指第一次。", "受训": "shòu 与 shǒu 声调不同，xùn 比 xù 多一个 n。「受训」指接受培训。", "守墓": "m 与 x 声母不同，声调相同。「守墓」指看守坟墓。", "手部": "x 与 b 声母不同，声调相同。「手部」指手的部位。"}, "sentence_index": null, "correct_answer": "手续"}, "level_3": {"options": [{"text": "手续", "is_correct": true, "explanation": "正确：“一步也不能少”说的是必须依次完成的程序，正好用“手续”。"}, {"text": "篮球", "is_correct": false, "explanation": "语义：篮球不是办事程序，句子说的是必须依次完成的事。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“少”一步要配程序，不能说饮料少了一步。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”是外形，不是按步骤完成的程序。"}], "explanations": {"手续": "正确：“一步也不能少”说的是必须依次完成的程序，正好用“手续”。", "篮球": "语义：篮球不是办事程序，句子说的是必须依次完成的事。", "饮料": "搭配：“少”一步要配程序，不能说饮料少了一步。", "发型": "体貌：“发型”是外形，不是按步骤完成的程序。"}, "sentence_index": 6, "correct_answer": "手续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请写好手续再交上来。", "explanation": "这里应该用〈申请书〉。“写”的对象是申请书，手续不能写。"}, {"text": "进门前要买手续。", "explanation": "这里应该用〈门票〉。“买”配门票，手续不能买。"}, {"text": "门口要贴手续。", "explanation": "这里应该用〈告示〉。“贴”配告示，手续不能贴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "办这张卡需要两只手续。", "corrected_sentence": "办这张卡需要两项手续。", "error_description": "错误：“手续”的量词用错。手续用量词“项”，“只”用于动物等，应说“两项手续”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91390, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "手续全部办了完以后才能拿证。", "corrected_sentence": "手续全部办完以后才能拿证。", "error_description": "错误：结果补语“完”应紧接动词“办”，“了”不能放在“完”之前，应说“办完”，不能说“办了完”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2565c913-d15b-412d-a0bf-b9546c6b99cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
