INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由职工组成的、维护职工权益的群众组织。", "primary_collocate": null, "pronunciation": "gōng huì", "ipa": "kʊŋ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他是公司工会的主席。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会帮工人要回了工资。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们把问题告诉了工会。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有一个工会。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会每年给工人发节日礼物。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她去年加入了工会。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会和公司谈好了新的工作时间。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们请工会帮他们和老板谈工资。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张在工会工作了十年。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工会组织大家去公园玩。", "target_word": "工会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个工会", "label": "量词"}, {"form": "工会主席", "label": "复合"}, {"form": "工會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由职工组成、维护职工权益的组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工会", "is_correct": true, "explanation": "正确。工会是工人组成的群众组织，「公司工会的主席」指公司工会的负责人。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：办公室一般设主任，不说「办公室的主席」。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：学校的负责人是校长，不说「学校的主席」。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是公司的下属机构，「公司公园的主席」说不通。"}], "explanations": {"工会": "正确。工会是工人组成的群众组织，「公司工会的主席」指公司工会的负责人。", "办公室": "搭配：办公室一般设主任，不说「办公室的主席」。", "学校": "搭配：学校的负责人是校长，不说「学校的主席」。", "公园": "语义：公园不是公司的下属机构，「公司公园的主席」说不通。"}, "sentence_index": 0, "correct_answer": "工会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几个国家组成了一个工会。", "explanation": "这里应该用〈联盟〉。工会只指职工组织，国家之间结成的组织要用联盟。"}, {"text": "同学们在学校有一个文学工会。", "explanation": "这里应该用〈社团〉。工会只指职工组织，文学爱好者的团体要用社团。"}, {"text": "我们厂有一个篮球工会。", "explanation": "这里应该用〈俱乐部〉。篮球爱好者的群体要说俱乐部，工会是为维护职工权益而设的组织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工会", "is_correct": true, "explanation": "正确。工会代表工人与公司谈判，所以能与公司谈好工作时间。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不能与公司谈判。"}, {"text": "大楼", "is_correct": false, "explanation": "配价：谈判需要有行为主体，大楼不能与公司谈好工作时间。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是电器，不能和公司谈工作时间。"}], "explanations": {"工会": "正确。工会代表工人与公司谈判，所以能与公司谈好工作时间。", "蛋糕": "语义：蛋糕是食物，不能与公司谈判。", "大楼": "配价：谈判需要有行为主体，大楼不能与公司谈好工作时间。", "电视": "语义：电视是电器，不能和公司谈工作时间。"}, "sentence_index": 6, "correct_answer": "工会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司有一只工会。", "explanation": "这里应该用〈个〉。工会不用“只”来量，“只”用于动物等。"}, {"text": "我们公司有一条工会。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，不用于工会。"}, {"text": "他们厂里有一把工会。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，工会不用“把”来量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王工会工作了五年。", "corrected_sentence": "小王在工会工作了五年。", "error_description": "“在”漏掉了。表示处所要说“在工会工作”，不能直接说“工会工作”。错误形式：工会工作；正确形式：在工会工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们厂里成立了一座工会。", "corrected_sentence": "他们厂里成立了一个工会。", "error_description": "量词「座」用于山、楼等大型固定物，工会要用「个」。正确是「成立了一个工会」，错误是「一座工会」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
