INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91394, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对数据进行收集、整理、计算和分析的过程。", "primary_collocate": null, "pronunciation": "shù jù chǔ lǐ", "ipa": "ʂu˥˩ tɕy˥˩ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "数据处理包括收集和分析。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理的第一步是收集数据。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次数据处理花了三个小时。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理的过程不能有错误。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了数据处理的几个步骤。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理需要整理、计算和分析。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理的结果要保存好。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习数据处理的方法。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学研究离不开数据处理。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据处理中出了错，结果就不对。", "target_word": "数据处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "數據處理", "label": "繁体"}, {"form": "数据处理中心", "label": "复合"}], "register": "中性", "sense_fingerprint": "收集整理计算分析数据的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfa04d34-6d12-4e16-bb64-7be55add196d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做饭菜，不包括收集和分析数据，与“收集和分析”冲突。"}, {"text": "数据处理", "is_correct": true, "explanation": "正确：指对数据进行收集、整理、计算和分析的过程。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：旅游是出行游览，不包括收集和分析数据，与“收集和分析”冲突。"}, {"text": "文字处理", "is_correct": false, "explanation": "搭配：“文字处理”指编辑文字，与“收集和分析”这类数据工作搭配不当。"}], "explanations": {"烹饪": "语义：烹饪是做饭菜，不包括收集和分析数据，与“收集和分析”冲突。", "数据处理": "正确：指对数据进行收集、整理、计算和分析的过程。", "旅游": "语义：旅游是出行游览，不包括收集和分析数据，与“收集和分析”冲突。", "文字处理": "搭配：“文字处理”指编辑文字，与“收集和分析”这类数据工作搭配不当。"}, "sentence_index": 0, "correct_answer": "数据处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台数据处理很贵。", "explanation": "这里应该用〈电脑〉。数据处理是对数据的整理过程，不是设备，不能用“台”来数。"}, {"text": "我们去数据处理散步。", "explanation": "这里应该用〈公园〉。数据处理是过程，不是地方，不能去散步。"}, {"text": "数据处理给病人看病。", "explanation": "这里应该用〈医生〉。数据处理不是人，不能给病人看病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞蹈", "is_correct": false, "explanation": "语义：舞蹈是表演动作，没有需要保存的结果，与“结果要保存好”冲突。"}, {"text": "数据处理", "is_correct": true, "explanation": "正确：数据处理的结果指整理、计算、分析之后得到的数据，需要保存。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步是步行活动，没有需要保存的结果，与“结果要保存好”冲突。"}, {"text": "婚礼", "is_correct": false, "explanation": "搭配：“结果”多用于考试、实验、比赛，与“婚礼的结果”搭配不当。"}], "explanations": {"舞蹈": "语义：舞蹈是表演动作，没有需要保存的结果，与“结果要保存好”冲突。", "数据处理": "正确：数据处理的结果指整理、计算、分析之后得到的数据，需要保存。", "散步": "语义：散步是步行活动，没有需要保存的结果，与“结果要保存好”冲突。", "婚礼": "搭配：“结果”多用于考试、实验、比赛，与“婚礼的结果”搭配不当。"}, "sentence_index": 6, "correct_answer": "数据处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用数据处理切菜。", "explanation": "这里应该用〈刀〉。数据处理是整理数字的过程，不能用来切菜。"}, {"text": "我们一起唱数据处理。", "explanation": "这里应该用〈歌〉。数据处理不是歌曲，不能唱。"}, {"text": "妈妈在厨房里烧了一锅数据处理。", "explanation": "这里应该用〈菜〉。数据处理不能烧来吃，应该说烧了一锅菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只数据处理用了三天。", "corrected_sentence": "一次数据处理用了三天。", "error_description": "量词错误：“数据处理”是过程，应用量词“次”，不能用“只”。正确说法：一次数据处理用了三天。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条数据处理用了一个上午。", "corrected_sentence": "这次数据处理用了一个上午。", "error_description": "量词错误：“数据处理”是一个过程，应用量词“次”，不能用“条”。正确说法：这次数据处理用了一个上午。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2e89a61-d62c-42c5-87ed-4c30668c8358') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
