INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91395, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比不过别人，会输。", "primary_collocate": null, "pronunciation": "dǎ bu guò", "ipa": "ta˨˩ pu kuo˥˩", "syllable_count": 3, "sentences": [{"text": "他比我高，我打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手太强了，我们打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个队很强，我们肯定打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他练了十年，我怎么也打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我知道自己打不过你，不比了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们人多，我们打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明打不过哥哥，就哭了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他比你大三岁，你打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打不过他，只好认输。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他力气那么大，谁都打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打得过", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "实力不如别人，对上就会输", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：实力不如对方，会输，与“他比我高”的语境一致。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”指仗势压人，与“实力不如对方”的语境不合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”是身体动作，与比赛胜负无关，句意不通。"}, {"text": "发烧", "is_correct": false, "explanation": "配价：“发烧”是不及物动词，不能带宾语“他”，“我发烧他”不成立。"}], "explanations": {"打不过": "打不过：实力不如对方，会输，与“他比我高”的语境一致。", "欺负": "语义：“欺负”指仗势压人，与“实力不如对方”的语境不合。", "咬": "语义：“咬”是身体动作，与比赛胜负无关，句意不通。", "发烧": "配价：“发烧”是不及物动词，不能带宾语“他”，“我发烧他”不成立。"}, "sentence_index": 0, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩打不过他。", "explanation": "这里应该用〈比不过〉。打不过用于较量胜负，成绩、水平的比较要用比不过。"}, {"text": "这道题很难，我打不过它。", "explanation": "这里应该用〈做不出〉。打不过指较量中败给对方，题目不是对手，表示解不出要用做不出。"}, {"text": "我们终于打不过他们，取得了胜利。", "explanation": "这里应该用〈打败〉。打不过表示实力不足而输，与“取得了胜利”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：实力不如对方，会输，与“小明”和“哥哥”的较量语境一致。"}, {"text": "模仿", "is_correct": false, "explanation": "语义：“模仿”指学样，与“就哭了”的因果不通。"}, {"text": "拜访", "is_correct": false, "explanation": "语域：“拜访”偏礼节用语，叙述孩子争执时语域不合，句意也不通。"}, {"text": "辅导", "is_correct": false, "explanation": "语义：“辅导”指指导学习，“辅导哥哥，就哭了”因果不通。"}], "explanations": {"打不过": "打不过：实力不如对方，会输，与“小明”和“哥哥”的较量语境一致。", "模仿": "语义：“模仿”指学样，与“就哭了”的因果不通。", "拜访": "语域：“拜访”偏礼节用语，叙述孩子争执时语域不合，句意也不通。", "辅导": "语义：“辅导”指指导学习，“辅导哥哥，就哭了”因果不通。"}, "sentence_index": 6, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的销售额打不过去年。", "explanation": "这里应该用〈超过〉。打不过用于人或队伍的较量，业绩、数量的比较要用超过。"}, {"text": "这么大的错误，老师一眼就看出来了，你打不过的。", "explanation": "这里应该用〈逃不过〉。打不过表示较量胜负，不表示躲避或瞒过。"}, {"text": "这些作业我打不过。", "explanation": "这里应该用〈做不完〉。打不过用于较量，作业做不完要说做不完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我练了一年，还是打不过了他。", "corrected_sentence": "我练了一年，还是打不过他。", "error_description": "错误：“了”插在可能补语“打不过”和宾语“他”之间。正确：应说“还是打不过他”，“了”不能放在补语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小红把打不过弟弟，就生气了。", "corrected_sentence": "小红打不过弟弟，就生气了。", "error_description": "错误：在可能补语“打不过”前多加了“把”。正确：“打不过”前面不能加“把”，应说“小红打不过弟弟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
