INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在打斗或比赛中无法战胜对方。", "primary_collocate": null, "pronunciation": "dǎ bu guò", "ipa": "ta˨˩ pu kuo˥˩", "syllable_count": 3, "sentences": [{"text": "我们队打不过他们队。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，我们恐怕打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人打不过三个人。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方是冠军，我们打不过。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乒乓球我总是打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗打不过大狗，跑开了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我练了很久，还是打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了伤，打不过对手了。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个拳手太厉害，大家都打不过他。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打不过就跑，别硬打。", "target_word": "打不过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "打得过", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "在打架或比赛中不能战胜对方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8afbf7a5-a183-4abb-8786-853e6dce4ba7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：在比赛中无法战胜对方，符合句意。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”不是比赛中的较量方式，句意不通。"}, {"text": "亲吻", "is_correct": false, "explanation": "语义：“亲吻”与比赛的胜负无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是离合词，不能带宾语“他们队”，句子不成立。"}], "explanations": {"打不过": "打不过：在比赛中无法战胜对方，符合句意。", "咬": "语义：“咬”不是比赛中的较量方式，句意不通。", "亲吻": "语义：“亲吻”与比赛的胜负无关，句意不通。", "睡觉": "配价：“睡觉”是离合词，不能带宾语“他们队”，句子不成立。"}, "sentence_index": 0, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛，我们终于打不过对手，拿到了冠军。", "explanation": "这里应该用〈战胜〉。打不过表示败给对方，与“拿到了冠军”的结果矛盾。"}, {"text": "这块石头打不过那棵大树。", "explanation": "这里应该用〈比不过〉。打不过指较量中败给对方，石头和树没有较量，只能说比不过。"}, {"text": "这门课我打不过，只好重修。", "explanation": "这里应该用〈考不过〉。打不过用于较量，考试不及格要用考不过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打不过", "is_correct": true, "explanation": "打不过：在较量中不能胜过对方，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接人作宾语表示较量，“吃他”不成立。"}, {"text": "钻研", "is_correct": false, "explanation": "配价：“钻研”的宾语是学问或技术，不能说“钻研他”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不与人组成较量关系，“唱他”不成立。"}], "explanations": {"打不过": "打不过：在较量中不能胜过对方，符合句意。", "吃": "搭配：“吃”不能接人作宾语表示较量，“吃他”不成立。", "钻研": "配价：“钻研”的宾语是学问或技术，不能说“钻研他”。", "唱": "搭配：“唱”不与人组成较量关系，“唱他”不成立。"}, "sentence_index": 6, "correct_answer": "打不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月的销售额打不过上个月。", "explanation": "这里应该用〈超过〉。打不过用于较量，业绩、数量的比较要用超过。"}, {"text": "这么多作业，我打不过。", "explanation": "这里应该用〈做不完〉。打不过用于较量，作业做不完要说做不完。"}, {"text": "我们打不过那班火车。", "explanation": "这里应该用〈赶不上〉。打不过用于较量，没赶上车要用赶不上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们队这次打不过了他们队。", "corrected_sentence": "我们队这次打不过他们队。", "error_description": "可能补语“打不过”后面不能直接加“了”，应写作“打不过他们队”；“了”放在可能补语后会使句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我弟弟能打不过邻居家的孩子。", "corrected_sentence": "我弟弟打不过邻居家的孩子。", "error_description": "“能”与可能补语“打不过”语义矛盾（两者都表示能力），不能同时使用，应去掉“能”，写作“我弟弟打不过邻居家的孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2f6889c-6c1a-49e5-b94d-e5fde98155c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
