INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91397, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "带领是走在前面，让别人跟着你走。", "primary_collocate": null, "pronunciation": "dài lǐng", "ipa": "tai˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "导游带领我们走进古城。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗带领我们找到了回家的路。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带领孩子过马路。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走在前面，带领大家上山。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员带领客人走到座位前。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人带领着孩子们穿过小路。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察带领我们走出了大楼。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向导带领探险队走进森林。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带领学生排队进教室。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥带领弟弟走过那座桥。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带领了", "label": "完成体"}, {"form": "带领着", "label": "持续体"}, {"form": "带领过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "自己走在前面，别人跟在后面走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91397, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带领", "is_correct": true, "explanation": "正确：「带领」表示走在前面领着我们进入古城，符合语境。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」是用牙齿咬，与带人走进古城无关。"}, {"text": "嫁", "is_correct": false, "explanation": "语义：「嫁」指出嫁，与带领他人前行无关。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：「咳嗽」是不及物动词，不能带「我们」作宾语。"}], "explanations": {"带领": "正确：「带领」表示走在前面领着我们进入古城，符合语境。", "咬": "语义：「咬」是用牙齿咬，与带人走进古城无关。", "嫁": "语义：「嫁」指出嫁，与带领他人前行无关。", "咳嗽": "配价：「咳嗽」是不及物动词，不能带「我们」作宾语。"}, "sentence_index": 0, "correct_answer": "带领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他带领一个大箱子上了楼。", "explanation": "这里应该用〈搬〉。带领的对象是人，把箱子运上楼要用〈搬〉。"}, {"text": "妈妈带领一盆花去了阳台。", "explanation": "这里应该用〈搬〉。带领的对象是人，搬运花盆要用〈搬〉。"}, {"text": "这位老师带领一盘午饭送到我们桌上，大家都很开心。", "explanation": "这里应该用〈端〉。带领的对象是人，不能带领一盘午饭，端着午饭要用〈端〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带领", "is_correct": true, "explanation": "正确：「带领」表示领着我们走出大楼，符合语境。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」是烹饪，与带人走出大楼无关。"}, {"text": "讲", "is_correct": false, "explanation": "配价：「讲」一般接话语或事情，不能直接带「我们」作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」是发出歌声，与带领人走出大楼无关。"}], "explanations": {"带领": "正确：「带领」表示领着我们走出大楼，符合语境。", "煮": "语义：「煮」是烹饪，与带人走出大楼无关。", "讲": "配价：「讲」一般接话语或事情，不能直接带「我们」作宾语。", "唱": "语义：「唱」是发出歌声，与带领人走出大楼无关。"}, "sentence_index": 6, "correct_answer": "带领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带领了一把伞，把它放回了柜子里。", "explanation": "这里应该用〈收〉。带领的对象是人，把雨伞收起来要用〈收〉。"}, {"text": "他带领着妹妹的手过马路。", "explanation": "这里应该用〈拉〉。带领的对象是人，不能带领身体部位，牵着手要用〈拉〉。"}, {"text": "他带领着马车在路上前进。", "explanation": "这里应该用〈驾〉。带领的对象是人，驾驶马车要用〈驾〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "领队带领走进山谷。", "corrected_sentence": "领队带领我们走进山谷。", "error_description": "「带领」后面应带上被领的人，这里漏掉了宾语「我们」。正确是「领队带领我们走进山谷」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长带领走出教室。", "corrected_sentence": "班长带领几名同学走出教室。", "error_description": "宾语缺失：「带领」后面应带上被领的人，这里漏掉了「几名同学」。错误是「班长带领走出教室」，正确是「班长带领几名同学走出教室」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
