INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "领着；引导（众人）前进。", "primary_collocate": null, "pronunciation": "dài lǐng", "ipa": "tai˥˩ liŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "老师带领同学们参观博物馆。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理带领我们完成了这个任务。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长带领大家向山顶走去。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带领公司走向了成功。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长带领全校学生唱国歌。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师带领我们班拿了第一名。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她带领着大家往前走。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村长带领村民修了一条新路。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练带领球队参加了比赛。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板带领员工一起加班完成工作。", "target_word": "带领", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "带领了", "label": "完成体"}, {"form": "带领着", "label": "持续体"}, {"form": "带领过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "带头引导一群人或一个集体一起向前、一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ee8993d-4865-4819-b75e-8462bbfe4aca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "带领", "is_correct": true, "explanation": "正确：「带领」表示领着同学们前往，符合「参观博物馆」的语境。"}, {"text": "批评", "is_correct": false, "explanation": "语义：「批评」是指出缺点、责备，不能表示领着同学们去参观。"}, {"text": "偷", "is_correct": false, "explanation": "语义：「偷」是暗中拿走，与引导参观无关。"}, {"text": "搬", "is_correct": false, "explanation": "配价：「搬」要接具体的物体作宾语，不能接「参观博物馆」这样的动作。"}], "explanations": {"带领": "正确：「带领」表示领着同学们前往，符合「参观博物馆」的语境。", "批评": "语义：「批评」是指出缺点、责备，不能表示领着同学们去参观。", "偷": "语义：「偷」是暗中拿走，与引导参观无关。", "搬": "配价：「搬」要接具体的物体作宾语，不能接「参观博物馆」这样的动作。"}, "sentence_index": 0, "correct_answer": "带领"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的电脑带领了我的工作，很快就完成了。", "explanation": "这里应该用〈帮助〉。带领的对象是人或团体，电脑不能带领工作，应该说〈帮助〉。"}, {"text": "他带领着孩子的手过马路。", "explanation": "这里应该用〈拉〉。带领的对象是人，不能带领身体部位，牵着孩子的手要用〈拉〉。"}, {"text": "路标带领着我们的方向。", "explanation": "这里应该用〈指引〉。带领是领着人前进，指出方向要用〈指引〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带领", "is_correct": true, "explanation": "正确：「带领」表示领着大家向前走，符合「往前走」的语境。"}, {"text": "扔", "is_correct": false, "explanation": "语义：「扔」是抛掷，不能用来形容领着大家往前走。"}, {"text": "忘", "is_correct": false, "explanation": "配价：「忘」后接的应是事情或信息，不能直接带「大家」作宾语。"}, {"text": "闭", "is_correct": false, "explanation": "配价：「闭」一般接眼睛、嘴等器官，不能带人作宾语。"}], "explanations": {"带领": "正确：「带领」表示领着大家向前走，符合「往前走」的语境。", "扔": "语义：「扔」是抛掷，不能用来形容领着大家往前走。", "忘": "配价：「忘」后接的应是事情或信息，不能直接带「大家」作宾语。", "闭": "配价：「闭」一般接眼睛、嘴等器官，不能带人作宾语。"}, "sentence_index": 6, "correct_answer": "带领"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他带领汽车去医院。", "explanation": "这里应该用〈驾驶〉。带领的对象是人或团体，不能带领车辆，开车要用〈驾驶〉。"}, {"text": "交警带领交通，很辛苦。", "explanation": "这里应该用〈指挥〉。带领是领着人前进，指挥交通要用〈指挥〉。"}, {"text": "飞行员带领飞机起飞。", "explanation": "这里应该用〈操纵〉。带领的对象是人，操纵飞机起飞要用〈操纵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长把带领几名同学打扫教室。", "corrected_sentence": "班长带领几名同学打扫教室。", "error_description": "「把」字误加在动词「带领」前：「把」后应接名词作处置对象，这里直接接动词，属结构错误。错误是「班长把带领几名同学打扫教室」，正确是「班长带领几名同学打扫教室」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队长带领走向终点。", "corrected_sentence": "队长带领队员们走向终点。", "error_description": "「带领」后面漏掉了被领的人，应补上宾语「队员们」。正确是「队长带领队员们走向终点」，错误是「队长带领走向终点」缺少宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41029984-13d8-4521-9fd7-656bf2eabd77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
