INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91399, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示它既是这个，又是另一个。", "primary_collocate": null, "pronunciation": "jì shì", "ipa": "tɕi˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这只小狗既是宠物，又是家人。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他既是校长，又是老师。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河既是交通要道，又是渔民的家。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日既是春天的开始，又是家人团聚的日子。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她既是我的姐姐，又是我最好的朋友。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店既是饭馆，又是书店。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷既是农民，又是诗人。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机既是电话，又是照相机。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人既是画家，又是医生。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地既是花园，又是菜地。", "target_word": "既是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连词；既是这个又是那个，一个事物兼有两种身份", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '90648837-04a1-444c-865a-4d09067f40f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "既是", "is_correct": true, "explanation": "正确：既是读 jì shì，表示一个事物兼有两种身份。"}, {"text": "纪实", "is_correct": false, "explanation": "纪实 jì shí：shí 与 shì 声调不同，意思是纪实。"}, {"text": "技师", "is_correct": false, "explanation": "技师 jì shī：shī（第一声）与 shì（第四声）声调不同，意思是技师。"}, {"text": "集市", "is_correct": false, "explanation": "集市 jí shì：jí（第二声）与 jì（第四声）声调不同，意思是集市。"}], "explanations": {"既是": "正确：既是读 jì shì，表示一个事物兼有两种身份。", "纪实": "纪实 jì shí：shí 与 shì 声调不同，意思是纪实。", "技师": "技师 jì shī：shī（第一声）与 shì（第四声）声调不同，意思是技师。", "集市": "集市 jí shì：jí（第二声）与 jì（第四声）声调不同，意思是集市。"}, "sentence_index": null, "correct_answer": "既是"}, "level_3": {"options": [{"text": "既是", "is_correct": true, "explanation": "正确：“既是”表示一个事物兼有两种身份，与后面的“又是”呼应。"}, {"text": "因为", "is_correct": false, "explanation": "语义：因为引出原因，此句并不是在说明原因。"}, {"text": "如果", "is_correct": false, "explanation": "语义：如果表示假设，句子没有对应的结果分句。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：而是需与前面的“不是”呼应，这里前面没有否定句。"}], "explanations": {"既是": "正确：“既是”表示一个事物兼有两种身份，与后面的“又是”呼应。", "因为": "语义：因为引出原因，此句并不是在说明原因。", "如果": "语义：如果表示假设，句子没有对应的结果分句。", "而是": "搭配：而是需与前面的“不是”呼应，这里前面没有否定句。"}, "sentence_index": 0, "correct_answer": "既是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "既是大家都累了，我们就早点休息吧。", "explanation": "这里的“既是”表示既然，说明已成立的原因，不表示并列两种身份。此句是〈既然〉的用法，不能用来说明一个事物兼有两种身份。"}, {"text": "既是没人知道，我们就先不说吧。", "explanation": "这里的“既是”表示既然，引出已成立的情况，不表示并列两种身份。此句是〈既然〉的用法，不是身份并列。"}, {"text": "既是孩子饿了，我们就先吃饭吧。", "explanation": "这里的“既是”表示既然，引出已知的原因，不表示并列两种身份。此句是〈既然〉的用法，不是身份并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "既是", "is_correct": true, "explanation": "正确：既是读 jì shì，表示一个事物兼有两种身份。"}, {"text": "技术", "is_correct": false, "explanation": "技术 jì shù：shù 与 shì 的韵母不同（ù／ì），意思是技术。"}, {"text": "即使", "is_correct": false, "explanation": "即使 jí shǐ：两个音节的声调都与 jì shì 不同，意思是即使。"}, {"text": "气势", "is_correct": false, "explanation": "气势 qì shì：qì 与 jì 的声母不同（q／j），意思是气势。"}], "explanations": {"既是": "正确：既是读 jì shì，表示一个事物兼有两种身份。", "技术": "技术 jì shù：shù 与 shì 的韵母不同（ù／ì），意思是技术。", "即使": "即使 jí shǐ：两个音节的声调都与 jì shì 不同，意思是即使。", "气势": "气势 qì shì：qì 与 jì 的声母不同（q／j），意思是气势。"}, "sentence_index": null, "correct_answer": "既是"}, "level_3": {"options": [{"text": "既是", "is_correct": true, "explanation": "正确：“既是”表示一个人兼有两种身份，与后面的“又是”呼应。"}, {"text": "或者", "is_correct": false, "explanation": "语义：或者表示选择，与“又是”表示并列的意思相矛盾。"}, {"text": "但是", "is_correct": false, "explanation": "语义：但是表示转折，前面没有与之对立的内容，句意不通。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：而且要连接前面已有的并列或递进成分，这里前面没有分句。"}], "explanations": {"既是": "正确：“既是”表示一个人兼有两种身份，与后面的“又是”呼应。", "或者": "语义：或者表示选择，与“又是”表示并列的意思相矛盾。", "但是": "语义：但是表示转折，前面没有与之对立的内容，句意不通。", "而且": "搭配：而且要连接前面已有的并列或递进成分，这里前面没有分句。"}, "sentence_index": 6, "correct_answer": "既是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "既是下雨了，比赛就推迟吧。", "explanation": "这里的“既是”表示既然，说明已成立的原因，不表示并列两种身份。此句是〈既然〉的用法，不能用来说明一个事物兼有两种身份。"}, {"text": "既是你不想去，我就不勉强你了。", "explanation": "这里的“既是”表示既然，引出已成立的情况，不表示并列两种身份。此句是〈既然〉的用法，不是身份并列。"}, {"text": "既是天黑了，孩子们就该回家了。", "explanation": "这里的“既是”表示既然，引出已知的原因，不表示并列两种身份。此句是〈既然〉的用法，不是身份并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = 