INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把伞既是雨伞，又既是遮阳伞。", "corrected_sentence": "这把伞既是雨伞，又是遮阳伞。", "error_description": "错误：“又”后多加了“既”。应为“又是遮阳伞”，表示同一事物兼有两种身份时，第二个分句只用“又是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地既是的草地，又是小路。", "corrected_sentence": "这块地既是草地，又是小路。", "error_description": "错误：“既是”后多加了“的”。应为“既是草地”，“既是”后直接接名词表示兼有的身份，加“的”会破坏并列结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed93c2dd-a358-4016-82a2-a56932e88544') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
