INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91401, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手机或银行把钱送给别人。", "primary_collocate": null, "pronunciation": "dǎ qián", "ipa": "ta˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我现在就用手机给你打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每个月给妈妈打钱。", "target_word": "打钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把卡号发给我，我马上打钱。", "target_word": "打钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，周末会给我打钱。", "target_word": "打钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在银行给朋友打钱。", "target_word": "打钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你告诉我卡号，我晚上打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机上点一下，就能给别人打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他忘了给房东打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在明天以前给学校打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不会用手机给我打钱。", "target_word": "打钱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打了钱", "label": "完成体"}, {"form": "打过钱", "label": "经历体"}], "register": "口语", "sense_fingerprint": "打钱·用手机或银行把钱送给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600a7bce-3638-4377-bbfd-4ecbfb4cb6a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91401, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打钱", "is_correct": true, "explanation": "正确：“我现在就用手机给你打钱”指通过手机把钱转给对方，符合语境。"}, {"text": "修理", "is_correct": false, "explanation": "语义：手机无法用来“修理”东西，“用手机给你修理”说不通。"}, {"text": "复印", "is_correct": false, "explanation": "语义：手机不能用来“复印”，“用手机给你复印”与语境矛盾。"}, {"text": "干掉", "is_correct": false, "explanation": "语域：“干掉”是口语俚语，且与“用手机给你”的平和语境不合。"}], "explanations": {"打钱": "正确：“我现在就用手机给你打钱”指通过手机把钱转给对方，符合语境。", "修理": "语义：手机无法用来“修理”东西，“用手机给你修理”说不通。", "复印": "语义：手机不能用来“复印”，“用手机给你复印”与语境矛盾。", "干掉": "语域：“干掉”是口语俚语，且与“用手机给你”的平和语境不合。"}, "sentence_index": 0, "correct_answer": "打钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每次都用现金打钱。", "explanation": "这里应该用〈付钱〉。“打钱”指通过手机或银行转账，用现金当面付钱不能说“打钱”。"}, {"text": "他把书包打钱给了同学。", "explanation": "这里应该用〈寄〉。“打钱”只用于转账金钱，不能用于书包这类实物。"}, {"text": "这张旧纸币可以打钱吗？", "explanation": "这里应该用〈换〉。“打钱”是通过银行或手机转账，不能用于把纸币兑换成钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打钱", "is_correct": true, "explanation": "正确：“手机上点一下，就能给别人打钱”指用手机转账，符合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“手机上点一下”只能完成转账之类的操作，不能与“打扫”搭配，句子说不通。"}, {"text": "缝补", "is_correct": false, "explanation": "搭配：手机点一下无法完成“缝补”，两者不搭配。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：在手机上点一下不能“给别人洗澡”，句子说不通。"}], "explanations": {"打钱": "正确：“手机上点一下，就能给别人打钱”指用手机转账，符合语境。", "打扫": "搭配：“手机上点一下”只能完成转账之类的操作，不能与“打扫”搭配，句子说不通。", "缝补": "搭配：手机点一下无法完成“缝补”，两者不搭配。", "洗澡": "语义：在手机上点一下不能“给别人洗澡”，句子说不通。"}, "sentence_index": 6, "correct_answer": "打钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在小卖部用硬币打钱买了一瓶水。", "explanation": "这里应该用〈付钱〉。“打钱”指通过手机或银行转账给别人，在商店用硬币当面付款不能说“打钱”。"}, {"text": "这些旧书可以打钱吗？", "explanation": "这里应该用〈卖〉。“打钱”是转账，不能用于出售实物换钱。"}, {"text": "他靠写文章打了很多钱。", "explanation": "这里应该用〈赚〉。“打钱”指把钱转给别人，不能表示靠写作获得收入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午把朋友打钱了。", "corrected_sentence": "我下午给朋友打钱了。", "error_description": "介词用错：引进收款人应用“给”，不能用“把”。“把”后面要接被处置的对象，说“把朋友打钱”不通，应说“给朋友打钱了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天在手机上打钱房东了。", "corrected_sentence": "他昨天在手机上打钱给房东了。", "error_description": "漏掉了引进收款人的介词“给”。“打钱”后要用“给+人”引出收款人，说“打钱房东”不对，应说“打钱给房东”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968a4035-d9c8-40b6-a255-4df7de601f8c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "反义：“平静”指情绪不激动，与“愤怒”相对。"}, {"text": "漂亮", "is_correct": false, "explanation": "无关：“漂亮”形容外貌，与“愤怒”不构成反义。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：“坚硬”形容质地，与情绪无关。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”指明白，不是与“愤怒”相对的词。"}], "correct_answer": "平静", "explanations": {"平静": "反义：“平静”指情绪不激动，与“愤怒”相对。", "漂亮": "无关：“漂亮”形容外貌，与“愤怒”不构成反义。", "坚硬": "无关：“坚硬”形容质地，与情绪无关。", "清楚": "无关：“清楚”指明白，不是与“愤怒”相对的词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "平静", "is_correct": true, "explanation": "反义：“平静”指情绪不激动，与“愤怒”相对。"}, {"text": "轻巧", "is_correct": false, "explanation": "无关：“轻巧”形容重量或动作，与“愤怒”不构成反义。"}, {"text": "柔软", "is_correct": false, "explanation": "无关：“柔软”形容质地，与情绪无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：“明亮”形容光线或眼神，不是与“愤怒”相对的词。"}], "correct_answer": "平静", "explanations": {"平静": "反义：“平静”指情绪不激动，与“愤怒”相对。", "轻巧": "无关：“轻巧”形容重量或动作，与“愤怒”不构成反义。", "柔软": "无关：“柔软”形容质地，与情绪无关。", "明亮": "无关：“明亮”形容光线或眼神，不是与“愤怒”相对的词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "愤怒是非常非常生气的样子。", "primary_collocate": null, "pronunciation": "fèn nù", "ipa": "fən˥˩ nu˥˩", "syllable_count": 2, "sentences": [{"text": "他愤怒地看着那个人。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，大家都很愤怒。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她愤怒的样子让孩子们很害怕。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他愤怒地摔门走了。", "target_word": "愤怒", "complexity_tier": "T3", "furigana": "tā fèn nù de shuāi mén zǒu le", "sentence_source": "generated"}, {"text": "老板愤怒地把杯子放在桌上。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到有人欺负小孩，妈妈十分愤怒。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愤怒极了，大声喊了起来。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机们愤怒地按着喇叭。", "target_word": "愤怒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一封愤怒的信。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很愤怒，一句话也不想说。", "target_word": "愤怒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "愤怒的", "label": "定语形式"}, {"form": "愤怒地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "非常生气的样子：愤怒地看着、愤怒的样子、十分愤怒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f7f4cc0-d72a-4bc5-95a4-88c0d7487b96') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愤怒", "is_correct": true, "explanation": "正确：“愤怒地看着”指带着怒气看，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来描述看的样子。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能用来描述看的样子。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”形容质地，不能用来形容看人的样子。"}], "explanations": {"愤怒": "正确：“愤怒地看着”指带着怒气看，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能用来描述看的样子。", "矮": "体貌：“矮”形容身高，不能用来描述看的样子。", "粗糙": "语义：“粗糙”形容质地，不能用来形容看人的样子。"}, "sentence_index": 0, "correct_answer": "愤怒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子很愤怒，所以我不想进去。", "explanation": "这里应该用〈阴暗〉。“愤怒”描述的是人的怒气，不能用来形容房间；形容光线不足要用“阴暗”。"}, {"text": "他愤怒地刻苦学习，每天十个小时。", "explanation": "这里应该用〈努力〉。愤怒指强烈的怒气，不能用来形容学习的态度，描述刻苦学习要用“努力”。"}, {"text": "收到生日礼物，他愤怒地说：“谢谢你，我太喜欢了！”", "explanation": "这里应该用〈高兴〉。收到礼物并表示喜欢是愉快的情绪，与“愤怒”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愤怒", "is_correct": true, "explanation": "正确：“他愤怒极了”指怒气很大，与“大声喊了起来”相符。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“安静”与后面的“大声喊了起来”矛盾。"}, {"text": "方便", "is_correct": false, "explanation": "语义：“方便”形容事情容易做，不能形容人的情绪，与“大声喊”不搭。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”与“大声喊了起来”的情绪矛盾。"}], "explanations": {"愤怒": "正确：“他愤怒极了”指怒气很大，与“大声喊了起来”相符。", "安静": "语义：“安静”与后面的“大声喊了起来”矛盾。", "方便": "语义：“方便”形容事情容易做，不能形容人的情绪，与“大声喊”不搭。", "冷静": "语义：“冷静”与“大声喊了起来”的情绪矛盾。"}, "sentence_index": 6, "correct_answer": "愤怒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，我愤怒得合不上嘴。", "explanation": "这里应该用〈惊讶〉。合不上嘴表示吃惊，“愤怒”不能用来表示这种反应。"}, {"text": "这块蛋糕很愤怒，大家都抢着吃。", "explanation": "这里应该用〈好吃〉。“愤怒”描述的是人的怒气，不能用来形容蛋糕；形容味道好要用“好吃”。"}, {"text": "这条路很愤怒，车开得很快。", "explanation": "这里应该用〈平坦〉。“愤怒”描述的是人的怒气，不能用来形容道路；形容路面平整要用“平坦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他愤怒的把门关上了。", "corrected_sentence": "他愤怒地把门关上了。", "error_description": "错误在“的”。“愤怒”在这里修饰动词“关”，作状语，应该用“地”，不能用“的”，即“愤怒地把门关上了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到这个消息，他很愤怒极了。", "corrected_sentence": "听到这个消息，他愤怒极了。", "error_description": "错误在“很”。“愤怒极了”已用“极了”表示程度，前面不能再加“很”，应删去“很”，即“他愤怒极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d2e5545-7e2f-4659-9d1d-005536b488bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时令是一年里这个时候的季节。", "primary_collocate": null, "pronunciation": "shí lìng", "ipa": "ʂɻ̩˧˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个时令，北方已经很冷了。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天是种花的好时令。", "target_word": "时令", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "时令一到，树叶就变黄了。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了几斤时令水果。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时令的西瓜最甜。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不同的时令，吃不同的东西。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天到了，该吃冬天时令的菜了。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖的时令蔬菜比较新鲜。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时令正好是收稻子的时候。", "target_word": "时令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人常说，要顺应时令吃东西。", "target_word": "时令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時令", "label": "繁体"}, {"form": "时令蔬菜", "label": "复合"}], "register": "中性", "sense_fingerprint": "时令：一年里此时此刻所处的季节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03f6c3ff-8465-4cfa-85d4-ff2eb6f04201') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时令", "is_correct": true, "explanation": "目标词，读作 shí lìng，指一年里此时所处的季节。"}, {"text": "食量", "is_correct": false, "explanation": "lìng 与 liàng 相比多了一个 a 音，声调相同（第四声），意思是饭量，与“时令”不同。"}, {"text": "实力", "is_correct": false, "explanation": "lì（第四声）没有 ng 韵尾，lìng 有，两者只差韵尾，意思是实际的能力。"}, {"text": "十两", "is_correct": false, "explanation": "liǎng（第三声）比 lìng 多一个 a 音，声调也不同（第四声），意思是十两，是重量单位。"}, {"text": "石林", "is_correct": false, "explanation": "lín 与 lìng 的韵尾不同（n 与 ng），声调也不同，意思是石头形成的山林。"}], "explanations": {"时令": "目标词，读作 shí lìng，指一年里此时所处的季节。", "食量": "lìng 与 liàng 相比多了一个 a 音，声调相同（第四声），意思是饭量，与“时令”不同。", "实力": "lì（第四声）没有 ng 韵尾，lìng 有，两者只差韵尾，意思是实际的能力。", "十两": "liǎng（第三声）比 lìng 多一个 a 音，声调也不同（第四声），意思是十两，是重量单位。", "石林": "lín 与 lìng 的韵尾不同（n 与 ng），声调也不同，意思是石头形成的山林。"}, "sentence_index": null, "correct_answer": "时令"}, "level_3": {"options": [{"text": "时令", "is_correct": true, "explanation": "时令指一年里此时所处的季节，“这个时令”指当前的季节，符合句意。"}, {"text": "方向", "is_correct": false, "explanation": "语义：方向指位置的指向，不指时段，不能用“这个方向”指当前季节。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情指情绪，与季节无关，不能说“这个心情，北方已经很冷了”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身体高度，只用于人，不能用来指季节。"}], "explanations": {"时令": "时令指一年里此时所处的季节，“这个时令”指当前的季节，符合句意。", "方向": "语义：方向指位置的指向，不指时段，不能用“这个方向”指当前季节。", "心情": "语义：心情指情绪，与季节无关，不能说“这个心情，北方已经很冷了”。", "身高": "体貌：身高指人的身体高度，只用于人，不能用来指季节。"}, "sentence_index": 0, "correct_answer": "时令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们生活在数字时令。", "explanation": "这里应该用〈时代〉。时令指季节，不指一个历史阶段。"}, {"text": "今天的时令很晴朗，适合爬山。", "explanation": "这里应该用〈天气〉。时令指季节，不指某一天的晴雨冷暖。"}, {"text": "中午十二点是吃饭的时令。", "explanation": "这里应该用〈时间〉。时令指一年中的季节，不指一天中的某个钟点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时令", "is_correct": true, "explanation": "目标词，读作 shí lìng，指一年里此时所处的季节。"}, {"text": "食粮", "is_correct": false, "explanation": "liáng（第二声）比 lìng 多一个 a 音，声调也不同，意思是粮食。"}, {"text": "实例", "is_correct": false, "explanation": "lì（第四声）没有 ng 韵尾，lìng 有，声调相同，意思是例子。"}, {"text": "十里", "is_correct": false, "explanation": "lǐ（第三声）没有 ng 韵尾，且声调不同，意思是十里路程。"}], "explanations": {"时令": "目标词，读作 shí lìng，指一年里此时所处的季节。", "食粮": "liáng（第二声）比 lìng 多一个 a 音，声调也不同，意思是粮食。", "实例": "lì（第四声）没有 ng 韵尾，lìng 有，声调相同，意思是例子。", "十里": "lǐ（第三声）没有 ng 韵尾，且声调不同，意思是十里路程。"}, "sentence_index": null, "correct_answer": "时令"}, "level_3": {"options": [{"text": "时令", "is_correct": true, "explanation": "时令指应季的季节，“冬天时令的菜”指冬天应季的菜，符合句意。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料是材料，不能指可以吃的菜。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是材料，不能用来指可以吃的菜。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色的菜”不是固定说法，指应季的菜要用“时令”。"}], "explanations": {"时令": "时令指应季的季节，“冬天时令的菜”指冬天应季的菜，符合句意。", "塑料": "语义：塑料是材料，不能指可以吃的菜。", "木头": "语义：木头是材料，不能用来指可以吃的菜。", "颜色": "搭配：“颜色的菜”不是固定说法，指应季的菜要用“时令”。"}, "sentence_index": 6, "correct_answer": "时令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "现在的时令是晚上八点。", "explanation": "这里应该用〈时间〉。时令指季节，不指具体的钟点。"}, {"text": "这几天的时令很低。", "explanation": "这里应该用〈气温〉。时令指季节，不能用“很低”来描述冷热程度。"}, {"text": "他已经到了退休的时令。", "explanation": "这里应该用〈年龄〉。时令指一年中的季节，不指人生的阶段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只时令正好适合收割。", "corrected_sentence": "这个时令正好适合收割。", "error_description": "错误：“这只时令”。正确：“这个时令”。时令是抽象名词，指示词加量词应用“个”，“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天时令了，花都开了。", "corrected_sentence": "春天到了，花都开了。", "error_description": "错误：“时令了”。正确：“到了”。时令是名词，不能当动词带“了”，表示季节来临应说“到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5a2c106-25b1-424e-b688-47b319112188') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
