INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "遇到不公平的事不低头，用力去对抗。", "primary_collocate": null, "pronunciation": "kàng zhēng", "ipa": "kʰaŋ˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他们不愿低头，决定抗争到底。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人为了公平的工资而抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直在同不公平的事抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对不公，他从不低头，一直抗争着。", "target_word": "抗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人为自己的家抗争过很多年。", "target_word": "抗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们不想再忍了，他们要抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们对这样的规定抗争了很久。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "遇到不公平的事，我们不能不抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不放弃，一直在为公平抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "受了不公平的对待，她决定抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗争着", "label": "体标"}, {"form": "抗争过", "label": "体标"}], "register": "中性", "sense_fingerprint": "遇到不公平的事不低头，用力对抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抗争", "is_correct": true, "explanation": "抗争（kàng zhēng）指遇到不公平的事用力对抗，是正确答案。"}, {"text": "抗战", "is_correct": false, "explanation": "抗战（kàng zhàn）与抗争（kàng zhēng）第二个音节的韵母和声调都不同，意思是抗击侵略的战争。"}, {"text": "抗震", "is_correct": false, "explanation": "抗震（kàng zhèn）与抗争第二个音节的韵母和声调不同，意思是抵抗地震。"}, {"text": "抗风", "is_correct": false, "explanation": "抗风（kàng fēng）与抗争第二个音节声母不同（f 与 zh），意思是抵抗风力。"}], "explanations": {"抗争": "抗争（kàng zhēng）指遇到不公平的事用力对抗，是正确答案。", "抗战": "抗战（kàng zhàn）与抗争（kàng zhēng）第二个音节的韵母和声调都不同，意思是抗击侵略的战争。", "抗震": "抗震（kàng zhèn）与抗争第二个音节的韵母和声调不同，意思是抵抗地震。", "抗风": "抗风（kàng fēng）与抗争第二个音节声母不同（f 与 zh），意思是抵抗风力。"}, "sentence_index": null, "correct_answer": "抗争"}, "level_3": {"options": [{"text": "抗争", "is_correct": true, "explanation": "抗争：指反抗并争取，与“不愿低头”相符，正确。"}, {"text": "屈服", "is_correct": false, "explanation": "语义：“屈服”与“不愿低头”的意思相反，与整句的反抗语气矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“决定睡觉到底”不能成立，“睡觉”不能与“决定……到底”搭配。"}, {"text": "求饶", "is_correct": false, "explanation": "语义：“求饶”就是低头认输，与“不愿低头”直接矛盾。"}], "explanations": {"抗争": "抗争：指反抗并争取，与“不愿低头”相符，正确。", "屈服": "语义：“屈服”与“不愿低头”的意思相反，与整句的反抗语气矛盾。", "睡觉": "搭配：“决定睡觉到底”不能成立，“睡觉”不能与“决定……到底”搭配。", "求饶": "语义：“求饶”就是低头认输，与“不愿低头”直接矛盾。"}, "sentence_index": 0, "correct_answer": "抗争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司每天都在抗争，争夺同一个市场。", "explanation": "这里应该用〈竞争〉。“抗争”指反抗不公平的事，不用于商业上的争夺。"}, {"text": "两国代表正在抗争，希望达成协议。", "explanation": "这里应该用〈谈判〉。“抗争”指用力对抗，不指双方协商。"}, {"text": "她一直在抗争自己的梦想。", "explanation": "这里应该用〈追求〉。“抗争”的对象应是不公、命运等阻碍，不能直接以梦想作宾语；追求梦想应说“追求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗争", "is_correct": true, "explanation": "抗争：指对不公平的规定奋力对抗，与“对这样的规定”相符，正确。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱，与学生们对规定的抵触情绪不符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“对……散步”不能成立，“散步”不能以规定为对象。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与对规定的不满无关，句意不通。"}], "explanations": {"抗争": "抗争：指对不公平的规定奋力对抗，与“对这样的规定”相符，正确。", "欣赏": "语义：“欣赏”是喜爱，与学生们对规定的抵触情绪不符。", "散步": "搭配：“对……散步”不能成立，“散步”不能以规定为对象。", "跳舞": "语义：“跳舞”与对规定的不满无关，句意不通。"}, "sentence_index": 6, "correct_answer": "抗争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他认真抗争这份工作，每天都很开心。", "explanation": "这里应该用〈享受〉。“抗争”指对抗不公、用力反抗，与“每天都很开心”的愉快感受不符，应说“享受”。"}, {"text": "他每天早上去公园抗争半个小时。", "explanation": "这里应该用〈锻炼〉。“抗争”指反抗不公平的事，不能表示运动、锻炼身体。"}, {"text": "这种材料能抗争高温，很结实。", "explanation": "这里应该用〈耐〉。“抗争”指人或群体的反抗，不用于描述材料的耐热性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们为了公平的工资抗争着很久。", "corrected_sentence": "工人们为了公平的工资抗争了很久。", "error_description": "错误是“抗争着很久”，正确是“抗争了很久”。动词后接时段“很久”表示持续了多长时间，要用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一起给不公平的制度抗争。", "corrected_sentence": "他们一起向不公平的制度抗争。", "error_description": "错误：“给不公平的制度抗争”，正确：“向不公平的制度抗争”。引出反抗对象要用介词“向”（或“对”），“给”表示给予，不能用来引出对象。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对抗并奋力争取；反抗。", "primary_collocate": null, "pronunciation": "kàng zhēng", "ipa": "kʰaŋ˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "小明想自由，开始向父母抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们一起抗争，想要得到自由。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们不怕困难，奋力抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人一直同病魔抗争。", "target_word": "抗争", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他同命运抗争了一辈子。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她为了孩子的未来而抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民们为了土地向政府抗争。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不能只等着，要自己去抗争。", "target_word": "抗争", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很想抗争，可是没有办法。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小国一直在抗争，想要独立。", "target_word": "抗争", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗争着", "label": "体标"}, {"form": "抗争过", "label": "体标"}], "register": "中性", "sense_fingerprint": "对抗并奋力争取，反抗困难、命运或压力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fdab5a9-2bdd-478f-be4b-21194dec5a85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗争", "is_correct": true, "explanation": "抗争：指对抗并奋力争取，与“想自由”和“向父母”的语境相符，正确。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“向父母”之后不能接“游泳”，“向父母游泳”不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "搭配：“向父母睡觉”不能成立；语义上也与“想自由”的意愿无关。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“想自由”的诉求无关，无法表达反抗的意思。"}], "explanations": {"抗争": "抗争：指对抗并奋力争取，与“想自由”和“向父母”的语境相符，正确。", "游泳": "搭配：“向父母”之后不能接“游泳”，“向父母游泳”不通。", "睡觉": "搭配：“向父母睡觉”不能成立；语义上也与“想自由”的意愿无关。", "吃饭": "语义：“吃饭”与“想自由”的诉求无关，无法表达反抗的意思。"}, "sentence_index": 0, "correct_answer": "抗争"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们正在抗争精彩的表演。", "explanation": "这里应该用〈观看〉。“抗争”指对抗并奋力争取，或反抗，不用于欣赏表演。"}, {"text": "他抗争了这份邀请。", "explanation": "这里应该用〈拒绝〉。“抗争”是对抗并奋力争取，不用于婉拒邀请。"}, {"text": "他抗争了一下午的游戏。", "explanation": "这里应该用〈玩〉。“抗争”指对抗并奋力争取，不用于一般的游戏活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗争", "is_correct": true, "explanation": "抗争：指对抗并奋力争取，与“为了土地”和向政府提出的诉求相符，正确。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“向政府”之后不能接“散步”，“向政府散步”不成立。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与“为了土地”的诉求无关，句意不通。"}, {"text": "购物", "is_correct": false, "explanation": "搭配：“向政府购物”不能成立，“购物”不以政府为对象。"}], "explanations": {"抗争": "抗争：指对抗并奋力争取，与“为了土地”和向政府提出的诉求相符，正确。", "散步": "搭配：“向政府”之后不能接“散步”，“向政府散步”不成立。", "跳舞": "语义：“跳舞”与“为了土地”的诉求无关，句意不通。", "购物": "搭配：“向政府购物”不能成立，“购物”不以政府为对象。"}, "sentence_index": 6, "correct_answer": "抗争"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司一起抗争，共同开发新产品。", "explanation": "这里应该用〈合作〉。“抗争”指对抗并奋力争取，不用于共同开发。"}, {"text": "这块布料能抗争水，下雨也不怕。", "explanation": "这里应该用〈防〉。“抗争”指奋力对抗，不用于描述防水的性能。"}, {"text": "老师让学生们抗争这张照片。", "explanation": "这里应该用〈欣赏〉。“抗争”指对抗或奋力争取，不用于看照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他为了生存抗争着很多年。", "corrected_sentence": "他为了生存抗争了很多年。", "error_description": "错误是“抗争着很多年”，正确是“抗争了很多年”。动词后接时段表示持续了多长时间，要用“了”，不能用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一直在给自由抗争。", "corrected_sentence": "他们一直在为自由抗争。", "error_description": "错误：“给自由抗争”，正确：“为自由抗争”。引出目的要用“为”，“给”表示给予，不能用来引出抗争的目的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c164ba52-20ee-4a77-b241-66b804c7e1e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
