INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "房屋、土地等不动产的统称。", "primary_collocate": null, "pronunciation": "fáng dì chǎn", "ipa": "faŋ˧˥ ti˥˩ ʈʂʰan˨˩˦", "syllable_count": 3, "sentences": [{"text": "房地产是指房屋、土地等不动产。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房地产属于不动产，不能像车一样开走。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对房地产的管理越来越严格。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家里有几处房地产，都在市中心。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房地产包括住宅、商店、办公楼和土地。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的房地产贷款比去年多了一些。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学学的是房地产专业。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房地产市场最近比较安静，买的人不多。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "税务局要对房地产的买卖收税。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房地产和股票是两种常见的投资方式。", "target_word": "房地产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "房地产商", "label": "复合"}, {"form": "房地产业", "label": "复合"}, {"form": "房地產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；房屋、土地等不动产的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房地产", "is_correct": true, "explanation": "房地产是房屋、土地等不动产的统称，符合定义。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是公司股份的凭证，不是房屋和土地的统称。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车是交通工具，不属于房屋和土地这一类。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是金融机构，不是房屋、土地等不动产。"}], "explanations": {"房地产": "房地产是房屋、土地等不动产的统称，符合定义。", "股票": "语义：股票是公司股份的凭证，不是房屋和土地的统称。", "汽车": "语义：汽车是交通工具，不属于房屋和土地这一类。", "银行": "语义：银行是金融机构，不是房屋、土地等不动产。"}, "sentence_index": 0, "correct_answer": "房地产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把房地产搬到了新家。", "explanation": "这里应该用〈家具〉。房地产属于不动产，不能像家具一样搬走，不能说“把房地产搬到新家”。"}, {"text": "他在房地产吃了一顿饭，味道很好。", "explanation": "这里应该用〈饭馆〉。房地产是不动产的统称，不是餐饮场所，不能说“在房地产吃饭”。"}, {"text": "他每个月的房地产是五千元。", "explanation": "这里应该用〈收入〉。房地产是房屋、土地等不动产的统称，不是每月的收入，不能说“每个月的房地产”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房地产", "is_correct": true, "explanation": "房地产专业是大学里的专业名称，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是学科，不能作为专业名称。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“专业”一般与学科名称搭配，不能说“面包专业”。"}, {"text": "西瓜", "is_correct": false, "explanation": "语义：西瓜是水果，不是学科，不能说“西瓜专业”。"}], "explanations": {"房地产": "房地产专业是大学里的专业名称，符合句意。", "冰箱": "语义：冰箱是家用电器，不是学科，不能作为专业名称。", "面包": "搭配：“专业”一般与学科名称搭配，不能说“面包专业”。", "西瓜": "语义：西瓜是水果，不是学科，不能说“西瓜专业”。"}, "sentence_index": 6, "correct_answer": "房地产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在房地产买了一些菜，都很新鲜。", "explanation": "这里应该用〈超市〉。房地产不是卖东西的地方，不能说“在房地产买菜”。"}, {"text": "他在房地产上学，成绩很好。", "explanation": "这里应该用〈学校〉。房地产是统称，不是学习的场所。"}, {"text": "他明天去房地产看病，早点出发。", "explanation": "这里应该用〈医院〉。房地产不是医疗机构，不能说“去房地产看病”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府正在调整房地产们的税收政策。", "corrected_sentence": "政府正在调整房地产的税收政策。", "error_description": "后缀错误：“们”只用于指人的名词之后，“房地产”不能加“们”，应去掉“们”，改为“政府正在调整房地产的税收政策。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "近几年房地产们的税收变化很大。", "corrected_sentence": "近几年房地产的税收变化很大。", "error_description": "后缀错误：“们”只用于指人的名词之后，“房地产”不能加“们”，应去掉“们”，改为“近几年房地产的税收变化很大。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
