INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "棒球是用大棒子打小球的运动。", "primary_collocate": null, "pronunciation": "bàng qiú", "ipa": "paŋ˥˩ tɕʰiou˧˥", "syllable_count": 2, "sentences": [{"text": "我哥哥很喜欢打棒球。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我们在公园打棒球，他用球棒打得很远。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看棒球比赛，我最爱看球员跑垒。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校很多学生都打棒球。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在日本，很多孩子喜欢棒球。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他打了两个小时棒球，累坏了。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会不会打棒球？", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下午我想去看棒球，你去吗？", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棒球是美国很受欢迎的运动。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前打过棒球，所以打得很好。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棒球队", "label": "复合"}, {"form": "棒球赛", "label": "复合"}], "register": "中性", "sense_fingerprint": "用球棒打球的球类运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棒球", "is_correct": true, "explanation": "棒球是球类运动，“打棒球”是常见搭配，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“打”不说“打钢琴”，弹乐器要说“弹”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“打”不能搭配“作业”，应说“做作业”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“打”的对象不是蛋糕，句子的运动语境也不成立。"}], "explanations": {"棒球": "棒球是球类运动，“打棒球”是常见搭配，符合句意。", "钢琴": "搭配：“打”不说“打钢琴”，弹乐器要说“弹”。", "作业": "搭配：“打”不能搭配“作业”，应说“做作业”。", "蛋糕": "语义：“打”的对象不是蛋糕，句子的运动语境也不成立。"}, "sentence_index": 0, "correct_answer": "棒球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用棒球打球。", "explanation": "这里应该用〈球棒〉。球棒是击球的棍子，“棒球”是运动名称，不能用来指击球工具。"}, {"text": "他戴上棒球，准备去比赛。", "explanation": "这里应该用〈帽子〉。棒球指运动和球，不能戴在头上，戴的是棒球帽一类的帽子。"}, {"text": "他每天早上喝一杯棒球。", "explanation": "这里应该用〈牛奶〉。棒球是一种运动，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棒球", "is_correct": true, "explanation": "棒球是球类运动，“打棒球”搭配正确，符合句意。"}, {"text": "围棋", "is_correct": false, "explanation": "搭配：围棋要说“下”，不说“打围棋”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“打”不能搭配“汽车”，开车要说“开”。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：“毛巾”不是可以“打”的运动或游戏对象，句意不通。"}], "explanations": {"棒球": "棒球是球类运动，“打棒球”搭配正确，符合句意。", "围棋": "搭配：围棋要说“下”，不说“打围棋”。", "汽车": "搭配：“打”不能搭配“汽车”，开车要说“开”。", "毛巾": "语义：“毛巾”不是可以“打”的运动或游戏对象，句意不通。"}, "sentence_index": 6, "correct_answer": "棒球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个书架是用棒球做的。", "explanation": "这里应该用〈木头〉。棒球指运动和球，不是可以做家具的材料。"}, {"text": "他是我们班最厉害的棒球。", "explanation": "这里应该用〈运动员〉。棒球是运动项目，不指人，“他是棒球”不成立。"}, {"text": "他坐棒球去学校。", "explanation": "这里应该用〈公交车〉。坐的是交通工具，棒球是运动和球，不能坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很会棒球。", "corrected_sentence": "他很会打棒球。", "error_description": "错误：漏掉动词“打”。正确：“很会打棒球”，棒球作为运动时要和“打”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前也过打棒球。", "corrected_sentence": "我以前也打过棒球。", "error_description": "错误：“过”放在了动词前。正确：“打过棒球”，“过”紧跟动词，表示曾经有过的经历。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
