INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "球类运动，球员用球棒击球并跑垒得分；也指所用的球。", "primary_collocate": null, "pronunciation": "bàng qiú", "ipa": "paŋ˥˩ tɕʰiou˧˥", "syllable_count": 2, "sentences": [{"text": "他送了我一个棒球。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个棒球是爸爸买的。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "棒球比赛里，球员用球棒打球，再跑垒得分。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把棒球扔给了朋友。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个棒球落在草地上了。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的棒球很旧了，球上有很多黑点。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队打棒球时，他跑垒得了一分。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学棒球，所以买了一根球棒。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸带着棒球去公园了。", "target_word": "棒球", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场棒球比赛我们赢了。", "target_word": "棒球", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "棒球帽", "label": "复合"}], "register": "中性", "sense_fingerprint": "棒球运动，也指棒球运动用的球", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f1d42d-5220-4b0c-9fb7-df56a4a71c3e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "棒球", "is_correct": true, "explanation": "棒球是球，量词“个”搭配正确，可以送人，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“送”的对象要能转交，“天空”不能送给别人。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能作为可以赠送的物件，句意不通。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“送”不能搭配“病”，把病传给别人要说“传”。"}], "explanations": {"棒球": "棒球是球，量词“个”搭配正确，可以送人，符合句意。", "天空": "语义：“送”的对象要能转交，“天空”不能送给别人。", "河流": "语义：河流不能作为可以赠送的物件，句意不通。", "病": "搭配：“送”不能搭配“病”，把病传给别人要说“传”。"}, "sentence_index": 0, "correct_answer": "棒球"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天坐棒球上学。", "explanation": "这里应该用〈公交车〉。坐的是交通工具，棒球是球和运动，不能坐。"}, {"text": "他用棒球做了一把椅子。", "explanation": "这里应该用〈木头〉。棒球是球和运动，不是做椅子的材料。"}, {"text": "他买了一支棒球。", "explanation": "这里应该用〈个〉。棒球是球，量词用“个”；“支”用于棍状物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "棒球", "is_correct": true, "explanation": "棒球是球类运动，“打棒球”搭配正确，符合句意。"}, {"text": "围棋", "is_correct": false, "explanation": "搭配：围棋要说“下”，不说“打围棋”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“打”不能搭配“书”，书要说“看”或“读”。"}, {"text": "毛巾", "is_correct": false, "explanation": "语义：“毛巾”不能作为“打”的对象，句意不通。"}], "explanations": {"棒球": "棒球是球类运动，“打棒球”搭配正确，符合句意。", "围棋": "搭配：围棋要说“下”，不说“打围棋”。", "书": "搭配：“打”不能搭配“书”，书要说“看”或“读”。", "毛巾": "语义：“毛巾”不能作为“打”的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "棒球"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把棒球戴在头上，准备去比赛。", "explanation": "这里应该用〈帽子〉。棒球是球和运动，不能戴在头上。"}, {"text": "我们约在棒球见面。", "explanation": "这里应该用〈操场〉。约见面要说地点，棒球是运动和球，不是地方。"}, {"text": "他爱吃棒球当零食。", "explanation": "这里应该用〈饼干〉。棒球是球和运动，不能当食物吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我了一个棒球。", "corrected_sentence": "妈妈给了我一个棒球。", "error_description": "错误：“了”放在了“我”的后面。正确：“给了我”，动词后加“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥给我买了一根棒球。", "corrected_sentence": "哥哥给我买了一个棒球。", "error_description": "错误：量词“根”。“根”用于细长条的东西，棒球是球，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13a4585d-21af-4e46-b284-0acd3d0e1972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
