INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91413, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人很疼或很难受。", "primary_collocate": null, "pronunciation": "zhé mó", "ipa": "ʈʂɤ˧˥ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "牙疼折磨了我一晚上。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高温折磨得大家睡不着觉。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咳嗽折磨着他，他一晚上没睡好。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肚子饿得难受，饥饿折磨着孩子们。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个病折磨了他三年。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "腰疼老是折磨我，坐久了更疼。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天的冷风折磨着路上的行人。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "头疼折磨得她一整天都不想吃饭。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蚊子咬得很痒，真折磨人。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间坐车折磨着他的腰。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "折磨着", "label": "持续体"}, {"form": "折磨了", "label": "完成体"}, {"form": "折磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "疼痛、疾病、饥饿、高温等让人身体很难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91413, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折磨", "is_correct": true, "explanation": "“折磨”表示让人身体很难受，与“牙疼……了我一晚上”的语境相符。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示对别人的恩情心存谢意，“牙疼”不能感激“我”，语义不合。"}, {"text": "照料", "is_correct": false, "explanation": "配价：“照料”需要有意识的照料者作主语，“牙疼”不能照料“我”。"}, {"text": "逗弄", "is_correct": false, "explanation": "搭配：“逗弄”多用于人或动物，不能说“牙疼逗弄我”。"}], "explanations": {"折磨": "“折磨”表示让人身体很难受，与“牙疼……了我一晚上”的语境相符。", "感激": "语义：“感激”表示对别人的恩情心存谢意，“牙疼”不能感激“我”，语义不合。", "照料": "配价：“照料”需要有意识的照料者作主语，“牙疼”不能照料“我”。", "逗弄": "搭配：“逗弄”多用于人或动物，不能说“牙疼逗弄我”。"}, "sentence_index": 0, "correct_answer": "折磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被一杯热牛奶折磨得很舒服。", "explanation": "这里应该用〈安慰〉。“折磨”表示使人难受，热牛奶带来的是温暖和舒适，两者语义相反。"}, {"text": "他折磨了那台旧机器一整天，才把它修好。", "explanation": "这里应该用〈修理〉。“折磨”的对象必须是能感到痛苦的人或动物，不能用于机器。"}, {"text": "这首歌很好听，每天晚上都折磨着我入睡。", "explanation": "这里应该用〈陪伴〉。“折磨”表示使人难受，好听的歌让人舒服，语境不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91413, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折磨", "is_correct": true, "explanation": "“折磨”表示使人身体难受，与“冬天的冷风……着路上的行人”的语境相符。"}, {"text": "体贴", "is_correct": false, "explanation": "搭配：“体贴”是人的品质或行为，“冷风”不能体贴行人。"}, {"text": "照耀", "is_correct": false, "explanation": "搭配：“照耀”多用于光线，不能说“冷风照耀行人”。"}, {"text": "挂念", "is_correct": false, "explanation": "配价：“挂念”需要有感情的人作主语，“冷风”不能挂念行人。"}], "explanations": {"折磨": "“折磨”表示使人身体难受，与“冬天的冷风……着路上的行人”的语境相符。", "体贴": "搭配：“体贴”是人的品质或行为，“冷风”不能体贴行人。", "照耀": "搭配：“照耀”多用于光线，不能说“冷风照耀行人”。", "挂念": "配价：“挂念”需要有感情的人作主语，“冷风”不能挂念行人。"}, "sentence_index": 6, "correct_answer": "折磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他天天在家休息，把身体折磨得很健康。", "explanation": "这里应该用〈照顾〉。“折磨”使身体难受，不能用来描述让身体变健康的做法。"}, {"text": "他每天打扫房间，把房间折磨得很干净。", "explanation": "这里应该用〈收拾〉。“折磨”的对象必须是能感到痛苦的人或动物，不能用于房间。"}, {"text": "他听到这个好消息，心里被折磨得很开心。", "explanation": "这里应该用〈安慰〉。“折磨”表示使人受痛苦，好消息带来的是开心，两者语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91413, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "腰疼折磨着我着一整天。", "corrected_sentence": "腰疼折磨着我一整天。", "error_description": "“着”只能出现一次，应紧跟动词，写作“折磨着我一整天”；“我”后多出的“着”是错误的，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91413, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "咳嗽折磨他了一夜。", "corrected_sentence": "咳嗽折磨了他一夜。", "error_description": "“了”应紧跟动词，写作“折磨了他”；“折磨他了”把“了”放在宾语后面，语序错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
