INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使人在肉体或精神上受到痛苦。", "primary_collocate": null, "pronunciation": "zhé mó", "ipa": "ʈʂɤ˧˥ mwo˧˥", "syllable_count": 2, "sentences": [{"text": "失眠一直折磨着他。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愧疚的心情折磨了他很多年。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "担心折磨着她，晚上睡不着。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想再折磨自己了。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坏人用各种办法折磨他。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别再折磨我了，我真的很累。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "长时间的等待折磨着每个人。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压力太大，工作折磨得他睡不好觉。", "target_word": "折磨", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过去的事一直折磨着她，她不快乐。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那次失败折磨过他很长时间。", "target_word": "折磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "折磨着", "label": "持续体"}, {"form": "折磨了", "label": "完成体"}, {"form": "折磨过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使人在身心上长期受苦（失眠、愧疚、压力等折磨某人）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a539d2-b9bf-4579-bf7e-a6cf9155014c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折磨", "is_correct": true, "explanation": "“折磨”指长时间使人身心受苦，与“失眠一直……着他”的语境相符。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”表示喜爱地得到或品味，不能用来描述让人痛苦的失眠。"}, {"text": "照顾", "is_correct": false, "explanation": "配价：“照顾”需要一个被照料的对象，主语“失眠”不能照顾“他”。"}, {"text": "安慰", "is_correct": false, "explanation": "搭配：“安慰”是人对人的动作，不能以“失眠”为主语去安慰“他”。"}], "explanations": {"折磨": "“折磨”指长时间使人身心受苦，与“失眠一直……着他”的语境相符。", "享受": "语义：“享受”表示喜爱地得到或品味，不能用来描述让人痛苦的失眠。", "照顾": "配价：“照顾”需要一个被照料的对象，主语“失眠”不能照顾“他”。", "安慰": "搭配：“安慰”是人对人的动作，不能以“失眠”为主语去安慰“他”。"}, "sentence_index": 0, "correct_answer": "折磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他折磨了一下午的题目，终于想出了解法。", "explanation": "这里应该用〈琢磨〉。“折磨”的对象必须是能感到痛苦的人；思考题目要说“琢磨”。"}, {"text": "朋友的关心一直折磨着他，让他心里很暖。", "explanation": "这里应该用〈温暖〉。“折磨”表示使人受痛苦，朋友的关心让人心里暖，两者语义相反。"}, {"text": "他每天跑步折磨身体，身体反而越来越好。", "explanation": "这里应该用〈锻炼〉。锻炼身体是有益的活动，“折磨”强调使人痛苦，不用于说明有益的身体练习。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折磨", "is_correct": true, "explanation": "“折磨”指长期使人受苦，与“长时间的等待……着每个人”相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赞美与喜爱，“等待”不能用来欣赏每个人，语义不合。"}, {"text": "体谅", "is_correct": false, "explanation": "配价：“体谅”需要有意识的人作主语，“等待”不能体谅别人。"}, {"text": "迷恋", "is_correct": false, "explanation": "搭配：“迷恋”通常指对人或事物着迷，不能说“等待迷恋每个人”。"}], "explanations": {"折磨": "“折磨”指长期使人受苦，与“长时间的等待……着每个人”相符。", "欣赏": "语义：“欣赏”表示赞美与喜爱，“等待”不能用来欣赏每个人，语义不合。", "体谅": "配价：“体谅”需要有意识的人作主语，“等待”不能体谅别人。", "迷恋": "搭配：“迷恋”通常指对人或事物着迷，不能说“等待迷恋每个人”。"}, "sentence_index": 6, "correct_answer": "折磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被家人折磨得精神特别好。", "explanation": "这里应该用〈照顾〉。“折磨”表示使人受痛苦，与“精神特别好”语义相反。"}, {"text": "这位护士耐心地折磨生病的老人，让他很快恢复了健康。", "explanation": "这里应该用〈照料〉。“折磨”指使人受痛苦，耐心照料则是让病人舒适，两者语义相反。"}, {"text": "他折磨了一下午的古籍，最后终于读懂了。", "explanation": "这里应该用〈研究〉。“折磨”的对象必须是能感到痛苦的人或动物，古籍不能被折磨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这段经历折磨她了很长时间。", "corrected_sentence": "这段经历折磨了她很长时间。", "error_description": "“了”应紧跟动词，写作“折磨了她”；“折磨她了”把“了”放在宾语后面，是错误的语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "失败的压力折磨他睡不着觉。", "corrected_sentence": "失败的压力折磨得他睡不着觉。", "error_description": "错误在于“折磨”后漏掉了补语标记“得”。表示折磨造成的结果“他睡不着觉”，要说“折磨得他睡不着觉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c55854b-069a-4056-9a51-b0e7a40997ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
