INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91415, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "所在是人或东西在的那个地方。", "primary_collocate": null, "pronunciation": "suǒ zài", "ipa": "swo˨˩˦ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "小狗不见了，我不知道它的所在。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把钥匙的所在告诉了妈妈。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上标着我们现在的所在。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我银行的所在，我想去取钱。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一个安静的所在，我常去那里看书。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人想知道孩子的所在，一直打电话。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们终于找到了他的所在。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店的所在不难找，就在地铁站旁边。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他当时的所在，他说在家睡觉。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小岛是个好所在，夏天很凉快。", "target_word": "所在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "所在地", "label": "复合"}], "register": "书面", "sense_fingerprint": "所在：人或东西在的那个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '014adc03-4858-4184-a9b1-120df8f0a908') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学历", "is_correct": false, "explanation": "语义：“学历”指人的受教育程度，不能用于小狗。"}, {"text": "所在", "is_correct": true, "explanation": "所在指人或东西所在的地方，这里指小狗的位置，与“不见了”相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是人劳动所得的报酬，小狗没有工资。"}, {"text": "身份证", "is_correct": false, "explanation": "搭配：“身份证”是人的证件，不能说小狗的身份证。"}], "explanations": {"学历": "语义：“学历”指人的受教育程度，不能用于小狗。", "所在": "所在指人或东西所在的地方，这里指小狗的位置，与“不见了”相符。", "工资": "语义：“工资”是人劳动所得的报酬，小狗没有工资。", "身份证": "搭配：“身份证”是人的证件，不能说小狗的身份证。"}, "sentence_index": 0, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在屋里找到了一张所在。", "explanation": "这里应该用〈个〉或〈处〉。〈张〉用于纸、桌子等平面的东西，所在是地方，不能用〈张〉。"}, {"text": "我们约定的所在是下午三点。", "explanation": "这里应该用〈时间〉。所在指地点，不指时间；约定的是时间，应说“约定的时间是下午三点”。"}, {"text": "他的所在是老师。", "explanation": "这里应该用〈职业〉。所在只表示地点，不能指一个人的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高度，是一个数值，不是可以“找到”的地方。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是人的重量数值，不是可以“找到”的地方。"}, {"text": "年纪", "is_correct": false, "explanation": "语义：“年纪”指年岁，不是可以寻找的对象，这句话不通。"}, {"text": "所在", "is_correct": true, "explanation": "所在指人或东西所在的地方，这里指他所在的位置，与“找到”相符。"}], "explanations": {"身高": "语义：“身高”指人的高度，是一个数值，不是可以“找到”的地方。", "体重": "语义：“体重”是人的重量数值，不是可以“找到”的地方。", "年纪": "语义：“年纪”指年岁，不是可以寻找的对象，这句话不通。", "所在": "所在指人或东西所在的地方，这里指他所在的位置，与“找到”相符。"}, "sentence_index": 6, "correct_answer": "所在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙的所在是白色的。", "explanation": "这里应该用〈颜色〉。所在指地点，不指颜色；说墙的颜色，应用“颜色”。"}, {"text": "这台机器的所在是切菜。", "explanation": "这里应该用〈功能〉。所在指地点，不指用途；说机器的功能，应用“功能”。"}, {"text": "这部电影的所在很精彩。", "explanation": "这里应该用〈内容〉。所在指地点，不能指电影的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于找到了一只隐蔽的所在。", "corrected_sentence": "我们终于找到了一个隐蔽的所在。", "error_description": "量词用错。“所在”是地方，应用量词“个”；“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "河边是孩子们最爱所在。", "corrected_sentence": "河边是孩子们最爱的所在。", "error_description": "“最爱”修饰“所在”时，中间要加结构助词“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '350b6046-953c-4c9a-a7ee-53585c01f84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
