INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "椅子是给人坐的东西，有靠背。", "primary_collocate": null, "pronunciation": "yǐ zi", "ipa": "i˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "妈妈在厨房里放了四把椅子。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人来了，快给他拿一把椅子。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在椅子上看了一个小时书。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子是木头做的。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椅子旁边有一张小桌子。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的椅子比你的高一点。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠着椅子睡着了。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店的椅子都是红色的。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把椅子推到桌子下面去。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬来一把椅子，让奶奶坐下。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "张", "label": "量词"}, {"form": "摇椅", "label": "复合词"}], "register": "中性", "sense_fingerprint": "给人坐的、有靠背的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91417, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "椅子", "is_correct": true, "explanation": "椅子（yǐ zi）：给人坐的、有靠背的东西，是正确答案。"}, {"text": "李子", "is_correct": false, "explanation": "李子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是李树的果实。"}, {"text": "影子", "is_correct": false, "explanation": "影子（yǐng zi）：第一个音节比 yǐ 多了鼻音韵尾 -ng，声调相同，意思是光照下的暗影。"}, {"text": "义子", "is_correct": false, "explanation": "义子（yì zi）：第一个音节声调不同（第四声），意思是收养的儿子。"}, {"text": "离子", "is_correct": false, "explanation": "离子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是带电的原子或原子团。"}], "explanations": {"椅子": "椅子（yǐ zi）：给人坐的、有靠背的东西，是正确答案。", "李子": "李子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是李树的果实。", "影子": "影子（yǐng zi）：第一个音节比 yǐ 多了鼻音韵尾 -ng，声调相同，意思是光照下的暗影。", "义子": "义子（yì zi）：第一个音节声调不同（第四声），意思是收养的儿子。", "离子": "离子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是带电的原子或原子团。"}, "sentence_index": null, "correct_answer": "椅子"}, "level_3": {"options": [{"text": "椅子", "is_correct": true, "explanation": "正确。椅子是给人坐的有靠背的东西，“四把”是它的量词，句子完整，符合句意。"}, {"text": "碗", "is_correct": false, "explanation": "搭配：碗一般用“个”计量，不说“四把碗”，搭配不当。"}, {"text": "剑", "is_correct": false, "explanation": "语义：剑是兵器，不是放在厨房里的物品，“厨房里放了四把剑”不合常理。"}, {"text": "小提琴", "is_correct": false, "explanation": "语义：小提琴是乐器，一般不会放在厨房里，“厨房里放了四把小提琴”不合常理。"}], "explanations": {"椅子": "正确。椅子是给人坐的有靠背的东西，“四把”是它的量词，句子完整，符合句意。", "碗": "搭配：碗一般用“个”计量，不说“四把碗”，搭配不当。", "剑": "语义：剑是兵器，不是放在厨房里的物品，“厨房里放了四把剑”不合常理。", "小提琴": "语义：小提琴是乐器，一般不会放在厨房里，“厨房里放了四把小提琴”不合常理。"}, "sentence_index": 0, "correct_answer": "椅子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子有两扇门，衣服可以挂在里面。", "explanation": "这里应该用〈柜子〉。椅子是给人坐的，没有门和挂衣服的空间；有门、能放衣服的应说柜子。"}, {"text": "这把椅子有四个轮子和方向盘，我每天开它去上班。", "explanation": "这里应该用〈汽车〉。椅子是给人坐的，不能开着去上班；有方向盘、能开的是汽车。"}, {"text": "饭做好了，快把椅子搬过来，我们在上面吃饭。", "explanation": "这里应该用〈桌子〉。椅子是给人坐的，不能在上面摆碗筷吃饭；吃饭要用桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91417, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "椅子", "is_correct": true, "explanation": "椅子（yǐ zi）：给人坐的、有靠背的东西，是正确答案。"}, {"text": "梨子", "is_correct": false, "explanation": "梨子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是梨。"}, {"text": "印子", "is_correct": false, "explanation": "印子（yìn zi）：第一个音节多了韵尾 -n，声调不同（第四声），意思是痕迹。"}, {"text": "里子", "is_correct": false, "explanation": "里子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是衣服的衬里。"}], "explanations": {"椅子": "椅子（yǐ zi）：给人坐的、有靠背的东西，是正确答案。", "梨子": "梨子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是梨。", "印子": "印子（yìn zi）：第一个音节多了韵尾 -n，声调不同（第四声），意思是痕迹。", "里子": "里子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是衣服的衬里。"}, "sentence_index": null, "correct_answer": "椅子"}, "level_3": {"options": [{"text": "椅子", "is_correct": true, "explanation": "正确。“靠着”后面接的是有靠背、能靠的东西，椅子符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：人不能靠着空气，“靠着空气睡着了”说不通。"}, {"text": "烟", "is_correct": false, "explanation": "语义：烟没有实体，不能用来靠，“靠着烟睡着了”不合常理。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，不能用来靠，“靠着字典睡着了”不合常理。"}], "explanations": {"椅子": "正确。“靠着”后面接的是有靠背、能靠的东西，椅子符合句意。", "空气": "语义：人不能靠着空气，“靠着空气睡着了”说不通。", "烟": "语义：烟没有实体，不能用来靠，“靠着烟睡着了”不合常理。", "字典": "语义：字典是书，不能用来靠，“靠着字典睡着了”不合常理。"}, "sentence_index": 6, "correct_answer": "椅子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子有制冷功能，牛奶可以放在里面保鲜。", "explanation": "这里应该用〈冰箱〉。椅子是用来坐的，不能制冷保鲜；能让牛奶保鲜的是冰箱。"}, {"text": "我把这把椅子铺上被子，晚上就睡在上面。", "explanation": "这里应该用〈床〉。椅子是给人坐的，不能铺被子睡觉；睡觉要用床。"}, {"text": "这把椅子有四层隔板，可以摆很多书。", "explanation": "这里应该用〈书架〉。椅子是用来坐的，没有摆书的隔板；摆书要用书架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她坐在椅子织毛衣。", "corrected_sentence": "她坐在椅子上织毛衣。", "error_description": "位置错误：“坐在……上”的“上”不能省。“坐在椅子”后面缺少“上”，应为“坐在椅子上织毛衣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋角放着一只椅子。", "corrected_sentence": "屋角放着一把椅子。", "error_description": "量词错误：椅子应用“把”计量，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
