INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有靠背、供一个人坐的家具。", "primary_collocate": null, "pronunciation": "yǐ zi", "ipa": "i˨˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "请坐在这把椅子上。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有三十把椅子。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子搬到了窗边。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子很舒服，我想买。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在椅子下面睡觉。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家把椅子放回桌子下。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椅子的靠背太硬了，我坐着不舒服。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子站在椅子上拿书架上的书。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐过很多椅子，还是喜欢这一把。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "椅子坏了，请找人来修一修。", "target_word": "椅子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "摇椅", "label": "复合词"}, {"form": "椅背", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有靠背、供一个人坐的家具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4ebe5ac-3a97-4d64-8d3b-45e11368ef3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "椅子", "is_correct": true, "explanation": "椅子（yǐ zi）：有靠背、供一个人坐的家具，是正确答案。"}, {"text": "李子", "is_correct": false, "explanation": "李子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是李树的果实。"}, {"text": "影子", "is_correct": false, "explanation": "影子（yǐng zi）：第一个音节比 yǐ 多了鼻音韵尾 -ng，声调相同，意思是光照下的暗影。"}, {"text": "义子", "is_correct": false, "explanation": "义子（yì zi）：第一个音节声调不同（第四声），意思是收养的儿子。"}, {"text": "离子", "is_correct": false, "explanation": "离子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是带电的原子或原子团。"}], "explanations": {"椅子": "椅子（yǐ zi）：有靠背、供一个人坐的家具，是正确答案。", "李子": "李子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是李树的果实。", "影子": "影子（yǐng zi）：第一个音节比 yǐ 多了鼻音韵尾 -ng，声调相同，意思是光照下的暗影。", "义子": "义子（yì zi）：第一个音节声调不同（第四声），意思是收养的儿子。", "离子": "离子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是带电的原子或原子团。"}, "sentence_index": null, "correct_answer": "椅子"}, "level_3": {"options": [{"text": "椅子", "is_correct": true, "explanation": "正确。椅子指有靠背、供一个人坐的家具，与“这把”搭配，符合句意。"}, {"text": "刀子", "is_correct": false, "explanation": "语义：刀子是用来切东西的，不能坐，“坐在这把刀子上”不合常理。"}, {"text": "伞", "is_correct": false, "explanation": "语义：伞是用来遮雨遮阳的，不供人坐，“坐在这把伞上”说不通。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：剪刀是用来剪东西的，不能坐，“坐在这把剪刀上”不合常理。"}], "explanations": {"椅子": "正确。椅子指有靠背、供一个人坐的家具，与“这把”搭配，符合句意。", "刀子": "语义：刀子是用来切东西的，不能坐，“坐在这把刀子上”不合常理。", "伞": "语义：伞是用来遮雨遮阳的，不供人坐，“坐在这把伞上”说不通。", "剪刀": "语义：剪刀是用来剪东西的，不能坐，“坐在这把剪刀上”不合常理。"}, "sentence_index": 0, "correct_answer": "椅子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把椅子擦干净，摆上碗筷，在上面吃饭。", "explanation": "这里应该用〈桌子〉。椅子是给人坐的，不能在上面摆碗筷吃饭；吃饭要用桌子。"}, {"text": "这把椅子有四个轮子和方向盘，我每天开它去上班。", "explanation": "这里应该用〈汽车〉。椅子是给人坐的，不能开着去上班；有方向盘、能开的是汽车。"}, {"text": "这把椅子上面有四层隔板，专门用来摆书。", "explanation": "这里应该用〈书架〉。椅子是给人坐的，没有摆书的隔板；摆书要用书架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91418, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "椅子", "is_correct": true, "explanation": "椅子（yǐ zi）：有靠背、供一个人坐的家具，是正确答案。"}, {"text": "梨子", "is_correct": false, "explanation": "梨子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是梨。"}, {"text": "印子", "is_correct": false, "explanation": "印子（yìn zi）：第一个音节多了韵尾 -n，声调不同（第四声），意思是痕迹。"}, {"text": "里子", "is_correct": false, "explanation": "里子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是衣服的衬里。"}], "explanations": {"椅子": "椅子（yǐ zi）：有靠背、供一个人坐的家具，是正确答案。", "梨子": "梨子（lí zi）：声母 l 与 y 不同，声调也不同（第二声），意思是梨。", "印子": "印子（yìn zi）：第一个音节多了韵尾 -n，声调不同（第四声），意思是痕迹。", "里子": "里子（lǐ zi）：声母 l 与 y 不同，声调相同（第三声），意思是衣服的衬里。"}, "sentence_index": null, "correct_answer": "椅子"}, "level_3": {"options": [{"text": "椅子", "is_correct": true, "explanation": "正确。只有椅子有靠背供人坐，“靠背太硬”“坐着不舒服”都指向它，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是写字的平面，没有靠背，“黑板的靠背太硬了”说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有靠背，人也不靠着桌子坐，“桌子的靠背太硬了”说不通。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：柜子用来放东西，没有靠背，人也不坐在上面，“柜子的靠背太硬了”不合常理。"}], "explanations": {"椅子": "正确。只有椅子有靠背供人坐，“靠背太硬”“坐着不舒服”都指向它，符合句意。", "黑板": "语义：黑板是写字的平面，没有靠背，“黑板的靠背太硬了”说不通。", "桌子": "语义：桌子没有靠背，人也不靠着桌子坐，“桌子的靠背太硬了”说不通。", "柜子": "语义：柜子用来放东西，没有靠背，人也不坐在上面，“柜子的靠背太硬了”不合常理。"}, "sentence_index": 6, "correct_answer": "椅子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把这把椅子铺上被子，晚上就睡在上面。", "explanation": "这里应该用〈床〉。椅子是给人坐的，不能铺被子睡觉；睡觉要用床。"}, {"text": "这把椅子有两扇门，衣服可以挂在里面。", "explanation": "这里应该用〈柜子〉。椅子没有门和挂衣服的空间；有门、能放衣服的应说柜子。"}, {"text": "这把椅子有制冷功能，牛奶可以放在里面保鲜。", "explanation": "这里应该用〈冰箱〉。椅子是用来坐的，不能制冷保鲜；能让牛奶保鲜的是冰箱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坐在椅子看书。", "corrected_sentence": "他坐在椅子上看书。", "error_description": "位置错误：“坐在……上”的“上”不能省。“坐在椅子”后面缺少“上”，应为“坐在椅子上看书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客厅里放着一只椅子。", "corrected_sentence": "客厅里放着一把椅子。", "error_description": "量词错误：椅子应用“把”计量，不能用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7346b50-fae3-4dab-8aac-85e10340955a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
