INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "以拍摄照片或影像为职业的人。", "primary_collocate": null, "pronunciation": "shè yǐng shī", "ipa": "ʂɤ˥˩ iŋ˨˩˦ ʂɻ̩˥", "syllable_count": 3, "sentences": [{"text": "我哥哥是一名摄影师。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位摄影师拍的照片很漂亮。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师在山上等着日出。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想当一名摄影师，到处旅行。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师把相机放在桌子上。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位摄影师拍过很多明星。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师让新娘站在花前。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做摄影师已经十年了。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师说今天的光线太好了。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识一位专门拍野生动物的摄影师。", "target_word": "摄影师", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}], "register": "中性", "sense_fingerprint": "以拍照或摄像为职业的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f81bc4bc-44c8-4cf6-a5b7-596f28b237e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摄影师", "is_correct": true, "explanation": "正确：“摄影师”是以拍照为职业的人，可以接“一名”，与句意相合。"}, {"text": "女护士", "is_correct": false, "explanation": "语义：“哥哥”是男性，“女护士”与之矛盾。"}, {"text": "孕妇", "is_correct": false, "explanation": "语义：“哥哥”是男性，不可能是“孕妇”。"}, {"text": "婴儿", "is_correct": false, "explanation": "搭配：“哥哥”是成年人，与“婴儿”的身份不搭配。"}], "explanations": {"摄影师": "正确：“摄影师”是以拍照为职业的人，可以接“一名”，与句意相合。", "女护士": "语义：“哥哥”是男性，“女护士”与之矛盾。", "孕妇": "语义：“哥哥”是男性，不可能是“孕妇”。", "婴儿": "搭配：“哥哥”是成年人，与“婴儿”的身份不搭配。"}, "sentence_index": 0, "correct_answer": "摄影师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "摄影师用画笔在画布上作画。", "explanation": "这里应该用〈画家〉。摄影师靠相机拍照，不用画笔作画。"}, {"text": "摄影师在法庭上为被告辩护。", "explanation": "这里应该用〈律师〉。摄影师以拍照为职业，不负责在法庭上为被告辩护。"}, {"text": "摄影师给病人看病开药。", "explanation": "这里应该用〈医生〉。摄影师以拍照为职业，不负责看病开药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摄影师", "is_correct": true, "explanation": "正确：“摄影师”能够指挥新娘站位拍照，与句意相合。"}, {"text": "椅子", "is_correct": false, "explanation": "配价：“让”要求施事是能发出指令的人，椅子不能让新娘站位。"}, {"text": "雨伞", "is_correct": false, "explanation": "配价：雨伞是物品，不能“让”别人做事。"}, {"text": "蛋糕", "is_correct": false, "explanation": "配价：蛋糕是食物，不能充当“让”的施事。"}], "explanations": {"摄影师": "正确：“摄影师”能够指挥新娘站位拍照，与句意相合。", "椅子": "配价：“让”要求施事是能发出指令的人，椅子不能让新娘站位。", "雨伞": "配价：雨伞是物品，不能“让”别人做事。", "蛋糕": "配价：蛋糕是食物，不能充当“让”的施事。"}, "sentence_index": 6, "correct_answer": "摄影师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一位摄影师在法庭上宣判被告有罪。", "explanation": "这里应该用〈法官〉。摄影师以拍照为职业，不能在法庭上宣判被告有罪。"}, {"text": "一位摄影师驾驶客机在机场起飞。", "explanation": "这里应该用〈飞行员〉。摄影师以拍照为职业，不负责驾驶客机。"}, {"text": "一位摄影师在饭店后厨炒菜做饭。", "explanation": "这里应该用〈厨师〉。摄影师以拍照为职业，不负责在饭店后厨炒菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥是一台摄影师，经常去山里拍照。", "corrected_sentence": "我哥哥是一名摄影师，经常去山里拍照。", "error_description": "量词错误：“台”用于机器，指人应用“名”或“位”。错误形式是“一台摄影师”，正确形式是“一名摄影师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她请了一摄影师来拍婚纱照。", "corrected_sentence": "她请了一位摄影师来拍婚纱照。", "error_description": "量词缺失：指人的名词前要带量词，“一摄影师”缺少量词。错误形式是“一摄影师”，正确形式是“一位摄影师”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f0bd82-ed93-4eb3-873e-652b9b4bc670') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
