INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91421, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拯救是帮一个人，让他不再有大危险。", "primary_collocate": null, "pronunciation": "zhěng jiù", "ipa": "ʈʂɤŋ˨˩˦ tɕjou˥˩", "syllable_count": 2, "sentences": [{"text": "是警察拯救了掉进河里的那个男孩。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拯救过很多遇到危险的人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她跳进水里，拯救了快要沉下去的朋友。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来拯救我？我困在山里两天了。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人用话语拯救了一个想放弃生活的年轻人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拯救了那个孩子，自己却受了伤。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生拯救了我的爸爸，我永远不会忘记他。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救护车来得很快，拯救了那位老人。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位英雄拯救了很多人，大家都爱他。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来不及拯救自己的朋友，心里很难过。", "target_word": "拯救", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拯救了", "label": "体标（了）"}, {"form": "拯救过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "动词；帮助处在大危险中的人，让他安全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'db945215-8bb7-469b-a806-7db5687ef759') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "结婚", "is_correct": false, "explanation": "配价：“结婚”是不及物动词，后面不能直接带“男孩”作宾语。"}, {"text": "拯救", "is_correct": true, "explanation": "“拯救”表示使掉进河里的男孩脱离危险，符合句意。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示热情接待，与“掉进河里”的危险情境不合。"}, {"text": "追赶", "is_correct": false, "explanation": "语义：“追赶”指追上逃跑的人或物，与“掉进河里”的情境不合。"}], "explanations": {"结婚": "配价：“结婚”是不及物动词，后面不能直接带“男孩”作宾语。", "拯救": "“拯救”表示使掉进河里的男孩脱离危险，符合句意。", "欢迎": "语义：“欢迎”表示热情接待，与“掉进河里”的危险情境不合。", "追赶": "语义：“追赶”指追上逃跑的人或物，与“掉进河里”的情境不合。"}, "sentence_index": 0, "correct_answer": "拯救"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "哥哥拯救了我的自行车。", "explanation": "这里应该用〈修理〉。自行车坏了只需修理，没有大危险，不能用“拯救”。"}, {"text": "他从桌子上拯救了一本书。", "explanation": "这里应该用〈拿〉。书放在桌子上没有任何危险，不能用“拯救”。"}, {"text": "我每天拯救一点零花钱。", "explanation": "这里应该用〈节省〉。“拯救”用于让人脱离大危险，零花钱的节省要用“节省”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆，不能用于人。"}, {"text": "拯救", "is_correct": true, "explanation": "“拯救”表示使我的爸爸脱离危险，与“永远不会忘记他”的感激语境相合。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：“扔掉”与“永远不会忘记他”的感激语境矛盾，句意不通。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：“演奏”的对象是乐器或乐曲，不能用于人。"}], "explanations": {"驾驶": "搭配：“驾驶”的对象是车辆，不能用于人。", "拯救": "“拯救”表示使我的爸爸脱离危险，与“永远不会忘记他”的感激语境相合。", "扔掉": "语义：“扔掉”与“永远不会忘记他”的感激语境矛盾，句意不通。", "演奏": "搭配：“演奏”的对象是乐器或乐曲，不能用于人。"}, "sentence_index": 6, "correct_answer": "拯救"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每周保养一次汽车，这次我拯救了它。", "explanation": "这里应该用〈修理〉。汽车只是出了毛病，需要修理，没有脱离大危险的意思，不能用“拯救”。"}, {"text": "他拯救了借出的书。", "explanation": "这里应该用〈收回〉。书被借走并没有危险，不能用“拯救”，应该说“收回”。"}, {"text": "这次考试他拯救了三分。", "explanation": "这里应该用〈得到〉。“拯救”表示使人或事物脱离危险，得分不能用“拯救”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f23376c-081b-4619-bb08-81c9f2e94748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
